// All design-token variables ($brand-*, $color-*, $aac-*, $la-*, $cat-*,
// $nav_*, $page-footer-*, $ll-bento-*) live in _variables.scss above.

/* Shared "raised glass pill" button — mirrors the boards-page Change
   Home Board button (`.ub-boards-page__set-home-btn`, ~app.scss:57064)
   so the boards-page New Board CTA and the setup Board Category CTAs all
   read as one button family. `$bg` / `$hover-bg` are parameterized so a
   caller can keep its own background while sharing the shape, border,
   layered shadow, and sizing. Defined here (before first use) because
   the setup rules that consume it live earlier in the file than the
   mid-file mixin cluster. */
@mixin home-board-pill($bg, $hover-bg, $border: rgba(255, 255, 255, 0.5), $hover-border: rgba(255, 255, 255, 0.6)) {
  flex-shrink: 0;
  display: inline-flex;
  align-items: center;
  gap: 6px;
  min-height: 44px;
  padding: 8px 14px;
  background: $bg;
  border: 1px solid $border;
  border-radius: 999px;
  color: var(--md-ink);
  font-size: 14px;
  font-weight: 600;
  cursor: pointer;
  white-space: nowrap;
  box-shadow:
    0 1px 0 rgba(255, 255, 255, 0.6) inset,
    0 1px 2px rgba($la-navy, 0.12),
    0 6px 14px rgba($la-navy, 0.22);
  transition: background 0.15s ease, border-color 0.15s ease, box-shadow 0.15s ease;

  &:hover,
  &:focus-visible {
    background: $hover-bg;
    border-color: $hover-border;
    box-shadow:
      0 1px 0 rgba(255, 255, 255, 0.65) inset,
      0 2px 4px rgba($la-navy, 0.14),
      0 10px 22px rgba($la-navy, 0.28);
  }
}

/* Modern board-card STYLING (the LingoLinq board-card direction), applied
   on top of each surface's EXISTING layout — `@include` it inside any
   `<surface> .simple_board_icon` rule. It changes only the look (glass
   surface, subtle outline, top edge-light, contained logo tile, type
   hierarchy, soft glass pills, gentle hover lift) — NOT the layout
   (no display/flex/width), so every surface keeps its own composition.
   `!important` on the conflicting cosmetics so the shared look wins over
   each surface's bespoke declarations regardless of source order. Dark/
   themed shells (e.g. bento --dark / --midday) re-assert their own bg +
   text colors after including this. */
// Shared "glass bar" surface — the translucent-white glossy panel used by BOTH the
// speak-mode compose bar (.md-board-detail-sentence-bar) and the edit-mode session
// bar (.md-board-edit-session) so the two ALWAYS match (one source of truth). Only
// the surface look lives here; each rule keeps its own layout (padding, radius, flex).
@mixin glass-bar-surface {
  background: linear-gradient(
    180deg,
    rgba(255, 255, 255, 0.95) 0%,
    rgba(255, 255, 255, 0.74) 50%,
    rgba(238, 244, 251, 0.64) 100%
  );
  -webkit-backdrop-filter: blur(20px) saturate(185%);
  backdrop-filter: blur(20px) saturate(185%);
  border: 1px solid rgba(255, 255, 255, 0.55);
  box-shadow:
    inset 0 1.5px 0 rgba(255, 255, 255, 0.98),        /* crisp specular top edge (gloss line) */
    inset 0 14px 22px -16px rgba(255, 255, 255, 0.65), /* upper sheen bloom */
    inset 0 -10px 22px -18px rgba($la-navy, 0.06),     /* faint lower depth */
    0 1px 2px rgba($la-navy, 0.05),
    0 12px 30px rgba($la-navy, 0.12);                  /* soft outer elevation */
  color: $la-navy;
  // GPU layer — prevents backdrop-filter recompute flash on scroll.
  will-change: transform;
  transform: translateZ(0);
}

@mixin board-card-modern {
  position: relative;
  border-radius: 28px !important;
  border: 1px solid rgba(76, 134, 216, 0.08) !important;
  background: linear-gradient(180deg, rgba(255, 255, 255, 0.92), rgba(248, 250, 255, 0.82)) !important;
  box-shadow:
    0 1px 2px rgba(27, 54, 93, 0.04),
    0 8px 20px rgba(27, 54, 93, 0.06) !important;
  overflow: hidden;
  transition: transform 220ms cubic-bezier(0.2, 0.8, 0.2, 1),
              box-shadow 220ms cubic-bezier(0.2, 0.8, 0.2, 1),
              border-color 220ms ease !important;

  &::before {
    content: '';
    position: absolute;
    inset: 0 0 auto 0;
    height: 2px;
    background: linear-gradient(90deg,
      rgba($brand-verdigris, 0) 0%,
      rgba($brand-verdigris, 0.5) 28%,
      rgba(76, 134, 216, 0.5) 72%,
      rgba(76, 134, 216, 0) 100%);
    opacity: 0.55;
    pointer-events: none;
    z-index: 1;
  }
  &:hover {
    transform: translateY(-3px);
    border-color: rgba(76, 134, 216, 0.16) !important;
    box-shadow:
      0 24px 48px rgba(27, 54, 93, 0.14),
      0 12px 24px rgba(42, 157, 143, 0.10) !important;
  }

  /* Contained logo tile — soft rounded glass surface, faint inner glow,
     gentle elevation. width:auto + max-width centers + contains it even
     where the surface forces width:100%. */
  & img {
    width: auto !important;
    max-width: 72% !important;
    height: 104px !important;
    object-fit: contain;
    object-position: center;
    margin: 2px auto 14px !important;
    padding: 11px !important;
    border-radius: 18px;
    background: radial-gradient(120% 120% at 30% 20%, rgba(255, 255, 255, 0.95), rgba(240, 245, 252, 0.7));
    border: 1px solid rgba(76, 134, 216, 0.10);
    box-shadow:
      inset 0 1px 0 rgba(255, 255, 255, 0.85),
      0 4px 12px rgba(27, 54, 93, 0.07);
    box-sizing: border-box;
  }
  /* LingoLinq default/fallback board icon: keep the tile/card (bg, border,
     radius, shadow inherited from `& img` above) but expand the image out
     to the tile's borders — zero the inner padding and fill so the logo
     uses the full tile instead of sitting inset. Vocab-icon boards keep
     the padded contained tile. */
  & img[src*="lingolinq-board-icon"] {
    padding: 0 !important;
    object-fit: cover !important;
  }

  /* Typography — also sets the compact spacing/layout (centered, clamped
     title; tight inline `by name`) so EVERY surface reads the same as the
     board_category page, not just the colors. Font sizes carry a 12px
     floor via max() so card text never renders below 12px (e.g. if a root
     font-size shrink scales the rem values down). The title is pinned to
     14px (1.4rem at the 10px root) per design. */
  & .name {
    width: 100% !important;
    font-size: max(14px, 1.4rem) !important;
    font-weight: 700 !important;
    color: $la-navy !important;
    line-height: 1.25 !important;
    text-align: center !important;
    margin: 0 0 4px !important;
    max-height: 2.5em !important;
    overflow: hidden !important;
    display: -webkit-box !important;
    -webkit-line-clamp: 2 !important;
    line-clamp: 2 !important;
    -webkit-box-orient: vertical !important;
  }
  & .board-icon__credit {
    font-size: max(12px, 0.85rem) !important;
    opacity: 0.72;
    text-align: center !important;
    margin: 0 0 2px !important;
  }
  & .author {
    display: flex !important;
    flex-direction: row !important;
    flex-wrap: wrap !important;
    align-items: baseline !important;
    justify-content: center !important;
    gap: 4px !important;
    /* Small breathing room after the `by …` line (the language pill /
       PREVIEW footer supply the rest of the rhythm). */
    margin: 0 0 6px !important;
    padding: 0 2px !important;
    max-width: 100% !important;
    font-size: max(12px, 0.9rem) !important;
    color: rgba(27, 54, 93, 0.72) !important;
  }
  & .author__label { color: rgba(27, 54, 93, 0.55) !important; }
  & .author__username,
  & .author__username--long {
    color: rgba(27, 54, 93, 0.72) !important;
    font-weight: 600 !important;
    font-size: max(12px, 0.9rem) !important;
  }

  /* Size chip — soft navy-gray glass (was a utility sticker). */
  & .board-icon__info {
    background: rgba(255, 255, 255, 0.62) !important;
    border: 1px solid rgba(27, 54, 93, 0.08) !important;
    color: rgba(27, 54, 93, 0.66) !important;
    box-shadow: none !important;
    backdrop-filter: blur(10px);
    -webkit-backdrop-filter: blur(10px);
    z-index: 2;
  }
  & .board-icon__info-icon,
  & .board-icon__info-size { color: rgba(27, 54, 93, 0.6) !important; }

  /* Language pill — soft verdigris glass. */
  & .board-icon__lang-marker {
    background: rgba(255, 255, 255, 0.62) !important;
    border: 1px solid rgba(42, 157, 143, 0.12) !important;
    color: $brand-verdigris !important;
    box-shadow: none !important;
    backdrop-filter: blur(10px);
    -webkit-backdrop-filter: blur(10px);
  }
  /* Preview pill — integrated dusty-denim glass. */
  & .info {
    background: linear-gradient(135deg, rgba(255, 255, 255, 0.95), rgba(228, 236, 255, 0.92)) !important;
    border: 1px solid rgba(76, 134, 216, 0.14) !important;
    box-shadow: 0 8px 18px rgba(76, 134, 216, 0.16) !important;
    color: $la-navy !important;
  }
}

/* Shared board-card LAYOUT (flex column + bottom-anchored Preview pill).
   `@include` inside surface rules that already set display:flex on
   `.simple_board_icon`; the base `.simple_board_icon` rule below
   includes this by default. Cosmetics stay in `board-card-modern`. */
@mixin simple-board-card-layout {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: flex-start;
  height: auto;
  min-height: 0;

  .author {
    order: 97;
    margin-top: 0;
    margin-bottom: 4px;
  }

  .board-icon__lang-marker {
    order: 98;
    margin: 0 0 8px;
  }

  .info {
    position: static !important;
    top: auto !important;
    left: auto !important;
    right: auto !important;
    bottom: auto !important;
    transform: none !important;
    order: 99;
    align-self: center;
    margin-top: auto !important;
    margin-bottom: 0;
  }
}

*, *:before, *:after {
  -moz-box-sizing: border-box; -webkit-box-sizing: border-box; box-sizing: border-box;
}

/*
  Keyboard focus indicator (Tab / switch / voice access):
  When someone moves through the app without a mouse, the focused control gets a clear
  navy ring so they always know which button, link, or field is active. Older styles
  used "outline: none", which hid that ring; this rule brings it back for keyboard-style
  focus only (not for every mouse click). Matches WCAG 2.4.7 (Focus Visible).
  Scoped to #within_ember; !important wins over legacy outline resets.
*/
/* Global keyboard focus indicator: 3px navy box-shadow ring around the focused
   element. Critically, this rule does NOT change the element's background or
   text color — those stay as the element designed them. Earlier iterations
   tried to add a light navy bg tint + dark text on focus, but that broke
   contrast in two opposite ways:
     - light-text buttons (Sign In on dark bg) became light-text-on-light-tint
     - dark-text active states (active pillnav on dark bg) became
       dark-text-on-dark-bg when the forced color override applied
   The simplest fix that works for every element type is to leave colors
   alone and let the ring be the sole focus indicator. WCAG 2.4.7 + 1.4.3. */
#within_ember *:focus-visible:not(.md-board-detail-edit-toolbar__search-input) {
  outline: none !important;
  box-shadow: 0 0 0 3px $la-navy !important;
  border-radius: 6px;
}
/* On dark backgrounds, use a light focus ring for contrast */
#within_ember.board-detail-view:has(.md-board-detail--dark) *:focus-visible:not(.md-board-detail-edit-toolbar__search-input),
.md-board-detail--dark *:focus-visible:not(.md-board-detail-edit-toolbar__search-input),
header:has(#speak) *:focus-visible,
#inner_header:has(#speak) *:focus-visible,
.md-board-detail-sentence-bar *:focus-visible,
.md-board-detail-header *:focus-visible,
.md-board-detail-board-actions *:focus-visible,
.md-board-detail-board-actions__btn:focus-visible {
  box-shadow: 0 0 0 3px rgba(255, 255, 255, 0.85) !important;
  border-radius: 6px;
}

/* Windows High Contrast Mode (forced-colors) compatibility:
   The global focus rules above use box-shadow for the ring. HCM strips
   box-shadow entirely AND we explicitly set outline:none, so HCM users would
   see no focus indicator at all. This block restores a visible focus ring
   using `outline` (which HCM respects) with the system `Highlight` color
   (which adapts to the user's chosen contrast theme). WCAG 2.4.7 compliance.

   Selector specificity must MATCH the global rule above (which uses
   `:not(.md-board-detail-edit-toolbar__search-input)` adding a class to its
   specificity count). Without the `:not(...)`, this rule loses the cascade
   battle in HCM and `outline: none !important` from the global rule wins. */
@media (forced-colors: active) {
  #within_ember *:focus-visible:not(.md-board-detail-edit-toolbar__search-input) {
    outline: 3px solid Highlight !important;
    outline-offset: 2px !important;
    box-shadow: none !important;
    background-color: transparent !important;
  }
}

/*
  Suppress the browser-default focus outline (and Bootstrap's default button
  focus box-shadow) for mouse clicks. When a pointer user clicks a link or
  button, :focus fires but :focus-visible does not — this rule catches that
  gap. Keyboard-style focus still shows the ring via the :focus-visible rule
  above, so WCAG 2.4.7 (Focus Visible) compliance is preserved.

  Carve-out: the speak-bar chip is a focusable control whose box-shadow is
  DECORATIVE (its glass elevation), not a focus ring — this reset would strip
  that shadow the instant a click focuses it, making the chip look "pressed".
  Exclude it so its elevation survives a click; its keyboard focus ring still
  comes from the `--editable:focus-visible` rule.
*/
#within_ember *:focus:not(:focus-visible):not(.md-board-detail-sentence-bar__chip) {
  outline: none !important;
  box-shadow: none !important;
}

/* Standard app layout (bento page with bottom navbar) – used for padding and fixed bars */
:root {
  --topbar-height: 68px;
  --bottombar-height: 59px;
}
/* Hide header entirely in board layout mode */
.header--hidden {
  display: none !important;
}
.content--no-top-padding {
  padding-top: 0 !important;
}
/* When user is logged in, use a shorter top navbar */
#within_ember:has(header:not(.header--unauthenticated)) {
  --topbar-height: 16px;
}
/* After authenticated topbar rule — hidden header must not reserve space (beta onboarding, board layout). */
#within_ember:has(> header.header--hidden) {
  --topbar-height: 0px;
}
/* App-navbar-only header (no speak row, no legacy #nav_header): bar is 70px; 16px left #content tucked under the fixed header (e.g. /offline-boards on narrow screens). */
#within_ember:has(> header.header-index-with-dark-toggle:not(.header--unauthenticated):has(#inner_header .app-navbar):not(:has(#inner_header #speak)):not(:has(#inner_header #nav_header))) {
  --topbar-height: 70px;
}
/* Eval WELCOME exception: it renders the full app-navbar (70px), but the
   line-above app-navbar detection doesn't match the eval intro's DOM, so
   #within_ember falls through to the 16px authenticated default and the eval
   view tucks under the fixed 70px header. Pin 70px for the eval welcome
   (board-view + app-navbar header + the .md-eval-intro__panel the eval-intro
   component renders) so #content and every other var(--topbar-height) consumer
   clears the navbar. Section intros keep the speak bar and match the taller
   129px rule below (higher id-count specificity), so they are unaffected. */
#within_ember.board-view:has(> header.header-index-with-dark-toggle):has(.md-eval-intro__panel) {
  --topbar-height: 70px;
}
/* Board page: navbar + board bar (speak or nav_header) need a taller header so both rows fit */
#within_ember:has(header.header-index-with-dark-toggle #speak),
#within_ember:has(header.header-index-with-dark-toggle #nav_header) {
  --topbar-height: 129px;
}
/* Board index route: header often lacks header-index-with-dark-toggle; speak bar still needs the same
   --topbar-height baseline so board/index ResizeObserver math matches #content padding (see docs/SPEAK_MODE_EVAL_LAYOUT.md). */
#within_ember.board-view:has(#inner_header #speak),
#within_ember.board-alt-view:has(#inner_header #speak) {
  --topbar-height: 129px;
}
/* Landing navbar: target height 88–96px; footer 50% taller and content vertically centered */
#within_ember:has(header.header--unauthenticated) {
  --topbar-height: 92px;
  --bottombar-height: 88.5px; /* 59px × 1.5 for unauthenticated footer */
}
/* Unauthenticated header with landing nav (index or /landing-alt): compact height and padding */
#within_ember:has(header.header--unauthenticated .la-topbar-nav) {
  --topbar-height: 44px;
}
header.header--unauthenticated:has(.la-topbar-nav) {
  min-height: 56px;
  padding-top: 0;
  padding-bottom: 0;
}
header.header--unauthenticated:has(.la-topbar-nav) #inner_header {
  padding-top: 6px !important;

  padding-bottom: 6px !important;

}
header.header--unauthenticated #inner_header {
  display: flex !important;

  align-items: center !important;

  height: 70px !important;

}
header.header--unauthenticated #inner_header #nav_header {
  height: 100% !important;

  margin-top: 0 !important;
  display: flex !important;

  align-items: center !important;

}
header.header--unauthenticated #inner_header h1,
header.header--unauthenticated #inner_header #nav_header h1,
header.header--unauthenticated #nav_header h1 {
  margin: 0 !important;
  padding: 0 !important;
  height: 100% !important;
  display: flex !important;
  align-items: center !important;
}
header.header--unauthenticated #inner_header .nav-header__brand {
  height: 100% !important;

  display: inline-flex !important;

  align-items: center !important;

}
header.header--unauthenticated #inner_header .nav-header__logo-link {
  height: 100% !important;

  display: inline-flex !important;

  align-items: center !important;

  /* Keep the focus ring hugging the logo content rather than stretching to
     fill the parent flex row. width: max-content prevents flex-row contexts
     from forcing the link wider than its image content. */
  width: max-content;

}
/* Hide page footer in unauthenticated view (login, register, landing-alt, etc.) */
#within_ember:has(header.header--unauthenticated) .page-footer {
  display: none !important;
}
/* Hide page footer on authenticated pages */
#within_ember:has(header:not(.header--unauthenticated)) .page-footer {
  display: none !important;
}

@font-face{
  font-family:'OpenDyslexic';
  src:url(../fonts/OpenDyslexicAlta-Regular.otf) format('opentype');
}
@font-face{
  font-family:'ArchitectsDaughter';
  src:url(../fonts/ArchitectsDaughter.ttf) format('truetype');
}

/* Applied in: app/templates/application.hbs (line 1), app/templates/brief.hbs (line 1)
   Main app wrapper - background_class, dim_sides, color_black set via application controller */
#within_ember {
  position: relative;
  background: #fff;
  overflow: hidden; /* Windows-only quirk causes extra scrollbars without this, if you
                      change, make sure to test sidebar and modal.highlight */
}

/* Page-level horizontal-scroll kill switch. No element inside the app should
   ever trigger a horizontal scrollbar on the document — that's always a bug,
   typically caused by a fixed-width child overshooting a narrow viewport. */
html, body {
  overflow-x: hidden !important;
  max-width: 100vw !important;
}
/* Bento page: standard app layout – .app (fixed inset) + .topbar/.bottombar fixed, .main scrolls with padding */
#within_ember:has(.page-footer) {
  position: fixed;
  inset: 0;
  display: flex;
  flex-direction: column;
  overflow: hidden;
  background: transparent;
}
/* Only #content grows; other direct children do not take flex space */
#within_ember:has(.page-footer) > *:not(#content) {
  flex: 0 0 auto;
}
#within_ember:has(.page-footer) > header {
  position: fixed !important;

  top: 0 !important;

  left: 0 !important;

  right: 0 !important;

  height: var(--topbar-height) !important;

  z-index: 1000 !important;

}
#within_ember:has(.page-footer) .page-footer {
  position: fixed !important;

  left: 0 !important;

  right: 0 !important;

  bottom: 0 !important;

  height: var(--bottombar-height) !important;

  z-index: 1000 !important;

}
/* Pricing and features pages: same as landing – full-page scroll, footer at end of content */
#within_ember.pricing-route,
#within_ember.features-route {
  position: static;
  overflow-x: hidden;
  overflow-y: visible;
  display: block;
  min-height: 100%;
}
#within_ember.pricing-route .page-footer,
#within_ember.features-route .page-footer {
  position: static !important;
  bottom: auto;
  left: auto;
  right: auto;
  height: auto;
  min-height: var(--bottombar-height);
}
/* Pricing and features pages: reserve space above footer when scrolled to bottom */
.la-wrapper.la-wrapper--pricing .la-main,
.la-wrapper.la-wrapper--features .la-main {
  padding-bottom: 0;
}
/* Pricing page: org management + bulk purchase above buttons, displayed horizontally */
.la-pricing-extra-links {
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  align-items: flex-start;
  gap: 24px 32px;
  margin-top: 2rem;
}

.la-pricing-extra-link {
  text-align: center;
  flex: 1 1 280px;
  max-width: 420px;
}

.la-pricing-org-management,
.la-pricing-bulk {
  p {
    margin: 0;
    font-size: 15px;
    line-height: 1.5;
    color: #2c3e50;
  }
}

.la-pricing-bulk {
  .la-pricing-bulk-explainer {
    margin-top: 0.5rem;
  }
}
.la-pricing-bulk-link {
  /* WCAG AA fix — was $brand-verdigris on white = 3.32:1. */
  color: var(--fs-dark-teal, $brand-verdigris-aa);
  text-decoration: none;
  font-weight: 500;
  border-bottom: 1px solid transparent;
  transition: border-color 0.12s ease;

  &:hover {
    border-bottom-color: var(--fs-dark-teal, $brand-verdigris-aa);
  }
}
.la-pricing-bulk-explainer {
  margin-top: 1rem;
  font-size: 15px;
  line-height: 1.5;
  color: #2c3e50;

  a {
    /* WCAG AA fix — was $brand-verdigris on white = 3.32:1. */
    color: var(--fs-dark-teal, $brand-verdigris-aa);
    text-decoration: none;
    border-bottom: 1px solid transparent;
    transition: border-color 0.12s ease;

    &:hover {
      border-bottom-color: var(--fs-dark-teal, $brand-verdigris-aa);
    }
  }
}
/* Speech page mockup: hide the main app header and bottom navigation */
#within_ember.speech-route > header,
#within_ember.speech-route .page-footer,
#within_ember.speech-route #setup_footer {
  display: none !important;
}
/* Content area: cap height so it ends above the fixed footer (footer is out-of-flow so doesn’t reserve space) */
#within_ember:has(.page-footer) #content.index.with_user {
  flex: 1 1 auto;
  min-height: calc(100vh - var(--topbar-height) - var(--bottombar-height));
  overflow-x: hidden;
  overflow-y: auto;
  padding-top: calc(var(--topbar-height) + 3rem);
  padding-bottom: var(--bottombar-height);
  display: flex;
  flex-direction: column;
  box-sizing: border-box;
  background: linear-gradient(to bottom,
    rgba(126, 184, 224, 0.25) 0%,
    rgba(212, 168, 75, 0.12) 50%,
    rgba(61, 122, 92, 0.14) 100%) !important;
}
