.cursor_area {
  padding: 5px 100px 5px 10px;
  margin: 5px 0;
  border: 2px solid #eee;
  border-radius: 10px;
  max-height: 330px;
  min-height: 220px;
  overflow: auto;
  position: relative;
  &.any_size {
    min-height: none;
    max-height: none;
    .big_btn {
      width: calc(100% - 10px); 
      height: calc(100vh - 180px); 
      overflow: auto;
      white-space: normal; 
      font-size: 50px;
      line-height: 55px;
      border-width: 4px;
      border-radius: 10px;
      span {
        display: inline-block;
      }
      .medium {
        font-size: 30px;
        line-height: 35px;
      }
      .small {
        font-size: 20px;
        line-height: 25px;
      }
      .big {
        font-size: 80px;
        line-height: 85px;
      }
      .huge {
        font-size: 100px;
        line-height: 105px;
      }
    }
  }
  .cursor_box {
    float: left;
    width: 150px;
    margin-right: -25px;
    padding-left: 20px;
    .cursor_blink {
      display: none;
      float: left; 
      margin-left: -10px;
      padding-left: 12.5px;
      margin-right: -10px;
      padding-right: 10px;
      width: 45px; 
      height: 104px; 
      overflow: hidden; 
      padding-top: 15px;
      opacity: 0.0;
      * {
        animation: cursorblink 1.0s infinite;
      }
      &.prior {
        margin-left: -35px;
      }
      .left, .right {
        display: inline-block; 
        width: 10px; 
        height: 70px; 
        border-top: 2px solid #000; 
        border-bottom: 2px solid #000; 
      }
      .left {
        border-right: 2px solid #000; 
        border-top-right-radius: 3px; 
        border-bottom-right-radius: 3px;
      }
      .right {
        border-left: 2px solid #000; 
        border-top-left-radius: 3px; 
        border-bottom-left-radius: 3px;
      }
      .glyphicon {
        display: none;
        font-size: 21px;
      }
    }
    .cursor_btn {
      padding: 2px;
      float: left;
      height: 104px;
      border-radius: 10px;
      position: relative; 
      z-index: 1;
    }
    &.cursor {
      .cursor_blink.posterior {
        display: block;
        opacity: 1.0;
      }
      &.prior {
        .cursor_blink.posterior {
          display: none;
          opacity: 0.0;
        }
        .cursor_blink.prior {
          display: block;
          opacity: 1.0;
        }
      }
    }
    &.over {
      .cursor_blink { 
        opacity: 1.0;
      }
      .cursor_btn {
        background: rgba(0, 123, 255, 0.3);
      }
    }
    &.selected {
      .cursor_blink { 
        opacity: 1.0;
        .left, .right {
          border-color: rgba(0, 123, 255, 1.0);
        }
        .glyphicon {
          color: rgba(0, 123, 255, 1.0);
        }
      }
      .cursor_btn {
        background: rgba(0, 123, 255, 1.0);
      }
      &.internal_left .cursor_blink.prior {
        background: rgb(179,215,255);
        * { opacity: 0.0; display: none; visibility: hidden; }
        opacity: 1.0;
        display: block;
      }
      &.internal_right .cursor_blink.posterior {
        background: rgb(179,215,255);
        * { opacity: 0.0; display: none; visibility: hidden; }
        opacity: 1.0;
        display: block;
      }
      &.moving {
        .cursor_blink { 
          opacity: 1.0;
          .left, .right {
            display: none;
          }
          .glyphicon {
            display: block;
          }
        }
      }
    }
  }
}

