    background: linear-gradient(135deg, var(--md-teal, $brand-verdigris), rgba(91, 141, 239, 0.9));
    color: #fff;
    border-color: transparent;
    box-shadow: 0 4px 14px rgba(44, 183, 176, 0.3);

    &:hover {
      background: linear-gradient(135deg, rgba(44, 183, 176, 0.9), rgba(91, 141, 239, 0.85));
      color: #fff;
      transform: translateY(-2px);
      box-shadow: 0 6px 18px rgba(44, 183, 176, 0.35);
