/* Applied in: FlashOutlet in application.hbs - flash messages */
@keyframes flash-slide-down {
  from {
    opacity: 0;
    transform: translateY(-10px) scale(0.97);
  }
  to {
    opacity: 1;
    transform: translateY(0) scale(1);
  }
}

@keyframes flash-slide-up {
  from {
    opacity: 0;
    transform: translateY(10px) scale(0.97);
  }
  to {
    opacity: 1;
    transform: translateY(0) scale(1);
  }
}

.flash {
  position: fixed;
  bottom: calc(env(safe-area-inset-bottom, 0px) + 1rem);
  left: 50%;
  transform: translateX(-50%);
  width: auto;
  max-width: min(480px, 90vw);
  min-width: 260px;
  opacity: 1;
  z-index: 1050;
  pointer-events: none;
  transition: opacity 1.2s ease, visibility 0s 1.2s linear;

  .alert {
    pointer-events: auto;
    position: relative;
    border: none;
    border-radius: 14px;
    padding: 12px 44px 12px 16px;
    font-size: 14px;
    font-weight: 600;
    line-height: 1.4;
    box-shadow: 0 8px 24px rgba(0, 0, 0, 0.14), 0 2px 6px rgba(0, 0, 0, 0.08);
    animation: flash-slide-up 0.22s cubic-bezier(0.22, 1, 0.36, 1) both;

    .shadow { display: none; }

    .close {
      position: absolute;
      top: 50%;
      right: 12px;
      transform: translateY(-50%);
      width: 24px;
      height: 24px;
      display: flex;
      align-items: center;
      justify-content: center;
      border-radius: 50%;
      opacity: 0.55;
      font-size: 16px;
      line-height: 1;
      padding: 0;
      margin: 0;
      float: none;
      transition: opacity 0.15s ease, background 0.15s ease;
      &:hover { opacity: 1; background: rgba(0,0,0,0.08); }
    }

    .btn[data-dismiss='alert'] {
      margin: 0;
      float: none;
      position: absolute;
      top: 50%;
      right: 12px;
      transform: translateY(-50%);
      font-size: 14px;
      padding: 4px 10px;
      border-radius: 8px;
    }

    &.alert-info {
      background: rgba(225, 242, 246, 0.97);
      color: #0c4a55;
      border-left: 3px solid #4aabb8;
      backdrop-filter: blur(8px);
      -webkit-backdrop-filter: blur(8px);
    }

    &.alert-success {
      background: rgba(226, 242, 224, 0.97);
      color: #1a4a22;
      border-left: 3px solid #5aaa62;
      backdrop-filter: blur(8px);
      -webkit-backdrop-filter: blur(8px);
    }

    &.alert-warning {
      background: rgba(255, 245, 220, 0.97);
      color: #5a3e00;
      border-left: 3px solid #e0a830;
      backdrop-filter: blur(8px);
      -webkit-backdrop-filter: blur(8px);
    }

    &.alert-danger {
      background: rgba(252, 232, 232, 0.97);
      color: #5a1a1a;
      border-left: 3px solid #d9534f;
      backdrop-filter: blur(8px);
      -webkit-backdrop-filter: blur(8px);
    }

    &.below_header {
      border-radius: 0 0 14px 14px;
      animation-name: flash-slide-down;
    }
  }

  &:has(.below_header) {
    bottom: auto;
  }
}

.flash.fade {
  opacity: 0;
  visibility: hidden;
}
