@keyframes target {
  0% {
    transform: scale(1.5);
    opacity: 0.3;
  }
  100% {
    transform: scale(0.5);
    opacity: 0.7;
  }
}
@-webkit-keyframes target {
  0% {
    transform: scale(1.5);
    opacity: 0.3;
  }
  100% {
    transform: scale(0.5);
    opacity: 0.7;
  }
}


@keyframes rota {
  0% { transform: rotate(0deg); }
  100% { transform: rotate(360deg); }
}

@-webkit-keyframes rota {
  0% { transform: rotate(0deg); }
  100% { transform: rotate(360deg); }
}

@keyframes opa {
  0% { opacity: 1; }
  50%, 100% { opacity: 0; }
}

@-webkit-keyframes opa {
  0% { opacity: 1; }
  50%, 100% { opacity: 0; }
}

#linger {
  display: block;
  width: 50px;
  height: 50px;
  background-color: $brand-danger;
  opacity: 0.3;
  position: absolute;
  top: -100px;
  left: -100px;
  z-index: 999999;
  border-radius: 100px;
  animation-duration: 2000ms;
  &.temp_hide {
    display: none;
    left: -100px;
  }
  &.cursor {
    border: 3px solid rgba(0, 0, 0, 0.5);
  }
  &.targeting.shrink {
    -webkit-animation-name: target;
    -webkit-animation-iteration-count: 1;
    -webkit-animation-timing-function: ease-in;  
    animation-name: target;
    animation-iteration-count: 1;
    animation-timing-function: ease-in;  
  }
  &.targeting.pie {
    background: #ccc;
    opacity: 0.6;
    
    .pie {
      width: 50%;
      height: 100%;
      transform-origin: 100% 50%;
      position: absolute;
      background: $brand-danger;
      border: rgba(0, 0, 0, 0.1);
    }

    .spinner {
      border-radius: 100% 0 0 100% / 50% 0 0 50%;
      z-index: 200;
      border-right: none;
      -webkit-animation: rota ease-in-out;
      -webkit-animation-duration: inherit;
      animation: rota ease-in-out;
      animation-duration: inherit;
      animation-iteration-count: 1;
    }

    .filler {
      border-radius: 0 100% 100% 0 / 0 50% 50% 0; 
      left: 50%;
      opacity: 0;
      z-index: 100;
      -webkit-animation: opa steps(1,end)  reverse;
      -webkit-animation-duration: inherit;
      animation: opa steps(1,end)  reverse;
      animation-duration: inherit;
      animation-iteration-count: 1;
      border-left: none;
    }

    .mask {
      width: 50%;
      height: 100%;
      position: absolute;
      background: inherit;
      opacity: 1;
      z-index: 300;
      border-top-left-radius: 100px;
      border-bottom-left-radius: 100px;
      -webkit-animation: opa steps(1,end);
      -webkit-animation-duration: inherit;
      animation: opa steps(1,end);
      animation-duration: inherit;
      animation-iteration-count: 1;
    }
  }
}
#dwell_icon {
  position: absolute;
  z-index: 300;
  border-radius: 10px;
  border: 2px solid #fff;
  background: #000;
  opacity: 0.5;
  width: 10px;
  height: 10px;
  margin-left: -5px;
  margin-top: -5px;
  &.with_transition {
    transition: left 0.1s, top 0.1s;
    transition-timing-function: ease-in-out;
  }
  &.big,&.arrow {
    opacity: 1.0;
    background: radial-gradient(rgba(255, 255, 0, 0.2), rgba(255, 255, 0, 0.8));
    border: 2px solid rgb(17, 112, 255);
    margin-left: -15px;
    margin-top: -15px;
    border-radius: 30px;
    width: 30px;
    height: 30px;
    &:after {
      margin-left: 15px;
      margin-top: 15px;
      content: "";
      display: block;
      width: 24px;
      height: 36px;
      background: url(../images/cursor.png);
      background-size: 24px 36px;
      border: 0;
      border-radius: 0;
      opacity: 1.0;
    }
  }

  &.red_circle {
    border-radius: 30px;
    width: 20px; 
    height: 20px; 
    margin-left: -10px;
    margin-top: -10px;
    background: rgba(255, 0, 0, 0.5);
    border: 2px solid #fff;
    box-shadow: 0px 0px 20px #000;
    opacity: 1.0;
  }

  &.circle {
    opacity: 1.0;
    border: 0;
    background: radial-gradient(closest-side, rgba(55, 55, 55, 0.8), rgba(55, 55, 55, 0.0));
    margin-left: -15px;
    margin-top: -15px;
    border-radius: 30px;
    width: 30px;
    height: 30px;
  }

  &.ball {
    opacity: 1.0;
    border: 0;
    background: radial-gradient(closest-side, rgba(55, 55, 55, 0.8), rgba(55, 55, 55, 0.0));
    margin-left: -30px;
    margin-top: -30px;
    border-radius: 30px;
    width: 60px;
    height: 60px;
  }
}

