/* ── Modern button-settings modal restyle ────────────── */

.modal-dialog:has(#button_settings) {
  width: 780px;
  max-width: 94vw;
}

.modal-content:has(#button_settings) {
  border: 1px solid rgba($la-navy, 0.10);
  box-shadow: 0 12px 48px rgba($la-navy, 0.18), 0 2px 8px rgba(0,0,0,0.06);
  background: #fff;
  overflow: hidden;
}

.modal-content:has(#button_settings) > .modal-header {
  background:
    linear-gradient(135deg, rgba($brand-verdigris, 0.08), rgba($brand-dusty-denim, 0.08), rgba(123, 107, 173, 0.05)),
    $surface-100;
  border-bottom: 1px solid rgba($la-navy, 0.08);
  padding: 18px 24px;
  padding-right: 56px;
}
.modal-content:has(#button_settings) > .modal-header h3 {
  margin: 0;
  font-size: 20px;
  font-weight: 700;
  color: $la-navy;
  letter-spacing: -0.3px;
}
.modal-content:has(#button_settings) > .modal-header .close {
  order: 0;
  width: 34px;
  height: 34px;
  border-radius: 50%;
  border: 1px solid rgba($la-navy, 0.12);
  background: rgba(255, 255, 255, 0.7);
  color: $brand-slate-gray;
  font-size: 20px;
  line-height: 1;
  display: flex;
  align-items: center;
  justify-content: center;
  opacity: 1;
  transition: background 0.15s ease, color 0.15s ease;
  float: none;
  margin: 0;
  padding: 0;
}
.modal-content:has(#button_settings) > .modal-header .close:hover {
  background: #fff;
  color: $brand-danger;
}

/* Nav pills sidebar */
#button_settings .nav-pills.nav-stacked {
  background:
    linear-gradient(180deg, rgba($brand-verdigris, 0.04), rgba($brand-dusty-denim, 0.03));
  border-radius: 12px;
  padding: 8px;
  border: 1px solid rgba($la-navy, 0.06);
}
#button_settings .nav-pills.nav-stacked > li {
  margin: 0;
}
/* Gradient divider under the pinned "Quick Actions" tab. */
#button_settings .nav-pills.nav-stacked > .md-bs-nav-sep {
  padding: 0 6px;
}
#button_settings .nav-pills.nav-stacked > .md-bs-nav-sep .md-bs-card__sep {
  margin: 8px 0;
}
#button_settings .nav-pills.nav-stacked > li > a {
  border-radius: 8px;
  padding: 10px 14px;
  font-size: 15px;
  font-weight: 500;
  color: #4a5568;
  transition: background 0.12s ease, color 0.12s ease;
  border: none;
  margin: 2px 0;
}
#button_settings .nav-pills.nav-stacked > li > a:hover {
  background: rgba($brand-verdigris, 0.08);
  color: $brand-verdigris;
}
#button_settings .nav-pills.nav-stacked > li.active > a,
#button_settings .nav-pills.nav-stacked > li.active > a:hover,
#button_settings .nav-pills.nav-stacked > li.active > a:focus-visible {
  /* Same silvery-glass verdigris→denim tint as the "Create editable copy"
     button; navy label keeps WCAG AA on the light gradient (>6:1). */
  background:
    linear-gradient(180deg, rgba(255, 255, 255, 0.55) 0%, rgba(255, 255, 255, 0.14) 42%, rgba(255, 255, 255, 0) 62%),
    linear-gradient(135deg, rgba($brand-verdigris, 0.50), rgba($brand-dusty-denim, 0.52)),
    #fff;
  color: $la-navy;
  font-weight: 600;
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.85),
    inset 0 -1px 0 rgba($la-navy, 0.06),
    0 1px 3px rgba($la-navy, 0.08);
}

/* Stronger keyboard focus ring for all interactive elements in button settings modal.
   Uses outline instead of box-shadow so it doesn't conflict with existing box-shadow on active tabs. */
.modal-content:has(#button_settings) *:focus-visible {
  @include focus-ring($width: 3px);
  border-radius: 6px;
}

/* Form controls */
#button_settings .form-control {
  border-radius: 10px;
  border: 1px solid rgba($la-navy, 0.15);
  padding: 10px 14px;
  font-size: 15px;
  transition: border-color 0.15s ease, box-shadow 0.15s ease;
  box-shadow: none;
  background: #fff;
}
#button_settings .form-control:focus-visible {
  border-color: $brand-verdigris;
  box-shadow: 0 0 0 3px rgba($brand-verdigris, 0.12);
  outline: none;
}
#button_settings .control-label {
  font-size: 14px;
  font-weight: 600;
  color: $brand-charcoal-dark;
  padding-top: 10px;
}
#button_settings .checkbox label,
#button_settings .radio label {
  font-size: 14px;
  color: #4a5568;
}

/* Quick action buttons (Help tab) — same brushed-silver glass as the Preview
   button in the Action section. */
#button_settings .btn-group-vertical .btn {
  border-radius: 10px !important;
  border: 1px solid rgba($la-navy, 0.16);
  padding: 14px 18px;
  font-size: 16px;
  font-weight: 500;
  color: $brand-charcoal-dark;
  background: linear-gradient(150deg,
    rgba(255, 255, 255, 0.95) 0%,
    rgba(236, 240, 245, 0.9) 50%,
    rgba(210, 217, 227, 0.85) 100%);
  backdrop-filter: blur(8px) saturate(150%);
  -webkit-backdrop-filter: blur(8px) saturate(150%);
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.9),
    inset 0 -1px 0 rgba($la-navy, 0.05),
    0 1px 3px rgba($la-navy, 0.08);
  text-align: left;
  transition: background 0.12s ease, box-shadow 0.12s ease, transform 0.1s ease, border-color 0.12s ease;
  margin-bottom: 6px;
}
#button_settings .btn-group-vertical .btn:hover {
  background: linear-gradient(150deg,
    #ffffff 0%,
    rgba(233, 238, 244, 0.96) 50%,
    rgba(200, 209, 221, 0.92) 100%);
  border-color: rgba($la-navy, 0.24);
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 1),
    0 2px 8px rgba($la-navy, 0.14);
  transform: translateX(2px);
}
#button_settings .btn-group-vertical .btn .glyphicon {
  color: $brand-verdigris;
  margin-right: 10px;
}

/* General buttons inside the modal body */
#button_settings .btn-default {
  border-radius: 10px;
  border: 1px solid rgba($la-navy, 0.12);
  background: #fff;
  color: $brand-charcoal-dark;
  font-weight: 500;
  transition: background 0.12s ease, box-shadow 0.12s ease;
}
#button_settings .btn-default:hover {
  background: $surface-200;
  box-shadow: 0 1px 4px rgba($la-navy, 0.10);
}
#button_settings .btn-primary {
  border-radius: 10px;
  /* Same SILVERY-GLASS verdigris→denim tint as the active side-panel tab (per
     request) instead of the darker solid gradient — one shared "primary" look
     across the modal. Navy label keeps AA contrast on the light gradient. */
  background:
    linear-gradient(180deg, rgba(255, 255, 255, 0.55) 0%, rgba(255, 255, 255, 0.14) 42%, rgba(255, 255, 255, 0) 62%),
    linear-gradient(135deg, rgba($brand-verdigris, 0.50), rgba($brand-dusty-denim, 0.52)),
    #fff;
  border: none;
  color: $la-navy;
  font-weight: 600;
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.85),
    inset 0 -1px 0 rgba($la-navy, 0.06),
    0 1px 3px rgba($la-navy, 0.08);
  transition: box-shadow 0.12s ease, transform 0.1s ease;
}
#button_settings .btn-primary:hover {
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.9),
    0 4px 12px rgba($brand-dusty-denim, 0.22);
  transform: translateY(-1px);
}

/* Content area headings */
#button_settings h4 {
  font-size: 18px;
  font-weight: 700;
  color: $la-navy;
  margin-bottom: 12px;
}
/* The header form-group inherits `.content .form-group { margin-bottom: 16px }`
   (higher specificity), which is the gap under "Button Settings". Override it at
   matching specificity + zero the h4 margin so "QUICK ACTIONS" sits just below. */
#button_settings .content .form-group.md-bs-help__head {
  margin-bottom: 6px;
}
#button_settings .md-bs-help__head h4 {
  margin-bottom: 0;
}

/* Image search results / options grid */
#button_settings .options {
  border-radius: 10px;
}

/* ── Action-tab guided cards (ACTION / DESTINATION / per-action config) ──
   Turns the Action tab into a stacked, card-based flow: a lightly-tinted
   glass card per step, an uppercase eyebrow label, helper text, and
   labels-above controls. Verdigris = selected/primary/focus; dusty-denim
   = secondary (browse / create / change). */
#button_settings .md-bs-card {
  background:
    linear-gradient(180deg, rgba($brand-verdigris, 0.035), rgba($brand-dusty-denim, 0.03)),
    #fff;
  border: 1px solid rgba($la-navy, 0.10);
  border-radius: 14px;
  padding: 18px 20px;
  margin-bottom: 24px;
  box-shadow: 0 1px 3px rgba($la-navy, 0.05);
}
#button_settings .md-bs-card:last-child {
  margin-bottom: 0;
}
/* The ACTION card holds a single control — keep it compact so the destination
   step sits higher on the page. */
#button_settings .md-bs-card--action {
  padding: 13px 20px 15px;
  margin-bottom: 18px;
}
#button_settings .md-bs-card--action .md-bs-card__hint {
  margin-bottom: 10px;
}
#button_settings .md-bs-card__eyebrow {
  text-transform: uppercase;
  letter-spacing: 0.08em;
  font-size: 12px;
  font-weight: 700;
  color: $brand-dusty-denim-aa;
  margin-bottom: 6px;
}
/* Modern gradient hairline between a card header and its body. */
#button_settings .md-bs-card__sep {
  height: 2px;
  margin: 10px 0 18px;
  border-radius: 2px;
  background: linear-gradient(90deg,
    transparent,
    rgba($brand-verdigris, 0.4) 25%,
    rgba($brand-dusty-denim, 0.4) 75%,
    transparent);
}
#button_settings .md-bs-card__hint {
  font-size: 15px;
  color: $brand-slate-gray;
  margin: 0 0 14px;
}
#button_settings .md-bs-field-label {
  display: block;
  font-size: 14px;
  font-weight: 600;
  color: $brand-charcoal-dark;
  margin: 16px 0 6px;
}
/* Give every control in these cards a comfortable touch target */
#button_settings .md-bs-card .form-control,
#button_settings .md-bs-card .bound-select__trigger {
  min-height: 50px;
}

/* Link/video action controls (modern) — checkbox rows, YouTube preview, time controls.
   Shares the card's brand palette so the ported video-popup section reads as native. */
#button_settings .md-bs-check {
  display: flex;
  align-items: center;
  gap: 10px;
  margin: 14px 0 0;
  font-size: 15px;
  font-weight: 600;
  color: $brand-charcoal-dark;
  cursor: pointer;
}
#button_settings .md-bs-check input[type="checkbox"] {
  width: 20px;
  height: 20px;
  flex: none;
  accent-color: $brand-verdigris;
  cursor: pointer;
}
/* 16:9 YouTube preview pane, rounded to match the card surfaces */
#button_settings .md-bs-video-preview {
  position: relative;
  width: 100%;
  aspect-ratio: 16 / 9;
  margin: 14px 0;
  border-radius: 12px;
  overflow: hidden;
  background: $brand-charcoal-dark;
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.06), 0 4px 14px rgba($la-navy, 0.14);
}
#button_settings .md-bs-video-preview iframe {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  border: 0;
}
/* Text-link affordance (e.g. "set thumbnail as button image") as a real <button> */
#button_settings .md-bs-linkish {
  display: inline-block;
  margin: 2px 0 12px;
  padding: 0;
  border: 0;
  background: none;
  color: $brand-dusty-denim-aa;
  font-size: 14px;
  font-weight: 600;
  text-decoration: underline;
  cursor: pointer;
}
#button_settings .md-bs-linkish:hover,
#button_settings .md-bs-linkish:focus-visible {
  color: color.adjust($brand-dusty-denim-aa, $lightness: -12%);
}
#button_settings .md-bs-video__times {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin: 4px 0 12px;
}
#button_settings .md-bs-video__time-fields {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 8px 10px;
}
#button_settings .md-bs-video__time-fields .md-bs-field-label {
  margin: 0;
}
#button_settings .md-bs-video__time-input {
  width: 90px;
  flex: none;
}
#button_settings .md-bs-video__time-unit {
  font-size: 14px;
  color: $brand-slate-gray;
}

/* Selected-board card (verdigris "chosen" state) */
#button_settings .md-bs-dest__selected {
  display: flex;
  align-items: center;
  gap: 14px;
  padding: 14px 16px;
  border: 1px solid rgba($brand-verdigris, 0.35);
  background: rgba($brand-verdigris, 0.06);
  border-radius: 12px;
}
#button_settings .md-bs-dest__icon {
  width: 48px;
  height: 48px;
  border-radius: 8px;
  object-fit: cover;
  background: #fff;
  border: 1px solid rgba($la-navy, 0.10);
  flex: 0 0 auto;
}
#button_settings .md-bs-dest__meta {
  flex: 1 1 auto;
  min-width: 0;
}
#button_settings .md-bs-dest__name {
  font-size: 17px;
  font-weight: 600;
  color: $la-navy;
  word-break: break-word;
}
#button_settings .md-bs-dest__change {
  flex: 0 0 auto;
}

/* "Selected" / state label above the status component */
#button_settings .md-bs-status__label {
  text-transform: uppercase;
  letter-spacing: 0.06em;
  font-size: 11px;
  font-weight: 700;
  color: $brand-slate-gray;
  margin-bottom: 6px;
}
/* Secondary line inside the selected-board card (owner / breadcrumb slot) */
#button_settings .md-bs-dest__owner {
  display: block;
  font-size: 13px;
  color: $brand-slate-gray;
  margin-top: 2px;
}

/* "Choose how to use this board" confirmation: a clean vertical preview card
   (thumbnail → title / grid / preview) on the left, and the explanation + two
   clearly-differentiated choices on the right. */
#button_settings .md-bs-choose {
  display: flex;
  gap: 30px;
  align-items: stretch;
}
#button_settings .md-bs-choose__status {
  font-size: 15px;
  color: $brand-charcoal-dark;
  margin: 0;
}
/* "Change Board" — reset the pending board and go back to the collection.
   Pushed to the bottom of the content column so it sits flush with the preview
   card's bottom edge. */
#button_settings .md-bs-choose__footer {
  display: flex;
  justify-content: flex-end;
  margin-top: auto;
  padding-top: 16px;
}
/* Sleek modern pill */
#button_settings .md-bs-choose__change,
#button_settings .md-bs-dest__change,
#button_settings .md-bs-help__skip {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  min-height: 40px;
  padding: 0 22px;
  border-radius: 999px;
  border: 1px solid rgba($brand-dusty-denim, 0.35);
  background: linear-gradient(180deg, #ffffff 0%, rgba($brand-dusty-denim, 0.07) 100%);
  color: $brand-dusty-denim-aa;
  font-weight: 600;
  font-size: 14px;
  letter-spacing: 0.01em;
  cursor: pointer;
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.9),
    0 1px 3px rgba($la-navy, 0.08);
  transition: background 0.14s ease, box-shadow 0.14s ease, transform 0.1s ease, border-color 0.14s ease;
}
#button_settings .md-bs-choose__change:hover,
#button_settings .md-bs-dest__change:hover,
#button_settings .md-bs-help__skip:hover {
  background: linear-gradient(180deg, #ffffff 0%, rgba($brand-dusty-denim, 0.14) 100%);
  border-color: rgba($brand-dusty-denim, 0.55);
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 1),
    0 3px 10px rgba($brand-dusty-denim, 0.22);
  transform: translateY(-1px);
}
#button_settings .md-bs-choose__change-icon,
#button_settings .md-bs-dest__change-icon {
  flex: 0 0 auto;
  opacity: 0.9;
}
/* Help tab: the skip/enable pill sits centered below the quick-action list. */
#button_settings .md-bs-help__skip-wrap {
  display: flex;
  justify-content: center;
  margin-top: 22px;
}

/* Color tab: live button preview + swatch palette + revert pill. */
#button_settings .md-bs-color__preview-wrap {
  display: flex;
  justify-content: center;
  margin-bottom: 20px;
}
#button_settings .md-bs-color__preview {
  width: 120px;
  height: 120px;
  border-radius: 12px;
  border: 3px solid #cccccc;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 6px;
  padding: 8px;
  box-shadow: 0 1px 4px rgba($la-navy, 0.10);
}
#button_settings .md-bs-color__preview-img {
  max-width: 62px;
  max-height: 62px;
  object-fit: contain;
}
#button_settings .md-bs-color__preview-label {
  font-size: 16px;
  font-weight: 600;
  color: #222222;
  text-align: center;
  line-height: 1.15;
  word-break: break-word;
}
/* Label on top (text-position preference) — flip the column so the label sits ABOVE
   the symbol. Id-scoped to match the base `#button_settings .md-bs-color__preview`
   specificity. "Text only" omits the <img> in the template, so no rule needed. */
#button_settings .md-bs-color__preview.md-bs-preview--text-top {
  flex-direction: column-reverse;
}
#button_settings .md-bs-color__field-label {
  font-size: 14px;
  font-weight: 600;
  color: $brand-charcoal-dark;
  margin-bottom: 10px;
}
/* Fitzgerald color swatches — labeled tiles (color chip + name + category). */
#button_settings .md-bs-color__swatches {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(92px, 1fr));
  gap: 10px;
}
#button_settings .md-bs-color__swatch {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 4px;
  padding: 8px;
  border-radius: 10px;
  border: 1px solid rgba($la-navy, 0.16);
  /* Brushed-silver glass, same as the quick-action buttons. */
  background: linear-gradient(150deg,
    rgba(255, 255, 255, 0.95) 0%,
    rgba(236, 240, 245, 0.9) 50%,
    rgba(210, 217, 227, 0.85) 100%);
  backdrop-filter: blur(8px) saturate(150%);
  -webkit-backdrop-filter: blur(8px) saturate(150%);
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.9),
    inset 0 -1px 0 rgba($la-navy, 0.05),
    0 1px 3px rgba($la-navy, 0.08);
  cursor: pointer;
  transition: transform 0.1s ease, box-shadow 0.12s ease, border-color 0.12s ease, background 0.12s ease;
}
#button_settings .md-bs-color__swatch:hover {
  transform: translateY(-2px);
  background: linear-gradient(150deg,
    #ffffff 0%,
    rgba(233, 238, 244, 0.96) 50%,
    rgba(200, 209, 221, 0.92) 100%);
  border-color: rgba($la-navy, 0.24);
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 1),
    0 3px 8px rgba($la-navy, 0.14);
}
#button_settings .md-bs-color__swatch.is-selected {
  border-color: $brand-verdigris;
  box-shadow: 0 0 0 2px rgba($brand-verdigris, 0.4);
}
#button_settings .md-bs-color__swatch-chip {
  width: 100%;
  height: 32px;
  border-radius: 6px;
  border-width: 2px;
  border-style: solid;
}
#button_settings .md-bs-color__swatch-name {
  font-size: 13px;
  font-weight: 600;
  color: $la-navy;
  line-height: 1.1;
}
#button_settings .md-bs-color__swatch-hint {
  font-size: 11px;
  color: $brand-slate-gray;
  text-transform: capitalize;
  line-height: 1.1;
}
#button_settings .md-bs-color__field-label--custom {
  margin-top: 22px;
}
#button_settings .md-bs-color__custom {
  display: flex;
  flex-direction: column;
  gap: 10px;
}
#button_settings .md-bs-color__custom-row {
  display: flex;
  align-items: center;
  gap: 12px;
}
#button_settings .md-bs-color__custom-label {
  flex: 0 0 56px;
  font-size: 14px;
  font-weight: 600;
  color: $brand-charcoal-dark;
}
#button_settings .md-bs-color__picker {
  flex: 0 0 auto;
  width: 46px;
  height: 40px;
  padding: 2px;
  border: 1px solid rgba($la-navy, 0.15);
  border-radius: 8px;
  background: #fff;
  cursor: pointer;
}
#button_settings .md-bs-color__value {
  flex: 1 1 auto;
  min-width: 0;
}
#button_settings .md-bs-color__footer {
  display: flex;
  justify-content: flex-end;
  margin-top: 22px;
}

/* Vertical preview card */
#button_settings .md-bs-choose__preview {
  flex: 0 0 auto;
  width: 230px;
  border: 1px solid rgba($la-navy, 0.12);
  border-radius: 14px;
  background: #fff;
  overflow: hidden;
  box-shadow: 0 1px 3px rgba($la-navy, 0.06);
}
#button_settings .md-bs-choose__thumb {
  padding: 16px;
  background: rgba($la-navy, 0.03);
  display: flex;
  align-items: center;
  justify-content: center;
}
#button_settings .md-bs-choose__thumb img {
  width: 100%;
  height: 130px;
  object-fit: contain;
  display: block;
}
#button_settings .md-bs-choose__preview-info {
  padding: 12px 14px 14px;
  border-top: 1px solid rgba($la-navy, 0.08);
  text-align: center;
}
#button_settings .md-bs-choose__preview-name {
  font-size: 15px;
  font-weight: 700;
  color: $la-navy;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
#button_settings .md-bs-choose__preview-owner {
  font-size: 13px;
  font-weight: 500;
  color: rgba($la-navy, 0.55);
  margin-top: 2px;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
#button_settings .md-bs-choose__preview-grid {
  font-size: 13px;
  color: $brand-slate-gray;
  margin: 2px 0 10px;
}
#button_settings .md-bs-choose__preview-btn {
  width: 100%;
  min-height: 40px;
  border-radius: 8px;
  /* Same brushed-silver glass as the "Use original board" button. */
  border: 1px solid rgba($la-navy, 0.16);
  background: linear-gradient(150deg,
    rgba(255, 255, 255, 0.95) 0%,
    rgba(236, 240, 245, 0.9) 50%,
    rgba(210, 217, 227, 0.85) 100%);
  color: $brand-dusty-denim-aa;
  font-weight: 600;
  font-size: 14px;
  backdrop-filter: blur(8px) saturate(150%);
  -webkit-backdrop-filter: blur(8px) saturate(150%);
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.9),
    inset 0 -1px 0 rgba($la-navy, 0.05),
    0 1px 3px rgba($la-navy, 0.08);
  transition: background 0.12s ease, box-shadow 0.12s ease, border-color 0.12s ease;
}
#button_settings .md-bs-choose__preview-btn:hover {
  background: linear-gradient(150deg,
    #ffffff 0%,
    rgba(233, 238, 244, 0.96) 50%,
    rgba(200, 209, 221, 0.92) 100%);
  border-color: rgba($la-navy, 0.24);
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 1),
    0 2px 8px rgba($la-navy, 0.14);
}

/* Decision content */
#button_settings .md-bs-choose__body {
  flex: 1 1 auto;
  min-width: 0;
  display: flex;
  flex-direction: column;
}
#button_settings .md-bs-choose__explain {
  font-size: 15px;
  color: $brand-charcoal-dark;
  margin: 0 0 16px;
}
#button_settings .md-bs-choose__note {
  font-size: 13px;
  color: $brand-slate-gray;
  margin: 0 0 16px;
}
#button_settings .md-bs-choose__actions {
  display: flex;
  flex-direction: column;
  gap: 10px;
}
#button_settings .md-bs-choose__actions .md-bs-or {
  margin: 2px 0;
}
#button_settings .md-bs-choose__btn {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: 2px;
  padding: 11px 16px;
  border-radius: 10px;
  border: 1px solid transparent;
  cursor: pointer;
  text-align: left;
  transition: background 0.12s ease, box-shadow 0.12s ease;
}
#button_settings .md-bs-choose__btn-label {
  font-size: 15px;
  font-weight: 700;
  line-height: 1.2;
}
#button_settings .md-bs-choose__btn-sub {
  font-size: 13px;
  font-weight: 400;
  line-height: 1.3;
  opacity: 0.9;
}
/* Recommended action: light verdigris→denim tint gradient with dark navy text.
   Navy (#1B365D) on this light gradient clears WCAG AA (>7:1); the sub uses
   charcoal (#374151, ~8:1). */
#button_settings .md-bs-choose__btn--primary {
  /* Silvery glass shine: a glossy top sheen over the verdigris→denim tint,
     with inset highlights + backdrop blur. The sheen only lightens the top, so
     the dark navy label keeps (and gains) contrast. */
  background:
    linear-gradient(180deg, rgba(255, 255, 255, 0.55) 0%, rgba(255, 255, 255, 0.14) 42%, rgba(255, 255, 255, 0) 62%),
    linear-gradient(135deg, rgba($brand-verdigris, 0.50), rgba($brand-dusty-denim, 0.52)),
    #fff;
  border: 1px solid rgba($la-navy, 0.18);
  color: $la-navy;
  backdrop-filter: blur(8px) saturate(155%);
  -webkit-backdrop-filter: blur(8px) saturate(155%);
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.85),
    inset 0 -1px 0 rgba($la-navy, 0.06),
    0 1px 3px rgba($la-navy, 0.08);
}
#button_settings .md-bs-choose__btn--primary:hover {
  background:
    linear-gradient(180deg, rgba(255, 255, 255, 0.6) 0%, rgba(255, 255, 255, 0.16) 42%, rgba(255, 255, 255, 0) 62%),
    linear-gradient(135deg, rgba($brand-verdigris, 0.58), rgba($brand-dusty-denim, 0.60)),
    #fff;
  border-color: rgba($la-navy, 0.26);
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 1),
    0 2px 10px rgba($la-navy, 0.14);
}
#button_settings .md-bs-choose__btn--primary .md-bs-choose__btn-sub {
  color: $brand-charcoal-dark;
  opacity: 1;
}
/* Secondary: brushed-silver glass — cool white→silver gradient with inset
   highlights + backdrop blur, navy label. */
#button_settings .md-bs-choose__btn--secondary {
  background: linear-gradient(150deg,
    rgba(255, 255, 255, 0.95) 0%,
    rgba(236, 240, 245, 0.9) 50%,
    rgba(210, 217, 227, 0.85) 100%);
  border-color: rgba($la-navy, 0.16);
  color: $la-navy;
  backdrop-filter: blur(8px) saturate(150%);
  -webkit-backdrop-filter: blur(8px) saturate(150%);
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.9),
    inset 0 -1px 0 rgba($la-navy, 0.05),
    0 1px 3px rgba($la-navy, 0.08);
}
#button_settings .md-bs-choose__btn--secondary:hover {
  background: linear-gradient(150deg,
    #ffffff 0%,
    rgba(233, 238, 244, 0.96) 50%,
    rgba(200, 209, 221, 0.92) 100%);
  border-color: rgba($la-navy, 0.24);
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 1),
    0 2px 8px rgba($la-navy, 0.14);
}
#button_settings .md-bs-choose__btn--secondary .md-bs-choose__btn-sub {
  color: $brand-slate-gray;
}

/* Status panel — the empty (no-board) state, styled as its own component.
   Recessed/inset look: sunken background + inner shadow so it reads as a
   "nothing here yet" well rather than a raised card. */
#button_settings .md-bs-status {
  padding: 12px 14px;
  border: 1px solid rgba($la-navy, 0.12);
  border-radius: 10px;
  background: $surface-200;
  box-shadow: inset 0 2px 4px rgba($la-navy, 0.10);
}
#button_settings .md-bs-status__row {
  display: flex;
  align-items: center;
  gap: 8px;
}
#button_settings .md-bs-status__dot {
  width: 10px;
  height: 10px;
  border-radius: 50%;
  background: #fff;
  border: 2px solid rgba($la-navy, 0.25);
  flex: 0 0 auto;
}
#button_settings .md-bs-status__text {
  font-size: 15px;
  font-weight: 600;
  color: $brand-charcoal-dark;
}
#button_settings .md-bs-status__hint {
  font-size: 13px;
  color: $brand-slate-gray;
  margin: 6px 0 0;
}

/* Method groups (search / browse / create) with tiny "or …" headers — the
   separators make the three alternative paths read as distinct choices. */
#button_settings .md-bs-group {
  margin-top: 16px;
}
#button_settings .md-bs-group-label {
  font-size: 13px;
  font-weight: 600;
  color: $brand-slate-gray;
  margin-bottom: 6px;
}
#button_settings .md-bs-dest__results:empty {
  display: none;
}

/* Search row: input is the dominant path, Search button beside it */
#button_settings .md-bs-dest__search-row {
  display: flex;
  gap: 10px;
  align-items: stretch;
}
#button_settings .md-bs-dest__search-field {
  flex: 1 1 auto;
  display: block;
}
#button_settings .md-bs-dest__search-input {
  width: 100%;
}
#button_settings .md-bs-dest__search-btn {
  flex: 0 0 auto;
  white-space: nowrap;
}
/* Card buttons (primary = verdigris, secondary = dusty-denim, outline = quiet) */
#button_settings .md-bs-btn {
  min-height: 50px;
  padding: 0 20px;
  border-radius: 10px;
  font-weight: 600;
  font-size: 15px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  border: 1px solid transparent;
  transition: background 0.12s ease, box-shadow 0.12s ease;
}
#button_settings .md-bs-btn--primary {
  background: linear-gradient(135deg, $brand-verdigris, $brand-dusty-denim);
  border: none;
  color: #fff;
}
#button_settings .md-bs-btn--primary:hover {
  box-shadow: 0 2px 10px rgba($brand-verdigris, 0.3);
}
#button_settings .md-bs-btn--secondary {
  background: rgba($brand-dusty-denim, 0.08);
  border-color: rgba($brand-dusty-denim, 0.30);
  color: $brand-dusty-denim-aa;
}
#button_settings .md-bs-btn--secondary:hover {
  background: rgba($brand-dusty-denim, 0.14);
}
/* Quiet secondary: white with a blue outline, so it reads as an alternative
   action rather than competing with the primary Search button. */
#button_settings .md-bs-btn--outline {
  background: #fff;
  border-color: rgba($brand-dusty-denim, 0.45);
  color: $brand-dusty-denim-aa;
}
#button_settings .md-bs-btn--outline:hover {
  background: rgba($brand-dusty-denim, 0.06);
  border-color: $brand-dusty-denim;
}
#button_settings .md-bs-btn--outline .glyphicon {
  color: $brand-dusty-denim-aa;
}
/* Wrapper card grouping the three destination methods (search / browse /
   create) so they read as one "choose a board" unit inside the card. */
#button_settings .md-bs-methods {
  margin-top: 12px;
  padding: 16px;
  border: 1px solid rgba($la-navy, 0.12);
  border-radius: 12px;
  /* Recessed/inset well so the white board-section cards sit proud of it. */
  background: $surface-200;
  box-shadow: inset 0 2px 5px rgba($la-navy, 0.10);
}
#button_settings .md-bs-methods > .md-bs-group:first-child {
  margin-top: 0;
}

/* Board-collection picker inside the destination card: reuses the Find Boards
   page's .md-board-collection markup/styles (light base theme outside a
   .md-board-detail--dark ancestor). Cap the height so the sectioned list scrolls
   inside the card instead of stretching the modal. */
#button_settings .md-bs-collection {
  margin-bottom: 4px;
}
#button_settings .md-bs-collection__header {
  padding: 0 0 10px;
}
#button_settings .md-bs-collection__body {
  max-height: 340px;
  overflow-y: auto;
}

/* "OR" separator between the three destination methods — mirrors the
   create-board-new chooser (.nb-create-chooser__or): centered uppercase OR
   with a short rule on each side. */
#button_settings .md-bs-or {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 12px;
  margin: 14px 4px;
  color: rgba($la-navy, 0.45);
  font-size: 12px;
  font-weight: 700;
  letter-spacing: 0.08em;
}
#button_settings .md-bs-or::before,
#button_settings .md-bs-or::after {
  content: "";
  flex: 1 1 auto;
  max-width: 90px;
  height: 1px;
  background: rgba($la-navy, 0.14);
}

/* Raised "choice" card — matches the create-board-new chooser buttons
   (.nb-create-chooser__btn): top-lit gradient, layered ambient shadow, and a
   glassy icon chip, so Create reads as a pressable key rather than a plain
   button. */
#button_settings .md-bs-choice {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 10px;
  width: 100%;
  min-height: 50px;
  padding: 0 16px;
  border-radius: 12px;
  border: 1px solid rgba($brand-slate-blue, 0.22);
  background: linear-gradient(180deg, #ffffff 0%, #eef2f8 100%);
  color: $la-navy;
  font-size: 16px;
  font-weight: 700;
  cursor: pointer;
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.95),
    inset 0 -2px 0 rgba($la-navy, 0.06),
    0 2px 4px rgba($la-navy, 0.08),
    0 10px 22px rgba($la-navy, 0.12);
  transition: transform 0.16s ease, box-shadow 0.16s ease, border-color 0.16s ease, background 0.16s ease;
}
#button_settings .md-bs-choice:hover,
#button_settings .md-bs-choice:focus-visible {
  transform: translateY(-3px);
  border-color: rgba($brand-slate-blue, 0.45);
  background: linear-gradient(180deg, #ffffff 0%, #e9eef6 100%);
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 1),
    inset 0 -2px 0 rgba($la-navy, 0.07),
    0 4px 8px rgba($la-navy, 0.12),
    0 18px 34px rgba($la-navy, 0.16);
  outline: none;
}
#button_settings .md-bs-choice:active {
  transform: translateY(-1px);
  box-shadow:
    inset 0 2px 5px rgba($la-navy, 0.14),
    0 2px 6px rgba($la-navy, 0.10);
}
#button_settings .md-bs-choice__icon {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex: 0 0 auto;
  width: 30px;
  height: 30px;
  border-radius: 8px;
  background: linear-gradient(180deg, rgba($brand-slate-blue, 0.16), rgba($brand-slate-blue, 0.07));
  color: $brand-slate-blue;
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.85),
    0 1px 2px rgba($la-navy, 0.12);
}
#button_settings .md-bs-choice__icon .glyphicon {
  color: $brand-slate-blue;
  top: 0;
}
#button_settings .md-bs-choice__label {
  flex: 0 0 auto;
}

/* Footer */
.modal-content:has(#button_settings) > .modal-footer {
  background:
    linear-gradient(135deg, rgba($brand-verdigris, 0.04), rgba($brand-dusty-denim, 0.04)),
    $surface-100;
  border-top: 1px solid rgba($la-navy, 0.08);
  padding: 14px 24px;
  display: flex;
  align-items: center;
  gap: 10px;
}
.modal-content:has(#button_settings) > .modal-footer .btn {
  border-radius: 10px;
  font-weight: 500;
  font-size: 15px;
  transition: background 0.12s ease, box-shadow 0.12s ease;
}
.modal-content:has(#button_settings) > .modal-footer .btn-lg {
  padding: 10px 22px;
  background: $brand-charcoal-blue;
  color: #fff;
  border: none;
  font-weight: 600;
}
.modal-content:has(#button_settings) > .modal-footer .btn-lg:hover {
  background: $brand-charcoal-blue;
  box-shadow: 0 2px 10px rgba($brand-charcoal-blue, 0.3);
}
/* Arrow nav buttons in footer */
.modal-content:has(#button_settings) > .modal-footer > span .btn {
  border-radius: 8px;
  border: 1px solid rgba($la-navy, 0.12);
  background: #fff;
  color: #4a5568;
}
.modal-content:has(#button_settings) > .modal-footer > span .btn:hover {
  background: $surface-200;
  color: $brand-verdigris;
}

/* Tab content spacing */
#button_settings .content .form-group {
  margin-bottom: 16px;
}

/* Image search area */
#button_settings .image_search,
#button_settings .sound_search {
  border-radius: 12px;
}

/* ── Picture tab — modern, spacious layout ──────────────────────────────────
   The picture content was legacy float/inline markup (cramped rows, tiny inline
   thumbnails). This adds breathing room and a professional modern feel: a larger
   rounded search field, modern icon buttons, a framed current-picture card, and a
   spaced grid of uniform rounded thumbnail cards with a hover lift. */
.md-bs-picture {
  padding: 2px 2px 14px;
  font-size: 14px;
  color: $brand-charcoal-dark;
}
.md-bs-picture .options {
  margin-top: 14px;
}
/* Search-term hint — quieter + centered. */
.md-bs-picture .text-muted {
  font-size: 13px;
  color: rgba($la-navy, 0.55);
  text-align: center;
  margin-top: 12px;
}
/* Search input — larger, rounded, modern focus ring. */
.md-bs-picture #find_picture {
  border-radius: 12px;
  border: 1px solid rgba($la-navy, 0.15);
  padding: 11px 16px;
  font-size: 15px;
  height: auto;
  box-shadow: none;
  transition: border-color 0.15s ease, box-shadow 0.15s ease;
}
.md-bs-picture #find_picture:focus {
  border-color: $brand-verdigris;
  box-shadow: 0 0 0 3px rgba($brand-verdigris, 0.12);
  outline: none;
}
/* Search / camera / upload / options buttons — modern rounded, consistent. */
.md-bs-picture .btn-default {
  border-radius: 10px;
  border: 1px solid rgba($la-navy, 0.15);
  background: #ffffff;
  font-weight: 500;
  transition: border-color 0.15s ease, box-shadow 0.15s ease;
}
.md-bs-picture .btn-default:hover {
  border-color: $brand-verdigris;
  box-shadow: 0 2px 8px rgba($la-navy, 0.10);
}
/* Current-picture card. */
.md-bs-picture .button_image {
  border: 1px solid rgba($la-navy, 0.12);
  border-radius: 16px;
  padding: 12px;
  box-shadow: 0 2px 12px rgba($la-navy, 0.08);
  background: #ffffff;
}
/* Results — a spaced grid of uniform rounded thumbnail cards with a hover lift. */
.md-bs-picture__results {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
  justify-content: center;
}
.md-bs-picture__result {
  width: 68px;
  height: 68px;
  padding: 5px;
  border: 1px solid rgba($la-navy, 0.12);
  border-radius: 12px;
  background: #ffffff;
  cursor: pointer;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  transition: transform 0.12s ease, box-shadow 0.15s ease, border-color 0.15s ease;
}
.md-bs-picture__result img {
  max-width: 100%;
  max-height: 100%;
  object-fit: contain;
}
.md-bs-picture__result:hover,
.md-bs-picture__result:focus-visible {
  transform: translateY(-2px);
  border-color: $brand-verdigris;
  box-shadow: 0 5px 14px rgba($la-navy, 0.16);
  outline: none;
}

/* Section header — navy eyebrow + subtitle, centered (matches the Action tab). */
.md-bs-picture__head {
  text-align: center;
  margin-bottom: 18px;
}
.md-bs-picture__head .md-bs-card__eyebrow {
  justify-content: center;
}
.md-bs-picture__subtitle {
  margin: 4px 0 0;
  font-size: 15px;
  color: rgba($la-navy, 0.62);
}
/* "Find a picture" card. */
.md-bs-picture__find {
  display: block;
  padding: 18px 20px 20px;
  margin-bottom: 22px;
}
.md-bs-picture__field-label {
  display: block;
  font-size: 12px;
  font-weight: 700;
  letter-spacing: 0.03em;
  text-transform: uppercase;
  color: rgba($la-navy, 0.55);
  margin: 14px 0 6px;
}
.md-bs-picture__find > .md-bs-card__eyebrow + .md-bs-picture__field-label {
  margin-top: 4px;
}
.md-bs-picture__library {
  max-width: 320px;
}
.md-bs-picture__library-static {
  font-size: 15px;
  font-weight: 600;
  color: $brand-charcoal-dark;
}
.md-bs-picture__premium-note {
  font-size: 12.5px;
  margin-top: 6px;
}
/* Search row — input grows, Search button fixed. */
.md-bs-picture__search-row {
  display: flex;
  align-items: stretch;
  gap: 8px;
  margin-top: 14px;
}
.md-bs-picture__search-row .picture_search_field {
  flex: 1 1 auto;
  min-width: 0;
  width: auto;
}
.md-bs-picture__search-btn {
  flex: 0 0 auto;
}
/* Progressive-disclosure "Search options". */
.md-bs-picture__disclosure {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  margin-top: 12px;
  padding: 4px 2px;
  background: none;
  border: none;
  font-size: 13.5px;
  font-weight: 600;
  color: $brand-verdigris-aa;
  cursor: pointer;
}
.md-bs-picture__disclosure-chevron {
  transition: transform 0.15s ease;
}
.md-bs-picture__disclosure.is-open .md-bs-picture__disclosure-chevron {
  transform: rotate(90deg);
}
.md-bs-picture__options-body {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 10px 16px;
  margin-top: 10px;
  padding: 12px 14px;
  border-radius: 12px;
  background: rgba($la-navy, 0.03);
}
.md-bs-picture__options-body .form-control {
  max-width: 240px;
}
.md-bs-picture__checkbox {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  font-size: 14px;
  font-weight: 500;
  margin: 0;
}
/* Own-image sources — labeled buttons (icon + text). */
.md-bs-picture__sources-label {
  margin-top: 18px;
}
.md-bs-picture__sources {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
}
.md-bs-picture__source-file {
  position: relative;
  display: inline-flex;
}
.md-bs-picture__source-btn {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 9px 16px;
  border-radius: 10px;
  border: 1px solid rgba($la-navy, 0.15);
  background: #ffffff;
  font-size: 14px;
  font-weight: 500;
  color: $brand-charcoal-dark;
  cursor: pointer;
  transition: border-color 0.15s ease, box-shadow 0.15s ease, transform 0.1s ease;
}
.md-bs-picture__source-btn:hover:not(:disabled),
.md-bs-picture__source-btn:focus-visible {
  border-color: $brand-verdigris;
  box-shadow: 0 2px 8px rgba($la-navy, 0.10);
  outline: none;
}
.md-bs-picture__source-btn:disabled {
  opacity: 0.5;
  cursor: not-allowed;
}
.md-bs-picture__source-icon {
  width: 20px;
  height: 20px;
  object-fit: contain;
  flex: 0 0 auto;
}
.md-bs-picture__source-icon--wordart {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  font-weight: 800;
  font-size: 16px;
  color: $brand-verdigris-aa;
}
/* Compact CURRENT PICTURE card — small thumbnail + label, horizontal. */
.md-bs-picture__current-eyebrow {
  margin: 6px 0 8px;
}
.md-bs-picture__current {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 18px;
  padding: 14px 18px;
  margin-bottom: 24px;
}
.md-bs-picture__current-thumb {
  flex: 0 0 auto;
  width: 130px;
  height: 130px;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 10px;
  border: 1px solid rgba($la-navy, 0.12);
  border-radius: 14px;
  background: #ffffff;
  box-shadow: 0 1px 4px rgba($la-navy, 0.08);
}
.md-bs-picture__current-thumb img {
  max-width: 100%;
  max-height: 100%;
  object-fit: contain;
}
.md-bs-picture__current-meta {
  min-width: 0;
}
.md-bs-picture__current-title {
  font-size: 16px;
  font-weight: 600;
  color: $brand-charcoal-dark;
}
.md-bs-picture__current-sub {
  font-size: 14px;
  color: rgba($la-navy, 0.55);
  margin-top: 3px;
}
/* SEARCH RESULTS — eyebrow + count, subtitle, glass surface around the grid. */
.md-bs-picture__results-eyebrow {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 10px;
  margin-top: 6px;
}
.md-bs-picture__results-count {
  font-size: 12px;
  font-weight: 600;
  letter-spacing: 0.02em;
  color: rgba($la-navy, 0.5);
  text-transform: none;
}
.md-bs-picture__results-sub {
  margin: 4px 0 12px;
  font-size: 14px;
  color: rgba($la-navy, 0.55);
}
.md-bs-picture__results-surface {
  padding: 16px;
  background: linear-gradient(135deg, rgba($brand-verdigris, 0.05), rgba($brand-dusty-denim, 0.05));
  border: 1px solid rgba($la-navy, 0.07);
  border-radius: 16px;
}
.md-bs-picture__results-surface .md-bs-picture__results {
  margin: 0;
  justify-content: flex-start;
}
/* Search section — groups the "Search" header + the search options (skin / safe
   search filters) + the results into one block, set off from the "Hide label"
   row and webcam above it. The inner results surface keeps its own card. */
.md-bs-picture__search-section {
  margin-top: 20px;
}
/* Per-button picture/label options under the Find a Picture card
   (hide_label + text_only / stretch_text_only). */
.md-bs-picture__label-options {
  display: flex;
  flex-direction: column;
  gap: 8px;
  margin: 0 0 22px;
}
.md-bs-picture__hide-label,
.md-bs-picture__text-only {
  display: flex;
  align-items: center;
  gap: 9px;
  margin: 0;
  padding: 12px 16px;
  border-radius: 12px;
  background: rgba($la-navy, 0.03);
  font-size: 14px;
  font-weight: 500;
  color: $brand-charcoal-dark;
  cursor: pointer;
}
.md-bs-picture__hide-label input[type="checkbox"],
.md-bs-picture__text-only input[type="checkbox"] {
  width: 18px;
  height: 18px;
  flex: 0 0 auto;
  cursor: pointer;
}

/* Close button — fixed top-right corner of the modal */
.modal-content:has(#button_settings) > .modal-header {
  position: relative;
}
.modal-content:has(#button_settings) > .modal-header .close {
  position: absolute;
  top: 14px;
  right: 16px;
  z-index: 2;
}

/* Dropdowns (select elements via bound-select) */
#button_settings select.form-control {
  appearance: none;
  -webkit-appearance: none;
  -moz-appearance: none;
  border-radius: 10px;
  border: 1px solid rgba($la-navy, 0.15);
  padding: 6px 32px 6px 12px;
  font-size: 14px;
  font-weight: 500;
  color: $brand-charcoal-dark;
  background: #fff url("data:image/svg+xml,%3Csvg width='12' height='8' viewBox='0 0 12 8' fill='none' xmlns='http://www.w3.org/2000/svg'%3E%3Cpath d='M1 1.5L6 6.5L11 1.5' stroke='%236b7280' stroke-width='2' stroke-linecap='round' stroke-linejoin='round'/%3E%3C/svg%3E") no-repeat right 10px center;
  background-size: 12px 8px;
  cursor: pointer;
  transition: border-color 0.15s ease, box-shadow 0.15s ease;
  line-height: 1.4;
  height: auto;
}
#button_settings select.form-control:focus-visible {
  border-color: $brand-verdigris;
  box-shadow: 0 0 0 3px rgba($brand-verdigris, 0.12);
  outline: none;
}
#button_settings select.form-control:hover {
  border-color: rgba($la-navy, 0.25);
}
#button_settings select.form-control option {
  padding: 6px 12px;
  font-size: 14px;
  color: $brand-charcoal-dark;
  background: #fff;
}
#button_settings select.form-control option:checked {
  background: linear-gradient(135deg, rgba($brand-verdigris, 0.12), rgba($brand-dusty-denim, 0.08));
  color: $la-navy;
  font-weight: 600;
}
/* Short dropdowns (image library, skin, etc.) */
#button_settings select.form-control.skip_select {
  padding: 4px 28px 4px 10px;
  font-size: 14px;
}

/* Responsive: stack sidebar on small screens */
@media (max-width: 768px) {
  .modal-dialog:has(#button_settings) {
    width: auto;
    margin: 10px;
  }
  #button_settings .nav-pills.nav-stacked {
    display: flex;
    flex-wrap: wrap;
    gap: 4px;
    padding: 6px;
  }
  #button_settings .nav-pills.nav-stacked > li > a {
    padding: 8px 12px;
    font-size: 14px;
  }
}

/* ── Modern board-details modal restyle ───────────────── */

.modal-dialog:has(.la-board-details-wrap) {
  width: 680px;
  max-width: 94vw;
}
.la-board-details-wrap {
  color: $brand-charcoal-dark;
}

.la-board-details-wrap > .modal-header {
  background:
    linear-gradient(135deg, rgba($brand-verdigris, 0.08), rgba($brand-dusty-denim, 0.08), rgba(123, 107, 173, 0.05)),
    $surface-100;
  border-bottom: 1px solid rgba($la-navy, 0.08);
  padding: 18px 24px;
  padding-right: 56px;
  position: relative;
}
.la-board-details-wrap > .modal-header h3 {
  margin: 0;
  font-size: 20px;
  font-weight: 700;
  color: $la-navy;
  letter-spacing: -0.3px;
}
.la-board-details-wrap > .modal-header .close {
  position: absolute;
  top: 14px;
  right: 16px;
  width: 34px;
  height: 34px;
  border-radius: 50%;
  border: 1px solid rgba($la-navy, 0.12);
  background: rgba(255, 255, 255, 0.7);
  color: $brand-slate-gray;
  font-size: 20px;
  line-height: 1;
  display: flex;
  align-items: center;
  justify-content: center;
  opacity: 1;
  transition: background 0.15s ease, color 0.15s ease;
  float: none;
  margin: 0;
  padding: 0;
}
.la-board-details-wrap > .modal-header .close:hover {
  background: #fff;
  color: $brand-charcoal-dark;
}

.la-board-details-wrap > .modal-body {
  padding: 8px 24px 24px;
  max-height: 70vh;
  overflow-y: auto;
  overflow-x: hidden;
  max-width: 100%;
  box-sizing: border-box;
  /* Force left-alignment everywhere inside the modal body — overrides
     any inherited `text-align: center` that Bootstrap or legacy
     stylesheets apply at the .modal / .modal-content level. */
  text-align: left;
}
.la-board-details-wrap .modal-body * {
  text-align: inherit;
}

/* Sections — compact card-like clusters. Quiet hairlines between
   them rather than heavy borders so the eye flows down the panel
   without speed-bumps. Modeled on the Linear / GitHub "About"
   sidebar pattern: left-aligned eyebrow heading, tight rows of
   property labels + values below. */
.la-board-details-section {
  padding: 16px 0 18px;
  border-bottom: 1px solid rgba($la-navy, 0.06);
  max-width: 100%;
  min-width: 0;
}
.la-board-details-section:first-of-type {
  padding-top: 4px;
}
.la-board-details-section:last-child {
  border-bottom: none;
}
.la-board-details-section__heading {
  font-size: 11px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.10em;
  color: $brand-verdigris-aa;
  margin: 0 0 10px 0;
  /* Left-aligned eyebrow — replaces the centered "OVERVIEW /
     LANGUAGE / VISIBILITY & LICENSE" headings that floated in the
     middle of the modal and broke the visual rhythm. */
  text-align: left;
}

/* Definition list grid — proper two-column layout with values
   left-aligned at a consistent left edge. Bootstrap's legacy
   `dl-horizontal` (right-aligned dt + floated dd) is replaced
   with a CSS grid; explicit text-align: left on dt and dd fights
   off any global centering. */
.la-board-details-wrap .dl-horizontal {
  display: grid;
  grid-template-columns: 150px minmax(0, 1fr);
  column-gap: 20px;
  row-gap: 0;
  margin: 0;
  max-width: 100%;
}
.la-board-details-wrap .dl-horizontal dt {
  font-size: 13px;
  font-weight: 500;
  color: rgba($la-navy, 0.55);
  padding: 8px 0;
  text-align: left !important;
  margin: 0;
  white-space: normal;
  width: auto;
  float: none;
  min-width: 0;
  line-height: 1.4;
  /* Subtle hairline between rows for scanability — Linear /
     Stripe Dashboard style. Skips the very last row in each
     section via :has() below. */
  border-top: 1px solid rgba($la-navy, 0.05);
}
.la-board-details-wrap .dl-horizontal dt:first-of-type,
.la-board-details-wrap .dl-horizontal dt:first-of-type + dd {
  border-top: none;
}
.la-board-details-wrap .dl-horizontal dd {
  font-size: 14px;
  font-weight: 500;
  color: $la-navy;
  padding: 8px 0;
  margin: 0;
  margin-left: 0;
  text-align: left !important;
  overflow-wrap: anywhere;
  word-break: break-word;
  min-width: 0;
  line-height: 1.55;
  border-top: 1px solid rgba($la-navy, 0.05);
}

/* Description block — full-width prominent content under the dl,
   not center-aligned, no decorative left border. Just clean body
   typography with preserved line breaks for the prose. */
.la-board-details-wrap .la-board-details__description {
  white-space: pre-line;
  font-size: 14px;
  color: $la-navy;
  line-height: 1.6;
  padding: 0;
  margin: 0;
  text-align: left !important;
}
/* When the description sits in the dd column, give it the same
   row treatment as siblings but allow its content to scroll
   internally if it's exceptionally long. */
.la-board-details-wrap .dl-horizontal dd .la-board-details__description,
.la-board-details-wrap .dl-horizontal dd.la-board-details__description {
  max-height: none;
}

/* Overview head — name + description block sitting prominently
   above the property grid. Replaces the previous "Name" / "Description"
   rows in the dl so the descriptive content reads like a card
   header rather than two more entries in a metadata table. */
.la-board-details-overview-head {
  margin: 4px 0 14px;
  padding: 0;
}
.la-board-details-overview-head__name {
  font-size: 18px;
  font-weight: 700;
  color: $la-navy;
  margin: 0 0 8px 0;
  line-height: 1.3;
  letter-spacing: -0.01em;
  display: flex;
  align-items: center;
  gap: 8px;
  flex-wrap: wrap;
}

/* Stat tiles — replaces the dl rows for "Stats & Connections" so
   numeric metadata reads as glanceable cards rather than a list
   of small text values. Pattern mirrors GitHub's "Insights"
   tiles + Linear's project metrics row. */
.la-board-details-stats {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(140px, 1fr));
  gap: 10px;
  margin: 4px 0 0;
}
.la-board-details-stat {
  padding: 12px 14px;
  border: 1px solid rgba($la-navy, 0.08);
  border-radius: 10px;
  background: rgba($la-navy, 0.02);
  display: flex;
  flex-direction: column;
  gap: 4px;
  min-width: 0;
}
.la-board-details-stat__value {
  font-size: 22px;
  font-weight: 700;
  color: $la-navy;
  line-height: 1.1;
  letter-spacing: -0.01em;
}
.la-board-details-stat__label {
  font-size: 11px;
  font-weight: 600;
  color: rgba($la-navy, 0.55);
  text-transform: uppercase;
  letter-spacing: 0.06em;
}
.la-board-details-stat__link {
  font-size: 12px;
  font-weight: 500;
  margin-top: 2px;
}
.la-board-details-stat__link a {
  color: $brand-verdigris-aa;
  text-decoration: none;
}
.la-board-details-stat__link a:hover {
  text-decoration: underline;
}

@media (max-width: 540px) {
  .la-board-details-wrap .dl-horizontal {
    grid-template-columns: 1fr;
  }
  .la-board-details-wrap .dl-horizontal dt {
    padding: 10px 0 0;
    font-size: 11px;
    text-transform: uppercase;
    letter-spacing: 0.06em;
    color: rgba($la-navy, 0.50);
    border-top: 1px solid rgba($la-navy, 0.06);
  }
  .la-board-details-wrap .dl-horizontal dt:first-of-type {
    border-top: none;
  }
  .la-board-details-wrap .dl-horizontal dd {
    padding: 2px 0 12px;
    border-top: none;
  }
}
.la-board-details-wrap .dl-horizontal a {
  /* WCAG AA fix — was $brand-verdigris on $surface-100 = 3.15:1. */
  color: $brand-verdigris-aa;
  text-decoration: none;
  font-weight: 500;
}
.la-board-details-wrap .dl-horizontal a:hover {
  color: #146462;
  text-decoration: underline;
}

/* Actions section */
.la-board-details-section--actions {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}
.la-board-details-wrap .btn-default {
  border-radius: 24px;
  border: 1px solid rgba($la-navy, 0.12);
  background: #fff;
  color: $brand-charcoal-dark;
  font-weight: 500;
  font-size: 14px;
  padding: 9px 20px;
  transition: background 0.15s ease, box-shadow 0.15s ease, transform 0.1s ease;
}
.la-board-details-wrap .btn-default:hover {
  background: $surface-200;
  box-shadow: 0 2px 8px rgba($la-navy, 0.10);
  transform: translateY(-1px);
}
.la-board-details-wrap .dl-horizontal a.la-board-details-rename-link {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  margin-left: 6px;
  color: $brand-charcoal-blue !important;
  opacity: 1;
  transition: color 0.15s ease;
  vertical-align: middle;
  font-weight: normal;
}
.la-board-details-rename-link svg {
  stroke-width: 2.5;
}
.la-board-details-wrap .dl-horizontal a.la-board-details-rename-link:hover {
  /* WCAG AA fix — hover was $brand-verdigris (3.15:1 on light bg). */
  color: $brand-verdigris-aa !important;
}
.la-board-details-delete-btn {
  color: $brand-danger !important;
  border-color: rgba($brand-danger, 0.2) !important;
}
.la-board-details-delete-btn:hover {
  background: rgba($brand-danger, 0.06) !important;
  color: #a93226 !important;
}

/* Edit Board Details button (top-right of modal body) */
.la-board-details-edit-btn-wrap,
.md-board-details-edit-btn-wrap {
  display: flex;
  justify-content: flex-end;
  margin-bottom: 4px;
}
.la-board-details-edit-btn,
.md-board-details-edit-btn {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 7px 14px;
  border-radius: 8px;
  border: 1px solid rgba($brand-verdigris, 0.25);
  background: rgba($brand-verdigris, 0.06);
  color: $brand-verdigris-aa; /* WCAG AA fix — was $brand-verdigris (3.32:1). */
  font-size: 14px;
  font-weight: 600;
  cursor: pointer;
  transition: background 0.12s ease, border-color 0.12s ease;
}
.la-board-details-edit-btn:hover,
.md-board-details-edit-btn:hover {
  background: rgba($brand-verdigris, 0.12);
  border-color: rgba($brand-verdigris, 0.4);
}
.la-board-details-edit-btn svg,
.md-board-details-edit-btn svg {
  flex-shrink: 0;
}

/* Footer */
.la-board-details-wrap > .modal-footer {
  background:
    linear-gradient(135deg, rgba($brand-verdigris, 0.04), rgba($brand-dusty-denim, 0.04)),
    $surface-100;
  border-top: 1px solid rgba($la-navy, 0.08);
  padding: 14px 24px;
}
.la-board-details-wrap > .modal-footer .btn-lg {
  border-radius: 10px;
  padding: 10px 22px;
  background: $brand-charcoal-blue;
  color: #fff;
  border: none;
  font-weight: 600;
  font-size: 15px;
  transition: background 0.12s ease, box-shadow 0.12s ease;
}
.la-board-details-wrap > .modal-footer .btn-lg:hover {
  background: $brand-charcoal-blue;
  box-shadow: 0 2px 10px rgba($brand-charcoal-blue, 0.3);
}

@media (max-width: 640px) {
  .la-board-details-wrap .dl-horizontal {
    grid-template-columns: 1fr;
  }
  .la-board-details-wrap .dl-horizontal dt {
    text-align: left;
    padding-bottom: 2px;
    border-bottom: none;
  }
  .la-board-details-wrap .dl-horizontal dd {
    padding-top: 0;
    padding-bottom: 12px;
  }
}

/* ── Modern board-actions modal restyle ───────────────── */

