.la-board-actions-wrap > .modal-header .close:hover {
  background: #fff;
  color: $brand-charcoal-dark;
}
.la-board-actions-wrap > .modal-body {
  padding: 12px 24px 24px;
  max-height: 70vh;
  overflow-y: auto;
}

/* Permission notice */
.la-board-actions-notice {
  display: flex;
  align-items: flex-start;
  gap: 10px;
  padding: 12px 16px;
  border-radius: 10px;
  background: rgba($brand-dusty-denim, 0.06);
  border: 1px solid rgba($brand-dusty-denim, 0.15);
  margin-bottom: 16px;
  font-size: 14px;
  line-height: 1.5;
  color: $brand-charcoal-dark;
}
.la-board-actions-notice svg {
  flex-shrink: 0;
  margin-top: 2px;
  color: $brand-dusty-denim;
}

/* Action items list */
.la-board-actions-list {
  display: flex;
  flex-direction: column;
  gap: 2px;
}
.la-board-actions-item {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 14px;
  width: 100%;
  padding: 14px 16px;
  border-radius: 12px;
  border: 1px solid transparent;
  background: transparent;
  cursor: pointer;
  text-align: left;
  transition: background 0.12s ease, border-color 0.12s ease;
}
.la-board-actions-item:hover {
  background: rgba($brand-verdigris, 0.05);
  border-color: rgba($brand-verdigris, 0.15);
}
.la-board-actions-item:active {
  background: rgba($brand-verdigris, 0.10);
}
.la-board-actions-item[disabled] {
  opacity: 0.45;
  cursor: not-allowed;
}
.la-board-actions-item[disabled]:hover {
  background: transparent;
  border-color: transparent;
}

/* Icon circle */
.la-board-actions-item__icon {
  flex-shrink: 0;
  width: 40px;
  height: 40px;
  border-radius: 10px;
  background: rgba($brand-verdigris, 0.08);
  display: flex;
  align-items: center;
  justify-content: center;
  color: $brand-verdigris;
  transition: background 0.12s ease;
}
.la-board-actions-item:hover .la-board-actions-item__icon {
  background: rgba($brand-verdigris, 0.14);
}
/* View Style — a STATIC (non-interactive) board-actions item: no hover/cursor and
   a top-aligned icon (it has multi-line content + the segmented toggle). The
   toggle's own buttons stay interactive; the panel itself isn't clickable. */
.la-board-actions-item--static {
  cursor: default;
  align-items: flex-start;
}
.la-board-actions-item--static:hover {
  background: transparent;
  border-color: transparent;
}
.la-board-actions-item--static:hover .la-board-actions-item__icon {
  background: rgba($brand-verdigris, 0.08);
}
/* Breathing room between the explainer text and the moved View Style toggle. */
.la-board-actions-view-style__toggle {
  margin-top: 10px;
}

/* Content */
.la-board-actions-item__content {
  flex: 1;
  min-width: 0;
}
.la-board-actions-item__label {
  display: block;
  font-size: 15px;
  font-weight: 600;
  color: $la-navy;
  line-height: 1.3;
}
.la-board-actions-item__desc {
  display: block;
  font-size: 14px;
  color: $brand-slate-gray;
  line-height: 1.4;
  margin-top: 2px;
}

/* Chevron arrow */
.la-board-actions-item__arrow {
  flex-shrink: 0;
  /* WCAG AA fix — was $brand-cool-steel (2.84:1). */
  color: $brand-slate-gray;
  transition: color 0.12s ease, transform 0.12s ease;
}
.la-board-actions-item:hover .la-board-actions-item__arrow {
  /* WCAG AA fix — was $brand-verdigris (3.32:1). */
  color: $brand-verdigris-aa;
  transform: translateX(2px);
}

/* Danger variant (delete) */
.la-board-actions-item--danger .la-board-actions-item__icon {
  background: rgba($brand-danger, 0.08);
  color: $brand-danger;
}
.la-board-actions-item--danger:hover {
  background: rgba($brand-danger, 0.04);
  border-color: rgba($brand-danger, 0.15);
}
.la-board-actions-item--danger:hover .la-board-actions-item__icon {
  background: rgba($brand-danger, 0.12);
}
.la-board-actions-item--danger .la-board-actions-item__label {
  color: $brand-danger;
}
.la-board-actions-item--danger:hover .la-board-actions-item__arrow {
  color: $brand-danger;
}

/* Footer */
.la-board-actions-wrap > .modal-footer {
  background:
    linear-gradient(135deg, rgba($brand-verdigris, 0.04), rgba($brand-dusty-denim, 0.04)),
    $surface-100;
  border-top: 1px solid rgba($la-navy, 0.08);
  padding: 14px 24px;
}
.la-board-actions-wrap > .modal-footer .btn-lg {
  border-radius: 10px;
  padding: 10px 22px;
  background: $brand-charcoal-blue;
  color: #fff;
  border: none;
  font-weight: 600;
  font-size: 15px;
  transition: background 0.12s ease, box-shadow 0.12s ease;
}
.la-board-actions-wrap > .modal-footer .btn-lg:hover {
  background: $brand-charcoal-blue;
  box-shadow: 0 2px 10px rgba($brand-charcoal-blue, 0.3);
}

@media (max-width: 640px) {
  .la-board-actions-item {
    padding: 12px 12px;
    gap: 10px;
  }
  .la-board-actions-item__icon {
    width: 36px;
    height: 36px;
    border-radius: 8px;
  }
  .la-board-actions-item__icon svg {
    width: 18px;
    height: 18px;
  }
  .la-board-actions-item__desc {
    display: none;
  }
}

