/* ── Modern board-privacy modal restyle ──────────────── */

.modal-dialog:has(.la-board-privacy-wrap) { width:620px; max-width:94vw; }
.la-board-privacy-wrap { color:$brand-charcoal-dark; }
.la-board-privacy-wrap > .modal-header {
  background: linear-gradient(135deg, rgba($brand-verdigris, 0.08), rgba($brand-dusty-denim, 0.08), rgba(123,107,173,0.05)), $surface-100;
  border-bottom:1px solid rgba($la-navy, 0.08); padding:18px 24px; padding-right:56px; position:relative;
}
.la-board-privacy-wrap > .modal-header h3 { margin:0; font-size:20px; font-weight:700; color:$la-navy; letter-spacing:-0.3px; }
.la-board-privacy-wrap > .modal-header .close {
  position:absolute; top:14px; right:16px; width:34px; height:34px; border-radius:50%;
  border:1px solid rgba($la-navy, 0.12); background:rgba(255,255,255,0.7); color:$brand-slate-gray;
  font-size:20px; line-height:1; display:flex; align-items:center; justify-content:center;
  opacity:1; transition:background 0.15s ease, color 0.15s ease; float:none; margin:0; padding:0;
}
.la-board-privacy-wrap > .modal-header .close:hover { background:#fff; color:$brand-charcoal-dark; }
.la-board-privacy-wrap > .modal-body { padding:24px; }
.la-board-privacy-desc { font-size:15px; color:$brand-charcoal-dark; margin-bottom:20px; line-height:1.5; }
.la-board-privacy-section { margin-bottom:18px; }
.la-board-privacy-section:last-child { margin-bottom:0; }
.la-board-privacy-label {
  display:block; font-size:14px; font-weight:700; text-transform:uppercase;
  letter-spacing:0.06em; color:$brand-verdigris-aa; margin-bottom:8px; /* WCAG AA fix. */
}
.la-board-privacy-boards {
  padding:12px 16px; background:rgba($brand-verdigris, 0.03); border:1px solid rgba($la-navy, 0.06);
  border-radius:12px;
  /* Removed `max-height: 240px; overflow-y: auto` — instead the
     modal-body below caps height with its own scroll, so expanding
     the hierarchy grows the modal up to viewport height before any
     scrollbar appears. */
}
/* Body grows with the boards hierarchy / privacy dropdown content —
   no fixed max-height. Modal stretches naturally up to viewport.
   Browser-level page scrolling kicks in if the dialog ever exceeds
   viewport height, which is the desired fall-back behavior. */
.la-board-privacy-wrap > .modal-body {
  max-height: none;
  overflow: visible;
}
/* Privacy dropdown's option list is `position: absolute` by default
   (so it floats over surrounding content and doesn't push siblings).
   Inside this modal we want the opposite — the list should occupy
   flow space below the trigger so the modal-body's height grows to
   contain it. position:static + auto offsets returns the list to
   normal flow; the list's existing styling (rounded card, shadow,
   max-height with internal scroll) is preserved. */
.la-board-privacy-wrap .bound-select__list {
  position: static;
  top: auto;
  left: auto;
  right: auto;
  margin-top: 6px;
}
/* Modern action links inside the board hierarchy (Select All | Expand
   All | Collapse All). Default browser link styling reads dated; pill
   chrome with verdigris accent matches the rest of the modal. */
.la-board-privacy-boards .board_hierarchy_actions,
.la-board-privacy-boards > div > a {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  padding: 4px 10px;
  margin: 0 2px 8px;
  font-size: 13px;
  font-weight: 600;
  color: $brand-verdigris-aa;
  background: rgba($brand-verdigris, 0.08);
  border: 1px solid rgba($brand-verdigris, 0.18);
  border-radius: 999px;
  text-decoration: none;
  transition: background 0.12s ease, color 0.12s ease, border-color 0.12s ease;
}
.la-board-privacy-boards > div > a:hover,
.la-board-privacy-boards > div > a:focus-visible {
  background: rgba($brand-verdigris, 0.16);
  color: $la-navy;
  border-color: rgba($brand-verdigris, 0.4);
  text-decoration: none;
  outline: none;
}
/* Modern custom checkboxes inside the boards hierarchy — replaces the
   default browser appearance with a 18px rounded square that fills with
   verdigris when checked. Matches the `.md-edit-profile__form` pattern
   used elsewhere in the modern modal restyles. */
.la-board-privacy-boards input[type="checkbox"] {
  -webkit-appearance: none;
  -moz-appearance: none;
  appearance: none;
  position: relative;
  display: inline-block;
  width: 18px;
  height: 18px;
  margin: 0 6px 0 0;
  vertical-align: middle;
  border: 1.5px solid rgba($la-navy, 0.30);
  border-radius: 4px;
  background: #fff;
  cursor: pointer;
  flex-shrink: 0;
  transition: border-color 0.15s ease, background 0.15s ease;
}
.la-board-privacy-boards input[type="checkbox"]:hover {
  border-color: rgba($brand-verdigris, 0.55);
}
.la-board-privacy-boards input[type="checkbox"]:checked {
  background: $brand-verdigris;
  border-color: $brand-verdigris;
}
.la-board-privacy-boards input[type="checkbox"]:checked::after {
  content: '';
  position: absolute;
  top: 2px;
  left: 5px;
  width: 5px;
  height: 9px;
  border-right: 2px solid #fff;
  border-bottom: 2px solid #fff;
  transform: rotate(45deg);
}
.la-board-privacy-boards input[type="checkbox"]:focus-visible {
  outline: 2px solid rgba($brand-verdigris, 0.5);
  outline-offset: 1px;
}
.la-board-privacy-boards input[type="checkbox"]:disabled {
  opacity: 0.4;
  cursor: not-allowed;
}
/* Tighter list rhythm for the recursive board hierarchy items. */
.la-board-privacy-boards .board_hierarchy ul {
  list-style: none;
  /* Indent comes from each node's content (depth padding), not the list, so
     the checkboxes line up in one column here too. */
  padding-left: 0;
