/* Speak Mode PIN entry modal — modern modal styling (matches pin-settings /
   md-modal-* shells). Keypad keeps id="pin" + .advanced_selection for
   eye-gaze/scanning; the look is modernized here. */
.speak-mode-pin__body {
  text-align: center;
}
.speak-mode-pin-entry {
  display: flex;
  align-items: stretch;
  gap: 12px;
  width: 100%;
  max-width: 360px;
  margin: 0 auto 16px;
}
.speak-mode-pin-entry__input {
  flex: 1 1 auto;
  min-width: 0;
  font-size: 38px;
  height: 56px;
  text-align: center;
  letter-spacing: 0.18em;
  line-height: 1;
  padding: 0 12px;
  margin-bottom: 0;
  border: 1px solid var(--md-line);
  border-radius: 12px;
  background: #fafbfc;
  color: $la-navy;
}
.speak-mode-pin-entry__submit {
  flex: 0 0 auto;
  align-self: stretch;
  min-height: 56px;
  justify-content: center;
  white-space: nowrap;
}
.speak-mode-pin-entry__error {
  color: #c0392b;
  font-size: 1rem;
  margin: 0 auto 12px;
  max-width: 360px;
}
table#pin {
  table-layout: fixed;
  width: 100%;
  max-width: 360px;
  margin: 0 auto;
  /* gap-style spacing between keys instead of a hard table grid */
  border-collapse: separate;
  border-spacing: 8px;
}
table#pin td {
  width: 33.33%;
  border: none;
  padding: 0;
}
table#pin td a,
table#pin td button.pin-key {
  display: flex;
  align-items: center;
  justify-content: center;
  height: 64px;
  width: 100%;
  cursor: pointer;
  color: $la-navy;
  font-size: 28px;
  font-weight: 600;
  padding: 0;
  border: 1px solid var(--md-line);
  border-radius: 14px;
  background: #fff;
  transition: background 0.12s ease, box-shadow 0.12s ease, transform 0.06s ease;
}
table#pin td button.pin-key:hover {
  background: rgba($brand-charcoal-blue, 0.06);
  box-shadow: 0 2px 8px rgba($la-navy, 0.10);
}
table#pin td button.pin-key:active {
  transform: scale(0.96);
  background: rgba($brand-charcoal-blue, 0.10);
}
table#pin td button.pin-key:focus-visible {
  outline: 2px solid $brand-charcoal-blue;
  outline-offset: 2px;
}
table#pin td a.pin-key__icon,
table#pin td button.pin-key__icon {
  color: $brand-charcoal-blue;
}
table#pin td a.pin-key__icon svg,
table#pin td button.pin-key__icon svg {
  display: block;
}
/* Modern text-link styling for the "Reveal PIN" footer action */
.speak-mode-pin__reveal-link {
  background: none;
  border: none;
  padding: 0;
  color: $brand-charcoal-blue;
  font-weight: 600;
  font-size: 14px;
  text-decoration: none;
  cursor: pointer;
}
.speak-mode-pin__reveal-link:hover {
  text-decoration: underline;
  color: #3a4350;
}
.speak-mode-pin__revealed {
  font-weight: 600;
