.subscription_table {
  border-collapse: separate;
  border-spacing: 0;
  max-width: 720px;
  width: 100%;
  background: #fff;
  border-radius: 20px;
  overflow: hidden;
  box-shadow: 0 8px 24px rgba($indigo, 0.10), 0 0 0 1px rgba($indigo, 0.04);

  .glyphicon {
    font-size: 20px;
  }

  th {
    padding: 8px 12px;
  }

  /* ── Base cell styles ── */
  td {
    padding: 16px 20px;
    border-bottom: 1px solid $color-linen;
    text-align: center;
    font-size: 15px;
    line-height: 1.5;
    color: $indigo;
    transition: background 0.12s ease;
    vertical-align: middle;

    .sale {
      background: linear-gradient(135deg, #d4edda 0%, #c3e6cb 100%);
      position: absolute;
      top: 0;
      width: 100%;
      margin-left: -20px;
      border-bottom: 1px solid $color-linen;
      color: $indigo;
      font-size: 14px;
      font-weight: 600;
      padding: 6px 0;
      letter-spacing: 0.06em;
      text-transform: uppercase;
    }
  }

  /* ── Column dividers ── */
  /* Supporter column: strong left border */
  td.separator {
    border-left: 2px solid #c5bfb3;
  }
  /* Eval column: left border to separate from Supporter */
  td:last-child {
    border-left: 2px solid #c5bfb3;
  }
  /* Don't double-border when separator IS the last child */
  td.separator:last-child {
    border-left: 2px solid #c5bfb3;
  }

  td.dim {
    background: $color-warm-white;
    div.middle {
      background: $color-warm-white;
    }
  }

  /* ── "- or -" divider badge ── */
  div.middle {
    background: #fff;
    position: absolute;
    right: -25px;
    width: 50px;
    height: 36px;
    padding-top: 6px;
    z-index: 2;
    top: 50px;
    font-size: 18px;
    color: $brand-slate-gray;
    font-weight: 500;
  }

  /* ── Currency & lifetime labels ── */
  .subscription-currency-us {
    color: var(--fs-dark-teal, $brand-verdigris);
    font-size: 14px;
    font-weight: 600;
    letter-spacing: 0.06em;
  }

  .subscription-table__lifetime-purchase {
    color: var(--fs-navy, $la-navy);
    font-weight: 600;
  }

  /* ── Cloud extras links ── */
  td a[href*='blog.mylingolinq.com'] {
    color: var(--fs-dark-teal, $brand-verdigris);
    text-decoration: none;
    font-weight: 500;
    border-bottom: 1px solid transparent;
    transition: border-color 0.12s ease;
  }
  td a[href*='blog.mylingolinq.com']:hover {
    color: var(--fs-dark-teal, $brand-verdigris);
    border-bottom-color: var(--fs-dark-teal, $brand-verdigris);
  }

  td.subscription-table__cloud-extras-right a[href*='blog.mylingolinq.com'] {
    color: var(--fs-dark-teal, $brand-verdigris);
    text-decoration: none;
    border-bottom: 1px solid transparent;
  }
  td.subscription-table__cloud-extras-right a[href*='blog.mylingolinq.com']:hover {
    border-bottom-color: var(--fs-dark-teal, $brand-verdigris);
  }

  .btn-primary .subscription-currency-us {
    color: rgba(255, 255, 255, 0.85);
  }

  /* ── Default row hover ── */
  tr:hover {
    td {
      background: rgba(58, 107, 199, 0.03);
    }
    div.middle {
      background: rgba(58, 107, 199, 0.03);
    }
  }

  /* ── Header row ── */
  tbody tr:first-child td {
    padding: 20px;
    border-bottom: 2px solid $color-linen;
  }
  /* Pin header cells to their default bg on hover — no hover effect */
  tbody tr:first-child:hover td.subscription-table__communicator-header {
    background: #2c5282;
  }
  tbody tr:first-child:hover td.subscription-table__supporter-header {
    background: color.adjust(#415a75, $lightness: 17%, $saturation: 12%);
  }
  tbody tr:first-child:hover td.subscription-table__eval-header {
    background: color.adjust($brand-slate-gray, $lightness: 23%);
  }
  tbody tr:first-child td:first-child {
    border-top-left-radius: 20px;
  }
  tbody tr:first-child td:last-child {
    border-top-right-radius: 20px;
  }

  .subscription-table__communicator-header {
    font-size: 22px;
    font-weight: 700;
    color: #fff;
    background: #2c5282;
    letter-spacing: 0.01em;
  }

  .subscription-table__supporter-header {
    font-size: 18px;
    font-weight: 700;
    color: #fff;
    background: color.adjust(#415a75, $lightness: 20%, $saturation: 12%); /* 15% lighter than sign-in button */
  }

  .subscription-table__eval-header {
    font-size: 18px;
    font-weight: 700;
    color: #fff;
    background: var(--fs-medium-gray, $brand-slate-gray);
  }

  /* ── Subtle column background tints (skip header row) ── */
  /* Communicator columns (default cells) */
  tbody tr:not(:first-child) td {
    background: rgba(44, 82, 130, 0.02);
  }
  /* Supporter column */
  tbody tr:not(:first-child) td.separator {
    background: rgba(26, 122, 110, 0.04);
  }
  /* Eval column */
  tbody tr:not(:first-child) td:last-child {
    background: rgba(139, 111, 58, 0.04);
  }

  /* ── Plan buttons row hover ── */
  tr.subscription-table__row--plan-buttons:hover td {
    background: rgba($la-teal, 0.08);
  }

  /* ── Last row rounding ── */
  tbody tr:last-child td {
    border-bottom: none;
    padding: 12px;
    .btn {
      width: 100%;
    }
  }
  tbody tr:first-child {
    td:first-child {
      border-top-left-radius: 20px;
    }
    td.separator {
      border-left-color: rgba(255, 255, 255, 0.25);
    }
    td:last-child {
      border-top-right-radius: 20px;
      border-left-color: rgba(255, 255, 255, 0.25);
    }
  }
  tbody tr:last-child {
    td:first-child {
      border-bottom-left-radius: 20px;
    }
    td:last-child {
      border-bottom-right-radius: 20px;
    }
  }

  /* ── Plan buttons ── */
  .btn {
    padding: 10px 16px;
    border-radius: 999px;
    font-weight: 600;
    font-size: 14px;
    line-height: 1.2;
    transition: all 0.25s ease;
    border: none;
  }
  .btn-primary {
    background: var(--fs-navy, $la-navy);
    color: #fff;
    box-shadow: 0 4px 12px rgba($indigo, 0.08);
  }
  .btn-primary:hover {
    background: #243F6B;
    box-shadow: 0 8px 24px rgba($indigo, 0.10);
    transform: translateY(-2px);
  }
  .btn-default {
    background: transparent;
    border: 2px solid var(--fs-navy, $la-navy);
    color: var(--fs-navy, $la-navy);
    box-shadow: 0 1px 4px rgba($indigo, 0.06);
  }

  /* Right plan buttons: white bg when unselected */
  tr.subscription-table__row--plan-buttons td:nth-child(2) .btn-default,
  tr.subscription-table__row--plan-buttons td:nth-child(3) .btn-default,
  tr.subscription-table__row--plan-buttons td:nth-child(4) .btn-default {
    background: #fff;
  }
  /* Right plan buttons hover */
  tr.subscription-table__row--plan-buttons td:nth-child(2) .btn-default:hover,
  tr.subscription-table__row--plan-buttons td:nth-child(3) .btn-default:hover,
  tr.subscription-table__row--plan-buttons td:nth-child(4) .btn-default:hover {
    background: #243F6B;
    border-color: #243F6B;
    color: #fff;
  }
  tr.subscription-table__row--plan-buttons td:nth-child(2) .btn:hover,
  tr.subscription-table__row--plan-buttons td:nth-child(3) .btn:hover,
  tr.subscription-table__row--plan-buttons td:nth-child(4) .btn:hover {
    transform: translateY(-2px) !important;
    box-shadow: 0 8px 24px rgba($indigo, 0.10);
  }

  /* First plan button: same outline ring */
  td.subscription-table__cell--first-plan .btn-default,
  td.subscription-table__cell--first-plan .btn-default:hover {
    box-shadow: 0 1px 4px rgba($indigo, 0.06) !important;
  }
  td.subscription-table__cell--first-plan .btn-primary {
    border: 2px solid var(--fs-navy, $la-navy);
    background: var(--fs-navy, $la-navy);
    color: #fff;
    box-shadow: 0 4px 12px rgba($indigo, 0.08);
  }
  td.subscription-table__cell--first-plan .btn-primary:hover {
    border-color: #243F6B;
    background: #243F6B;
    color: #fff;
    box-shadow: 0 8px 24px rgba($indigo, 0.10);
  }
  tr.subscription-table__row--plan-buttons:hover td.subscription-table__cell--first-plan .btn-primary {
    background: var(--fs-navy, $la-navy) !important;
    color: #fff;
  }
  tr.subscription-table__row--plan-buttons:has(td:nth-child(2):hover) td.subscription-table__cell--first-plan .btn-primary,
  tr.subscription-table__row--plan-buttons:has(td:nth-child(3):hover) td.subscription-table__cell--first-plan .btn-primary,
  tr.subscription-table__row--plan-buttons:has(td:nth-child(4):hover) td.subscription-table__cell--first-plan .btn-primary {
    background: #fff !important;
    color: var(--fs-navy, $la-navy);
  }
  tr.subscription-table__row--plan-buttons:has(td:nth-child(2):hover) td.subscription-table__cell--first-plan .btn-primary .subscription-currency-us,
  tr.subscription-table__row--plan-buttons:has(td:nth-child(3):hover) td.subscription-table__cell--first-plan .btn-primary .subscription-currency-us,
  tr.subscription-table__row--plan-buttons:has(td:nth-child(4):hover) td.subscription-table__cell--first-plan .btn-primary .subscription-currency-us {
    color: var(--fs-dark-teal, $brand-verdigris);
  }
  .btn-default:hover {
    background: var(--fs-navy, $la-navy);
    border: 2px solid var(--fs-navy, $la-navy);
    color: #fff;
    box-shadow: 0 4px 12px rgba($indigo, 0.08);
    transform: translateY(-2px) !important;
  }
  td .btn:hover {
    transform: translateY(-2px) !important;
  }

  /* ── Feature rows: alternating light bg ── */
  tr.subscription-table__row--light-gray-bg td {
    background: $color-warm-white;
  }
  tr.subscription-table__row--light-gray-bg:hover td {
    background: #f5f5f0;
  }

  /* ── Pricing row ── */
  tr.subscription-table__row--pricing td {
    vertical-align: middle;
    padding-top: 24px;
    padding-bottom: 24px;
  }
  tr.subscription-table__row--pricing div.middle {
    top: 50%;
    transform: translateY(-50%);
  }

  /* Large price amounts */
  tr.subscription-table__row--pricing td span[style*='font-size: 40px'],
  tr.subscription-table__row--pricing td span[style*='font-size: 25px'] {
    font-weight: 700 !important;
    color: var(--fs-navy, $la-navy) !important;
  }

  /* ── No-hover rows ── */
  tr.subscription-table__row--no-hover:hover td {
    background: #fff;
  }
  tr.subscription-table__row--no-hover:hover div.middle {
    background: #fff;
  }

  /* ── Blue accent row (supervisor credits / bulk) ── */
  tr.subscription-table__row--blue-bg td {
    background: rgba(58, 107, 199, 0.08);
    border-bottom-color: rgba(58, 107, 199, 0.12);
  }
  tr.subscription-table__row--blue-bg:hover td {
    background: rgba(58, 107, 199, 0.12);
  }
  tr.subscription-table__row--blue-bg td a {
    color: var(--fs-dark-teal, $brand-verdigris);
    font-weight: 600;
    text-decoration: none;
  }
  tr.subscription-table__row--blue-bg td a:hover {
    text-decoration: underline;
  }

  /* ── Navy CTA row (trial / gift / modeling) ── */
  tbody tr.subscription-table__row--navy-bg td {
    background: var(--fs-navy, $la-navy);
    color: $brand-honey-bronze;
    padding-top: 20px !important;
    padding-bottom: 20px !important;

    a {
      color: $brand-honey-bronze;
      text-decoration: none;
      font-weight: 600;
      &:hover {
        text-decoration: underline;
      }
    }
    .btn-default {
      border-color: var(--fs-teal, $la-teal);
      color: var(--fs-teal, $la-teal);
    }
    .btn-default:hover {
      background: rgba($la-teal, 0.15);
      border-color: var(--fs-teal, $la-teal);
      color: var(--fs-teal, $la-teal);
    }
    .btn-primary {
      background: var(--fs-teal, $la-teal);
      color: var(--fs-navy, $la-navy);
      font-weight: 700;
    }
    .btn-primary:hover {
      background: $brand-verdigris;
      color: #fff;
    }
  }
  tr.subscription-table__row--navy-bg:hover td {
    background: #243F6B;
    color: $brand-honey-bronze;
    a {
      color: $brand-honey-bronze;
    }
  }
}

/* ── Subscription form card layout (replaces table on subscription-form) ── */
form.row.subscription-form-with-cards {
  width: 100%;
  max-width: 960px;
}

/* ── Subscribe modal: pricing card grid (modern) ─────────────
   Each card is now an elevated rounded tile that mirrors the
   boards-page .md-card aesthetic: white vertical gradient
   surface, hairline border, navy-tinted bottom border for
   weight, soft shadow, hover lift. Replaces the legacy flat
   table look (flush border-left dividers, dense 16/20 padding,
   colored stripe rows) that competed with .la-about-glass-card. */
.subscription-form-cards {
  display: grid;
  grid-template-columns: 1fr 1fr 1fr;
  gap: 16px;
  width: 100%;
  max-width: 100%;
  margin-top: 4px;
  background: transparent;
  border-radius: 0;
  overflow: visible;
  box-shadow: none;
}

.subscription-form-card {
  display: flex;
  flex-direction: column;
  border: none;

  &:first-child { border-left: none; }
}

/* Override .la-about-glass-card from dark-theme landing variant to
   light-theme modal variant (still scoped to subscription form). */
.subscription-form-cards .la-about-glass-card {
  display: flex;
  flex-direction: column;
  flex: 1;
  background: linear-gradient(180deg, rgba(255, 255, 255, 0.99), rgba(245, 248, 252, 0.95));
  backdrop-filter: none;
  -webkit-backdrop-filter: none;
  border: 1px solid var(--md-line, rgba($brand-blue-black, 0.08));
  border-bottom: 2px solid rgba($la-navy, 0.10);
  border-radius: $aac-radius-xl;
  padding: 24px 22px 0;
  box-shadow:
    0 6px 24px rgba($la-navy, 0.06),
    0 1px 3px rgba($la-navy, 0.04);
  transform: none;
  transition: transform 0.25s ease, box-shadow 0.25s ease, background 0.25s ease;
  overflow: hidden;

  &:hover {
    transform: translateY(-3px);
    background: linear-gradient(180deg, #fff, rgba(245, 248, 252, 1));
    box-shadow:
      0 12px 32px rgba($la-navy, 0.12),
      0 2px 6px rgba($la-navy, 0.06);
  }
}

.subscription-form-cards .la-about-glass-card__header {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 10px;
  margin-bottom: 8px;
}

.subscription-form-cards .la-about-glass-card__icon {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  width: 48px;
  height: 48px;
  border-radius: 14px;
  background: rgba($brand-dusty-denim, 0.12);
  color: $la-navy;

  svg { width: 28px; height: 28px; stroke: currentColor; }
}
.subscription-form-cards .la-about-glass-card__icon--communicator { background: rgba(44, 82, 130, 0.10); color: #2c5282; }
.subscription-form-cards .la-about-glass-card__icon--supporter    { background: rgba($brand-verdigris, 0.12); color: $brand-verdigris-aa; }
.subscription-form-cards .la-about-glass-card__icon--eval         { background: rgba($brand-slate-gray, 0.14); color: $brand-slate-gray; }

.subscription-form-cards .la-about-glass-card__title {
  font-family: 'Lexend', 'Nunito Sans', system-ui, sans-serif;
  font-size: 19px;
  font-weight: $aac-font-weight-bold;
  color: var(--md-ink, $brand-blue-black);
  margin: 0;
  text-align: center;
}

.subscription-form-cards .la-about-glass-card__text {
  font-size: 14px;
  color: var(--md-muted, $la-navy);
  line-height: 1.55;
  margin: 0 0 4px;
  text-align: center;

  strong { color: var(--md-ink, $brand-blue-black); }
}

/* la-pricing-card (centered column inside each glass card) */
.subscription-form-cards .la-pricing-card {
  display: flex;
  flex-direction: column;
  align-items: center;
  text-align: center;
  transform: none;
  transition: none;
  flex: 1;

  &:hover { transform: none; }
}

.subscription-form-cards .la-pricing-card__prices {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 4px;
  width: 100%;
  margin: 14px 0;
  padding: 14px 0;
  border-top: 1px solid var(--md-line, rgba($brand-blue-black, 0.08));
  border-bottom: 1px solid var(--md-line, rgba($brand-blue-black, 0.08));
}

.subscription-form-cards .la-pricing-card__price-row {
  display: flex;
  flex-direction: column;
  align-items: center;
}

.subscription-form-cards .la-pricing-card__amount {
  font-family: 'Lexend', 'Nunito Sans', system-ui, sans-serif;
  font-size: 34px;
  font-weight: $aac-font-weight-black;
  color: var(--md-ink, $brand-blue-black);
  line-height: 1.05;
  letter-spacing: -0.01em;
}

.subscription-form-cards .la-pricing-card__currency {
  font-size: 14px;
  font-weight: $aac-font-weight-semi;
  color: $brand-slate-gray;
  vertical-align: middle;
  margin-right: 1px;
}

.subscription-form-cards .la-pricing-card__term {
  font-size: 13px;
  color: $brand-charcoal-dark;
  font-weight: $aac-font-weight-medium;
  margin-top: 4px;
}

.subscription-form-cards .la-pricing-card__or {
  font-size: 13px;
  color: rgba($brand-charcoal-dark, 0.5);
  padding: 4px 0;
}

/* Sale badge — used for "sale! 50% off" / "save 25%" */
.subscription-form-cards .la-pricing-card .sale {
  display: inline-block;
  background: linear-gradient(135deg, $brand-verdigris 0%, color.adjust($brand-verdigris, $lightness: -8%) 100%);
  color: #fff;
  font-size: 11px;
  font-weight: 700;
  padding: 4px 10px;
  border-radius: $aac-radius-pill;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  margin-bottom: 6px;
}

/* Strikethrough price (when sale active) */
.subscription-form-cards .la-pricing-card__amount span[style*="line-through"] {
  font-size: 18px !important;
  font-weight: 500 !important;
  color: $brand-slate-gray !important;
  margin-right: 6px;
}

/* Features list — clean rows with hairline dividers */
.subscription-form-cards .la-pricing-card__features {
  list-style: none;
  margin: 6px 0 14px;
  padding: 0;
  text-align: left;
  width: 100%;
  font-size: 14px;
  line-height: 1.45;
  color: var(--md-ink, $brand-blue-black);

  li {
    padding: 10px 0;
    border-bottom: 1px solid var(--md-line, rgba($brand-blue-black, 0.06));
    &:last-child { border-bottom: none; }
  }
}

/* "Cloud extras" inline-link/button inside features */
.subscription-form__cloud-extras-link {
  padding: 0;
  margin: 0;
  border: none;
  background: none;
  font: inherit;
  color: $brand-verdigris-aa;
  text-decoration: none;
  font-weight: 600;
  cursor: pointer;
  border-bottom: 1px solid transparent;
  transition: border-color 0.12s ease;

  &:hover { border-bottom-color: $brand-verdigris-aa; }
}

/* Card body — plan-select buttons row + sub-rows. Pulled to the
   card's edges so backgrounds (sub-rows, navy-bg) extend full-width. */
.subscription-form-card__body {
  display: flex;
  flex-direction: column;
  flex: 1;
  margin: 0 -22px;
  font-size: 14px;
  color: var(--md-ink, $brand-blue-black);
  background: transparent;
}

.subscription-form-cards .subscription-form-card--communicator .subscription-form-card__body,
.subscription-form-cards .subscription-form-card--supporter   .subscription-form-card__body,
.subscription-form-cards .subscription-form-card--eval        .subscription-form-card__body {
  background: transparent;
}

/* Plan-select buttons row (one per card) */
.subscription-form-card__buttons {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  padding: 14px 18px;
  border-top: 1px solid var(--md-line, rgba($brand-blue-black, 0.08));
  background: transparent;

  > div { flex: 1; min-width: 110px; }
}

.subscription-form-card__buttons button,
.subscription-form-cards button[rel='monthly'],
.subscription-form-cards button[rel='long_term'],
.subscription-form-cards button[rel='slp_paid'],
.subscription-form-cards button[rel='eval_paid'] {
  width: 100%;
  display: inline-flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 2px;
  padding: 12px 14px;
  border-radius: $aac-radius-pill;
  /* Canonical modern action button palette — same as
     .md-btn--primary (rgba dusty-denim 0.3 + navy text). */
  background: rgba($brand-dusty-denim, 0.30);
  border: 1.5px solid rgba($brand-dusty-denim, 0.22);
  color: $la-navy;
  font-size: 13px;
  font-weight: 600;
  line-height: 1.25;
  cursor: pointer;
  transition: background 0.18s ease, border-color 0.18s ease, color 0.18s ease, transform 0.18s ease, box-shadow 0.18s ease;

  b {
    font-size: 13px;
    font-weight: 700;
    color: inherit;
  }

  &:hover:not(:disabled) {
    background: rgba($brand-dusty-denim, 0.45);
    border-color: rgba($brand-dusty-denim, 0.35);
    box-shadow: 0 4px 14px rgba($brand-dusty-denim, 0.15);
    transform: translateY(-1px);
  }

  /* Selected plan (Subscription.update_classes adds .active / .btn-primary).
     Bumps to a stronger denim wash so the chosen plan reads as committed
     without leaving the action-button palette. */
  &.active,
  &.btn-primary {
    background: rgba($brand-dusty-denim, 0.65);
    border-color: rgba($brand-dusty-denim, 0.55);
    color: $la-navy;
    box-shadow: 0 6px 18px rgba($brand-dusty-denim, 0.30);

    b { color: $la-navy; font-weight: 800; }
  }

  .subscription-currency-us {
    font-size: 10px;
    font-weight: 500;
    color: inherit;
    opacity: 0.75;
  }
}

/* Sub-rows (premium symbols, supervisor credits, navy/gift-trial) */
.subscription-form-card__row {
  padding: 12px 18px;
  border-top: 1px solid var(--md-line, rgba($brand-blue-black, 0.08));
  font-size: 13px;
  line-height: 1.45;
  color: var(--md-ink, $brand-blue-black);

  &:empty { display: none; }
}

.subscription-form-card__row.subscription-table__row--light-gray-bg {
  background: rgba($brand-slate-gray, 0.05);

  label {
    display: flex;
    align-items: flex-start;
    gap: 10px;
    margin: 0;
    font-weight: 500;
    cursor: pointer;
  }
}

.subscription-form-card__row.subscription-table__row--blue-bg {
  background: rgba($brand-dusty-denim, 0.06);

  a {
    color: $brand-verdigris-aa;
    text-decoration: none;
    font-weight: 600;
    border-bottom: 1px solid transparent;
    transition: border-color 0.12s ease;

    &:hover { border-bottom-color: $brand-verdigris-aa; }
  }

  .text-muted {
    color: $brand-slate-gray;
    font-style: italic;
  }
}

/* Navy CTA row at bottom of each card — gift code, trial button,
   modeling-only link. Grounds the card with a brand-color base. */
.subscription-form-card__row.subscription-table__row--navy-bg {
  margin-top: auto;
  margin: auto -22px -1px -22px;
  padding: 16px 18px;
  background: linear-gradient(180deg, $la-navy 0%, color.adjust($la-navy, $lightness: -5%) 100%);
  color: #fff;
  border: none;
  border-radius: 0;
  text-align: center;

  a {
    color: $brand-honey-bronze;
    text-decoration: none;
    font-weight: 600;
    border-bottom: 1px solid transparent;
    transition: border-color 0.12s ease;

    &:hover { border-bottom-color: $brand-honey-bronze; }
  }

  /* Trial pill on dark bg flips to white surface */
  .subscribe-trial-btn {
    width: 100%;
    background: rgba(#fff, 0.96);
    color: $la-navy;
    box-shadow: 0 4px 14px rgba(0, 0, 0, 0.22);

    &:hover {
      background: #fff;
      color: $la-navy;
      box-shadow: 0 6px 20px rgba(0, 0, 0, 0.28);
    }
  }

  /* Gift code input + Check button */
  .form-control {
    background: rgba(#fff, 0.96);
    border: 1px solid rgba(#fff, 0.3);
    color: $la-navy;
    border-radius: $aac-radius-md;
    font-weight: 600;
    text-align: center;
  }
  .btn {
    border-radius: $aac-radius-md;
    background: $brand-honey-bronze;
    color: $la-navy;
    border: none;
    font-weight: 600;
    padding: 10px 14px;

    &:hover {
      background: color.adjust($brand-honey-bronze, $lightness: -6%);
      color: $la-navy;
    }
  }
}

/* Premium-symbol image (LessonPix/PCS preview) */
.subscription-form__premium-symbol-image {
  float: none;
  width: 40px;
  height: 40px;
  margin: 0;
  flex-shrink: 0;
}

/* Bulk purchase explainer card */
.subscription-form-with-cards .form-group:has(.glyphicon-paperclip) {
  margin-top: 24px;

  p {
    background: rgba($brand-honey-bronze, 0.08);
    border: 1px solid rgba($brand-honey-bronze, 0.22);
    border-radius: $aac-radius-lg;
    padding: 16px 18px;
    margin: 0;
    font-size: 14px;
    line-height: 1.6;
    color: var(--md-ink, $brand-blue-black);
  }

  .glyphicon-paperclip {
    color: $brand-honey-bronze;
    font-size: 22px !important;
    margin: 2px 12px 0 0 !important;
  }
}

/* Expiration-notes explanation block */
.subscribe-modal-body .explanation {
  max-width: 60ch;
  margin: 16px auto 0 !important;
  padding: 12px 18px;
  background: rgba($brand-slate-gray, 0.06);
  border-radius: $aac-radius-lg;
  font-size: 13px;
  line-height: 1.5;
  color: $brand-charcoal-dark;
  text-align: center;
}

/* Trial-choice rare 2-button mode (trial vs purchasing) */
.subscription-form-trial-choice {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 14px;
  margin-top: 24px;
}
.subscription-form-trial-choice__btn {
  min-height: 90px;
  padding: 16px 20px;
  border-radius: $aac-radius-xl;
  font-size: 15px;
  font-weight: 600;
  line-height: 1.3;
  cursor: pointer;
  transition: background 0.18s ease, border-color 0.18s ease, transform 0.18s ease, box-shadow 0.18s ease;
}
.subscription-form-trial-choice__btn--trial {
  background: #fff;
  border: 1.5px solid var(--md-line, rgba($brand-blue-black, 0.15));
  color: var(--md-ink, $brand-blue-black);

  &:hover {
    background: $surface-100;
    border-color: rgba($brand-blue-black, 0.25);
    transform: translateY(-1px);
  }
}
.subscription-form-trial-choice__btn--pricing {
  /* Modern action-button palette (.md-btn--primary) — dusty
     denim wash with navy text, slightly stronger than the
     plan-select rest state since this is the primary choice. */
  background: rgba($brand-dusty-denim, 0.60);
  border: 1.5px solid rgba($brand-dusty-denim, 0.55);
  color: $la-navy;
  box-shadow: 0 6px 18px rgba($brand-dusty-denim, 0.28);

  &:hover {
    background: rgba($brand-dusty-denim, 0.75);
    border-color: rgba($brand-dusty-denim, 0.7);
    box-shadow: 0 8px 24px rgba($brand-dusty-denim, 0.38);
    transform: translateY(-1px);
  }
}
@media (max-width: 480px) {
  .subscription-form-trial-choice { grid-template-columns: 1fr; }
}

/* Stack cards on narrow viewports */
.skinny_subscription .subscription-form-cards {
  grid-template-columns: 1fr;
}

@media (max-width: 950px) {
  .subscription-form-cards { grid-template-columns: 1fr; }
}

/* ── Activate row (hero CTA + secondary actions) ─────────────
   Replaces the old white outlined activate button + cramped
   trial link with a hero pill gradient + softer outlined
   secondary actions. */
.subscription-activate-row {
  display: flex;
  align-items: center;
  justify-content: center;
  flex-wrap: wrap;
  gap: 14px;
  margin-top: 28px;
  padding-top: 22px;
  border-top: 1px solid var(--md-line, rgba($brand-blue-black, 0.10));
}

/* Hero activate CTA — strongest variant of the canonical
   .md-btn--primary action-button palette (dusty-denim + navy).
   Stays on-brand with the plan-select pills but uses a 60%
   fill + thicker border + stronger shadow to read as the
   primary action of the modal. */
.subscription-activate-btn {
  flex: 1 1 280px;
  max-width: 480px;
  display: inline-flex;
  flex-direction: column;
  align-items: center;
  gap: 4px;
  padding: 16px 28px;
  border-radius: $aac-radius-pill;
  border: 1.5px solid rgba($brand-dusty-denim, 0.55) !important;
  background: rgba($brand-dusty-denim, 0.60) !important;
  color: $la-navy !important;
  box-shadow: 0 8px 24px rgba($brand-dusty-denim, 0.28) !important;
  font-weight: 700;
  text-decoration: none;
  transition: background 0.25s ease, border-color 0.25s ease, box-shadow 0.25s ease, transform 0.25s ease;

  &:hover:not(:disabled) {
    background: rgba($brand-dusty-denim, 0.75) !important;
    border-color: rgba($brand-dusty-denim, 0.7) !important;
    box-shadow: 0 12px 32px rgba($brand-dusty-denim, 0.38) !important;
    transform: translateY(-1px);
  }
}
.subscription-activate-btn__heading-row {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  margin-bottom: 0;
}
.subscription-activate-btn__heading {
  font-family: 'Lexend', 'Nunito Sans', system-ui, sans-serif;
  font-size: 18px;
  font-weight: 800;
  color: $la-navy;
  letter-spacing: -0.01em;
}
.subscription-activate-btn__arrow {
  color: $la-navy;
  font-size: 18px;
}
.subscription-activate-btn__icon { color: $la-navy; }
.subscription-activate-btn__discount {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  margin-bottom: 4px;
  padding: 3px 12px;
  border-radius: $aac-radius-pill;
  background: rgba($la-navy, 0.12);
  font-size: 11px;
  font-weight: 700;
  color: $la-navy;
  letter-spacing: 0.06em;
  text-transform: uppercase;

  .subscription-activate-btn__icon { color: $la-navy; }
}
.subscription-activate-btn__price {
  color: rgba($la-navy, 0.88);
  font-size: 13px;
  font-weight: 500;
}
.subscription-activate-btn__paren {
  color: rgba($la-navy, 0.78);
  font-weight: 600;
}
.subscription-activate-btn__paying-line {
  color: $la-navy;
  font-weight: 600;
}
.subscription-activate-btn__subtext {
  display: block;
  margin-top: 4px;
  color: rgba($la-navy, 0.75);
  font-size: 12px;
  font-style: italic;
  font-weight: 400;
}

/* Secondary actions in activate row (trial link, cancel, reload, log out, need-more-time) */
.subscription-activate-row .subscribe-trial-btn {
  flex: 0 1 auto;
  margin-left: 0;
  font-size: 14px;
  background: transparent;
  color: var(--md-muted, $la-navy);
  border: 1.5px solid var(--md-line, rgba($brand-blue-black, 0.15));
  box-shadow: none;

  &:hover {
    background: rgba($la-navy, 0.05);
    color: var(--md-ink, $brand-blue-black);
    border-color: rgba($la-navy, 0.35);
    box-shadow: none;
    transform: translateY(-1px);
  }
}
.subscription-activate-row > .btn,
.subscription-activate-row > a:not(.subscribe-trial-btn) {
  flex: 0 1 auto;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 10px 20px;
  border-radius: $aac-radius-pill;
  background: transparent;
  border: 1.5px solid var(--md-line, rgba($brand-blue-black, 0.15));
  color: var(--md-muted, $la-navy);
  font-size: 14px;
  font-weight: 600;
  text-decoration: none;
  cursor: pointer;
  transition: background 0.18s ease, border-color 0.18s ease, color 0.18s ease;

  &:hover {
    background: rgba($la-navy, 0.05);
    border-color: rgba($la-navy, 0.35);
    color: var(--md-ink, $brand-blue-black);
    text-decoration: none;
  }
}

/* Supporter / Eval secondary states */
.subscription-form-card .semi_dim { opacity: 0.85; }

.subscription-form-cards .subscription-table__cloud-extras-right a[href*='blog.mylingolinq.com'],
.subscription-form-cards a[href*='blog.mylingolinq.com'] {
  color: var(--fs-dark-teal, $brand-verdigris);
  text-decoration: none;
  font-weight: 500;
  border-bottom: 1px solid transparent;
  transition: border-color 0.12s ease;
}

.subscription-form-cards a[href*='blog.mylingolinq.com']:hover {
  border-bottom-color: var(--fs-dark-teal, $brand-verdigris);
}

/* Applied in: speak-menu component - speak options dropdown */
/* ── Modern Speak Menu ─────────────────────────────────── */
.modal-content:has(.md-speak-menu) {
  border-radius: 20px;
  border: none;
  overflow: hidden;
  background: #ffffff;
}
.md-speak-menu {
  padding: 16px 20px 12px !important;
  font-size: 16px;
  background: #ffffff;
  border-radius: 20px;
  overflow: hidden;
}

/* Header */
.md-speak-menu__header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding-bottom: 12px;
  margin-bottom: 14px;
  border-bottom: 1px solid rgba($la-navy, 0.15);
}
.md-speak-menu__title {
  font-size: 1.25rem; /* 20px — meets AAC ~30% larger than web default */
  font-weight: 700;
  color: $la-navy;
}
.md-speak-menu__close {
  width: 44px; /* WCAG 2.5.5 — minimum touch target 44×44 */
  height: 44px;
  border: 1px solid rgba($la-navy, 0.12);
  background: rgba($la-navy, 0.05);
  border-radius: 50%;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  color: $brand-slate-gray;
  transition: background 0.12s ease, color 0.12s ease, transform 0.12s ease;
  padding: 0;
}
.md-speak-menu__close:hover {
  background: rgba($la-navy, 0.10);
  color: $brand-charcoal-dark;
  transform: scale(1.05);
}

/* Sections */
.md-speak-menu__section {
  margin-bottom: 20px;
}
.md-speak-menu__section--punctuation {
  /* Punctuation is the FIRST section now — separator sits UNDERNEATH it. */
  border-bottom: 1px solid rgba($la-navy, 0.15);
  padding-bottom: 16px;
}
.md-speak-menu__section-label {
  font-size: 1rem; /* 16px — large enough with uppercase treatment */
  font-weight: 700;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  color: rgba($la-navy, 0.85); /* ~7.8:1 contrast on white — passes AAA */
  margin-bottom: 8px;
  padding-left: 2px;
}

/* Button rows */
.md-speak-menu__row {
  display: grid;
  gap: 8px;
}
.md-speak-menu__row--1 { grid-template-columns: 1fr; }
.md-speak-menu__row--2 { grid-template-columns: repeat(2, 1fr); }
.md-speak-menu__row--3 { grid-template-columns: repeat(3, 1fr); }
.md-speak-menu__row--5 { grid-template-columns: repeat(5, 1fr); }
/* Full punctuation set in one row (single-tap reach, no "More" submenu). 7 across
   only while the targets stay comfortably hittable — see the narrow-screen wrap below. */
.md-speak-menu__row--7 { grid-template-columns: repeat(7, 1fr); }
.md-speak-menu__row--locale {
  grid-template-columns: repeat(auto-fill, minmax(148px, 1fr));
}

/* Speak menu: board tools (speak mode + languages) above main actions */
.md-speak-menu__section-wrap--board-tools {
  border-bottom: 1px solid rgba($la-navy, 0.15);
  margin-bottom: 16px;
  padding-bottom: 4px;
}
/* No separator beneath this wrap — used on the Speak Mode section (the LAST
   section), so there's no divider line trailing the bottom of the modal. */
.md-speak-menu__section-wrap--no-divider {
  border-bottom: none;
  margin-bottom: 0;
  padding-bottom: 0;
}
.md-speak-menu__btn--text-row {
  min-height: 52px;
  justify-content: center;
  padding: 12px 10px;
}
.md-speak-menu__btn--locale-chip {
  min-height: 48px;
  padding: 10px 8px;
}
.md-speak-menu__btn-label--locale {
  font-size: 1rem; /* 16px — meets WCAG AA body text, bold compensates for slightly under 18px */
  line-height: 1.35;
  font-weight: 600;
  word-break: break-word;
}

/* Individual buttons */
.md-speak-menu__btn {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 6px;
  padding: 14px 8px;
  cursor: pointer;
  text-align: center;
  position: relative;
  border-radius: 14px;
  border: 1px solid rgba($la-navy, 0.08);
  background: #E9EBED;
  transition: background 0.12s ease, box-shadow 0.12s ease;
  color: $la-navy;
  box-shadow: 0 1px 4px rgba(0, 0, 0, 0.06);
}
.md-speak-menu__btn:hover {
  background: #F2F3F5;
  box-shadow: 0 3px 10px rgba(0, 0, 0, 0.10);
}
.md-speak-menu__btn:active {
  background: #DFE1E4;
  transform: scale(0.97);
}
.md-speak-menu__btn svg {
  flex-shrink: 0;
  /* Flat duotone base: every icon's primary shapes are AA-contrast teal; accent
     paths set their own stroke="#46505F" (charcoal) inline. Uses the AA token
     ($brand-verdigris-aa, 4.73:1 on white) rather than the dashboard's #2A9D8F
     so the icons clear WCAG 1.4.11 on the grey speak-menu button background.
     (Per-path stroke attrs win over this inherited value.) */
  stroke: $brand-verdigris-aa;
}
.md-speak-menu__btn-label {
  font-size: 1.125rem; /* 18px — AAC requirement */
  font-weight: 600;
  line-height: 1.35;
  color: $brand-charcoal-dark;
}
.md-speak-menu__badge {
  position: absolute;
  top: 4px;
  right: 6px;
  background: $brand-danger;
  color: #fff;
  font-size: 14px;
  font-weight: 700;
  padding: 2px 6px;
  border-radius: 10px;
  line-height: 1;
}
.md-speak-menu__punctuation {
  font-size: 42px;
  line-height: 36px;
  display: block;
  color: $brand-charcoal-dark;
  font-weight: 700;
}
.md-speak-menu__punctuation--sm {
  font-size: 22px;
  line-height: 28px;
}
#menu_punctuation_button .md-speak-menu__punctuation--sm {
  background: linear-gradient(135deg, $brand-verdigris, $brand-dusty-denim);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
}

/* Bottom actions */
.md-speak-menu__bottom {
  padding-top: 8px;
  margin-top: 4px;
}
.md-speak-menu__bottom-btn {
  display: flex;
  align-items: center;
  gap: 8px;
  width: 100%;
  padding: 10px 12px;
  background: transparent;
  border: none;
  border-radius: 10px;
  cursor: pointer;
  font-size: 15px;
  font-weight: 500;
  color: $la-navy;
  transition: background 0.12s ease;
  text-align: left;
}
.md-speak-menu__bottom-btn:hover {
  background: rgba(255, 255, 255, 0.20);
}
.md-speak-menu__bottom-btn--remember {
  color: $brand-verdigris;
  font-weight: 600;
}
.md-speak-menu__bottom-btn--action {
  /* WCAG AA fix — was $brand-dusty-denim on white = 3.49:1. */
  color: $brand-dusty-denim-aa;
  font-weight: 600;
}
.md-speak-menu__bottom-btn--remembered {
  font-size: 14px;
  color: $brand-charcoal-dark;
}
.md-speak-menu__bottom-btn--remembered .md-speak-menu__remembered-text {
  font-size: 16px;
  font-weight: 600;
  color: $la-navy;
}
.md-speak-menu__bottom-btn svg {
  flex-shrink: 0;
  color: inherit;
  opacity: 0.7;
}

/* Legacy list fallback */
.md-speak-menu__legacy-list {
  list-style: none;
  margin: 0;
  padding: 8px 0;
}
.md-speak-menu__legacy-list li { padding: 0; }
.md-speak-menu__legacy-list a {
  display: block;
  padding: 12px 16px;
  color: $la-navy;
  font-size: 16px;
  font-weight: 500;
  text-decoration: none;
  border-radius: 10px;
  transition: background 0.12s ease;
}
.md-speak-menu__legacy-list a:hover {
  background: rgba($brand-verdigris, 0.06);
}
.md-speak-menu__legacy-context {
  padding: 12px 16px 4px;
  font-size: 14px;
  color: rgba(75, 78, 92, 0.55);
}

@media (max-width: 768px) {
  .md-speak-menu__row--3 {
    grid-template-columns: repeat(2, 1fr);
  }
  /* 7 punctuation targets across is too small to hit reliably on a phone --
     wrap to 4+3 so each stays a comfortable touch target (AAC motor accuracy). */
  .md-speak-menu__row--7 {
    grid-template-columns: repeat(4, 1fr);
  }
}

