.board_hierarchy {
  > ul {
    padding-left: 0;
  }
  ul {
    list-style-type: none;
    /* No list indent — every row (and thus every checkbox) starts at the same
       left edge. Hierarchy is shown by indenting each node's CONTENT by depth
       (.recursive-board__content), so all checkboxes line up in one column. */
    padding-left: 0;
    margin: 0;
  }
  .recursive-board__item {
    padding: 0;
    opacity: 0.65;
    &.selected { opacity: 1; }
  }
  /* The row (checkbox + toggle + label) is its OWN flex line so the nested
     <ul> stays a block below it — the checkbox/toggle/label line up while the
     children indent normally. */
  .recursive-board__row {
    display: flex;
    align-items: center;
    gap: 8px;
    padding: 5px 0;
    font-size: 15px;
  }
  /* The content (toggle + label) carries the depth indent via inline
     padding-left, leaving the checkbox before it fixed in a single column. */
  .recursive-board__content {
    display: flex;
    align-items: center;
    gap: 8px;
    min-width: 0;
    flex: 1 1 auto;
  }
  /* Fixed-width toggle column (chevron for folders, empty for leaves) so leaf
     rows align with folder rows. */
  .recursive-board__toggle {
    flex-shrink: 0;
    width: 18px;
    height: 18px;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    color: #6b7683;
    text-decoration: none;
  }
  .recursive-board__chevron {
    transition: transform 0.15s ease;
  }
  .recursive-board__chevron--open {
    transform: rotate(90deg);
  }
  .recursive-board__label {
    min-width: 0;
    word-break: break-word;
  }
  /* Modern custom checkbox (verdigris fill) — same treatment the board-privacy
     hierarchy already used, now shared by every board-hierarchy consumer. */
  .recursive-board__check {
    appearance: none;
    -webkit-appearance: none;
    -moz-appearance: none;
    position: relative;
    flex-shrink: 0;
    width: 18px;
    height: 18px;
    margin: 0;
    border: 1.5px solid rgba($la-navy, 0.30);
    border-radius: 4px;
    background: #fff;
    cursor: pointer;
    transition: border-color 0.15s ease, background 0.15s ease;
  }
  .recursive-board__check:hover { border-color: rgba($brand-verdigris, 0.55); }
  .recursive-board__check:checked {
    background: $brand-verdigris;
    border-color: $brand-verdigris;
  }
  .recursive-board__check:checked::after {
    content: '';
    position: absolute;
    top: 2px;
    left: 5px;
    width: 5px;
    height: 9px;
    border-right: 2px solid #fff;
    border-bottom: 2px solid #fff;
    transform: rotate(45deg);
  }
  .recursive-board__check:focus-visible {
    outline: 2px solid rgba($brand-verdigris, 0.5);
    outline-offset: 1px;
  }
  .recursive-board__check:disabled { opacity: 0.4; cursor: not-allowed; }
}

