/* ==========================================================================
   Lingoling – Modern Bento UI (ll-bento-*)
   Scoped styles for authenticated dashboard. All classnames use ll-bento-
   prefix to avoid conflicts with existing .btn, .content, .grid, .card,
   .tab, .search, .avatar, etc. used elsewhere in the project.
   Applied in: dashboard/authenticated-view.hbs
   ========================================================================== */

/* Main app shell wrapper - centers content, provides padding.
   Design tokens (--ll-bento-*) defined here for bento components. */
.ll-bento-app-shell {
  /* Bento design tokens - clean, modern color system */
  --ll-bento-bg: #dcdde0;
  --ll-bento-ink: #1e2430;
  --ll-bento-muted: rgba(30, 36, 48, 0.62);
  --ll-bento-card: rgba(255, 252, 250, 0.88);
  --ll-bento-card-strong: rgba(255, 255, 255, 0.92);
  --ll-bento-stroke: rgba(20, 24, 36, 0.08);
  --ll-bento-shadow-lg: 0 18px 50px rgba(19, 29, 56, 0.12);
  --ll-bento-shadow-md: 0 10px 28px rgba(19, 29, 56, 0.05);
  --ll-bento-shadow-sm: 0 6px 16px rgba(19, 29, 56, 0.06);
  --ll-bento-radius-xl: 28px;
  --ll-bento-radius-lg: 22px;
  --ll-bento-radius-md: 18px;
  --ll-bento-radius-sm: 14px;
  /* Primary: Teal → Blue → Indigo */
  --ll-bento-primary-1: #4ec5c8;
  --ll-bento-primary-2: #5fb8ff;
  --ll-bento-primary-3: #7b8cff;
  /* Secondary: Soft lavender / violet */
  --ll-bento-secondary: #b8a8d8;
  /* Functional: Green (success/speak), Coral (premium/attention) */
  --ll-bento-functional-green: #5cb88a;
  --ll-bento-functional-coral: #e88a7a;
  /* Animation easing */
  --ll-bento-ease-out: cubic-bezier(0.33, 1, 0.68, 1);
  --ll-bento-ease-in-out: cubic-bezier(0.65, 0, 0.35, 1);
  /* Icon lighting - light direction 135deg (top-left), gloss, rim */
  --ll-bento-icon-gloss: linear-gradient(135deg, rgba(255, 255, 255, 0.2) 0%, transparent 50%);
  --ll-bento-icon-rim: inset 1px 1px 0 rgba(255, 255, 255, 0.42);
  /* Content alignment - horizontal inset to match tab row edges */
  --ll-bento-content-inset: 4px;

  /* Unified material system - blur + inner light + counter shadow for depth consistency */
  --ll-bento-material-blur: 28px;
  --ll-bento-material-inner-highlight: inset 0 1px 0 rgba(255, 255, 255, 0.6),
                                       inset 0 1px 0 rgba(255, 255, 255, 0.12) !important;
  --ll-bento-material-counter-shadow: inset 0 -1px 2px rgba(0, 0, 0, 0.035);

  display: grid;
  place-items: center;
  padding: 24px;
  position: relative;
  overflow: hidden;
  font-family: 'Lexend', 'Nunito Sans', system-ui, sans-serif;
  font-weight: 400;
  background: transparent; /* gradient on #content fills the content viewport */
}

/* Shell fills height only when NOT in footer layout (avoids min-height in cascade when bento-page-with-footer or :has(.page-footer)). */
#within_ember:not(.bento-page-with-footer):not(:has(.page-footer)) .ll-bento-app-shell {
  min-height: 100% !important;
}

/* Bento page with footer: override grid so app shell is flex; min-height: 0 so shell can shrink in flex chain. */
#within_ember.bento-page-with-footer #content .ll-bento-app-shell,
#within_ember:has(.page-footer) #content.index.with_user .ll-bento-app-shell {
  display: flex;
  flex-direction: column;
  flex: 1 1 auto;
  min-height: 0 !important; /* override base .ll-bento-app-shell min-height: 100% !important so shell can shrink in flex chain */
  align-items: center;
  place-items: unset;
  justify-content: flex-start;
  width: 100%;
  padding-top: 48px;
  margin-top: 0;
}

/* Decorative blurred orbs in background */
.ll-bento-bg-orbs {
  position: absolute;
  inset: -80px;
  pointer-events: none;
  filter: blur(22px);
  opacity: 0.75;

  .ll-bento-orb {
    position: absolute;
    border-radius: 999px;
    transform: translateZ(0);

    &--a {
      width: 420px;
      height: 420px;
      left: 6%;
      top: 12%;
      background: radial-gradient(circle at 30% 30%, rgba(95, 199, 255, 0.38), transparent 58%),
                  radial-gradient(circle at 70% 70%, rgba(123, 140, 255, 0.32), transparent 60%) !important;
    }

    &--b {
      width: 520px;
      height: 520px;
      right: 4%;
      top: 18%;
      background: radial-gradient(circle at 35% 35%, rgba(67, 198, 195, 0.30), transparent 60%),
                  radial-gradient(circle at 70% 70%, rgba(183, 155, 255, 0.28), transparent 58%) !important;
    }

    &--c {
      width: 560px;
      height: 560px;
      left: 20%;
      bottom: 6%;
