  color: var(--ll-coral);
}
.ll-upgrade:active { transform: scale(var(--ll-tap)); }
.ll-upgrade--topbar {
  padding: 6px 12px;
  font-size: 14px;
}

.ll-main { padding: 14px; }

.ll-dock {
  position: fixed;
  left: 12px; right: 12px; bottom: 12px;
  height: 70px;
  display: flex;
  justify-content: space-between;
  gap: 8px;
  padding: 10px 10px;
  border-radius: 24px;
  background: rgba(255, 255, 255, 0.8);
