}
.ll-dockIcon { font-size: 18px; }
.ll-dockLabel { font-size: 0.875rem; font-weight: 650; opacity: 1; } /* 14px — dock labels — minimum readable with weight 650 */

.ll-overlay {
  position: fixed;
  inset: 0;
  background: rgba(15, 23, 42, 0.3);
  z-index: 50;
}

.ll-sheet {
