  background: rgba(255, 255, 255, 0.75);
  border: 1px solid rgba(15, 23, 42, 0.08);
}
.ll-sheetItem:active { transform: scale(var(--ll-tap)); }
.ll-sheetTitle { font-weight: 750; }
.ll-sheetSub { font-size: 0.9375rem; color: var(--ll-muted); margin-top: 2px; } /* 15px */

.ll-sheetFooter { margin-top: 10px; }
.ll-upgrade--wide { width: 100%; }

.ll-sheetRow {
  width: 100%;
  text-align: left;
  padding: 14px 12px;
  border-radius: 16px;
  background: rgba(255, 255, 255, 0.75);
  border: 1px solid rgba(15, 23, 42, 0.08);
  margin-bottom: 10px;
}
.ll-sheetRow--danger {
  background: linear-gradient(135deg, rgba(240, 106, 91, 0.14), rgba(44, 183, 176, 0.12));
}
.ll-sheetRow:active { transform: scale(var(--ll-tap)); }

.ll-searchOverlay {
  position: fixed;
  inset: 0;
  background: rgba(246, 247, 251, 0.95);
  backdrop-filter: blur(16px);
  z-index: 70;
  display: flex;
  flex-direction: column;
  padding: 14px;
}
.ll-searchTop {
  display: flex;
  gap: 10px;
  align-items: center;
}
.ll-searchInput {
  flex: 1;
  padding: 12px 14px;
  border-radius: 16px;
  border: 1px solid rgba(15, 23, 42, 0.1);
  background: rgba(255, 255, 255, 0.85);
  outline: none;
  box-shadow: 0 10px 22px rgba(15, 23, 42, 0.06);
}
.ll-searchInput:focus-visible {
  @include focus-ring;
}
.ll-ghost {
  padding: 10px 12px;
  border-radius: 14px;
  border: 1px solid rgba(15, 23, 42, 0.1);
  background: rgba(255, 255, 255, 0.65);
}
.ll-searchBody { margin-top: 14px; overflow: auto; padding-bottom: 100px; }
.ll-searchGroup { margin-bottom: 14px; }
.ll-searchGroupTitle { font-weight: 800; margin: 8px 2px; }
.ll-searchRow {
  width: 100%;
  text-align: left;
  padding: 14px 12px;
  border-radius: 16px;
  background: rgba(255, 255, 255, 0.75);
  border: 1px solid rgba(15, 23, 42, 0.08);
  margin-bottom: 10px;
}
.ll-searchRow:active { transform: scale(var(--ll-tap)); }
.ll-muted { color: var(--ll-muted); font-size: 0.9375rem; padding: 8px 2px; } /* 15px */

.ll-orbit { padding-top: 10px; }

.ll-orbitStage {
  position: relative;
  height: min(440px, 58vh);
  border-radius: 28px;
  background: radial-gradient(circle at 50% 60%, rgba(91, 141, 239, 0.18), transparent 55%),
              radial-gradient(circle at 35% 40%, rgba(44, 183, 176, 0.22), transparent 55%),
              radial-gradient(circle at 65% 45%, rgba(240, 106, 91, 0.18), transparent 55%),
              rgba(255, 255, 255, 0.65);
  border: 1px solid rgba(15, 23, 42, 0.1);
  box-shadow: var(--ll-shadow);
  overflow: hidden;
  display: flex;
  align-items: center;
  justify-content: center;
}

.ll-softGlow {
  position: absolute;
  inset: -40%;
  background: radial-gradient(circle at 50% 55%, rgba(255, 255, 255, 0.7), transparent 55%);
  filter: blur(0);
  opacity: 0.9;
}

.ll-rings {
  position: absolute;
  width: 120%;
  height: 120%;
  border-radius: 999px;
  border: 1px solid rgba(255, 255, 255, 0.55);
  box-shadow: inset 0 0 0 1px rgba(15, 23, 42, 0.05);
  opacity: 0.45;
}

.ll-orb {
  position: relative;
  width: 230px;
  height: 230px;
  border-radius: 999px;
