.ll-orbSub { color: var(--ll-muted); font-size: 0.9375rem; } /* 15px */

.ll-chip {
  position: absolute;
  min-width: 160px;
  max-width: 190px;
  text-align: left;
  padding: 12px 12px;
  border-radius: 18px;
