  background: var(--ll-surface);
  border: 1px solid var(--ll-line);
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.9), 0 2px 4px rgba($la-navy, 0.06), 0 6px 16px rgba($la-navy, 0.1);
  font-size: 26px;

  /* Speak mode icon: solid white bg (overrides theme/transparent) */
  &.ll-bento-action-card__icon--speak {
    background: var(--ll-surface) !important;
    border-color: var(--ll-line);
    box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.9), 0 2px 4px rgba($la-navy, 0.06), 0 6px 16px rgba($la-navy, 0.1);
  }
  /* Keep hero size when dashboard icon classes are applied */
  &.ll-bento-action-card__icon {
    width: 62px;
    height: 62px;
    border-radius: 20px;
  }
}
.ll-heroIcon__img {
  width: 36px;
  height: 36px;
  object-fit: contain;
}

.ll-section { margin-top: 14px; }

.ll-carousel {
  display: flex;
  gap: 10px;
  overflow-x: auto;
  padding-bottom: 6px;
  scroll-snap-type: x mandatory;
}
.ll-carousel--even {
  overflow-x: visible;
  scroll-snap-type: none;
  justify-content: space-evenly;
  flex-wrap: wrap;
  padding-bottom: 0;
}
.ll-carousel--even .ll-boardCard {
  scroll-snap-align: none;
  flex: 1 1 160px;
  max-width: 220px;
}
.ll-carousel::-webkit-scrollbar { height: 10px; }
.ll-carousel::-webkit-scrollbar-thumb { background: var(--ll-line); border-radius: 999px; }

.ll-boardCard {
  min-width: 180px;
  scroll-snap-align: start;
  text-align: center;
  padding: 14px 14px;
  border-radius: 22px;
  background: var(--ll-surface);
  border: 1px solid var(--ll-line);
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.9), 0 2px 6px rgba($la-navy, 0.06), 0 8px 24px rgba($la-navy, 0.12);
}
.ll-boardCard:hover {
  background: #F0F0F0;
}
.ll-boardCard:active { transform: scale(var(--ll-tap)); }
.ll-boardCard--new:hover {
  background: #F0F0F0;
}
.ll-boardCard--new {
  background: #95E1DC; /* #7AD9D3 light teal at 20% lighter */
}
.ll-boardCard--new .ll-boardName { color: var(--ll-text); }
.ll-boardName { font-weight: 900; color: var(--ll-text); }
.ll-boardMeta { margin-top: 6px; color: var(--ll-muted); font-size: 0.9375rem; } /* 15px */

.ll-supervisorsBox .ll-sectionTitle {
  font-size: 15px;
  font-weight: 800;
  letter-spacing: 0.02em;
  color: var(--ll-muted);
}
.ll-supervisorsBox {
  margin-top: 12px;
  padding: 18px;
  border-radius: 26px;
  background: linear-gradient(to bottom, var(--ll-bg), var(--ll-surface));
  border: 1px solid var(--ll-line);
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.9), 0 2px 6px rgba($la-navy, 0.06), 0 8px 24px rgba($la-navy, 0.12);
}
/* Three-column layout so supervisor names are centered over the full row */
.ll-sectionHead--withSupervisor {
  display: grid;
  grid-template-columns: 1fr auto 1fr;
  align-items: center;
  gap: 10px;
}
.ll-sectionHead--withSupervisor .ll-sectionHeadLeft {
  display: flex;
  align-items: center;
  gap: 10px;
  min-width: 0;
}
.ll-sectionHead--withSupervisor .ll-sectionHeadSupervisors {
  display: flex;
  justify-content: center;
  align-items: center;
  gap: 10px;
}
.ll-sectionHead--withSupervisor .ll-seeAll {
  justify-self: end;
}
/* Separator between Supervisors label and supervisor list – actual element so shadow applies */
.ll-sectionHeadLeft .ll-sectionTitle {
  margin-right: 4px;
}
.ll-sectionHeadSeparator {
  position: relative;
  display: inline-block;
  width: 1px;
  align-self: stretch;
  min-height: 1.2em;
  margin: 0 12px 0 0;
  background: var(--ll-line);
  /* Same shadow as other section lines (::after), cast to the right */
  box-shadow: 4px 0 10px rgba($la-navy, 0.22),
              8px 0 24px rgba($la-navy, 0.14);
}
/* Light teal band to the right of the line (same as ::before above other section lines) */
.ll-sectionHeadSeparator::after {
  content: '';
  position: absolute;
  left: 100%;
  top: 0;
  bottom: 0;
  width: 3px;
  background: var(--ll-teal-tint);
  pointer-events: none;
}
.ll-mainSupervisor {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 8px 14px;
  border-radius: 999px;
  background: var(--ll-surface);
  border: 1px solid var(--ll-line);
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.9), 0 2px 4px rgba($la-navy, 0.06), 0 4px 12px rgba($la-navy, 0.1);
  font-weight: 700;
  font-size: 14px;
  color: var(--ll-text);
}
.ll-mainSupervisor:hover {
  background: #F0F0F0;
  border-color: var(--ll-line);
}
.ll-mainSupervisor:active { transform: scale(var(--ll-tap)); }
.ll-mainSupervisorName { letter-spacing: 0.01em; }

.ll-grid2 {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 10px;
}

.ll-metricCard {
  text-align: left;
  padding: 14px 14px;
  border-radius: 20px;
  background: var(--ll-surface);
  border: 1px solid var(--ll-line);
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.9), 0 2px 6px rgba($la-navy, 0.06), 0 8px 24px rgba($la-navy, 0.12);
}
.ll-metricCard:hover {
  background: #F0F0F0;
}
.ll-metricCard:active { transform: scale(var(--ll-tap)); }
.ll-metricTitle { font-weight: 900; color: var(--ll-text); }
.ll-sparkline {
  margin-top: 10px;
  width: 100%;
  aspect-ratio: 200 / 60;
  min-height: 52px;
  border-radius: 14px;
  position: relative;
  display: block;
  overflow: hidden;
  border: 1px solid var(--ll-line);
}
.ll-sparklineChart {
  display: block;
  width: 100%;
  height: 100%;
  object-fit: contain;
}
.ll-sparkline--usage {
  background:
    linear-gradient(180deg, var(--ll-teal-tint), transparent 70%),
    var(--ll-navy-tint);
}
.ll-sparkline--sessions {
  background:
    linear-gradient(180deg, var(--ll-coral-tint), transparent 70%),
    var(--ll-navy-tint);
}

.ll-softCard {
  display: flex;
  align-items: center;
  gap: 12px;
  text-align: left;
  padding: 14px 14px;
  border-radius: 20px;
  background: var(--ll-surface);
  border: 1px solid var(--ll-line);
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.9), 0 2px 6px rgba($la-navy, 0.06), 0 8px 24px rgba($la-navy, 0.12);
}
.ll-softCard:hover {
  background: #F0F0F0;
}
.ll-softCard:active { transform: scale(var(--ll-tap)); }
.ll-softCard__icon {
  flex-shrink: 0;
  width: 48px;
  height: 48px;
  border-radius: 14px;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--ll-surface);
  border: 1px solid var(--ll-line);
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.9), 0 2px 4px rgba($la-navy, 0.06), 0 4px 12px rgba($la-navy, 0.08);
}
.ll-softCard__icon--modeling,
.ll-softCard__icon--extras {
  background: var(--ll-surface) !important;
  border-color: var(--ll-line);
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.9), 0 2px 4px rgba($la-navy, 0.06), 0 4px 12px rgba($la-navy, 0.08);
}
.ll-softCard__img {
  width: 28px;
  height: 28px;
  object-fit: contain;
}
.ll-softCard__body { min-width: 0; }
.ll-softTitle { font-weight: 900; }
.ll-softSub { margin-top: 4px; color: var(--ll-muted); font-size: 0.9375rem; } /* 15px */

@media (min-width: 768px) {
  .ll-main { padding: 18px; max-width: 980px; margin: 0 auto; }
  .ll-topbar__inner { max-width: 980px; margin: 0 auto; padding-left: 18px; padding-right: 18px; }
  .ll-shell { padding-bottom: 18px; }
  .ll-orb { width: 260px; height: 260px; }
  .ll-chip { min-width: 200px; }
  .ll-pos--right { right: 26px; }
  .ll-pos--left { left: 26px; }
  .ll-dock { max-width: 640px; margin: 0 auto; left: 0; right: 0; }
}

