// =============================================================================
// AAC SPEECH PAGE — Mixins
// _mixins.scss
// =============================================================================

@mixin aac-respond-to($bp) {
  @if $bp == 'sm'  { @media (max-width: #{$aac-breakpoint-sm})  { @content; } }
  @if $bp == 'md'  { @media (max-width: #{$aac-breakpoint-md})  { @content; } }
  @if $bp == 'lg'  { @media (max-width: #{$aac-breakpoint-lg})  { @content; } }
  @if $bp == 'xl'  { @media (max-width: #{$aac-breakpoint-xl})  { @content; } }
  @if $bp == 'md+' { @media (min-width: #{$aac-breakpoint-md})  { @content; } }
  @if $bp == 'lg+' { @media (min-width: #{$aac-breakpoint-lg})  { @content; } }
}

@mixin aac-font-display($size: $aac-font-size-xl, $weight: $aac-font-weight-regular) {
  font-family: $aac-font-display;
  font-size: $size;
  font-weight: $weight;
  line-height: $aac-line-height-tight;
}

@mixin aac-font-body($size: $aac-font-size-base, $weight: $aac-font-weight-regular) {
  font-family: $aac-font-body;
  font-size: $size;
  font-weight: $weight;
  line-height: $aac-line-height-base;
}

@mixin aac-label-caps {
  font-family: $aac-font-body;
  font-size: $aac-font-size-xs;
  font-weight: $aac-font-weight-black;
  letter-spacing: $aac-letter-spacing-wider;
  text-transform: uppercase;
}

@mixin aac-flex-center {
  display: flex;
  align-items: center;
  justify-content: center;
}

@mixin aac-flex-between {
  display: flex;
  align-items: center;
  justify-content: space-between;
}

@mixin aac-flex-start {
  display: flex;
  align-items: center;
  justify-content: flex-start;
}

@mixin aac-surface($bg: white, $border: true) {
  background: $bg;
  border-radius: $aac-radius-lg;
  @if $border {
    border: 1px solid $color-border;
  }
}

@mixin aac-card-hover {
  transition: transform $aac-transition-base, box-shadow $aac-transition-base, border-color $aac-transition-base;
  &:hover {
    transform: translateY(-3px);
    box-shadow: $aac-shadow-lg;
    border-color: $color-text-ghost;
  }
  &:active {
    transform: scale(0.97);
    box-shadow: $aac-shadow-sm;
  }
}

@mixin aac-focus-ring($color: $brand-smart-blue) {
  &:focus-visible {
    /* Keyboard ring: app-wide #within_ember *:focus-visible; optional accent glow */
    box-shadow: 0 0 0 3px rgba($color, 0.4);
  }
}

@mixin aac-sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}
.sr-only { @include aac-sr-only; }

@mixin aac-btn-base {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: $aac-spacing-8;
  font-family: $aac-font-body;
  font-weight: $aac-font-weight-bold;
  border: none;
  cursor: pointer;
  border-radius: $aac-radius-md;
  transition: background $aac-transition-fast, transform $aac-transition-fast, box-shadow $aac-transition-fast;
  user-select: none;

  &:active { transform: scale(0.97); }
  @include aac-focus-ring;
}

@mixin aac-btn-primary {
  @include aac-btn-base;
  background: $brand-smart-blue;
  color: white;
  padding: $aac-spacing-10 $aac-spacing-20;
  font-size: $aac-font-size-sm;

  &:hover { background: $brand-smart-blue; }
  &:disabled {
    background: $color-text-ghost;
    cursor: not-allowed;
    transform: none;
  }
}

@mixin aac-btn-secondary {
  @include aac-btn-base;
  background: transparent;
  color: $color-text-mid;
  border: 1.5px solid $color-border-strong;
  padding: $aac-spacing-8 $aac-spacing-14;
  font-size: $aac-font-size-sm;

  &:hover {
    background: $color-surface;
    border-color: $color-text-ghost;
    color: $color-text;
  }
}

@mixin aac-btn-ghost {
  @include aac-btn-base;
  background: rgba(white, 0.08);
  color: $color-text-ghost;
  border: 1.5px solid rgba(white, 0.15);
  padding: $aac-spacing-8 $aac-spacing-14;
  font-size: $aac-font-size-sm;

  &:hover {
    background: rgba(white, 0.14);
    color: white;
  }
}

@mixin aac-custom-scrollbar($width: 6px, $color: $color-text-ghost) {
  &::-webkit-scrollbar         { width: $width; }
  &::-webkit-scrollbar-track   { background: transparent; }
  &::-webkit-scrollbar-thumb   { background: $color; border-radius: $aac-radius-pill; }
}

@mixin aac-truncate {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

@mixin aac-progress-bar($color: $brand-smart-blue, $height: 8px) {
  height: $height;
  background: $color-border;
  border-radius: $aac-radius-pill;
  overflow: hidden;

  .progress__fill {
    height: 100%;
    background: $color;
    border-radius: $aac-radius-pill;
    transition: width 0.6s ease;
  }
}

// =============================================================================
// AAC SPEECH PAGE — Base & Reset
// _base.scss
// =============================================================================

.app-shell {
  @include aac-font-body($aac-font-size-base, $aac-font-weight-regular);
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  @include aac-custom-scrollbar;

  h1, h2, h3, h4, h5, h6 {
    font-family: $aac-font-display;
    font-weight: $aac-font-weight-regular;
    line-height: $aac-line-height-tight;
    color: $color-text;
  }

  h1 { font-size: $aac-font-size-2xl; }
  h2 { font-size: $aac-font-size-xl; }
  h3 { font-size: $aac-font-size-lg; }
  h4 { font-size: $aac-font-size-md; }
  h5 { font-size: $aac-font-size-base; }
  h6 { font-size: $aac-font-size-sm; }

  p {
    line-height: $aac-line-height-loose;
    color: $color-text-mid;
  }
}

.aac-section-label {
  @include aac-label-caps;
  color: $color-text-ghost;
  margin-bottom: $aac-spacing-4;
}

// =============================================================================
// AAC SPEECH PAGE — App Shell Layout
// components/_app-shell.scss
// =============================================================================

.app-shell {
  display: grid;
  grid-template-rows: $aac-topbar-height 1fr;
  grid-template-columns: $aac-sidebar-width 1fr $aac-panel-width;
  grid-template-areas:
    "topbar  topbar  topbar"
    "sidebar main    panel";
  height: 100vh;
  overflow: hidden;

  @include aac-respond-to('lg') {
    grid-template-columns: $aac-sidebar-width 1fr;
    grid-template-areas:
      "topbar  topbar"
      "sidebar main";

    .app-panel { display: none; }
  }

  @include aac-respond-to('md') {
    grid-template-columns: 1fr;
    grid-template-rows: $aac-topbar-height 1fr;
    grid-template-areas:
      "topbar"
      "main";

    .app-sidebar { display: none; }
  }
}

.app-topbar {
  grid-area: topbar;
  background: $indigo;
  @include aac-flex-start;
  padding: 0 $aac-spacing-24;
  gap: $aac-spacing-20;
  border-bottom: 2px solid $indigo;
  z-index: $aac-z-topbar;
}

.topbar__logo {
  @include aac-font-display($aac-font-size-lg);
  color: $brand-smart-blue;
  letter-spacing: $aac-letter-spacing-base;
  flex-shrink: 0;

  span {
    color: $color-sand-light;
    font-style: italic;
  }
}

.topbar__search {
  flex: 1;
  max-width: 400px;
  background: rgba(white, 0.08);
  border: 1px solid rgba(white, 0.15);
  border-radius: $aac-radius-md;
  padding: $aac-spacing-8 $aac-spacing-16;
  color: white;
  font-size: $aac-font-size-sm;
  outline: none;
  transition: background $aac-transition-fast;

  &::placeholder { color: $brand-slate-gray; }
  &:focus-visible {
    background: rgba(white, 0.12);
    @include focus-ring;
  }
}

.topbar__right {
  margin-left: auto;
  @include aac-flex-start;
  gap: $aac-spacing-12;
}

.topbar__badge {
  background: $color-sand;
  color: $indigo;
  font-size: $aac-font-size-xs;
  font-weight: $aac-font-weight-black;
  padding: $aac-spacing-4 $aac-spacing-10;
  border-radius: $aac-radius-pill;
  letter-spacing: $aac-letter-spacing-wide;
}

.topbar__badge--non-clinical {
  background: $brand-smart-blue;
  color: white;
}

.topbar__avatar {
  width: 36px;
  height: 36px;
  border-radius: $aac-radius-circle;
  background: linear-gradient(135deg, $brand-smart-blue, $brand-smart-blue);
  @include aac-flex-center;
  color: white;
  font-weight: $aac-font-weight-bold;
  font-size: $aac-font-size-sm;
  cursor: pointer;
  transition: opacity $aac-transition-fast;

  &:hover { opacity: 0.85; }
}

.app-sidebar {
  grid-area: sidebar;
  background: $color-surface;
  border-right: 1px solid $color-border;
  padding: $aac-spacing-20 $aac-spacing-12;
  overflow-y: auto;
  display: flex;
  flex-direction: column;
  gap: $aac-spacing-6;
  @include aac-custom-scrollbar;
}

.sidebar__section-label {
  @include aac-label-caps;
  color: $color-text-ghost;
  padding: $aac-spacing-10 $aac-spacing-12 $aac-spacing-4;
  margin-top: $aac-spacing-8;

  &:first-child { margin-top: 0; }
}

.nav-item {
  @include aac-flex-start;
  gap: $aac-spacing-10;
  padding: $aac-spacing-10 $aac-spacing-14;
  border-radius: $aac-radius-md;
  cursor: pointer;
  font-size: $aac-font-size-sm;
  font-weight: $aac-font-weight-semi;
  color: $color-text-mid;
  border: 1.5px solid transparent;
  transition: all $aac-transition-base;
  user-select: none;

  &:hover {
    background: $color-border;
    color: $color-text;
  }

  &.active {
    background: $color-sage-pale;
    color: $brand-smart-blue;
    border-color: $brand-smart-blue;
  }

  @include aac-focus-ring;
}

.nav-item__icon {
  font-size: 18px;
  width: 24px;
  text-align: center;
  flex-shrink: 0;
}

.app-main {
  grid-area: main;
  overflow-y: auto;
  padding: $aac-spacing-28;
  background: $color-background;
  @include aac-custom-scrollbar;
}

.main__title {
  @include aac-font-display($aac-font-size-xl);
  color: $color-text;
  margin-bottom: $aac-spacing-6;
}

.main__subtitle {
  font-size: $aac-font-size-sm;
  color: $color-text-muted;
  margin-bottom: $aac-spacing-24;
}

.app-panel {
  grid-area: panel;
  background: $color-surface;
  border-left: 1px solid $color-border;
  padding: $aac-spacing-24 $aac-spacing-20;
  overflow-y: auto;
  display: flex;
  flex-direction: column;
  gap: $aac-spacing-20;
  @include aac-custom-scrollbar;
}

.panel-card {
  @include aac-surface(white);
  padding: $aac-spacing-16;

  &__title {
    @include aac-label-caps;
    color: $color-text-muted;
    margin-bottom: $aac-spacing-12;
  }
}

// =============================================================================
// AAC SPEECH PAGE — Phrase Bar
// components/_phrase-bar.scss
// =============================================================================

.phrase-bar {
  background: $indigo;
  border-radius: $aac-radius-xl;
  padding: $aac-spacing-16 $aac-spacing-20;
  @include aac-flex-start;
  gap: $aac-spacing-14;
  margin-bottom: $aac-spacing-24;
  min-height: 64px;
  box-shadow: $aac-shadow-md;
}

.phrase-bar__tokens {
  flex: 1;
  display: flex;
  flex-wrap: wrap;
  gap: $aac-spacing-6;
  align-items: center;
}

.phrase-bar__placeholder {
  font-size: $aac-font-size-md;
  color: $brand-slate-gray;
  font-style: italic;
  font-weight: $aac-font-weight-light;
}

.phrase-token {
  display: inline-flex;
  align-items: center;
  gap: $aac-spacing-4;
  padding: $aac-spacing-4 $aac-spacing-10;
  border-radius: $aac-radius-sm;
  font-size: $aac-font-size-md;
  font-weight: $aac-font-weight-semi;
  color: white;
  cursor: pointer;
  transition: opacity $aac-transition-fast;
  position: relative;

  &:hover {
    opacity: 0.8;

    .phrase-token__remove { opacity: 1; }
  }
}

.phrase-token__remove {
  opacity: 0;
  font-size: $aac-font-size-xs;
  color: rgba(white, 0.7);
  transition: opacity $aac-transition-fast;
  cursor: pointer;
  padding: 0 $aac-spacing-2;

  &:hover { color: white; }
}

@each $name, $vals in $categories {
  .phrase-token--#{$name} {
    color: color.adjust(list.nth($vals, 1), $lightness: 20%);
  }
}

.phrase-bar__actions {
  display: flex;
  gap: $aac-spacing-8;
  flex-shrink: 0;
}

.btn-speak {
  @include aac-btn-primary;
  padding: $aac-spacing-10 $aac-spacing-20;
  font-size: $aac-font-size-sm;
  border-radius: $aac-radius-md;

  &--large {
    padding: $aac-spacing-14 $aac-spacing-28;
    font-size: $aac-font-size-base;
    border-radius: $aac-radius-lg;
  }
}

.btn-clear {
  @include aac-btn-ghost;
  padding: $aac-spacing-8 $aac-spacing-14;
}

.btn-backspace {
  @include aac-btn-ghost;
  padding: $aac-spacing-8 $aac-spacing-12;
  border-radius: $aac-radius-md;
}

// =============================================================================
// AAC SPEECH PAGE — Symbol Board
// components/_symbol-board.scss
// =============================================================================

.category-row {
  display: flex;
  gap: $aac-spacing-8;
  flex-wrap: wrap;
  margin-bottom: $aac-spacing-24;
}

.cat-chip {
  padding: $aac-spacing-6 $aac-spacing-16;
  border-radius: $aac-radius-pill;
  font-size: $aac-font-size-xs;
  font-weight: $aac-font-weight-bold;
  cursor: pointer;
  border: 2px solid transparent;
  transition: all $aac-transition-base;
  opacity: 0.72;
  user-select: none;

  &:hover,
  &.active {
    opacity: 1;
    transform: translateY(-1px);
  }

  &.all {
    background: $indigo;
    color: white;
    opacity: 1;

    &:hover { background: $indigo; }
  }

  @include aac-focus-ring;
}

@each $name, $vals in $categories {
  .cat-chip.#{$name} {
    background:   list.nth($vals, 2);
    color:        list.nth($vals, 3);
    border-color: list.nth($vals, 1);
  }
}

.quick-row {
  display: flex;
  gap: $aac-spacing-8;
  flex-wrap: wrap;
  margin-bottom: $aac-spacing-24;
}

.quick-btn {
  @include aac-btn-secondary;
  border-radius: $aac-radius-md;
  font-size: $aac-font-size-sm;

  &:hover {
    background: $color-sage-pale;
    border-color: $brand-smart-blue;
    color: $brand-smart-blue;
  }
}

.symbol-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(120px, 1fr));
  gap: $aac-spacing-14;
  margin-bottom: $aac-spacing-32;

  @include aac-respond-to('sm') {
    grid-template-columns: repeat(3, 1fr);
    gap: $aac-spacing-10;
  }
}

.symbol-card {
  background: white;
  border-radius: $aac-radius-xl;
  padding: $aac-spacing-16 $aac-spacing-12 $aac-spacing-12;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: $aac-spacing-10;
  cursor: pointer;
  border: 2px solid $color-border;
  position: relative;
  overflow: hidden;
  @include aac-card-hover;
  @include aac-focus-ring;

  &::before {
    content: '';
    position: absolute;
    top: 0; left: 0; right: 0;
    height: 4px;
  }
}

@each $name, $vals in $categories {
  .symbol-card--#{$name} {
    &::before { background: list.nth($vals, 1); }

    .symbol-card__icon-wrap { background: list.nth($vals, 2); }

    &:hover { border-color: color.adjust(list.nth($vals, 1), $lightness: 18%); }
  }
}

.symbol-card__icon-wrap {
  width: 60px;
  height: 60px;
  border-radius: $aac-radius-lg;
  @include aac-flex-center;
  font-size: 32px;
  flex-shrink: 0;
  transition: transform $aac-transition-fast;

  .symbol-card:hover & { transform: scale(1.06); }
}

.symbol-card__icon-img {
  width: 44px;
  height: 44px;
  object-fit: contain;
}

.symbol-card__label {
  font-size: $aac-font-size-sm;
  font-weight: $aac-font-weight-bold;
  color: $color-text;
  text-align: center;
  line-height: $aac-line-height-tight;
  @include aac-truncate;
  max-width: 100%;
}

.symbol-card--sm {
  padding: $aac-spacing-10 $aac-spacing-8 $aac-spacing-8;
  gap: $aac-spacing-6;

  .symbol-card__icon-wrap {
    width: 44px;
    height: 44px;
    font-size: 24px;
  }

  .symbol-card__label { font-size: $aac-font-size-xs; }
}

.symbol-card--lg {
  padding: $aac-spacing-24 $aac-spacing-20 $aac-spacing-16;
  gap: $aac-spacing-14;

  .symbol-card__icon-wrap {
    width: 80px;
    height: 80px;
    font-size: 44px;
    border-radius: $aac-radius-xl;
  }

  .symbol-card__label { font-size: $aac-font-size-base; }
}

.symbol-card--skeleton {
  background: $color-linen;
  animation: aac-skeleton-pulse 1.4s ease-in-out infinite;
  height: 140px;
  pointer-events: none;

  &::before { display: none; }
}

@keyframes aac-skeleton-pulse {
  0%, 100% { opacity: 1; }
  50%       { opacity: 0.45; }
}

.symbol-grid__empty {
  grid-column: 1 / -1;
  text-align: center;
  padding: $aac-spacing-48 $aac-spacing-24;
  color: $color-text-muted;

  p { margin-bottom: $aac-spacing-12; }

  button {
    @include aac-btn-secondary;
  }
}

// =============================================================================
// AAC SPEECH PAGE — Panel Components
// components/_panel.scss
// =============================================================================

.recent-phrase-list {
  display: flex;
  flex-direction: column;
}

.recent-phrase {
  @include aac-flex-start;
