}

.recent-phrase__time {
  margin-left: auto;
  font-size: $aac-font-size-xs;
  color: $color-text-ghost;
  flex-shrink: 0;
}

.progress-list {
  display: flex;
  flex-direction: column;
  gap: $aac-spacing-12;
}

.progress-item__header {
  @include aac-flex-between;
  margin-bottom: $aac-spacing-4;
}

.progress-item__label {
  font-size: $aac-font-size-sm;
  font-weight: $aac-font-weight-bold;
  color: $color-text-mid;
}

.progress-item__value {
  font-size: $aac-font-size-xs;
  font-weight: $aac-font-weight-bold;
