.la-pricing-preview-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: $aac-spacing-24;
  width: 100%;
  max-width: 1200px;
  margin: 0 auto;
}

/* 2 columns: first two cards in a row, third wraps and fills the next line */
@media (max-width: $aac-breakpoint-lg) {
  .la-pricing-preview-grid,
  .pricing-wrapper.la-pricing-preview-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: $aac-spacing-20;
    max-width: 100%;
  }

  /* 3rd card spans full row when it wraps, so it's wider than each of the first two */
  .pricing-wrapper.la-pricing-preview-grid .pricing-card:nth-child(3) {
    grid-column: 1 / -1;
  }
}

/* Stack all pricing cards on small screens */
@media (max-width: $aac-breakpoint-md) {
  .la-pricing-preview-grid,
  .pricing-wrapper.la-pricing-preview-grid {
    grid-template-columns: 1fr;
    gap: $aac-spacing-16;
    max-width: 100%;
  }

  .pricing-wrapper.la-pricing-preview-grid .pricing-card:nth-child(3) {
    grid-column: auto;
    max-width: none;
    margin-left: 0;
    margin-right: 0;
  }
}

.la-pricing-card {
  display: flex;
  flex-direction: column;
  align-items: center;
  text-align: center;
  will-change: transform; // GPU layer — prevents backdrop-filter recompute on scroll
  transform: translateY(-6px);
  transition: transform 0.35s ease, box-shadow 0.35s ease, background 0.35s ease;

  &:hover {
    transform: translateY(-12px);
  }
}

/* Bottom-align CTA button in each pricing card (grid gives equal-height cards) */
.pricing-card .cta,
.la-pricing-card .cta {
  margin-top: auto;
  padding-top: $aac-spacing-20;
}

.la-pricing-card__prices {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 0.25rem;
  margin: $aac-spacing-16 0;
  padding: $aac-spacing-12 0;
  border-top: 1px solid rgba(0, 0, 0, 0.08);
  border-bottom: 1px solid rgba(0, 0, 0, 0.08);
  width: 100%;
}

/* Communicator card: two price options side by side with divider in the middle */
.pricing-card--communicator .price-block:not(.single).la-pricing-card__prices {
  flex-direction: row;
  flex-wrap: wrap;
  justify-content: center;
  align-items: center;
  gap: $aac-spacing-12;
}

.pricing-card--communicator .price-block:not(.single) .or-divider {
  margin: 0;
}

.la-pricing-card__price-row {
  display: flex;
  flex-direction: column;
  align-items: center;
}

/* Pricing page card structure (pricing-wrapper / pricing-card) */
.pricing-wrapper {
  list-style: none;
  padding: 0;
  margin: 0;
}

.pricing-card {
  position: relative;

  .pricing-card__badge,
  .badge {
    position: absolute;
    top: 0.55rem;
    right: 0.75rem;
    font-size: 14px;
    font-weight: 600;
    text-transform: uppercase;
    letter-spacing: 0.05em;
    padding: 4px 10px;
    border-radius: 999px;
    background: rgba($brand-teal, 0.2);
    color: $brand-stormy-teal;
  }

  .plan-subtitle {
    margin: 0 0 1rem;
  }

  .price-block {
    &.single .price-option {
      margin: 0 auto;
    }
  }

  .or-divider {
    margin: 0.5rem 0;
    font-size: 14px;
    color: rgba(0, 0, 0, 0.5);
  }

  .feature-list {
    list-style: none;
    padding: 0;
    margin: 1rem 0;
    text-align: left;
    width: 100%;

    li {
      padding: 0.35em 0;
      font-size: 15px;
      line-height: 1.4;
    }
  }

  .cta {
    display: inline-block;
    margin-top: auto; /* bottom-align with other cards; padding from .pricing-card .cta, .la-pricing-card .cta */
    padding: 12px 24px;
    border-radius: 8px;
    font-weight: 600;
    text-decoration: none;
    text-align: center;
    transition: opacity 0.15s ease;

    &:hover {
      opacity: 0.9;
    }

    &.primary {
      background: var(--fs-dark-teal, $brand-verdigris);
      color: #fff;
      border: none;
    }

    &.secondary {
      background: transparent;
      color: var(--fs-dark-teal, $brand-verdigris);
      border: 2px solid var(--fs-dark-teal, $brand-verdigris);
    }
  }
}

.la-pricing-card__amount {
  font-family: 'Lexend', 'Nunito Sans', system-ui, sans-serif;
  font-size: 36px;
  font-weight: $aac-font-weight-black;
  color: $indigo;
  line-height: 1.1;
}

.la-pricing-card__currency {
  font-size: 18px;
  font-weight: $aac-font-weight-semi;
  color: #888;
  vertical-align: middle;
}

.la-pricing-card__term {
  font-size: 14px;
  color: $brand-charcoal-dark;
  font-weight: $aac-font-weight-medium;
  margin-top: 2px;
}

.la-pricing-card__or {
  font-size: 16px;
  color: rgba($brand-charcoal-dark, 0.6);
  padding: 0.25rem 0;
}

.price-strikethrough {
  text-decoration: line-through;
}

.la-pricing-table-layout {
  grid-template-columns: 1fr 2fr;
}

@media (max-width: $aac-breakpoint-lg) {
  .la-pricing-table-layout {
    grid-template-columns: 1fr;
  }
}

.la-pricing-table-wrap {
  overflow-x: auto;
  -webkit-overflow-scrolling: touch;
  padding: $aac-spacing-4;

  .subscription_table {
    max-width: 100%;
  }
}

.la-pricing-table-wrap--full {
  width: 100%;
  margin-bottom: 3rem;

  form.row {
    max-width: 760px !important;
    margin: 0 auto;
    padding: 0 $aac-spacing-16;
  }

  .subscription_table {
    margin: 0 auto;
  }

  .la-pricing-trial-hint,
  .la-pricing-actions {
    max-width: 760px;
    margin-left: auto;
    margin-right: auto;
  }
}

.la-plan-text--centered {
  text-align: center;
  max-width: 640px;
  margin: 0 auto $aac-spacing-32;

  .la-plan-title,
  .la-plan-subtitle {
    max-width: 100%;
  }

  .la-plan-title {
    text-align: center;
    margin-left: auto;
    margin-right: auto;
    max-width: 100%; /* same width as .la-plan-subtitle (override base 90%) */
  }
}

.la-wrapper .la-plan-text--centered .la-plan-title {
  max-width: 100%;
}

// Pricing: "Compare plans in detail" — same size as "Simple, honest pricing" hero title
.la-wrapper.la-wrapper--pricing .la-plan-text--centered .la-plan-title {
  font-size: 35px;
  font-weight: $aac-font-weight-black;
  letter-spacing: -0.035em;
  line-height: 1.05;
  color: $indigo;
  margin: 0 0 $aac-spacing-16;

  em {
    color: $brand-smart-blue;
  }

  @media (max-width: 1366px) { font-size: 27px; }
  @media (max-width: 1200px) { font-size: 24px; }
  @media (max-width: 1024px) { font-size: 20px; }
  @media (max-width: 768px)  { font-size: 20px; }
  @media (max-width: 480px)  { font-size: 17px; }
}

.la-wrapper.la-wrapper--pricing .la-plan-text--centered .la-about-hero-separator {
  margin: 0 auto $aac-spacing-24;
}

.la-pricing-trial-hint {
  text-align: center;
  font-size: 18px;
  color: $color-text-muted;
  margin: $aac-spacing-40 0 $aac-spacing-8;
}

.la-pricing-actions {
  display: flex;
  gap: $aac-spacing-16;
  justify-content: center;
  flex-wrap: wrap;
  margin-top: $aac-spacing-24;
}

// Pricing page: larger bottom margin for Full Comparison and Plans sections
.la-wrapper.la-wrapper--pricing .la-plan-section {
  margin-bottom: $aac-spacing-64;
}
.la-wrapper.la-wrapper--pricing .la-section {
  margin-top: calc(#{$aac-spacing-48} * 1.2);
  padding-top: $aac-spacing-32;
  margin-bottom: 0;
  align-items: center;
}

// Pricing page: Plans section badge — larger bottom margin; entrance from left on load
.la-wrapper.la-wrapper--pricing .la-section .la-section-header .la-section-eyebrow-badge {
  margin-bottom: 2.5rem;
  opacity: 0;
  transform: translateX(-36px);
  animation: la-hero-title-from-left 0.6s cubic-bezier(0.25, 0.46, 0.45, 0.94) forwards;
}

.la-wrapper.la-wrapper--pricing .la-section .la-section-header .la-hero-title-wrap {
  opacity: 0;
  transform: translateX(-36px);
  animation: la-hero-title-from-left 0.6s cubic-bezier(0.25, 0.46, 0.45, 0.94) 0.15s forwards;
}

// Pricing page: "Choose your plan" — same size as hero and Compare plans headers, same separator
.la-wrapper.la-wrapper--pricing .la-section .la-section-header .la-section-title {
  font-size: 35px;
  color: $indigo;
  letter-spacing: -0.035em;
  line-height: 1.05;
  margin: 0;

  em {
    color: $brand-smart-blue;
  }

  @media (max-width: 1366px) { font-size: 27px; }
  @media (max-width: 1200px) { font-size: 24px; }
  @media (max-width: 1024px) { font-size: 20px; }
  @media (max-width: 768px)  { font-size: 20px; }
  @media (max-width: 480px)  { font-size: 17px; }
}
.la-wrapper.la-wrapper--pricing .la-section .la-section-header .la-hero-title {
  margin-bottom: $aac-spacing-16;
  font-weight: normal;
  text-align: center;
}
.la-wrapper.la-wrapper--pricing .la-section .la-section-header .la-about-hero-separator {
  margin: 0 auto 0;
  margin-top: -2rem;
  margin-bottom: 0;
}
.la-wrapper.la-wrapper--pricing .la-section .la-section-header {
  margin-bottom: 0;
  max-width: 748px;
  margin-left: auto;
  margin-right: auto;
  padding-left: 1rem;
  padding-right: 1rem;
  width: 100%;
  box-sizing: border-box;
  text-align: center;
}

.la-wrapper.la-wrapper--pricing .la-section .la-section-header .la-hero-title-wrap {
  margin-left: auto;
  margin-right: auto;
}
.la-pricing-cloud-extras-cta {
  display: flex;
  justify-content: center;
  margin: 0 auto $aac-spacing-24;
  padding: 0 1rem;
  max-width: 748px;
  box-sizing: border-box;
}

/* Pricing cards: cloud extras open-modal control reads clearly as a link */
.la-wrapper.la-wrapper--pricing .la-pricing-card__cloud-extras-link {
  font-weight: $aac-font-weight-semi;
  text-decoration: none;
  border-bottom-width: 2px;
  border-bottom-style: solid;
  border-bottom-color: rgba($brand-verdigris, 0.55);
  padding-bottom: 1px;

  &:hover,
  &:focus-visible {
    border-bottom-color: var(--fs-dark-teal, $brand-verdigris);
    color: color.adjust($brand-verdigris, $lightness: -8%);
    outline: none;
  }

  &:focus-visible {
    box-shadow: 0 0 0 2px rgba(255, 255, 255, 0.9), 0 0 0 4px var(--fs-dark-teal, $brand-verdigris);
    border-radius: 2px;
  }
}

.la-wrapper.la-wrapper--pricing .la-section .la-pricing-preview-grid {
  margin-top: 0;
}

.la-wrapper .la-main {
  width: 100%;
  max-width: 100%;
  margin-left: 0;
  margin-right: 0;
  padding-left: calc(#{$aac-spacing-28} + 5rem);
  padding-right: calc(#{$aac-spacing-28} + 5rem);
  overflow-y: visible;
  background: linear-gradient(180deg, #f2f3f5 0%, #e6e8ec 50%, #d8dce0 100%);
}

// ── Font overrides (toggled via controller) ─────────────────────────────────
.la-wrapper.la-font--atkinson {
  font-family: 'Atkinson Hyperlegible', sans-serif !important;

  h1, h2, h3, h4, h5, h6,
  p, a, span, li, blockquote,
  .la-hero-title, .la-section-title, .la-stat-number,
  .la-feature-card h3, .la-cta-title, .la-logo,
  .la-btn, .la-topbar-link, .la-topbar-cta,
  .la-plan-title, .la-cta-headline,
  .la-testimonial-display-text, .la-testimonial-mark {
    font-family: 'Atkinson Hyperlegible', sans-serif !important;
  }
}

.la-wrapper.la-font--lexend {
  font-family: 'Lexend', sans-serif !important;

  h1, h2, h3, h4, h5, h6,
  p, a, span, li, blockquote,
  .la-hero-title, .la-section-title, .la-stat-number,
  .la-feature-card h3, .la-cta-title, .la-logo,
  .la-btn, .la-topbar-link, .la-topbar-cta,
  .la-plan-title, .la-cta-headline,
  .la-testimonial-display-text, .la-testimonial-mark {
    font-family: 'Lexend', sans-serif !important;
  }
}

// ── Color tokens (re-use landing palette) ────────────────────────────────
// $la-* color tokens, two-tone logo, and shadow scale defined in _variables.scss

// ── Topbar ───────────────────────────────────────────────────────────────────
.la-topbar {
  grid-area: topbar;
  position: sticky;
  top: 0;
  background: color.adjust($indigo, $lightness: -6%);
  display: flex;
  align-items: center;
  min-height: 92px;
  padding: 0 $aac-spacing-24;
  gap: 32px; /* logo to nav links */
  border-bottom: 1px solid color.adjust($indigo, $lightness: -6%);
  z-index: $aac-z-topbar;
}

.la-logo {
  display: flex;
  align-items: center;
  gap: 8px;
  font-family: 'Lexend', 'Nunito Sans', system-ui, sans-serif;
  font-size: $aac-font-size-lg;
  font-weight: $aac-font-weight-black;
  letter-spacing: $aac-letter-spacing-base;
  white-space: nowrap;
  flex-shrink: 0;
  text-decoration: none;

  .app-logo__lingo,
  & > span:first-child { color: $la-logo-left; }
  .app-logo__linq,
  & > span:last-child { color: $la-logo-right; font-style: italic; }

  &:hover { text-decoration: none; }
}

/* App-logo wordmark (footer, etc.): same two-tone */
.app-logo__lingo { color: $la-logo-left; }
.app-logo__linq { color: $la-logo-right; font-style: italic; }

.la-logo-img {
  height: 37px;
  width: auto;
}

.la-topbar-nav {
  display: flex;
  align-items: center;
  gap: 32px; /* nav link to nav link */
  margin-left: 0;

  &::before {
    content: '';
    display: block;
    width: 1px;
    height: 20px;
    background: rgba(white, 0.3);
    margin-right: 0;
  }
}

/* Logo to nav 32px when nav is inside .app-navbar (no .la-topbar gap) */
.app-navbar .la-topbar-nav {
  margin-left: 31px; /* 31px + 1px separator = 32px to first link */
}

.la-topbar-link {
  color: rgba(white, 0.7) !important;

  font-size: 14px; /* 20% smaller than 17px */
  font-weight: $aac-font-weight-semi !important;

  padding: $aac-spacing-6 $aac-spacing-12;
  border-radius: $aac-radius-md;
  text-decoration: none;
  transition: color 0.15s ease, background 0.15s ease;

  &:hover {
    color: white;
    background: rgba(white, 0.08);
    text-decoration: none;
  }

  &.active {
    color: white;
  }
}

.la-topbar-link:focus-visible {
  @include focus-ring;
}

.la-topbar-alt-link {
  color: rgba(white, 0.75);
  font-size: 14px;
  font-weight: $aac-font-weight-semi;
  padding: $aac-spacing-4 $aac-spacing-8;
  border-radius: $aac-radius-md;
  text-decoration: none;
  margin-left: $aac-spacing-4;
  transition: color 0.15s ease, background 0.15s ease;

  &:hover {
    color: rgba(white, 0.7);
    background: rgba(white, 0.06);
    text-decoration: none;
  }
}

.la-topbar-alt-link:focus-visible {
  @include focus-ring;
}

.la-topbar-right {
  display: flex;
  align-items: center;
  gap: 16px; /* right CTA gap */
}

/* ── Hamburger button (hidden on desktop, shown ≤1024px) ── */
.la-topbar-hamburger {
  display: none;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  width: 38px;
  height: 38px;
  margin-right: 24px;
  padding: 0;
  background: rgba(255, 255, 255, 0.10);
  border: 1px solid rgba(255, 255, 255, 0.18);
  border-radius: 10px;
  cursor: pointer;
  transition: background 0.2s ease, border-color 0.2s ease;

  &:hover {
    background: rgba(255, 255, 255, 0.18);
    border-color: rgba(255, 255, 255, 0.3);
  }
  &:focus-visible {
    background: rgba(255, 255, 255, 0.18);
    border-color: rgba(255, 255, 255, 0.3);
    @include focus-ring;
  }
}

.la-topbar-hamburger__bar {
  display: block;
  width: 18px;
  height: 2px;
  background: rgba(255, 255, 255, 0.9);
  border-radius: 1px;

  & + & {
    margin-top: 4px;
  }
}

/* Footer hamburger sits on a light background — override the white bars from
   the base rule (designed for the dark topbar) with a dark color. */
.la-footer__hamburger .la-topbar-hamburger__bar {
  background: $brand-charcoal-dark;
}

/* ── Mobile drawer (slide-in from right) ── */
.la-mobile-drawer {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  z-index: 10000;
}

.la-mobile-drawer__backdrop {
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  background: rgba($indigo, 0.35);
  animation: la-drawer-fade-in 0.25s ease forwards;
}

@keyframes la-drawer-fade-in {
  from { opacity: 0; }
  to { opacity: 1; }
}

.la-mobile-drawer__panel {
  position: absolute;
  top: 0;
  right: 0;
  width: auto;
  height: 100%;
  background: #fff;
  box-shadow: -4px 0 24px rgba($indigo, 0.15);
  padding: 56px 40px 32px 32px;
  display: flex;
  flex-direction: column;
  gap: 4px;
  animation: la-drawer-slide-in 0.28s cubic-bezier(0.4, 0, 0.2, 1) forwards;
  /* Scroll when content exceeds viewport height (tall footer menus on short screens). */
  overflow-y: auto;
  overflow-x: hidden;
  -webkit-overflow-scrolling: touch;
  overscroll-behavior: contain;
}

@keyframes la-drawer-slide-in {
  from { transform: translateX(100%); }
  to { transform: translateX(0); }
}

.la-mobile-drawer__close {
  position: absolute;
  top: 16px;
  right: 16px;
  width: 44px;
  height: 44px;
  display: flex;
  align-items: center;
  justify-content: center;
  background: transparent;
  border: 1px solid rgba($indigo, 0.1);
  border-radius: 10px;
  font-size: 22px;
  color: rgba($indigo, 0.5);
  cursor: pointer;
  transition: background 0.15s ease, color 0.15s ease;

  &:hover {
    background: rgba($indigo, 0.05);
    color: rgba($indigo, 0.8);
  }
}

.la-mobile-drawer__close:focus-visible {
  @include focus-ring($color: $brand-verdigris);
}

.la-mobile-drawer__link {
  display: block;
  padding: 14px 16px;
  font-size: 17px;
  font-weight: 600;
  color: $la-navy;
  text-decoration: none;
  border-radius: 12px;
  transition: background 0.15s ease;

  &:hover {
    background: rgba($indigo, 0.05);
    text-decoration: none;
    color: $la-navy;
  }
}

.la-mobile-drawer__link:focus-visible {
  @include focus-ring($color: $brand-verdigris);
}

/* Button-style drawer items (Upgrade, Help, Theme): match .la-mobile-drawer__link look with navy */
.la-mobile-drawer__link--button {
  width: 100%;
  text-align: left;
  background: none;
  border: none;
  appearance: none;
  cursor: pointer;
  display: block;
  padding: 14px 16px;
  font-size: 17px;
  font-weight: 600;
  color: $la-navy;
  text-decoration: none;
  border-radius: 12px;
  transition: background 0.15s ease;

  &:hover {
    background: rgba($indigo, 0.05);
    color: $la-navy;
  }
}

.la-mobile-drawer__link--button:focus-visible {
  @include focus-ring($color: $brand-verdigris);
}

.la-mobile-drawer__header {
  display: block;
  padding: 14px 16px 4px;
  font-size: 14px;
  font-weight: 700;
  color: rgba($indigo, 0.6);
  text-transform: uppercase;
  letter-spacing: 0.02em;
}

.la-mobile-drawer__cta {
  display: inline-block;
  align-self: flex-start;
  margin-top: 12px;
  padding: 10px 20px;
  background: color.adjust($brand-honey-bronze, $saturation: -7%);
  color: $la-navy;
  font-size: 14px;
  font-weight: 800;
  text-align: center;
  text-decoration: none;
  border-radius: 100px;
  transition: filter 0.15s ease;

  &:hover {
    filter: brightness(1.08);
    text-decoration: none;
    color: $la-navy;
  }
}

.la-mobile-drawer__divider {
  height: 1px;
  background: rgba($indigo, 0.08);
  margin: 8px 0;
  /* The panel is a flex column with overflow; without this the zero-content
     divider collapses to 0 height under flex-shrink on tall menus (its margins
     stay, so a gap shows but no line). Pin its size so the hairline always paints. */
  flex-shrink: 0;
}
/* Modern divider — brand verdigris→navy gradient hairline (fades at both ends),
   matching the app's modern dividers. Used to separate the user's quick links from
   the rest of the drawer. */
.la-mobile-drawer__divider--modern {
  height: 2px;
  background: linear-gradient(
    90deg,
    rgba($la-navy, 0) 0%,
    rgba($brand-verdigris-aa, 0.45) 18%,
    rgba($la-navy, 0.32) 50%,
    rgba($brand-verdigris-aa, 0.35) 82%,
    rgba($la-navy, 0) 100%
  );
  margin: 12px 0;
}

/* Display Style drawer link — the inner-header disc covers this above 640px, so
   the drawer entry appears ONLY at <=640px (where the disc is hidden). The
   two-class selector beats the single-class base link rules regardless of source
   order. */
.la-mobile-drawer__link.la-mobile-drawer__link--display-style { display: none; }
@media (max-width: $aac-breakpoint-sm) {
  .la-mobile-drawer__link.la-mobile-drawer__link--display-style { display: block; }
}
/* Modern divider — brand verdigris→navy gradient hairline (fades at both ends),
   matching the app's modern dividers. Used to separate the user's quick links from
   the rest of the drawer. */
.la-mobile-drawer__divider--modern {
  height: 2px;
  background: linear-gradient(
    90deg,
    rgba($la-navy, 0) 0%,
    rgba($brand-verdigris-aa, 0.45) 18%,
    rgba($la-navy, 0.32) 50%,
    rgba($brand-verdigris-aa, 0.35) 82%,
    rgba($la-navy, 0) 100%
  );
  margin: 12px 0;
}

.la-mobile-drawer__footer-note {
  display: block;
  padding: 14px 16px 4px;
  font-size: $aac-font-size-xs;
  color: rgba($indigo, 0.6);
  letter-spacing: 0.02em;
}

.la-mobile-drawer__badges {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: $aac-spacing-10;
  padding: 10px 16px 4px;
}

/* ── LingoLinq company sidebar (About, Pricing, Developers, etc.) ── */
.ll-company-sidebar {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  z-index: 10000;
}

.ll-company-sidebar__backdrop {
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  background: rgba($indigo, 0.35);
  animation: la-drawer-fade-in 0.25s ease forwards;
}

.ll-company-sidebar__panel {
  position: absolute;
  top: 0;
  right: 0;
  width: 300px;
  max-width: 90vw;
  height: 100%;
  background: #fff;
  box-shadow: -4px 0 24px rgba($indigo, 0.15);
  padding: 72px 24px 32px 24px;
  display: flex;
  flex-direction: column;
  gap: 4px;
  animation: la-drawer-slide-in 0.28s cubic-bezier(0.4, 0, 0.2, 1) forwards;
  font-family: 'Lexend', 'Nunito Sans', system-ui, sans-serif;
}

.ll-company-sidebar__close {
  position: absolute;
  top: 16px;
  right: 16px;
  width: 36px;
  height: 36px;
  display: flex;
  align-items: center;
  justify-content: center;
  background: transparent;
  border: 1px solid rgba($indigo, 0.1);
  border-radius: 10px;
  font-size: 22px;
  color: rgba($indigo, 0.5);
  cursor: pointer;
  transition: background 0.15s ease, color 0.15s ease;

  &:hover {
    background: rgba($indigo, 0.05);
    color: rgba($indigo, 0.8);
  }
}

.ll-company-sidebar__title {
  margin: 0 0 20px 0;
  font-size: 14px;
  font-weight: 600;
  color: $la-navy;
  letter-spacing: -0.01em;
}

.ll-company-sidebar__nav {
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.ll-company-sidebar__link {
  display: block;
  padding: 12px 14px;
  font-size: 14px;
  font-weight: 500;
  color: $la-navy;
  text-decoration: none;
  border-radius: 10px;
  transition: background 0.15s ease, color 0.15s ease;

  &:hover {
    background: rgba($indigo, 0.06);
    text-decoration: none;
    color: $la-navy;
  }
}

.la-topbar-compare-link {
  color: rgba(white, 0.55);
  font-size: $aac-font-size-xs;
  font-weight: $aac-font-weight-semi;
  text-decoration: none;
  transition: color 0.15s ease;

  &:hover { color: rgba(white, 0.9); text-decoration: none; }
}

// ── Font-toggle buttons ─────────────────────────────────────────────────────
.la-font-toggles {
  display: flex;
  align-items: center;
  gap: $aac-spacing-6;
}

.la-font-toggle {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 30px;
  height: 30px;
  border-radius: $aac-radius-circle;
  border: 1px solid rgba(white, 0.15);
  background: rgba(white, 0.08);
  color: rgba(white, 0.55);
  font-size: 14px;
  font-weight: $aac-font-weight-bold;
  cursor: pointer;
  transition: all 0.15s ease;
  padding: 0;
  line-height: 1;

  &:hover {
    background: rgba(white, 0.15);
    color: rgba(white, 0.85);
    border-color: rgba(white, 0.25);
  }

  &:focus-visible {
    @include focus-ring($color: $la-teal);
  }

  &--active {
    background: rgba(white, 0.2);
    color: white;
    border-color: rgba(white, 0.4);
    box-shadow: 0 0 0 1px rgba(white, 0.1);
  }
}

.la-font-toggle-letter--atkinson {
  font-family: 'Atkinson Hyperlegible', sans-serif;
}

.la-font-toggle-letter--lexend {
  font-family: 'Lexend', sans-serif;
}

.la-topbar-sign-in {
  font-size: 14px;
  font-weight: $aac-font-weight-semi;
  color: rgba(255, 255, 255, 0.82);
  text-decoration: none;
  letter-spacing: $aac-letter-spacing-base;
  padding: 6px 20px;
  border-radius: $aac-radius-pill;
  border: 1px solid rgba(255, 255, 255, 0.18);
  transition: color 0.15s ease, background 0.15s ease, border-color 0.15s ease;
  white-space: nowrap;

  &:hover {
    color: #fff;
    background: rgba(255, 255, 255, 0.10);
    border-color: rgba(255, 255, 255, 0.30);
    text-decoration: none;
  }
}

.la-topbar-cta {
  background: $la-hero-cta-bg;
  color: $la-navy;
  font-size: 14px;
  font-weight: $aac-font-weight-black;
  padding: 6px 16px;
  border-radius: $aac-radius-pill;
  text-decoration: none;
  border: 1px solid rgba($brand-honey-bronze, 0.5);
  letter-spacing: $aac-letter-spacing-base;
  transition: filter 0.15s ease;
  white-space: nowrap;

  &:hover { filter: brightness(1.08); text-decoration: none; color: $la-navy; }
}

/* Try Free in inner header — same bg as Try LingoLinq (hero .la-btn--primary), slightly smaller than hero CTA */
#inner_header .la-topbar-cta {
  background: $la-hero-cta-bg !important;

  color: $la-navy !important;

  font-size: 14px !important;

  font-weight: 600; /* semi-bold: a bit more bold, not full bold */
  padding: 6px 16px !important;

  border: 1px solid rgba($brand-honey-bronze, 0.5) !important;

  filter: brightness(1.02) !important;

  box-shadow: none !important;

  transition: filter 0.15s ease, transform 0.2s ease !important;


  &:hover {
    filter: brightness(0.96) !important;

    transform: translateY(-2px) !important;

    box-shadow: none !important;

    color: $la-navy !important;

    text-decoration: none !important;

  }
}

/* Sign In (identity button) — same glass as Watch Demo, same shadow as Try Free; overrides gradient/base .btn when in header */
header #identity #identity_button.btn {
  background: rgba(255, 255, 255, 0.22) !important;
  background-image: none !important;
  backdrop-filter: blur(10px) !important;

  -webkit-backdrop-filter: blur(10px) !important;

  color: $la-navy !important;
  border: 1px solid rgba(0, 0, 0, 0.04) !important;
  box-shadow: none !important;
  transition: background 0.25s ease, border-color 0.25s ease, color 0.25s ease, box-shadow 0.25s ease !important;


  &:hover,
  &:focus-visible {
    background: rgba(255, 255, 255, 0.32) !important;
    background-image: none !important;
    color: $la-navy !important;
    border-color: rgba(0, 0, 0, 0.06) !important;
    box-shadow: none !important;
    filter: none !important;

  }
}
header #identity #identity_button.btn::before,
header #identity #identity_button.btn::after {
  display: none !important;
  background: none !important;
  background-image: none !important;
}

/* Unauthenticated pages: identity/Sign In button — solid dark slate to match dropdown (landing, login, register, etc.). Pill-shaped (not circular). */
#within_ember header.header--unauthenticated #identity #identity_button.btn,
#within_ember header.header--unauthenticated .app-navbar #identity #identity_button.btn {
  width: auto !important;
  min-width: unset !important;
  height: 42px !important;
  padding-left: 2.2rem !important;
  padding-right: 2.2rem !important;
  padding-top: 2px !important;
  padding-bottom: 2px !important;
  border-radius: 999px !important;
  display: inline-flex !important;
  align-items: center !important;
  justify-content: center !important;
  gap: 0.25rem !important;
  white-space: nowrap !important;
  background: rgba($brand-charcoal-dark, 1) !important;
  background-image: none !important;
  color: rgba(255, 255, 255, 0.95) !important;
  border: 1px solid rgba(255, 255, 255, 0.12) !important;
  box-shadow: none !important;

  &:hover,
  &:focus-visible {
    background: color.adjust(rgba($brand-charcoal-dark, 1), $lightness: 8%) !important;
    background-image: none !important;
    color: #ffffff !important;
    border-color: rgba(255, 255, 255, 0.2) !important;
    box-shadow: none !important;
  }
}

.la-topbar-login {
  background: $brand-smart-blue;
  color: $la-white;
  font-size: $aac-font-size-sm;
  font-weight: $aac-font-weight-black;
  padding: $aac-spacing-8 $aac-spacing-20;
  border-radius: $aac-radius-pill;
  text-decoration: none;
  letter-spacing: $aac-letter-spacing-base;
  transition: filter 0.15s ease;
  white-space: nowrap;

  &:hover { filter: brightness(1.08); text-decoration: none; color: $la-white; }
}

/* Tiny link to left of Try Free: toggles hero + sign-in/speak button colors (current vs previous slate) */
.la-hero-color-toggle {
  margin-right: 12px;
  padding: 2px 6px;
  font-size: 14px;
  line-height: 1.2;
  color: rgba(255, 255, 255, 0.6);
  background: transparent;
  border: none;
  border-radius: 4px;
  cursor: pointer;
  transition: color 0.15s ease, background 0.15s ease;

  &:hover {
    color: rgba(255, 255, 255, 0.95);
    background: rgba(255, 255, 255, 0.12);
  }
}

// ── Sidebar ──────────────────────────────────────────────────────────────────
.la-sidebar {
  grid-area: sidebar;
  background: $color-surface;
  border-right: 1px solid $color-border;
  padding: $aac-spacing-16 $aac-spacing-8;
  overflow-y: auto;
  display: flex;
  flex-direction: column;
  gap: $aac-spacing-16;

  > * + * {
    border-top: 1px solid rgba(0, 0, 0, 0.08);
    padding-top: $aac-spacing-16;
  }
}

.la-sidebar-label {
  font-size: $la-panel-font-size-xs;
  font-weight: $aac-font-weight-black;
  text-transform: uppercase;
  letter-spacing: $aac-letter-spacing-wide;
  color: $brand-teal;
  padding: $aac-spacing-10 $aac-spacing-12 $aac-spacing-4;
  margin-top: $aac-spacing-6;

  &:first-child { margin-top: 0; }

  &.la-sidebar-label--lower { margin-top: 0; }
}

.la-sidebar-quicklinks {
  margin: 0 0 auto 0;
  padding-bottom: $aac-spacing-16;
  border-bottom: 1px solid rgba(0, 0, 0, 0.08);
}

.la-nav-item {
  display: flex;
  align-items: center;
  gap: $aac-spacing-10;
  /* WCAG 2.5.5 AAA touch target — was 10×14 (~20 tall). */
  padding: $aac-spacing-12 $aac-spacing-14;
  min-height: 44px;
  border-radius: $aac-radius-md;
  cursor: pointer;
  font-size: $la-panel-font-size-sm;
  font-weight: $aac-font-weight-semi;
  color: $color-text-mid;
  border: 1.5px solid transparent;
  text-decoration: none;
  transition: all 0.15s ease;
  user-select: none;

  &:hover {
    background: $color-border;
    color: $color-text;
    text-decoration: none;
  }

  &.la-active {
    background: rgba($brand-honey-bronze, 0.08);
    color: color.adjust($brand-honey-bronze, $lightness: -10%);
    border-color: rgba($brand-honey-bronze, 0.25);
  }
}

.la-nav-icon {
  font-size: $la-panel-font-size-base;
  width: 22px;
  text-align: center;
  flex-shrink: 0;
}

.la-panel-badges {
  margin: auto 0;
  padding: $aac-spacing-16 $aac-spacing-12;
  display: flex;
  justify-content: center;
  gap: $aac-spacing-8;
  border-top: 1px solid rgba(0, 0, 0, 0.08);
  border-bottom: 1px solid rgba(0, 0, 0, 0.08);
}

.la-badge {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: $aac-spacing-4 $aac-spacing-10;
  border-radius: $aac-radius-pill;
  font-size: $la-panel-font-size-xs;
  font-weight: $aac-font-weight-medium;
  letter-spacing: $aac-letter-spacing-wide;
  text-transform: uppercase;
  opacity: 0.55;
  box-shadow: none;

  &.la-badge--oss {
    background: rgba($cat-people-text, 0.06);
    color: $cat-people-text;
    border: 1px solid rgba($cat-people-text, 0.08);
  }
}

// ── Main content ─────────────────────────────────────────────────────────────
.la-main {
  grid-area: main;
  overflow-y: auto;
  padding: $aac-spacing-48 $aac-spacing-28;
  padding-bottom: 0;
  background: #F3F1ED;
  position: relative;
  display: flex;
  flex-direction: column;
  gap: $aac-spacing-28; /* reduced from 48 for tighter section spacing */
}

// ── Background orbs (used on register, login, forgot pages; landing uses fluctuating gradient) ──
.la-bg-orbs {
  position: absolute;
  inset: -80px;
  pointer-events: none;
  filter: blur(28px);
  opacity: 0.82;
  z-index: 0;
}

.la-bg-orb {
  position: absolute;
  border-radius: 999px;
  transform: translateZ(0);

  &--a {
    width: 500px;
    height: 500px;
    right: 5%;
    top: 3%;
    background: radial-gradient(circle at 30% 30%, rgba(58, 107, 199, 0.42), transparent 58%),
                radial-gradient(circle at 70% 70%, rgba(100, 140, 220, 0.34), transparent 60%);
  }

  &--b {
    width: 420px;
    height: 420px;
    left: 4%;
    top: 8%;
    background: radial-gradient(circle at 35% 35%, rgba($brand-honey-bronze, 0.36), transparent 60%),
                radial-gradient(circle at 70% 70%, rgba(230, 180, 80, 0.28), transparent 58%);
  }

  &--c {
    width: 480px;
    height: 480px;
    left: 15%;
    top: 45%;
    background: radial-gradient(circle at 35% 35%, rgba($la-teal, 0.32), transparent 58%),
                radial-gradient(circle at 70% 70%, rgba(245, 140, 100, 0.26), transparent 60%);
  }

  &--d {
    width: 540px;
    height: 540px;
    right: 8%;
    bottom: 10%;
    background: radial-gradient(circle at 30% 30%, rgba(58, 107, 199, 0.32), transparent 58%),
                radial-gradient(circle at 70% 70%, rgba(140, 170, 230, 0.26), transparent 60%);
  }
}

// ── Hero card ────────────────────────────────────────────────────────────────
// Full-width hero: break out of .la-main so hero spans viewport; content stays centered. Sits just below navbar.
.la-hero-card {
  position: relative;
  margin-top: clamp(0rem, calc(0rem + 2vw), 2rem); /* 2rem less than previous */
  width: 100vw;
  margin-left: calc(50% - 50vw);
  margin-right: calc(50% - 50vw);
  background:
    radial-gradient(circle at 20% 20%, rgba($la-teal, 0.05), transparent 60%),
    radial-gradient(circle at 80% 80%, rgba($la-navy, 0.05), transparent 60%),
    linear-gradient(180deg, #{color.adjust($brand-stone-100, $lightness: 10%)} 0%, #{color.adjust($brand-stone-200, $lightness: 10%)} 50%, #{color.adjust($brand-stone-300, $lightness: 10%)} 100%);
  border-radius: 0;
  position: relative;
  z-index: 1;
  overflow: visible;
  /* Bottom shadow to lift hero off the section below */
  box-shadow: 0 10px 18px -6px rgba($indigo, 0.22);
  transition: background 0.25s ease;
}

.hero-background {
  padding-top: 0; /* 2rem less than previous 2rem */

  @media (max-width: 1024px) {
    padding-top: 6rem; /* 2rem less than previous 8rem */
  }

  // Bottom curve removed — hero has flat bottom
  &::after {
    display: none;
  }
}

/* hero-background::before overlay removed */

#within_ember.la-hero-colors-alt .la-hero-card {
  background: color.adjust($la-hero-blue, $lightness: 11%, $saturation: 6%);
}
/* Alt toggle: buttons 15% lighter than rgb(75, 110, 144) (#4b6e90) */
#within_ember.la-hero-colors-alt .la-topbar-login,
#within_ember.la-hero-colors-alt .la-mockup-speak,
#within_ember.la-hero-colors-alt #identity .btn {
  background: color.adjust(#4b6e90, $lightness: 15%);
}

/* Hero container: layout only, fully transparent (no glass panel); above wave image */
.la-hero-card .hero-container {
  position: relative;
  z-index: 1;
  max-width: min(1320px, 94%);
  margin: clamp(1.5rem, calc(0.5rem + 1.75vw), 3rem) auto 0;
  padding: clamp(24px, calc(12px + 2.5vw), 48px) clamp(28px, calc(12px + 3.5vw), 72px) clamp(28px, calc(14px + 2.9vw), 56px) clamp(20px, calc(4px + 3vw), 48px);
  border-radius: clamp(16px, calc(10px + 1.25vw), 28px);
  background: transparent;
  backdrop-filter: none;
  -webkit-backdrop-filter: none;
  border: none;
  box-shadow: none;
}

.la-hero-card-inner {
  max-width: min(1320px, 100%);
  margin: 0 auto;
  padding: 0;
  display: grid;
  grid-template-columns: 6fr 4fr; /* 60% left (text), 40% right (mockup) */
  gap: clamp(24px, calc(8px + 3.3vw), 56px);
  align-items: start; /* let columns grow with content so mockup margin/scale have room */
  position: relative;
  background: transparent;

  // warm glow — top right, balances mockup side
  &::before {
    content: '';
    position: absolute;
    top: -60px;
    right: -40px;
    width: 420px;
    height: 420px;
    border-radius: 50%;
    background: radial-gradient(circle, rgba($brand-honey-bronze, 0.12) 0%, transparent 55%);
    pointer-events: none;
  }

  // cool glow — bottom left, soft fill on text side
  &::after {
    content: '';
    position: absolute;
    bottom: -50px;
    left: 25%;
    width: 360px;
    height: 360px;
    border-radius: 50%;
    background: radial-gradient(circle, rgba($la-teal, 0.09) 0%, transparent 55%);
    pointer-events: none;
  }

  .la-section-eyebrow-badge {
    color: #0d5c5f;
    background: rgba(13, 92, 95, 0.15);
    border-color: rgba(13, 92, 95, 0.35);
  }
}

/* Hero text: layout only, no container bg */
.la-hero-text {
  max-width: min(860px, 100%);
  padding-left: 0.5rem;
  padding-right: 0.5rem;
  display: flex;
  flex-direction: column;
  gap: 0;
}

/* Dark gray text and borders on transparent hero so content reads on glass panel; Lexend font */
.la-hero-card .la-hero-text .la-hero-title,
.la-hero-card .la-hero-text .la-hero-title .la-hero-title-line1,
.la-hero-card .la-hero-text .la-hero-title .la-hero-title-line2 {
  font-family: 'Lexend', 'Nunito Sans', system-ui, sans-serif;
  color: $brand-charcoal-dark;
}
/* "every student" — gradient +5% saturation */
.la-hero-card .la-hero-text .la-hero-title .la-hero-highlight {
  background: $la-highlight-gradient;
  -webkit-background-clip: text;
  background-clip: text;
  -webkit-text-fill-color: transparent;
  color: transparent;
}
.la-hero-card .la-hero-text .la-hero-subtitle {
  font-family: 'Lexend', 'Nunito Sans', system-ui, sans-serif;
  color: $brand-charcoal-dark;
}
.la-hero-card .la-hero-text .la-hero-badge-label {
  font-family: 'Lexend', 'Nunito Sans', system-ui, sans-serif;
}
.la-hero-card .la-hero-text .la-hero-headline {
  border-bottom-color: rgba(0, 0, 0, 0.09);
}
.la-hero-card .la-hero-text .la-hero-badges-section {
  background: rgba(0, 0, 0, 0.04);
  border-color: rgba(0, 0, 0, 0.08);
}
.la-hero-card .la-hero-text .la-hero-badge-label {
  color: $brand-charcoal-dark;
}
.la-hero-card .la-hero-text .la-btn--ghost {
  color: rgba(255, 255, 255, 0.86);
  border-color: rgba(255, 255, 255, 0.11);
}
.la-hero-card .la-hero-text .la-btn--ghost:hover {
  color: rgba(255, 255, 255, 0.95);
  background: rgba(65, 75, 91, 0.85);
}

/* Left content block: headline max-width, vertical rhythm per spacing map */
.la-hero-headline-and-badges .la-hero-headline,
.la-hero-title-wrap {
  max-width: min(590px, 100%);
}

// Hero left column: distinct sections (headline, badges, actions)
.la-hero-section {
  position: relative;
}

// Wrapper so the headline's border matches the badge container width (grid column = badge width)
.la-hero-headline-and-badges {
  display: grid;
  grid-template-columns: 1fr;
  width: fit-content;
}

.la-hero-headline-and-badges .la-hero-headline {
  min-width: 0; /* allow column to shrink to badge width */
  width: calc(100% - 1rem);
}

.la-hero-headline {
  margin-bottom: 28px; /* 28px divider → paragraph (vertical rhythm) */
  border-bottom: 1px solid rgba(255, 255, 255, 0.09);
}

/* Hero vertical rhythm: headline 24px → divider, 28px → paragraph, 32px → pills, 28px → CTA */
.la-hero-card .la-hero-headline .la-hero-title-wrap {
  padding-bottom: 24px;
}

.la-hero-trust-line {
  margin-top: 0;
  margin-bottom: 14px;
  padding-top: 18px;
  border-top: 1px solid rgba(255, 255, 255, 0.11);
  font-size: 16px;
  font-weight: 500;
  letter-spacing: 0.035em;
  color: rgba(255, 255, 255, 0.78);
  font-family: 'Lexend', 'Nunito Sans', system-ui, sans-serif;
}
@media (max-width: 768px) {
  .la-hero-trust-line {
    font-size: 14px;
  }
}

.la-hero-card .la-hero-text .la-hero-trust-line {
  border-top-color: rgba(0, 0, 0, 0.04);
  color: $brand-cool-steel;
}

.la-hero-badges-section {
  width: fit-content;
  padding: clamp(8px, calc(4px + 0.56vw), 12px);
  margin-bottom: 28px; /* 28px feature pills → CTA buttons */
  background: rgba(255, 255, 255, 0.94);
  border: 1px solid rgba(0, 0, 0, 0.12);
  border-radius: 16px;
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  box-shadow: 0 6px 16px rgba(0, 0, 0, 0.08), 0 2px 6px rgba(0, 0, 0, 0.04);
}

.la-hero-badges-section .la-hero-badges {
  margin-top: 0;
  margin-bottom: 0;
  width: 100%;
}

.la-hero-badges-section .la-hero-badge {
  flex: 1 1 0;
  min-width: 0;
  padding-left: 14px;
  padding-right: 22px;
  justify-content: flex-start;
}

.la-hero-badges-section .la-hero-badge-label {
  white-space: nowrap;
}

.la-hero-actions-section {
  padding-top: 16px; /* 8px more above CTAs for breathing room below pills */
}

.la-hero-eyebrow {
  font-size: clamp(11px, calc(8px + 0.35vw), 14px);
  font-weight: $aac-font-weight-bold;
  text-transform: uppercase;
  letter-spacing: 0.12em;
  color: $brand-honey-bronze;
  margin-bottom: $aac-spacing-16;
}

.la-hero-title-wrap {
  padding-bottom: clamp(12px, calc(6px + 1.25vw), 24px);
}

.la-wrapper .la-hero-title {
  font-family: 'Maitree', serif;
  font-size: clamp(2rem, calc(0.8rem + 3.47vw), 3.575rem);
  font-weight: 600; /* semi-bold: cleaner, calmer, more editorial than 700 */
  color: #ffffff;
  line-height: 1.08;
  letter-spacing: -0.025em; /* tight for display; keeps two-line headline feeling like one unit */
  font-kerning: normal;
  margin: 0;
  margin-bottom: 0;
  display: block;
  height: auto;

  span {
    display: inline;
    position: static;
    left: auto;
    top: auto;
    font-weight: inherit;
  }

  .la-hero-title-line1 {
    color: #FFFFFF;
    font-size: 1.2em;
  }

  .la-hero-highlight {
    font-size: 1.1025em; /* 5% larger than 1.05em */
    font-weight: normal;
  }

  .la-hero-title-line2 {
    display: inline;
    /* Scale with viewport like line1 does (line1 uses 1.2em which scales via
       the parent's clamp). Floor 18px on tiny phones, ceiling 32px at 768. */
    font-size: clamp(18px, calc(12px + 2.5vw), 32px);
  }
}

/* Hero title entrance: Communication from left, "access for every student" from right */
@keyframes la-hero-title-from-left {
  from {
    opacity: 0;
    transform: translateX(-36px);
  }
  to {
    opacity: 1;
    transform: translateX(0);
  }
}

@keyframes la-hero-title-from-right {
  from {
    opacity: 0;
    transform: translateX(36px);
  }
  to {
    opacity: 1;
    transform: translateX(0);
  }
}

@keyframes ub-letter-bounce {
  0%   { opacity: 0; transform: translateY(-14px); color: $brand-verdigris; }
  60%  { opacity: 1; transform: translateY(2px);  color: $brand-dusty-denim; }
  80%  { transform: translateY(-1px);             color: #3a6bb0; }
  100% { opacity: 1; transform: translateY(0);    color: $indigo; }
}
.la-hero-card .la-hero-title .la-hero-title--from-left {
  display: inline-block;
  animation: la-hero-title-from-left 1s cubic-bezier(0.25, 0.46, 0.45, 0.94) forwards;
}
.la-hero-card .la-hero-title .la-hero-title--from-right {
  display: inline-block;
  animation: la-hero-title-from-left 1s cubic-bezier(0.25, 0.46, 0.45, 0.94) 0.2s forwards;
  opacity: 0;
}

/* Dashboard hero: subtitle enters from the right (after title from left) */
@keyframes md-hero-from-right {
  from {
    opacity: 0;
    transform: translateX(36px);
  }
  to {
    opacity: 1;
    transform: translateX(0);
  }
}

/* Dashboard hero: "It's great to see you" from left, "Let's continue..." from right (same timing as landing-alt); centered on page */
.md-navbar__speech-dot {
  display: inline-block;
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: $brand-cool-steel;
  margin-right: 10px;
  vertical-align: middle;
  cursor: pointer;
  transition: background 0.15s ease, transform 0.15s ease;
}
.md-navbar__speech-dot:hover {
  background: $brand-slate-gray;
  transform: scale(1.3);
}
.md-hero__speech-dot {
  display: inline-block;
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: $brand-cool-steel;
  margin-top: 8px;
  cursor: pointer;
  transition: background 0.15s ease, transform 0.15s ease;
}
.md-hero__speech-dot:hover {
  background: $brand-slate-gray;
  transform: scale(1.3);
}
.md-hero--dashboard {
  text-align: center;
  padding-bottom: 20px;
  margin-bottom: 8px;
}
/* Positioning context for the absolutely-placed `.md-tour__trigger`
   pill in the top-right of the dashboard hero. NOTE the
   two-class compound selector: `.md-hero.md-hero--dashboard` is
   0,2,0 specificity, which beats the general
   `.md-hero { position: static !important }` rule (~line 38413,
   0,1,0). The earlier single-class attempt at this same site
   silently lost the cascade — `!important` does NOT override
   source order at equal specificity, so the later `.md-hero`
   rule still won. Higher specificity is the real fix.
   See LEARNINGS.md duplicate-selectors-in-app.scss pattern. */
.md-hero.md-hero--dashboard {
  position: relative !important;
}
@media (min-width: 1025px) {
  /* Lift the tour trigger onto the pill-nav row, right-aligned to the
     content gutter. The workspace becomes the containing block (scoped
     to the dashboard via :has) and the hero gives up its relative so the
     absolute trigger resolves to the workspace. */
  .md-shell > .md-workspace:has(.md-hero--dashboard) {
    position: relative !important;
  }
  .md-shell > .md-workspace:has(.md-hero--dashboard) .md-hero.md-hero--dashboard {
    position: static !important;
  }
  .md-shell > .md-workspace:has(.md-hero--dashboard) .md-tour__trigger {
    /* Same fixed top-left-below-navbar anchor as the base rule (~92966). */
    position: fixed !important;
    top: calc(var(--topbar-height, 16px) + 7.5rem) !important;
    left: 24px !important;
    right: auto !important;
    z-index: 1001 !important;
  }
}
/* Getting Started entry badge — a single gradient icon circle (reusing
   .beta-welcome-steps__num) pinned to the top-right of the home page, fixed to
   the viewport and level with the Take a tour button (same top offset).
   z-index sits just BELOW the fixed inner-header navbar (z-index:1000, ~l.442) so
   the identity dropdown — which opens from the navbar and overlaps this badge —
   renders ABOVE it. The badge can't be hidden by the navbar: the header is only
   `--topbar-height` tall and this badge sits ~7.5rem below it, so they never
   overlap; the lower z-index only matters where the dropdown extends over it. */
.md-home-steps {
  position: fixed;
  top: calc(var(--topbar-height, 16px) + 7.5rem);
  right: 24px;
  z-index: 999;
  display: flex;
  flex-direction: column;
  gap: 10px;
}
/* The Getting Started trigger reuses the .beta-welcome-steps__num glass circle
   as an actionable icon button — reset native button chrome, indigo icon
   (currentColor), and a subtle hover lift. */
.md-display-style__trigger {
  /* Always a pill showing the icon + "Get Started" label at EVERY width
     (overrides the .beta-welcome-steps__num fixed 36px circle to an auto-width
     pill). */
  width: auto !important;
  height: auto !important;
  min-height: 40px !important;
  border-radius: 999px !important;
  padding: 7px 18px 7px 12px !important;
  display: inline-flex !important;
  align-items: center !important;
  gap: 8px !important;
  cursor: pointer;
  -webkit-appearance: none;
  appearance: none;
  color: $indigo;
  transition: transform 0.15s ease, box-shadow 0.15s ease;
}
.md-display-style__trigger:hover {
  transform: translateY(-1px);
}
.md-display-style__trigger:focus-visible {
  outline: 2px solid rgba($brand-dusty-denim, 0.55);
  outline-offset: 3px;
}
/* Display Style button fill — the glassmorphism disc formerly supplied by
   `.beta-welcome-steps__num` (renamed off this control so the class reflects its
   purpose; that class still styles the beta-welcome-message steps list). Size/shape
   come from `.md-display-style__trigger` + `.app-navbar__home-actions`; this
   supplies only the translucent denim→verdigris glass fill, rim, and glow for Gentle
   View (Focused View overrides the background with the nav-pill gradient). */
.display-style {
  color: $indigo;
  background:
    radial-gradient(125% 125% at 30% 18%, rgba(255, 255, 255, 0.9) 0%, rgba(255, 255, 255, 0) 52%),
    linear-gradient(150deg, rgba($brand-dusty-denim, 0.32) 0%, rgba($brand-verdigris, 0.28) 100%);
  backdrop-filter: blur(8px) saturate(1.4);
  -webkit-backdrop-filter: blur(8px) saturate(1.4);
  border: 1px solid rgba(255, 255, 255, 0.7);
  box-shadow:
    0 6px 16px rgba($brand-dusty-denim, 0.20),
    inset 0 1px 1px rgba(255, 255, 255, 0.85),
    inset 0 -4px 8px rgba($brand-verdigris, 0.16);
}

/* Focused layout — the Take-a-Tour + Get-Started triggers are relocated into the
   inner header (app-navbar-authenticated-inner, beside the Search field) as compact
   CIRCLE icon buttons. Here they shed their fixed positioning + text label and
   become 40px discs that keep ONLY their icon + their own glassy fill. Scoped to
   .app-navbar__home-actions, so the dashboard's own (non-focused) fixed pills are
   untouched. !important beats the triggers' base position/size/padding (which are
   !important). */
.app-navbar__home-actions {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  /* Sits inside nav-header right after the 180px Search field — small gap so the
     two discs read as left-aligned next to it, not flush against it. */
  margin-left: 12px;
}
.app-navbar__home-actions .md-tour__trigger,
.app-navbar__home-actions .md-display-style__trigger {
  position: static !important;
  top: auto !important;
  left: auto !important;
  right: auto !important;
  width: 40px !important;
  height: 40px !important;
  min-height: 40px !important;
  padding: 0 !important;
  gap: 0 !important;
  border-radius: 50% !important;
  display: inline-flex !important;
  align-items: center !important;
  justify-content: center !important;
}
.app-navbar__home-actions .md-tour__trigger-label,
.app-navbar__home-actions .md-display-style__trigger-label {
  display: none !important;
}
/* Navbar circle buttons (Take a Tour + Get Started / Dashboard Design) — on
   Focused View they MATCH the active nav-pill: the same 135° blue-grey→charcoal-
   blue gradient with a white icon. Scoped to body.ll-layout-focused (set by
   dashboard/authenticated-view); Gentle View falls back to the original
   .beta-welcome-steps__num glass disc. The 40px circle SIZE/shape rule above is
   unscoped so both layouts stay circular. */
body.ll-layout-focused .app-navbar__home-actions .md-tour__trigger,
body.ll-layout-focused .app-navbar__home-actions .md-display-style__trigger {
  background: linear-gradient(135deg, $focus-accent-from, $focus-nav-accent-to) !important;
  border: 1px solid rgba($focus-on-dark, 0.16) !important;
  color: $focus-on-dark !important;
  box-shadow:
    inset 0 1px 0 rgba($focus-on-dark, 0.18),
    0 4px 10px rgba($focus-shadow-ink, 0.28) !important;
  backdrop-filter: none !important;
  -webkit-backdrop-filter: none !important;
}
/* The Guided Tour disc on Focused View takes the SAME glossy desaturated-navy
   surface as the home page "Let's Communicate" hero (.md-card--speak-focused),
   so the tour entry point echoes the focal communicate button. Only the
   background changes from the shared focused-disc rule above; the Display Style
   disc keeps the blue-grey→charcoal-blue gradient. */
body.ll-layout-focused .app-navbar__home-actions .md-tour__trigger {
  background: radial-gradient(ellipse at center in oklab,
    #{$focus-hero-center} 0%,
    #{$focus-hero-edge} 100%) !important;
}
body.ll-layout-focused .app-navbar__home-actions .md-tour__trigger-icon,
body.ll-layout-focused .app-navbar__home-actions .md-display-style__trigger-icon {
  color: $focus-on-dark !important;
}
/* The map (Take a Tour) glyph uses HARDCODED hex strokes (#4C86D8 / #46505F), not
   currentColor, so `color` doesn't reach it — override the strokes to white. */
body.ll-layout-focused .app-navbar__home-actions .md-tour__trigger-icon * {
  stroke: $focus-on-dark !important;
}
/* While the Getting Started modal series is open the page chrome is dimmed
   (body.md-ds-active, set by display-style). Hide the relocated inner-header
   Take-a-Tour + Get-Started discs then, so they don't sit over the modal backdrop. */
body.md-ds-active .app-navbar__home-actions { display: none !important; }
/* ≤1024px — keep the two discs in the navbar (every layout). Legacy ≤1024
   `.md-tour__trigger` rules try to re-pin the trigger to a fixed corner; re-assert
   the in-navbar circle treatment + visibility here so they stay on the navbar. */
@media (max-width: 1024px) {
  .app-navbar__home-actions { display: inline-flex !important; }
  .app-navbar__home-actions .md-tour__trigger,
  .app-navbar__home-actions .md-display-style__trigger {
    position: static !important;
    top: auto !important;
    right: auto !important;
    left: auto !important;
    bottom: auto !important;
    width: 40px !important;
    height: 40px !important;
    border-radius: 50% !important;
    padding: 0 !important;
  }
  /* Left-align the discs immediately to the right of the brand. At <=1024 the
     nav-header is `display:contents`, so its children (brand, search, discs)
     flatten into the inner-header flex row; the brand `h1` is kept content-width
     (see the nav-header h1 rule below) so the discs tuck in right after it via
     `order`. `#identity`'s own `margin-left:auto` still pushes the avatar/menu to
     the far right. */
  .app-navbar .app-navbar__nav-header:has(.app-navbar__home-actions) .app-navbar__home-actions {
    order: -1 !important;
    margin-left: 12px !important;
  }
}
/* <=640px: drop the Display Style disc from the inner header — it moves into the
   mobile drawer (`.la-mobile-drawer__link--display-style`, shown only at this
   width) instead. The guided-tour disc stays in the navbar. */
@media (max-width: $aac-breakpoint-sm) {
  .app-navbar__home-actions .md-display-style__trigger { display: none !important; }
}
.md-display-style__trigger-icon {
  display: block;
}
/* Trigger label — always shown, to the right of the icon. */
.md-display-style__trigger-label {
  display: inline;
  font-size: 14px;
  font-weight: 700;
  color: $indigo;
  line-height: 1;
  white-space: nowrap;
}
/* Getting Started modal — a bit larger and pinned near the top of the
   viewport. Scoped via the `md-ds-modal` class on its welcome step so the
   home-tour welcome/outro keep their default size + centering. Shepherd's
   base .shepherd-element has no `position` — floating-ui sets position/top/left
   INLINE at runtime — so these `!important` rules (which beat inline styles)
   take full, explicit control: fixed, horizontally centered, near the top. */
.shepherd-element.md-ds-modal {
  position: fixed !important;
  top: 6vh !important;
  left: 50% !important;
  transform: translateX(-50%) !important;
  margin: 0 !important;
  max-width: 600px;
}
.shepherd-element.md-ds-modal .shepherd-text {
  max-width: 40ch;
}
/* "Choose your display style" step — a WIDER modal to fit the three options
   side-by-side plus the Gentle Layout preview below; text uses full width.

   SPECIFICITY (0,3,0), via the redundant-looking `.md-ds-modal` in the selector:
   this step also carries `md-tour__step--intro`, and the SHORT-VIEWPORT rule
   `@media (max-height: 800px) .shepherd-element.md-tour__step--intro`
   (app.scss ~97049) re-imposes `transform: translateX(-50%) !important` + a
   `top: 12px` meant for the CENTERED tour cards. At (0,2,0) that rule tied with
   this one and won on source order, so on any viewport 1024px wide or less AND
   800px tall or less the modal got `left: 0` from the media block below AND a
   translateX(-50%) on top — sliding it half its own width (50vw) off the LEFT
   edge. Going to (0,3,0) here settles it by specificity at every viewport size,
   and leaves the intro/outro ranking that rule's own comment documents intact.
   (The "Customize" step never showed the bug because its `:has()` rule below is
   already (0,3,0).) */
.shepherd-element.md-ds-modal.md-ds-modal--display {
  /* FULL-BLEED: the whole viewport, both axes. Every step of this modal now shows
     page previews, which need all the room available — at 80vw the two previews had
     to be cropped to fit and could not show the whole page.
     Previously this was 80vw with two extra rules layering on top (a
     `max-width: 1024px` media block and a `:has(.md-ds-preview--with-toggles)` rule
     for the customize step) that each re-declared the same full-width values. Those
     are folded in here so there is ONE authoritative size rule — per the
     edit-in-place convention, rather than three rules competing. */
  width: 100vw !important;
  max-width: 100vw !important;
  height: 100vh !important;
  max-height: 100vh !important;
  top: 0 !important;
  left: 0 !important;
  transform: none !important;
  margin: 0 !important;
  border-radius: 0 !important;
  overflow-x: hidden !important;
  overflow-y: auto !important;
}
/* Full-width content — override the centered-intro 33ch cap that otherwise
   squishes the options + preview into a narrow centre column. */
/* Full-height flex column: the text region grows so the footer sits at the END
   of the content — pushed to the bottom of the modal when content is short, and
   after all content (reached by scrolling) when it's tall. Replaces the old
   sticky footer, which floated up to the content's end and, on small screens,
   stayed pinned over the content. */
.shepherd-element.md-ds-modal--display .shepherd-content {
  max-width: none !important;
  width: 100% !important;
  display: flex;
  flex-direction: column;
  min-height: 100%;
  box-sizing: border-box;
}
.shepherd-element.md-ds-modal--display .shepherd-text {
  max-width: none !important;
  width: 100% !important;
  margin: 0 !important;
  padding-left: 28px !important;
  padding-right: 28px !important;
  box-sizing: border-box !important;
  flex: 1 0 auto;
}
/* Style-chooser step ONLY: make the text region a flex column so the two preview rows
   can divide its height between them. `height: 100%` cannot do this — the region's own
   height comes from flex-growing inside .shepherd-content, so a percentage child has no
   definite height to resolve against. Scoped with :has() to the previews variant so the
   "Customize your dashboard" step, which shares this element's other rules, keeps its
   existing block layout. */
.shepherd-element.md-ds-modal--display .shepherd-text:has(.md-ds-options--with-previews) {
  display: flex;
  flex-direction: column;
  min-height: 0;
}
.shepherd-element.md-ds-modal--display .shepherd-footer {
  margin-top: 16px;
  padding-top: 16px;
  border-top: 1px solid rgba($la-navy, 0.08);
}

/* ── Getting Started — welcome (first) page ───────────────────────────────────
   Doubled-size intro (~600px → ~1100px wide; the stepper + two preview cards make
   it ~2× taller too). Content: a short lead, a horizontal 1→2 progress stepper
   (reusing the .beta-welcome-steps__num glass badges + a connecting line), and two
   button cards that preview the next two steps as mini-mockups. */
.shepherd-element.md-ds-modal--welcome {
  max-width: 1100px;
  width: 92vw;
  top: 4vh !important;
}
/* Override the centered-intro 40ch text cap so the cards use the full width. */
.shepherd-element.md-ds-modal--welcome .shepherd-text {
  max-width: none !important;
}
.md-ds-welcome {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 28px;
  padding: 8px 0 4px;
}
.md-ds-welcome__lead {
  margin: 0;
  max-width: 60ch;
  text-align: center;
  font-size: 17px;
  line-height: 1.5;
  color: rgba($la-navy, 0.75);
}
/* Horizontal 1 —— 2 stepper. Side padding seats the badge centres over the two
   card columns (25% / 75%); the flexible line connects them. */
.md-ds-welcome__progress {
  display: flex;
  align-items: center;
  width: 100%;
  padding: 0 calc(25% - 18px);
  box-sizing: border-box;
}
.md-ds-welcome__num { font-size: 16px; }
.md-ds-welcome__line {
  flex: 1;
  height: 2px;
  margin: 0 12px;
  border-radius: 999px;
  background: linear-gradient(90deg, rgba($brand-verdigris, 0.5) 0%, rgba($brand-dusty-denim, 0.5) 100%);
  opacity: 0.5;
}
.md-ds-welcome__cards {
  display: flex;
  gap: 24px;
  width: 100%;
}
/* Non-actionable step label — just names a step; sits under its number. No card
   chrome (background/border/shadow/radius) so it doesn't read as a clickable card. */
.md-ds-welcome-card {
  flex: 1 1 0;
  min-width: 0;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 14px;
  /* Pull each label up snug under its number: cancel most of the parent's 28px
     column gap and drop the vertical padding (kept only side padding). */
  margin-top: -18px;
  padding: 0 16px;
  text-align: center;
}
.md-ds-welcome-card__title {
  font-size: 18px;
  font-weight: 700;
  color: $indigo;
}
@media (max-width: 720px) {
  .md-ds-welcome__cards { flex-direction: column; }
  .md-ds-welcome__progress { padding: 0; justify-content: center; }
}
/* The two layout-style cards sit SIDE-BY-SIDE with the OR divider between them.
   `nowrap` keeps the divider from being stranded on a wrapped row — the narrow
   fallback is the explicit column stack in the media query near the end of this
   file, not flex wrapping. */
/* Width of the card+button column in the previews layout. Shared by the column itself
   and the OR divider, so the divider stays centred over the cards rather than over the
   full-width row — they must not drift apart. */
$ds-choice-width: 380px;
.md-ds-options {
  display: flex;
  flex-direction: row;
  flex-wrap: nowrap;
  justify-content: center;
  gap: 12px;
  margin: 8px auto 0;
  max-width: 920px;
}
/* With per-style page previews the pair STACKS: each style card sits on its own row
   beside a `→` and a preview of the current page in that style, so the two rows read
   as "this choice → this result". Wider max-width because each row now carries a card
   AND a preview. */
.md-ds-options--with-previews {
  flex-direction: column;
  align-items: stretch;
  gap: 10px;
  /* Full-bleed modal: use the width, and claim the leftover height so the two preview
     rows can share it. Without this the rows collapse to their content and the previews
     stay small however tall the modal is. Grows inside the flex column set on
     .shepherd-text above.
     The base rule's `margin: 8px auto 0` must be neutralised horizontally: `auto` side
     margins on a FLEX ITEM shrink-wrap and centre it, which pinned both rows to their
     content width and left the previews narrow and portrait-shaped. */
  max-width: none;
  width: 100%;
  margin-left: 0;
  margin-right: 0;
  align-self: stretch;
  flex: 1 1 auto;
  min-height: 0;
}
/* This variant is a column at EVERY width, so the OR divider needs its horizontal
   "— OR —" form always — not only under the 800px stacking query further down, which
   is what governs the no-preview layout. Declared here (on the variant) rather than by
   overriding .md-ds-options__or, so each layout keeps one authoritative rule. */
.md-ds-options--with-previews > .md-ds-options__or {
  flex-direction: row;
  /* Sits over the CHOICE COLUMN, not the full row: the two things it divides are the
     Gentle and Focused cards on the left, so centring it across the whole width (which
     includes the previews) floated it away from what it separates. Same width as that
     column, pinned to the start, and centred within itself. */
  align-self: flex-start;
  width: $ds-choice-width;
  max-width: 100%;
  justify-content: center;
}
.md-ds-options--with-previews > .md-ds-options__or::before,
.md-ds-options--with-previews > .md-ds-options__or::after {
  flex: 0 0 auto;
  width: 18px;
  height: 2px;
  min-height: 0;
}
/* Rows size to their CONTENT rather than splitting the column height equally. Equal
   splitting capped each preview at half the leftover height, which forced the fit to be
   height-constrained and left the panels well short of the right edge. The preview is now
   scaled to fill the width instead, and the roster cap (PREVIEW_MAX_ROSTER_ROWS) is what
   keeps the resulting height in bounds; the modal scrolls if it ever does not. */
.md-ds-optionrow {
  display: flex;
  flex: 0 0 auto;
  flex-direction: row;
  align-items: center;
  gap: 18px;
  min-width: 0;
}
/* The card keeps a readable measure; the preview takes the rest of the row. `min-width:
   0` so a long label shrinks the flex item instead of overflowing. Centred rather than
   stretched: the cards hold only a heading and two bullets, so stretching them to the
   preview's full height left a large blank area under the text. */
.md-ds-optionrow > .md-ds-optionrow__choice {
  flex: 0 1 $ds-choice-width;
  min-width: 0;
  align-self: center;
}
/* Card stacked over its Select button. `align-items: center` shrinks the button to its
   own content width instead of stretching it to the card's. */
.md-ds-optionrow__choice {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 12px;
  min-width: 0;
}
.md-ds-optionrow__choice > .md-ds-option {
  align-self: stretch;
  /* MUST override the base `flex: 1 1 0`. That basis was written for the side-by-side ROW
     (where it equalises WIDTH); in this column it resolves against the cross axis and
     gives the card a height basis of 0, which — with the card's `overflow: hidden` —
     clipped the description away and left only the title showing. */
  flex: 0 0 auto;
}
.md-ds-optionrow__arrow {
  flex: 0 0 auto;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  color: rgba($la-navy, 0.42);
}
/* Preview figure. `:empty` on the viewport collapses the whole figure when there was
   no page shell to photograph, so the chooser degrades to plain cards rather than
   showing an empty frame. */
.md-ds-stylepreview {
  flex: 1 1 auto;
  min-width: 0;
  min-height: 0;
  height: 100%;
  margin: 0;
  display: flex;
  flex-direction: column;
  gap: 6px;
}
.md-ds-stylepreview:has(.md-ds-stylepreview__viewport:empty) {
  display: none;
}
/* The preview window. The iframe inside renders at full viewport size and is scaled to
   fit this box ENTIRELY (see _fitStylePreview) so the whole page is visible — nothing is
   cropped. The box takes whatever height the row gives it; `min-height` keeps the page
   legible if the modal is very short. */
.md-ds-stylepreview__viewport {
  position: relative;
  overflow: hidden;
  /* BOTH dimensions are set inline by _fitStylePreviews, to the scaled size of the
     page's actual content — so the panel hugs the page rather than letterboxing it, and
     a short layout produces a short panel instead of a blank tail. `flex: 0 0 auto` so
     the column does not stretch it back out to fill the row.
     Left-aligned in the leftover space (not centred): the figure keeps a full-width flex
     basis so _fitStylePreviews has a stable box to measure against — centring the
     shrunken panel inside it opened a ~270px gap after the arrow and broke the
     "card → preview" adjacency the whole row is meant to convey. */
  flex: 0 0 auto;
  width: 100%;
  margin-inline: 0 auto;
  /* Floor only for the moment before the fit runs; the inline height supersedes it. */
  min-height: 80px;
  border-radius: 12px;
  border: 1px solid rgba($la-navy, 0.16);
  background: #fff;
  box-shadow: 0 2px 10px rgba($la-navy, 0.1);
}
.md-ds-stylepreview__frame {
  position: absolute;
  top: 0;
  left: 0;
  border: 0;
  transform-origin: top left;
  /* Decorative screenshot — never interactive, so pointer + touch go to the card. */
  pointer-events: none;
}
/* Centred UNDER ITS OWN PANEL, not under the figure. The panel is left-aligned in the
   figure's leftover space, and those two are only the same width while the scale is
   below 1:1 — once it clamps (a viewport wider than the page renders at), the panel is
   narrower than the figure and a figure-centred caption drifts off to the right. So
   _fitStylePreviews stamps the caption with the panel's width and this centres within
   that. */
.md-ds-stylepreview__caption {
  font-size: 15px;
  font-weight: 600;
  color: rgba($la-navy, 0.62);
  text-align: center;
}
/* The selected style's preview is the one the user is committing to — give it the
   same accent treatment the selected card gets, so the pair reads as one unit. */
.md-ds-optionrow:has(.md-ds-select.is-selected) .md-ds-stylepreview__viewport {
  border-color: rgba($la-teal, 0.55);
  box-shadow: 0 3px 14px rgba($la-teal, 0.22);
}
.md-ds-optionrow:has(.md-ds-select.is-selected) .md-ds-optionrow__arrow {
  color: rgba($la-teal, 0.9);
}
/* Narrow: each option becomes a COLUMN — card, Select button, arrow, preview stacked —
   and the arrow rotates to point down at the preview so the "choice → result" reading
   survives the reflow.
   Side by side, proximity alone makes it obvious which preview belongs to which card.
   Stacked, everything is in one vertical line and that grouping is lost, so the row
   becomes a visible GROUP CONTAINER: its own surface, border and padding, drawing a box
   around all of one view's content. */
@media (max-width: 900px) {
  .md-ds-options--with-previews {
    /* Wider gap than the in-row spacing, so the break BETWEEN the two groups reads as
       larger than the spacing inside either one. */
    gap: 18px;
  }
  .md-ds-optionrow {
    flex-direction: column;
    align-items: center;
    gap: 14px;
    padding: 18px 16px;
    border-radius: 20px;
    border: 1px solid rgba($la-navy, 0.10);
    background: rgba(255, 255, 255, 0.42);
    box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.7);
  }
  /* The chosen group is tinted so the selection is still obvious once the cards are no
     longer beside each other for comparison. */
  .md-ds-optionrow:has(.md-ds-select.is-selected) {
    border-color: rgba($la-teal, 0.45);
    background: rgba($la-teal, 0.06);
  }
  /* Was `> .md-ds-option`, which stopped matching when the card gained its `__choice`
     wrapper — the card is no longer a direct child of the row. */
  /* Pass-through: the card and its Select button stop being wrapped and become direct
     flex items of the row, so `order` can place them independently. Stacked, the reading
     order is card → arrow → preview → caption → BUTTON: you look at the option, see what
     the page becomes, and only then commit. Side by side the button stays tucked under
     its card, where the whole choice column is taken in at once.
     `order` alone cannot do this — the button is nested inside `__choice`, and order only
     sorts siblings. `__choice` carries no background or border of its own, so dropping its
     box costs nothing. */
  .md-ds-optionrow__choice {
    display: contents;
  }
  /* Centred, and the 420px reading-measure cap lifted a little: stretched-with-a-max-width
     pins the box to the START of the cross axis, which left the card hugging the group's
     left edge instead of sitting in the middle of it. */
  .md-ds-optionrow__choice > .md-ds-option {
    order: 1;
    align-self: center;
    width: 100%;
    max-width: 560px;
  }
  .md-ds-optionrow__arrow {
    order: 2;
    transform: rotate(90deg);
  }
  /* MUST stretch. The row is `align-items: center` here, which makes the figure
     shrink-to-fit — and `_fitStylePreviews` derives the preview scale from
     `figure.clientWidth`, so a shrink-wrapped figure collapsed the preview to a fraction
     of the width available (measured ~220px inside a ~756px group). */
  .md-ds-stylepreview {
    order: 3;
    align-self: stretch;
    height: auto;
  }
  .md-ds-select {
    order: 4;
  }
  /* Full width and centred: pinning it to a 380px column only makes sense while the
     cards occupy that column, which they no longer do here. */
  .md-ds-options--with-previews > .md-ds-options__or {
    align-self: center;
    width: 100%;
  }
}
/* Stylized OR divider between the two layout-style buttons, so the pair reads as
   an either/or choice. Side-by-side (the default) it's a VERTICAL rule: the word
   OR with a hairline running the full card height above and below it. Stacked
   (narrow screens) the same element rotates into the horizontal "— OR —" between
   the two cards — see the media query at the end of this file. */
.md-ds-options__or {
  flex: 0 0 auto;
  align-self: stretch;
  display: inline-flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 8px;
  font-size: 14px;
  font-weight: 700;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: rgba($la-navy, 0.5);
}
.md-ds-options__or::before,
.md-ds-options__or::after {
  content: "";
  /* Grow to fill the card height as a vertical hairline; `min-height` keeps a
     visible tick even when the cards are short. */
  flex: 1 1 auto;
  width: 2px;
  min-height: 18px;
  border-radius: 2px;
  background: rgba($la-navy, 0.2);
}
/* Layout option card — mirrors the dashboard Speak Mode as-button: glassy
   white surface, hairline border, layered raised shadow + hover lift. Number
   badge reuses the .beta-welcome-steps__num glass circle. */
.md-ds-option {
  /* Side-by-side: the two cards share the row EQUALLY (`flex: 1 1 0` ignores the
     differing content widths) and stretch to equal HEIGHT (container align-items
     defaults to stretch). `min-width: 0` lets them shrink instead of overflowing;
     the cap keeps a long line from stretching a card past a readable measure.
     Stacked (narrow screens) they hug their content again — see the media query
     at the end of this file. */
  flex: 1 1 0;
  min-width: 0;
  max-width: 420px;
  overflow: hidden;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 14px;
  padding: 16px 18px;
  text-align: center;
  font: inherit;
  color: inherit;
  border-radius: 18px;
  border: 1px solid rgba($la-navy, 0.10);
  background: linear-gradient(135deg, rgba(255, 255, 255, 0.96) 0%, rgba(248, 250, 252, 0.92) 100%);
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.85),
    inset 0 -1px 0 rgba($la-navy, 0.06),
    0 1px 2px rgba($la-navy, 0.05),
    0 4px 10px rgba($la-navy, 0.08),
    0 12px 28px rgba($la-navy, 0.10);
  /* No `cursor: pointer`: the card is presentational now, and the Select button inside it
     is the control. A pointer cursor over non-clickable text would promise an action the
     card no longer performs. */
  transition: box-shadow 180ms ease-out, transform 140ms ease-out;
  -webkit-tap-highlight-color: transparent;
}
/* Select button — the actual control. Sits at the bottom of its card, pushed there by
   `margin-top: auto` so both buttons line up even when the two descriptions differ in
   length.
   Each button is styled as the PRIMARY CTA of the view it selects, so the pair doubles as
   a swatch of what the buttons look like in each style: "Select Gentle View" wears the
   Gentle Done button, "Select Focused View" wears the Focused one. The per-view fills are
   below and are keyed off `data-gst-layout`, NOT off the live `body.ll-layout-focused` —
   both must be visible at once regardless of which view is currently active.
   Shape mirrors `.shepherd-element .shepherd-button` (pill, 1.5px border, 600 weight) so
   these read as the same family of control. */
.md-ds-select {
  /* Shrinks to its own content — it sits under the card, not across it. */
  align-self: center;
  max-width: 100%;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  /* Padding scales with the type so the pill stays proportionate as it shrinks.
     calc() around the mixed units is REQUIRED — SassC cannot evaluate px + vw at compile
     time inside clamp() (docs/CSS_SCSS_GUIDELINES.md). */
  padding: clamp(8px, calc(6px + 0.35vw), 11px) clamp(14px, calc(10px + 0.8vw), 22px);
  font-family: inherit;
  /* Fluid and deliberately smaller than the footer CTA: this is a choice, not the
     page's primary action, and two of them sit in a narrow column. px not rem —
     bootstrap sets `html { font-size: 10px }`, so rem here would render tiny. */
  font-size: clamp(13px, calc(11px + 0.32vw), 15px);
  font-weight: 600;
  letter-spacing: 0;
  line-height: 1.25;
  border-radius: $aac-radius-pill;
  border: 1.5px solid transparent;
  cursor: pointer;
  transition: transform 0.18s ease, box-shadow 0.18s ease,
              background 0.18s ease, border-color 0.18s ease, color 0.18s ease;
  -webkit-tap-highlight-color: transparent;
}
/* GENTLE — mirrors `.shepherd-element .md-tour__btn--primary`: verdigris glass fill,
   navy text, illuminated bevel. */
.md-ds-select[data-gst-layout="gentle"] {
  background: rgba(44, 183, 176, 0.22);
  border-color: rgba($brand-dusty-denim, 0.28);
  color: $la-navy;
  box-shadow:
    inset 0 2px 1px rgba(255, 255, 255, 1),
    inset 0 -2px 3px rgba(76, 134, 216, 0.16),
    0 1px 1px rgba(22, 34, 70, 0.06),
    0 3px 6px rgba(22, 34, 70, 0.10),
    0 14px 32px rgba(76, 134, 216, 0.26);
}
.md-ds-select[data-gst-layout="gentle"]:hover {
  background: rgba(44, 183, 176, 0.32);
  border-color: rgba($brand-dusty-denim, 0.40);
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 1),
    inset 0 -1px 0 rgba(76, 134, 216, 0.14),
    0 1px 2px rgba(22, 34, 70, 0.10),
    0 16px 36px rgba(76, 134, 216, 0.30);
  transform: translateY(-1px);
}
.md-ds-select[data-gst-layout="gentle"]:focus-visible {
  outline: none;
  box-shadow:
    0 0 0 3px rgba($brand-dusty-denim, 0.45),
    inset 0 1px 1px rgba(255, 255, 255, 0.7),
    0 10px 24px rgba(76, 134, 216, 0.20);
}
/* FOCUSED — mirrors the focused-view primary: glossy desaturated-navy radial fill, white
   text, raised bevel. Same values as the `body.ll-layout-focused …md-tour__btn--primary`
   rule further down this file. */
.md-ds-select[data-gst-layout="focused"] {
  background: radial-gradient(ellipse at center in oklab,
    #{$focus-hero-center} 0%,
    #{$focus-hero-edge} 100%);
  border-color: rgba($focus-on-dark, 0.14);
  color: $focus-on-dark;
  box-shadow:
    inset 0 2px 0 rgba($focus-on-dark, 0.34),
    inset 0 -5px 10px rgba($focus-shadow-ink, 0.34),
    0 3px 8px rgba($focus-shadow-ink, 0.28),
    0 0 18px rgba($focus-hero-glow, 0.10);
}
.md-ds-select[data-gst-layout="focused"]:hover {
  border-color: rgba($focus-on-dark, 0.2);
  box-shadow:
    inset 0 2px 0 rgba($focus-on-dark, 0.38),
    inset 0 -5px 10px rgba($focus-shadow-ink, 0.36),
    0 4px 12px rgba($focus-shadow-ink, 0.32),
    0 0 26px rgba($focus-hero-glow-hover, 0.35);
  /* No lift — matches the focused primary, which deliberately drops the translateY. */
  transform: none;
}
.md-ds-select[data-gst-layout="focused"]:focus-visible {
  outline: none;
  box-shadow:
    0 0 0 3px rgba($focus-accent, 0.45),
    inset 0 2px 0 rgba($focus-on-dark, 0.34),
    0 6px 14px rgba($focus-shadow-ink, 0.34);
}
/* Chosen state is carried by the CHECK MARK plus the card/preview accent (via `:has()`),
   deliberately NOT by changing the fill — the fill is now information in its own right
   (it shows what that view's primary button looks like) and must stay put. */
.md-ds-select__check {
  display: none;
  align-items: center;
}
.md-ds-select.is-selected .md-ds-select__check {
  display: inline-flex;
}
/* Label swap: "Select Gentle View" → "Selected…". Both are in the DOM; only one is ever
   displayed, so the accessible name changes with the visual label and no JS rewrites copy.
   `display: none` (not `visibility`) so the pill re-shrinks to whichever label is showing
   — the button is sized by its content now. */
.md-ds-select__label--done {
  display: none;
}
.md-ds-select.is-selected .md-ds-select__label--idle {
  display: none;
}
.md-ds-select.is-selected .md-ds-select__label--done {
  display: inline;
}
/* Lift on hovering the CARD is kept (the card and its button read as one unit), but the
   focus ring below moved to the button — the card is a <div> now and never takes focus. */
.md-ds-option:hover,
.md-ds-optionrow__choice:has(.md-ds-select:focus-visible) .md-ds-option {
  transform: translateY(-1px);
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.95),
    inset 0 -1px 0 rgba($la-navy, 0.07),
    0 2px 4px rgba($la-navy, 0.06),
    0 8px 18px rgba($la-navy, 0.10),
    0 20px 44px rgba($la-navy, 0.14);
}
.md-ds-optionrow__choice:has(.md-ds-select:active) .md-ds-option {
  transform: translateY(0.5px);
}
.md-ds-option__label {
  display: flex;
  flex-direction: column;
  align-items: center;
  font-size: 16px;
  font-weight: 700;
  color: $indigo;
  letter-spacing: 0.01em;
  line-height: 1.25;
}
/* Thin intentional underline beneath each option, in the brand highlight
   gradient (matches the dashboard card dividers). */
.md-ds-option__label::after {
  content: "";
  /* Extend 4px past the label text (2px each side). Percentages don't feed
     the flex item's intrinsic width, so the label still hugs its text and the
     underline tracks each header's actual width. */
  width: calc(100% + 4px);
  margin-left: -2px;
  height: 2px;
  margin-top: 8px;
  border-radius: 2px;
  background: $la-highlight-gradient;
}
/* Title + one-line descriptor stack to the right of the number circle. */
.md-ds-option__text {
  display: flex;
  flex-direction: column;
  align-items: center;
  min-width: 0;
}
/* Small, muted one-line descriptor beneath each layout title — adds decision
   clarity without raising visual priority or cognitive load. */
.md-ds-option__desc {
  margin-top: 6px;
  font-size: 14px;
  font-weight: 500;
  line-height: 1.3;
  color: rgba($la-navy, 0.55);
  /* Center the lead line + bracketed bullet group on the card. The bullets keep
     their own left-to-right read inside the bracket; the whole group is centered. */
  display: flex;
  flex-direction: column;
  align-items: center;
  text-align: center;
}
/* Lead line above the Gentle View bullet list ("May be a good fit if you:") —
   a touch stronger/darker than the bullets so it reads as their intro. */
.md-ds-option__desc-lead {
  display: block;
  font-weight: 600;
  color: rgba($la-navy, 0.7);
}
/* Overarching bracket wrapping the bullet group — a modern "[": a soft
   verdigris left rule with short rounded top/bottom ticks, framing the three
   "good fit" items as one set. */
.md-ds-option__bracket {
  position: relative;
  margin-top: 8px;
  padding-left: 13px;
  /* The bracket group is centered as a block on the card (via the centered desc),
     but the bullets themselves read LEFT-aligned inside it. */
  text-align: left;
}
.md-ds-option__bracket::before {
  content: "";
  position: absolute;
  left: 0;
  top: 1px;
  bottom: 1px;
  width: 7px;
  border: 2px solid rgba($brand-verdigris, 0.45);
  border-right: none;
  border-radius: 5px 0 0 5px;
}
/* Professional bullet list under the lead — custom verdigris dots (not the
   default browser markers) for a polished, on-brand look. */
.md-ds-option__list {
  margin: 0;
  padding: 0;
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 5px;
}
.md-ds-option__list li {
  position: relative;
  padding-left: 16px;
  font-size: 14px;
  line-height: 1.3;
  color: rgba($la-navy, 0.55);
}
.md-ds-option__list li::before {
  content: "";
  position: absolute;
  left: 2px;
  top: 0.62em;
  width: 5px;
  height: 5px;
  border-radius: 50%;
  background: $brand-verdigris;
}
@media (prefers-reduced-motion: reduce) {
  .md-ds-option {
    transition: none;
  }
  .md-ds-option:hover,
  .md-ds-option:focus-visible,
  .md-ds-option:active {
    transform: none;
  }
}
/* Selected option (set by the show hook on click) — verdigris ring. */
.md-ds-optionrow__choice:has(.md-ds-select.is-selected) .md-ds-option {
  border-color: rgba($brand-verdigris, 0.6) !important;
  /* Calm verdigris atmospheric tint layered over the white base — instantly
     identifiable at a glance, but no saturated fill or harsh "selected tab" look. */
  background:
    radial-gradient(130% 130% at 0% 0%, rgba($brand-verdigris, 0.10), transparent 58%),
    linear-gradient(135deg, rgba(255, 255, 255, 0.97) 0%, rgba(243, 250, 249, 0.94) 100%) !important;
  box-shadow:
    0 0 0 2px rgba($brand-verdigris, 0.45),     /* crisp inner ring — slightly stronger */
    0 0 20px rgba($brand-verdigris, 0.18),      /* soft outer glow — gentle anchoring */
    inset 0 1px 0 rgba(255, 255, 255, 0.95),
    0 10px 26px rgba($la-navy, 0.16) !important; /* elevated surface depth */
}
/* Brighter, slightly thicker divider under the SELECTED layout's title — a small
   accent that reinforces the choice without raising overall visual volume. */
.md-ds-optionrow__choice:has(.md-ds-select.is-selected) .md-ds-option__label::after {
  height: 3px;
  box-shadow: 0 0 6px rgba($brand-verdigris, 0.3);
}
/* Disabled Next button — until a layout option is chosen. */
.md-tour__btn--disabled,
.md-tour__btn:disabled {
  opacity: 0.45 !important;
  cursor: not-allowed !important;
  box-shadow: none !important;
  transform: none !important;
}
/* ── Gentle Layout preview — a larger, professional miniature of THIS user's
   actual home dashboard, shown below the options. Cards are placed via inline
   grid-row/column from the component so it mirrors the real (user-type-aware)
   grid, and each is labeled with its real card name. ── */
.md-ds-preview {
  /* Page 1 (display style): clear separation from the style cards above so the
     "[ PREVIEW ]" legend reads as the start of a distinct preview region. */
  margin-top: 28px;
}
/* Two "what you can do" checklist items below the Customize step header, joined
   by an "— and/or —" divider. Pills mirror the section-toggle chips; the check
   sits in a brand gradient disc. */
.md-ds-howto {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: center;
  gap: 10px 14px;
  margin: 4px auto 16px;
}
.md-ds-howto__item {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  padding: 7px 16px;
  border-radius: 999px;
  border: 1px solid rgba($la-navy, 0.10);
  background: linear-gradient(135deg, #ffffff, rgba(248, 250, 252, 0.94));
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.9), 0 1px 2px rgba($la-navy, 0.05), 0 5px 14px rgba($la-navy, 0.05);
  font-size: 14px;
  font-weight: 600;
  color: $indigo;
}
/* Stylish diamond bullet — a small rounded-corner square rotated 45°, filled with
   the brand denim→verdigris gradient and a soft drop shadow + inner highlight. */
.md-ds-howto__bullet {
  flex: 0 0 auto;
  width: 9px;
  height: 9px;
  transform: rotate(45deg);
  border-radius: 2px;
  background:
    linear-gradient(135deg, rgba(255, 255, 255, 0.55), rgba(255, 255, 255, 0) 55%),
    linear-gradient(150deg, $brand-dusty-denim, $brand-verdigris);
  box-shadow: 0 1px 2px rgba($la-navy, 0.28), inset 0 1px 0 rgba(255, 255, 255, 0.4);
}
.md-ds-howto__sep {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  font-size: 13px;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: rgba($la-navy, 0.5);
}
.md-ds-howto__sep::before,
.md-ds-howto__sep::after {
  content: "";
  width: 14px;
  height: 2px;
  border-radius: 2px;
  background: rgba($la-navy, 0.2);
}
/* Responsive — once the two how-to pills can't sit side-by-side, stack them into
   a centered column so the "— AND/OR —" wraps onto its OWN centered row between
   them (instead of being stranded inline beside a pill). This step's modal is
   full viewport width and the pills are compact, so they fit side-by-side down
   to ~md; below that they wrap. (The container already centers via
   `align-items:center`, so just flipping to column is enough.) */
@media (max-width: $aac-breakpoint-md) {
  .md-ds-howto {
    flex-direction: column;
  }
}
/* Page 2 (Customize your dashboard): two-up layout — the live preview on the LEFT,
   the section-visibility toggles as a PANEL on the RIGHT (was a single centered
   column with the toggles stacked on top). Grid areas put the legend above the
   live preview in the left column; the toggles panel spans both rows on the right. */
.md-ds-preview--with-toggles {
  margin-top: 6px;
  display: grid;
  /* The toggles panel hugs its content (widest pill + padding); the preview takes
     the rest. The long heading is wrapped (not allowed to stretch the panel) by
     the .md-ds-sections__title rule below. */
  grid-template-columns: minmax(0, 1fr) max-content;
  grid-template-rows: auto minmax(0, 1fr);
  /* The legend spans BOTH columns so it centers across the full page width (its
     own justify-content:center then centers the content). sections still sits in
     the LIVE row (row 2) so the toggles panel's top lines up with the live
     preview card's top, not with the legend above it. */
  grid-template-areas:
    "legend   legend"
    "live     sections";
  align-items: start;
  column-gap: 24px;
}
.md-ds-preview--with-toggles .md-ds-preview__legend { grid-area: legend; }
.md-ds-preview--with-toggles .md-ds-preview__live { grid-area: live; }
/* Toggles become the right-hand panel: drop the centered-top-block max-width +
   auto margins (the inset card treatment is kept and now reads as a side panel),
   sit it at the top of its area, and stack the pills vertically in the column. */
.md-ds-preview--with-toggles .md-ds-sections {
  grid-area: sections;
  max-width: none;
  margin: 0;
  align-self: start;
}
.md-ds-preview--with-toggles .md-ds-sections__title {
  text-align: left;
  /* Wrap the heading to the pill-stack width instead of letting its long single
     line stretch the whole panel: width:min-content makes it contribute only its
     longest word to the panel's content-width (so the wider pills win), then
     min-width:100% expands it back to the resolved panel width to wrap cleanly. */
  width: min-content;
  min-width: 100%;
}
.md-ds-preview--with-toggles .md-ds-sections__list {
  flex-direction: column;
  flex-wrap: nowrap;
  align-items: flex-start;
  justify-content: flex-start;
}
/* Narrow viewports (small landscape): fall back to the original single column
   with the toggles stacked on top of the preview. */
@media (max-width: 860px) {
  .md-ds-preview--with-toggles {
    grid-template-columns: 1fr;
    grid-template-areas:
      "sections"
      "legend"
      "live";
    column-gap: 0;
  }
  .md-ds-preview--with-toggles .md-ds-sections {
    max-width: 920px;
    margin: 0 auto 24px;
  }
  .md-ds-preview--with-toggles .md-ds-sections__title {
    text-align: center;
  }
  .md-ds-preview--with-toggles .md-ds-sections__list {
    flex-direction: row;
    flex-wrap: wrap;
    align-items: center;
    justify-content: center;
  }
}
/* Combined preview legend — one professional line above the live preview that
   reads as a progression: a bracketed preview tag, a dot, then the swap
   instruction. Replaces the separate top caption + bottom drag hint. */
.md-ds-preview__legend {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: center;
  gap: 12px 14px;
  margin: 2px 0 10px;
}
/* "Preview — Gentle Layout" framed by thin, modern brackets (drawn via
   ::before/::after in the brand accent) — uppercase, tracked, quietly muted. */
.md-ds-preview__legend-tag {
  position: relative;
  padding: 0 15px;
  font-size: 14px;
  font-weight: 600;
  letter-spacing: 0.07em;
  text-transform: uppercase;
  color: rgba($la-navy, 0.5);
}
.md-ds-preview__legend-tag::before,
.md-ds-preview__legend-tag::after {
  position: absolute;
  top: 50%;
  transform: translateY(-52%);
  font-size: 19px;
  font-weight: 300;
  line-height: 1;
  color: rgba($brand-dusty-denim, 0.55);
}
.md-ds-preview__legend-tag::before { content: "["; left: 0; }
.md-ds-preview__legend-tag::after  { content: "]"; right: 0; }
/* Dot connector between the tag and the instruction. */
.md-ds-preview__legend-dot {
  width: 4px;
  height: 4px;
  border-radius: 50%;
  background: rgba($la-navy, 0.26);
}
/* The swap instruction — calm sentence guidance, sized for the AAC 13px floor. */
.md-ds-preview__legend-hint {
  font-size: 14px;
  font-weight: 500;
  /* A touch more contrast than the bracketed tag's effective weight, so the
     interaction guidance scans as an equal partner to the preview context —
     without enlarging or bolding it. */
  color: rgba($la-navy, 0.6);
}
/* Section visibility checklist — modern custom checkboxes that toggle which
   home-dashboard cards appear; toggling one also live-hides the matching card
   in the preview clone below. */
.md-ds-sections {
  max-width: 920px;
  /* More space below the section block so it reads as a finished step before the
     "[ PREVIEW ]" legend / live grid begins. */
  margin: 0 auto 30px;
  /* Inset grouping that reads as NESTED INTO the modal surface, not a separate
     floating slab: a very faint tint that blends with the modal background, an
     almost-invisible edge, and a soft, shallow inner shadow (softer top edge,
     gentler bottom-edge contrast) so it feels carved into the surface. */
  padding: 16px 18px 18px;
  border-radius: 18px;
  background: linear-gradient(180deg, rgba($la-navy, 0.035), rgba($la-navy, 0.015));
  border: 1px solid rgba($la-navy, 0.05);
  box-shadow: inset 0 1px 4px rgba($la-navy, 0.05), inset 0 -1px 0 rgba(255, 255, 255, 0.3);
}
.md-ds-sections__title {
  font-size: 14px;
  /* Lighter weight + a touch less contrast so this reads as supportive guidance,
     not a heading competing with the layout titles. Size unchanged (AAC). */
  font-weight: 500;
  color: rgba($la-navy, 0.55);
  text-align: center;
  margin-bottom: 10px;
}
.md-ds-sections__list {
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  gap: 10px 14px;
}
.md-ds-section {
  display: inline-flex;
  align-items: center;
  gap: 9px;
  /* Slender, fully-rounded pill. Trim vertical padding for a thinner capsule; extra
     right padding (vs left, which hosts the check) keeps the label visually centred.
     Layered shadow (crisp 1px lift + soft ambient) reads modern, not heavy. */
  padding: 6px 18px 6px 8px;
  border-radius: 999px;
  border: 1px solid rgba($la-navy, 0.10);
  /* Always-on offset ring on EVERY pill (not just the focused/selected one) — the
     halo the browser used to draw only on click, now a consistent design element.
     `outline` (+ offset) doesn't affect layout, so it never reflows the row. */
  outline: 1.5px solid rgba($brand-dusty-denim, 0.28);
  outline-offset: 2px;
  background: linear-gradient(135deg, #ffffff, rgba(248, 250, 252, 0.94));
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.9), 0 1px 2px rgba($la-navy, 0.05), 0 5px 14px rgba($la-navy, 0.05);
  cursor: pointer;
  user-select: none;
  transition: border-color 160ms ease-out, box-shadow 160ms ease-out;
}
.md-ds-section:hover {
  border-color: rgba($brand-dusty-denim, 0.45);
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.95), 0 4px 12px rgba($la-navy, 0.10);
}
/* Visually-hidden native input — keeps keyboard focus + a11y semantics while
   the styled box does the visuals. */
.md-ds-section__input {
  position: absolute;
  opacity: 0;
  width: 1px;
  height: 1px;
  margin: 0;
  pointer-events: none;
}
.md-ds-section__box {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 20px;
  height: 20px;
  flex: 0 0 auto;
  /* Modern circle. Unchecked: a softly RECESSED well — top-down light gradient + an
     inner shadow at the top edge and a thin white catch at the bottom, so it reads
     as a dimensional concave dot rather than a flat ring. */
  border-radius: 50%;
  border: 1px solid rgba($la-navy, 0.20);
  background: linear-gradient(180deg, #ffffff, #e9eef4);
  color: #ffffff;
  box-shadow: inset 0 1px 2px rgba($la-navy, 0.14), inset 0 -1px 0 rgba(255, 255, 255, 0.9);
  transition: background 150ms ease-out, border-color 150ms ease-out, box-shadow 150ms ease-out;
}
.md-ds-section__check {
  opacity: 0;
  transform: scale(0.6);
  transition: opacity 130ms ease-out, transform 130ms ease-out;
}
.md-ds-section__input:checked ~ .md-ds-section__box {
  /* Checked: the circle pops UP — brand gradient fill, an outer drop shadow (raised
     off the pill), a glossy top highlight and a bottom inner shadow for a rounded,
     three-dimensional button feel. */
  background: $la-highlight-gradient;
  border-color: transparent;
  box-shadow: 0 2px 5px rgba($brand-stormy-teal, 0.30), inset 0 1px 0 rgba(255, 255, 255, 0.5), inset 0 -2px 3px rgba($la-navy, 0.20);
}
.md-ds-section__input:checked ~ .md-ds-section__box .md-ds-section__check {
  opacity: 1;
  transform: scale(1);
}
.md-ds-section__input:focus-visible ~ .md-ds-section__box {
  outline: 2px solid rgba($brand-dusty-denim, 0.6);
  outline-offset: 2px;
}
.md-ds-section__label {
  font-size: 14px;
  font-weight: 600;
  color: $indigo;
}
/* The live preview frame holds a 1:1, non-interactive clone of the real home
   dashboard grid, injected by the show hook. */
.md-ds-preview__live {
  position: relative;
  /* Single source of truth for the preview's render scale. Applied as a CSS
     `zoom` on .md-ds-preview__page (below) so the cloned dashboard renders 20%
     smaller WITHOUT a transform's leftover layout gap, and read by JS
     (_onDisplayShow) so the drag-to-swap ghost can divide its cursor delta by the
     same factor and stay 1:1 under the pointer. */
  --md-ds-preview-zoom: 0.8;
  border-radius: 16px;
  border: 1px solid rgba($la-navy, 0.10);
  background:
    radial-gradient(1000px 460px at 6% 0%, rgba($brand-stormy-teal, 0.12), transparent 55%),
    radial-gradient(900px 460px at 96% 14%, rgba($brand-dusty-denim, 0.10), transparent 55%),
    linear-gradient(180deg, #fdfdfe, #f3f6fb);
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.9), 0 10px 26px rgba($la-navy, 0.10);
  overflow: hidden;
  /* Extra top padding so the scaled grid sits lower in the frame, with breathing
     room above the first row of cards. */
  padding: 30px 0 16px;
  min-height: 188px;
}
/* Empty-state overlay — shown over the preview when no display elements are
   selected (Next is disabled until at least one is). Frosted scrim + a centered
   glass card, matching the modal's surfaces. */
.md-ds-empty {
  position: absolute;
  inset: 0;
  display: none;
  align-items: center;
  justify-content: center;
  padding: 24px;
  background: rgba(248, 250, 252, 0.66);
  -webkit-backdrop-filter: blur(6px);
  backdrop-filter: blur(6px);
  z-index: 2;
}
.md-ds-empty.is-visible {
  display: flex;
}
/* Placeholder box — a gray DOUBLE outline (border + offset outline), no fill or
   shadow, so it reads as an empty-state hint and is never mistaken for a
   card/button that will appear on the home page. */
.md-ds-empty__card {
  max-width: 440px;
  text-align: center;
  padding: 26px 30px 28px;
  border-radius: 16px;
  background: transparent;
  border: 2px solid rgba(100, 116, 139, 0.5);
  outline: 2px solid rgba(100, 116, 139, 0.5);
  outline-offset: 5px;
}
.md-ds-empty__icon {
  color: $brand-dusty-denim;
  margin-bottom: 14px;
}
.md-ds-empty__title {
  font-size: 19px;
  font-weight: 700;
  color: $indigo;
  letter-spacing: 0.01em;
  margin-bottom: 8px;
}
.md-ds-empty__text {
  font-size: 15px;
  line-height: 1.45;
  color: rgba($la-navy, 0.66);
}
/* Landscape-orientation overlay reused on the display step (same visual as the
   board-detail one). Hidden by default; shown at ≤640px — rotating to landscape
   widens past 640px and auto-hides it. Lifted above the Shepherd modal content
   so it gates the step. */
.md-board-detail-portrait-overlay.md-ds-orientation {
  display: none;
  z-index: 100000;
}
@media (max-width: 640px) {
  .md-board-detail-portrait-overlay.md-ds-orientation {
    display: flex;
  }
}
/* create-board-new variant of the same landscape-rotate overlay. Same visual as
   the board-detail/display-style ones; hidden by default and shown at ≤768px
   (the build canvas is too cramped below that to create + customize a board).
   `--dismissed` (set by "Continue Anyway") beats the media query so mounted /
   non-rotatable setups can proceed. See create-board-new.hbs. */
.md-board-detail-portrait-overlay.nb-orientation-overlay {
  display: none;
  z-index: 100000;
}
@media (max-width: 768px) {
  .md-board-detail-portrait-overlay.nb-orientation-overlay {
    display: flex;
  }
}
.md-board-detail-portrait-overlay.nb-orientation-overlay.nb-orientation-overlay--dismissed {
  display: none !important;
}
/* Workspace-like wrapper so the cloned grid lays out at the same width as the
   real home page; the clone is the actual `.md-grid--dashboard`, so its
   responsive (viewport-driven) layout is identical to what the user sees. */
.md-ds-preview__page {
  /* Slightly narrower than before (1080 vs 1200, a touch more side inset) so the
     dashboard renders a bit smaller and less dominant — still well above the
     950px viewport breakpoint, so it keeps the real two-column desktop layout. */
  max-width: min(1080px, calc(100% - 48px));
  margin: 0 auto;
  /* Render the whole cloned workspace 20% smaller. `zoom` (not transform: scale)
     shrinks the LAYOUT box too, so there's no leftover empty space below the
     preview the way a transform would leave. Viewport media queries are unaffected,
     so the clone keeps its real two-column desktop layout — just scaled down. The
     drag math compensates for this factor (see --md-ds-preview-zoom). */
  zoom: var(--md-ds-preview-zoom, 1);
}
/* Welcome-hero banner clone — sits above the grid clone in the preview; inert and
   spaced from the cards below. Hidden/shown by syncState like the section cards. */
.md-ds-preview__hero {
  pointer-events: none;
  margin-bottom: 18px;
}
/* The clone is a pure visual preview — never interactive (looks live, isn't). */
.md-ds-preview__clone,
.md-ds-preview__clone * {
  pointer-events: none !important;
  cursor: default !important;
  -webkit-user-select: none !important;
  user-select: none !important;
}
/* Drag-to-swap (flagged): a transparent OVERLAY hosts the pointer drag so the card
   itself keeps the clone's `pointer-events:none` and never enters :hover — i.e. no
   hover lift/glow, the only affordance is the overlay's grab cursor. JS adds these
   nodes only when the flag is on (presence IS the gate). The card is made a
   positioning context so the overlay can inset to it; the overlay re-enables
   pointer-events (compound selector 0,2,0 + !important beats the clone's inert
   `*` rule) and sets `touch-action:none` so touch drags aren't hijacked as scrolls. */
.md-ds-preview__clone .md-ds-draggable {
  position: relative;
  transition: opacity 140ms ease-out, outline-color 140ms ease-out;
}
.md-ds-preview__clone .md-ds-drag-overlay {
  position: absolute;
  inset: 0;
  z-index: 4;
  border-radius: inherit;
  pointer-events: auto !important;
  cursor: grab !important;
  touch-action: none !important;
}
/* The dragged card becomes a translucent "ghost" that follows the cursor (JS
   translates it). The lift shadow uses `filter: drop-shadow` rather than
   box-shadow because box-shadow is pinned inline (hover-suppression) and can't be
   overridden from CSS; filter is free and also softly clips to the card shape. */
.md-ds-preview__clone .md-ds-draggable.md-ds-dragging {
  opacity: 0.9;
  /* Lift shadow is an inline box-shadow set by JS on grab (composites cheaply on the
     will-change:transform layer) rather than `filter: drop-shadow`, which forced a
     filter render pass that re-rasterized the large gradient card as it moved. */
  transition: none !important;
  will-change: transform;
}
.md-ds-preview__clone .md-ds-draggable.md-ds-dragging .md-ds-drag-overlay {
  cursor: grabbing !important;
}
/* R2 — the user is hovering a drop the active layout forbids (Focused View: an action
   button dragged out onto a full-width row). Warning outline on the ghost + a not-allowed
   cursor on the captured overlay; the legend hint simultaneously swaps to say what IS
   allowed (reorder within the row). The denim dashed outline above = a valid target; this
   red dashed outline = blocked, so the two never read the same. */
.md-ds-preview__clone .md-ds-draggable.md-ds-dragging.md-ds-drag-blocked {
  outline: 2px dashed rgba($brand-danger, 0.85);
  outline-offset: 2px;
}
.md-ds-preview__clone .md-ds-draggable.md-ds-dragging.md-ds-drag-blocked .md-ds-drag-overlay {
  cursor: not-allowed !important;
}
.md-ds-preview__legend-hint--blocked {
  color: $brand-danger;
  font-weight: 600;
}
/* Every card that will be SWAPPED OUT by the current drop lights up — not just the
   one under the cursor (e.g. both cards a Boards mirror displaces). Outline only (no
   background) so cards with their own wave/gradient backgrounds aren't clobbered. */
.md-ds-preview__clone .md-ds-draggable.md-ds-drop-target {
  outline: 3px dashed rgba($brand-dusty-denim, 0.92);
  outline-offset: 2px;
}
/* Drag affordance hint shown above the live preview when dragging is enabled. */
/* ── While the Getting Started series is active (body.md-ds-active): clear
   the page down to just the brand (logo + name) + the identity avatar dropdown
   in the header, and the dimmed page bg gradient behind the modal. Everything
   else is hidden; the Shepherd modal overlay supplies the dim. ── */
body.md-ds-active .md-workspace {
  visibility: hidden !important;
}
body.md-ds-active .header-search-wrap,
body.md-ds-active .app-navbar__quick-actions,
body.md-ds-active #identity .md-pillnav__upgrade-nav,
body.md-ds-active #identity .ll-header-settings-btn,
body.md-ds-active #identity .ll-bento-help-btn,
body.md-ds-active .app-navbar__beta-feedback-link {
  display: none !important;
}

/* Responsive fallback — stack the two options into a centered COLUMN (Gentle,
   the OR on its OWN centered row, then Focused) once there is no longer room for
   them side-by-side. Threshold from the cards' measured natural width, not a
   round guess: each card's widest line is its longest bullet ("Prefer a softer,
   more relaxed interface", 14px Lexend) which makes the card 331px at max-content;
   two equal-width cards + the 24px OR column + two 12px gaps need ~711px of
   content. The display modal is 100vw at <=1024px with 28px of side padding
   (56px) and a ~15px scrollbar, so the row stops fitting just under ~782px of
   viewport — 800px stacks with a little slack. Above 1024px the modal is 80vw
   (>=820px of panel), which always clears the row. `align-items: center` centers
   both the cards and the OR row horizontally. */
@media (max-width: 800px) {
  .md-ds-options {
    flex-direction: column;
    align-items: center;
  }
  /* Stacked, the cards hug their content again (equal-width sharing only makes
     sense across a row; in a column `flex: 1 1 0` would equalize HEIGHTS). */
  .md-ds-option {
    flex: 0 1 auto;
  }
  /* Divider rotates back to the horizontal "— OR —" rule between the two cards. */
  .md-ds-options__or {
    flex-direction: row;
    align-self: center;
  }
  .md-ds-options__or::before,
  .md-ds-options__or::after {
    flex: 0 0 auto;
    width: 18px;
    height: 2px;
    min-height: 0;
  }
}
.md-hero--dashboard-user {
  padding-top: 0;
}
.md-hero--dashboard .md-hero__title .md-hero__title--from-left {
  display: inline-block;
  font-size: inherit;
  opacity: 0;
  animation: la-hero-title-from-left 1s cubic-bezier(0.25, 0.46, 0.45, 0.94) forwards;
}
.md-hero--dashboard .md-hero__sub .md-hero__sub--from-right {
  display: inline-block;
  font-size: inherit;
  opacity: 0;
  animation: md-hero-from-right 1s cubic-bezier(0.25, 0.46, 0.45, 0.94) 0.5s forwards;
}
/* ── Supervisor home header (Gentle view) ───────────────────────────────────────
   Centered stacked title ("Welcome back, …") + subheader (role · rooms · communicators).
   The title keeps its from-left motion and the subheader its from-right motion (rules
   above, since this stays inside .md-hero--dashboard). */
.md-slp-hero {
  text-align: center;
}
.md-slp-hero__text {
  display: flex;
  flex-direction: column;
  align-items: center;
}
.md-slp-hero__title {
  margin: 0;
}
/* Subheader in the brand slate blue (#5A6A85, ~5.2:1 on white — passes WCAG AA). Needs
   0,2,0 + !important to beat the base `.md-hero__sub { color: var(--md-muted) !important }`. */
.md-slp-hero .md-slp-hero__sub {
  margin: 4px 0 0 !important;
  color: $brand-slate-blue !important;
}
.md-slp-hero__dot {
  margin: 0 9px;
  color: rgba($brand-slate-blue, 0.5);
  font-weight: 700;
}
/* ≤1024px hero layout: pull the .md-tour__trigger out of its absolute
   top-right pin (where it lives via .md-tour__trigger position:
   absolute / top:16 / right:16 at l. ~89271) and into the document
   flow above the centered hero title. The hero becomes a flex column
   only at this breakpoint; the tour trigger gets order:-1 so it
   visually leads, even though the template renders it AFTER the
   title and sub (no template change required). 2rem margin-top on
   the title creates the requested breathing room between the
   trigger and the page header text. Title and sub stretch to the
   full hero width by default (flex column items inherit
   align-items:stretch), so the existing text-align:center on the
   hero keeps the H1/sub horizontally centered exactly as they were
   above 1024px. The tour trigger uses align-self:center so the
   chip itself stays content-width and centered rather than
   stretching across the full hero. */
@media (max-width: 1024px) {
  .md-hero.md-hero--dashboard {
    display: flex !important;
    flex-direction: column !important;
  }
  .md-hero.md-hero--dashboard .md-tour__trigger {
    /* Same fixed top-left-below-navbar anchor as the base rule (~92966); the
       trigger no longer flows inside the hero column at this breakpoint. */
    position: fixed !important;
    top: calc(var(--topbar-height, 16px) + 7.5rem) !important;
    left: 24px !important;
    right: auto !important;
    align-self: auto !important;
    order: 0 !important;
    z-index: 1001 !important;
  }
  .md-hero.md-hero--dashboard .md-hero__title {
    margin-top: 2rem !important;
  }
}
.md-hero__gradient-text {
  font-style: normal;
  background: $la-highlight-gradient;
  -webkit-background-clip: text;
  background-clip: text;
  -webkit-text-fill-color: transparent;
  color: transparent;
}
/* Reports subheader username — navy, not the blue-green gradient (which read
   as a link). Solid brand navy so it's clearly a label, not clickable. */
.md-hero__sub-user {
  font-style: normal;
  font-weight: normal;
  color: $la-navy;
}
/* Small centered divider between the report title and the Joined/Last-active
   subheader — a short brand-gradient rule for a gentle separation. */
.md-hero--org .md-hero__divider,
.md-hero--reports-dashboard .md-hero__divider {
  display: block;
  width: 84px;
  height: 2px;
  margin: 11px auto 12px;
  border-radius: 2px;
  /* Faded on both ends → solid brand color in the middle. */
  background: linear-gradient(90deg,
    transparent 0%,
    rgba($brand-verdigris, 0.55) 35%,
    rgba($brand-dusty-denim, 0.55) 65%,
    transparent 100%);
}
/* Reports subheader now carries the Joined / Last active meta (the title is
   the "Communication activity for…" line). Inline items at the sub's own
   size — each a calendar icon / verdigris status dot + label + bold value. */
/* Compound `.md-hero__sub.md-hero__sub--meta` (0,4,0) beats the base
   `.md-hero--dashboard .md-hero__sub .md-hero__sub--from-right` rule
   (inline-block, 0,3,0) so the row actually becomes a flex row — without
   this the items baseline-align (calendar 16px vs dot 9px) and look
   vertically offset. align-items:center lines both items up on their
   vertical centers. The animation/opacity from the base rule still applies
   (only `display` is overridden here). */
.md-hero--reports-dashboard .md-hero__sub.md-hero__sub--meta .md-hero__sub--from-right,
.md-hero--org .md-hero__sub.md-hero__sub--meta .md-hero__sub--from-right {
  display: inline-flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: center;
}
.md-hero-meta__item {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  /* Uniform size for both items (label + value), independent of the hero
     sub's responsive sizing, so "Joined…" and "Last active…" always match. */
  font-size: clamp(15px, 1.4vw, 18px);
  color: var(--md-muted, rgba($la-navy, 0.6));
}
/* Clear gap between the two meta items. */
.md-hero-meta__item + .md-hero-meta__item {
  margin-left: 30px;
}
.md-hero-meta__item strong {
  font-size: inherit;
  color: $la-navy;
  font-weight: 700;
}
.md-hero-meta__icon {
  flex-shrink: 0;
}
.md-hero-meta__dot {
  flex-shrink: 0;
  width: 9px;
  height: 9px;
  /* Extra breathing room after the status dot (on top of the item's 7px
     gap) so it doesn't crowd "Last active". The 3px halo also eats into
     the visual gap, so compensate. */
  margin-right: 6px;
  border-radius: 50%;
  background: $brand-verdigris;
  box-shadow: 0 0 0 3px rgba($brand-verdigris, 0.18);
}

.la-hero-highlight {
  background: $la-highlight-gradient;
  -webkit-background-clip: text;
  background-clip: text;
  -webkit-text-fill-color: transparent;
  color: transparent;
  font-size: 1.155em; /* 5% larger than 1.1em */
}

/* "every student" in hero — teal to blue gradient */
.hero-gradient {
  background: linear-gradient(90deg, $brand-verdigris, $brand-dusty-denim);
  -webkit-background-clip: text;
  background-clip: text;
  -webkit-text-fill-color: transparent;
  color: transparent;
  font-size: 1.155em; /* match previous la-hero-highlight emphasis */
}

/* Same gradient as "every student" for "actually", "nothing you don't", "a voice", pricing hero "pricing" */
.la-wrapper .la-section-title em,
.la-wrapper .la-plan-title em,
.la-wrapper .la-cta-headline em,
.la-wrapper .la-hero-title em {
  background: $la-highlight-gradient;
  -webkit-background-clip: text;
  background-clip: text;
  -webkit-text-fill-color: transparent;
  color: transparent;
}

.la-hero-subtitle-badges-wrap {
  width: fit-content;
  max-width: 100%;
  display: flex;
  flex-direction: column;
}

.la-wrapper .la-hero-subtitle {
  font-family: 'Lexend', 'Nunito Sans', system-ui, sans-serif;
  font-size: clamp(1.25rem, calc(0.65rem + 1.38vw), 1.755rem);
  font-weight: 400;
  color: #FFFFFF;
  line-height: 1.7;
  letter-spacing: 0.01em;
  margin: 0 0 32px; /* 32px paragraph → feature pills (vertical rhythm) */
  max-width: 65ch; /* 55–70 chars per line for readability */
}

/* Small screens (≤640px): floor la-hero-subtitle at 15px so it stays legible
   when the clamp above would otherwise scale it too small. */
@media (max-width: $aac-breakpoint-sm) {
  .la-wrapper .la-hero-subtitle {
    font-size: 15px;
  }
}

@keyframes la-badges-enter {
  from {
    opacity: 0;
    transform: translateX(-48px);
  }
  to {
    opacity: 0.95;
    transform: translateX(0);
  }
}

.la-hero-badges {
  display: flex;
  flex-wrap: nowrap;
  gap: clamp(4px, calc(2px + 0.42vw), 8px);
  margin-top: 0;
  margin-bottom: 0;
}

.la-hero-badge {
  display: inline-flex;
  align-items: center;
  gap: clamp(8px, calc(4px + 0.56vw), 12px);
  padding: clamp(3px, calc(2px + 0.14vw), 5px) clamp(12px, calc(4px + 1.11vw), 20px) clamp(3px, calc(2px + 0.14vw), 5px) clamp(12px, calc(8px + 0.56vw), 16px);
  flex-shrink: 0; /* overridden in .la-hero-badges-section for equal fit */
  background: rgba(255, 255, 255, 0.98);
  border: 1px solid rgba(0, 0, 0, 0.1);
  border-radius: 12px; /* more square than pill so badges don’t look like action buttons */
  opacity: 0.98;
  box-shadow: 0 3px 10px rgba(0, 0, 0, 0.07), inset 0 1px 0 rgba(255, 255, 255, 0.95);
  transition: background 0.2s ease, opacity 0.2s ease, box-shadow 0.2s ease;
  will-change: transform;
  animation: la-badges-enter 0.85s cubic-bezier(0.25, 0.46, 0.45, 0.94) forwards;

  &:nth-child(1) { animation-delay: 0.2s; opacity: 0; }
  &:nth-child(2) { animation-delay: 0.4s; opacity: 0; }
  &:nth-child(3) { animation-delay: 0.6s; opacity: 0; }

  &:hover {
    background: #ffffff;
    border-color: rgba(0, 0, 0, 0.12);
    box-shadow: 0 4px 14px rgba(0, 0, 0, 0.12), inset 0 1px 0 rgba(255, 255, 255, 1);
    opacity: 1;
  }
}

// $la-hero-badge-icon-bg defined in _variables.scss

.la-hero-badge-icon {
  display: flex;
  align-items: center;
  justify-content: center;
