.la-wrapper .la-about-glass-card__icon--communicator { background: rgba(44, 82, 130, 0.12); color: #2c5282; }
.la-wrapper .la-about-glass-card__icon--supporter { background: rgba(26, 122, 110, 0.12); color: #1a7a6e; }
.la-wrapper .la-about-glass-card__icon--eval { background: rgba($brand-slate-gray, 0.12); color: $brand-slate-gray; }

.la-wrapper .la-about-glass-card__title {
