  }
}

.la-chip-icon {
  width: 36px;
  height: 36px;
  border-radius: 10px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 18px;
  flex-shrink: 0;

  &.la-chip-icon--teal  { background: rgba($la-teal, 0.14); }
  &.la-chip-icon--coral { background: rgba($brand-honey-bronze, 0.12); }
