// Mockup category colors (switched for landing): actions→teal, objects→orange, people→purple, questions→red, descriptors→blue

.la-mockup {
  position: relative;
  z-index: 1;
  width: clamp(252px, calc(126px + 20.4vw), 420px);
  max-width: 100%;
  margin-top: clamp(18px, calc(8px + 2vw), 36px);
  background: white;
  border-radius: 20px;
  overflow: hidden;
  box-shadow:
    0 4px 6px rgba(0, 0, 0, 0.04),
    0 14px 32px rgba(0, 0, 0, 0.06),
    0 2px 4px rgba(0, 0, 0, 0.03);
  transform: scale(0.98); /* 10% smaller than previous (was 1.09) */
  transform-origin: top center;
}

.la-mockup-bar {
  background: #f5f5f7;
  display: flex;
  align-items: center;
  justify-content: flex-start;
  gap: 10px;
  padding: 12px 18px;
  border-bottom: 1px solid rgba(0, 0, 0, 0.05);
}

.la-mockup-dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  flex-shrink: 0;

  &.la-mockup-dot--r { background: #ff6b6b; }
  &.la-mockup-dot--y { background: #ffd43b; }
  &.la-mockup-dot--g { background: #51cf66; }
}

.la-mockup-url {
  font-size: 14px;
  color: #868e96;
  font-weight: 500;
  font-family: 'Lexend', 'Nunito Sans', system-ui, sans-serif;
  letter-spacing: 0.01em;
  background: rgba(255, 255, 255, 0.9);
  padding: 6px 14px;
  border-radius: 8px;
  border: 1px solid rgba(0, 0, 0, 0.06);
  max-width: 180px;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.la-mockup-screen {
  position: relative;
  padding: 18px;
  display: flex;
  flex-direction: column;
  gap: 14px;
  background: #fafbfc;
}

.la-mockup-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 10px;
}

.la-aac-btn {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 6px;
  padding: 11px 7px;
  border-radius: 12px;
  font-size: 14px;
  font-weight: 700;
  font-family: 'Lexend', 'Nunito Sans', system-ui, sans-serif;
  color: color.adjust($indigo, $lightness: 15%);
  text-align: center;
  cursor: pointer;
  border: 1px solid rgba(0, 0, 0, 0.05);
  box-shadow: 0 1px 2px rgba(0, 0, 0, 0.04);
  transition: box-shadow 0.2s ease, transform 0.15s ease;

  &:hover {
    box-shadow: 0 2px 8px rgba(0, 0, 0, 0.08);
    transform: translateY(-1px);
  }

  /* c1 feel, c5 want = questions (red); c2 eat = objects (orange); c3 go, c6 play, c7 read = actions (teal); c4 hi = people (purple); c8 more = descriptors (blue) */
  &.la-aac-btn--c1 { background: $la-mockup-red-bg; }
  &.la-aac-btn--c2 { background: $la-mockup-orange-bg; }
  &.la-aac-btn--c3 { background: $la-mockup-teal-bg; }
  &.la-aac-btn--c4 { background: $la-mockup-purple-bg; }
  &.la-aac-btn--c5 { background: $la-mockup-red-bg; }
  &.la-aac-btn--c6 { background: $la-mockup-teal-bg; }
  &.la-aac-btn--c7 { background: $la-mockup-teal-bg; }
  &.la-aac-btn--c8 { background: $la-mockup-blue-bg; }
