// ── Stats strip ──────────────────────────────────────────────────────────────
@keyframes la-stat-enter {
  0% {
    opacity: 0;
    transform: translateY(24px) scale(0.96);
  }
  100% {
    opacity: 1;
    transform: translateY(0) scale(1);
  }
}

.la-stats-strip {
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  gap: $aac-spacing-20 $aac-spacing-24;
  margin-left: auto;
  margin-right: auto;
  width: fit-content;
  align-items: flex-start;
  padding: $aac-spacing-24 $aac-spacing-32;
  background: linear-gradient(
    160deg,
    rgba(255, 255, 255, 0.96) 0%,
    rgba(243, 241, 237, 0.94) 42%,
    rgba(212, 216, 226, 0.65) 85%,
    rgba($brand-teal, 0.05) 100%
  );
  border-radius: $aac-radius-xl;
  border: 1px solid rgba(0, 0, 0, 0.08);
  box-shadow: 0 4px 20px rgba(0, 0, 0, 0.08), 0 1px 3px rgba(0, 0, 0, 0.05);
  position: relative;
  z-index: 1;
}

.la-stat-cell {
  background: #ffffff;
  border-radius: 18px;
  border: 1px solid rgba(0, 0, 0, 0.08);
  padding: $aac-spacing-24 $aac-spacing-20;
  text-align: center;
  box-shadow: 0 6px 20px rgba(0, 0, 0, 0.08), 0 2px 6px rgba(0, 0, 0, 0.04);
  flex: 1 1 0;
  min-width: 154px;
  max-width: 242px;
  transition: transform 0.4s ease, box-shadow 0.4s ease;
  animation: la-stat-enter 0.55s cubic-bezier(0.22, 1, 0.36, 1) forwards;
  opacity: 0;

  &:nth-child(1) { animation-delay: 0.08s; }
  &:nth-child(2) { animation-delay: 0.18s; }
  &:nth-child(3) { animation-delay: 0.28s; }
  &:nth-child(4) { animation-delay: 0.38s; }

  @media (prefers-reduced-motion: reduce) {
    animation: none;
    opacity: 1;
  }

  // Organic variation — shape only, tops aligned
  &:nth-child(1) {
    border-radius: 20px 16px 18px 22px;
  }
  &:nth-child(2) {
    border-radius: 16px 22px 20px 14px;
    max-width: 231px;
  }
  &:nth-child(3) {
    border-radius: 22px 18px 14px 20px;
    max-width: 253px;
  }
  &:nth-child(4) {
    border-radius: 14px 20px 22px 16px;
  }
}

.la-stat-number {
  font-family: 'Lexend', 'Nunito Sans', system-ui, sans-serif;
  font-size: $aac-font-size-2xl;
  font-weight: $aac-font-weight-black;
  color: $la-navy;
  letter-spacing: -0.02em;
  font-kerning: normal;
  margin-bottom: $aac-spacing-4;
}

// Stats inside hero: compact, modern, on dark background; same enter animation
.la-stats-strip--in-hero {
  padding: $aac-spacing-12 0 $aac-spacing-20;
  margin: 0;
  width: 100%;
  max-width: 100%;
  background: none;
  border: none;
  border-radius: 0;
  box-shadow: none;
  gap: $aac-spacing-10 $aac-spacing-16;
  justify-content: flex-start;
}

// Stats below mockup (right column): center under the device, add top margin
.la-stats-strip--below-mockup {
  position: relative;
  z-index: 1;
  margin-top: $aac-spacing-20;
  padding-top: 0;
  padding-bottom: 0;
  justify-content: center;

  .la-stat-cell {
    min-width: 0;
    max-width: none;
    flex: 0 1 auto;
    padding: $aac-spacing-10 $aac-spacing-14;
    background: rgba(255, 255, 255, 0.1);
    border: 1px solid rgba(255, 255, 255, 0.18);
    border-radius: 12px;
    box-shadow: 0 2px 8px rgba(0, 0, 0, 0.08);
    backdrop-filter: blur(8px);
    -webkit-backdrop-filter: blur(8px);

    &:nth-child(1),
    &:nth-child(2),
    &:nth-child(3),
    &:nth-child(4) {
      border-radius: 12px;
      max-width: none;
    }
  }

  .la-stat-number {
    font-size: 14px;
    font-weight: $aac-font-weight-black;
    color: #ffffff;
    margin-bottom: 2px;
  }

  .la-stat-label {
    font-size: 14px;
    color: rgba(255, 255, 255, 0.82);
    line-height: 1.4;
    letter-spacing: 0.01em;
  }
}

.la-stat-label {
  font-size: $aac-font-size-xs * 1.518;
  color: #3D4F46;
  line-height: 1.6;
}

.la-scroll-hint {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: $aac-spacing-6;
  padding: $aac-spacing-8 0;
}

.la-scroll-hint__arrow {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 36px;
  height: 36px;
  border-radius: 50%;
  background: rgba($brand-teal, 0.08);
  border: 1px solid rgba($brand-teal, 0.18);
  color: $brand-teal;
  font-size: 18px;
  animation: la-bounce 2s ease-in-out infinite;
}

.la-scroll-hint__label {
  font-size: 14px;
  font-weight: $aac-font-weight-semi;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: rgba($brand-teal, 0.65);
}

@keyframes la-bounce {
  0%, 100% { transform: translateY(0); }
  50%      { transform: translateY(4px); }
}

/* Section anchoring: light gray band so flow is white (hero) → light gray (features) → parallax → white (CTA) */
#la-features {
  /* No margin-top: the section sits directly under the spotlight and supplies its own
     top spacing via padding-top. (.la-section sets no margin, so this resolves to 0.) */
  padding-top: $aac-spacing-32;
  background: transparent;
  border: none;
}

/* Landing-alt: Why LingoLinq section — tighter spacing hierarchy (eyebrow 16px, headline 24px) */
/* Shared glass badge: landing + about page (About LingoLinq, What we offer, Trust & transparency, Open source, Ready to start, Attributions, etc.) */
#la-features .la-section-header .la-section-eyebrow-badge,
#about-hero .la-section-header .la-section-eyebrow-badge,
#la-plan .la-section-eyebrow-badge,
#la-slp-spotlight .la-section-eyebrow-badge,
#la-devices-spotlight .la-section-eyebrow-badge,
#la-devices-spotlight-desktop .la-section-eyebrow-badge,
#la-testimonial .la-section-eyebrow-badge,
#la-a11y .la-section-eyebrow-badge,
.la-wrapper .la-cta-section .la-cta-eyebrow,
.la-wrapper.la-wrapper--about .la-section .la-section-header .la-section-eyebrow-badge,
.la-wrapper.la-wrapper--about .la-plan-section .la-section-eyebrow-badge,
.la-wrapper.la-wrapper--about .la-a11y-statement .la-section-eyebrow-badge,
.la-wrapper.la-wrapper--about .la-cta-section .la-section-eyebrow-badge,
.la-wrapper.la-wrapper--about .la-attr-section .la-section-eyebrow-badge,
.la-wrapper.la-wrapper--pricing .la-section .la-section-header .la-section-eyebrow-badge,
.la-wrapper.la-wrapper--contact .la-hero-card .la-section-eyebrow-badge,
.la-features-modal-body .la-section-header .la-section-eyebrow-badge,
.ub-boards-page__page-header .la-section-eyebrow-badge,
.beta-welcome-card .la-section-header .la-section-eyebrow-badge,
.beta-feedback-panel .la-section-eyebrow-badge {
  background: linear-gradient(
    180deg,
    rgba(255, 255, 255, 0.35) 0%,
    rgba($brand-teal, 0.08) 35%,
    rgba($brand-teal, 0.18) 100%
  );
  backdrop-filter: blur(10px) saturate(1.2);
  -webkit-backdrop-filter: blur(10px) saturate(1.2);
  border: 1px solid rgba(255, 255, 255, 0.5);
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.4),
    0 2px 12px rgba($brand-teal, 0.15);
}
#la-features .la-section-header .la-section-eyebrow-badge,
#about-hero .la-section-header .la-section-eyebrow-badge,
.la-features-modal-body .la-section-header .la-section-eyebrow-badge {
  margin-bottom: 16px;
}
/* Contact page: badge text color and brand colors to match about */
.la-wrapper.la-wrapper--contact .la-hero-card .la-section-eyebrow-badge {
  color: #0d5c5f;
}
.la-wrapper.la-wrapper--contact .la-hero-card .la-about-hero-brand {
  color: $la-navy;
}
.la-wrapper.la-wrapper--contact .la-hero-card .la-about-hero-brand--italic {
  color: $brand-smart-blue;
}
#la-features .la-section-header .la-section-title,
#la-mission .la-section-header .la-section-title,
#about-hero .la-section-header .la-section-title,
.la-features-modal-body .la-section-header .la-section-title {
  font-weight: normal;
  margin-bottom: 24px;
}
#about-what-we-offer .la-section-header .la-section-title,
#faq-items .la-section-header .la-section-title,
#faq-questions .la-section-header .la-section-title {
