/* Support page: content wrapper and card (same pattern as contact) */
.la-support-content-wrapper {
  max-width: 748px;
  margin-left: auto;
  margin-right: auto;
  padding-left: 1rem;
  padding-right: 1rem;
  width: 100%;
  box-sizing: border-box;
}

.la-support-page-card {
  padding: $aac-spacing-20 $aac-spacing-24;
}

.la-support-page-card__divider {
  height: 1px;
  margin: 0 $aac-spacing-24;
  background: rgba(0, 0, 0, 0.12);
}

.la-support-page-card__section {
  padding-top: $aac-spacing-16;
}

.la-support-page-card__head {
  margin-bottom: $aac-spacing-12;
}

.la-support-page-card__title {
  font-size: 22px;
  font-weight: 900;
  letter-spacing: -0.02em;
  color: $indigo;
  margin: 0 0 $aac-spacing-4;
}

.la-support-page-card__sub {
  font-size: 16px;
  line-height: 1.5;
  color: $brand-charcoal-dark;
  margin: 0;
}

/* Support page: 25% larger font for resources lead, list items, and action buttons */
/* Support page resources section: small cards (same style as landing-alt features) */
.la-wrapper--support .la-support-resources__heading {
  font-size: 1.40625rem; /* 1.125rem × 1.25 */
  font-weight: 600;
  letter-spacing: 0.02em;
  color: $brand-charcoal-dark;
  margin: 0 0 $aac-spacing-20;
  line-height: 1.4;
}

.la-wrapper--support .md-workspace--support {
  margin-top: 6rem;
}

.la-wrapper--support #support-hero {
  margin-top: 0;
  padding-top: 0;
}

.la-wrapper--support .la-support-list--cards {
  list-style: none;
  margin: 0 0 $aac-spacing-24;
  padding: 0;
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(260px, 1fr));
  gap: $aac-spacing-16;
}

.la-wrapper--support .la-support-list--cards li {
  margin: 0;
}

/* Small feature-style card (same look as #la-features .la-feature-card) */
.la-wrapper--support .la-support-resource-card {
  display: block;
  background: #ffffff;
  border: 1px solid rgba($indigo, 0.06);
  border-radius: 20px;
  box-shadow:
    0 8px 20px rgba(0, 0, 0, 0.06),
    0 2px 6px rgba(0, 0, 0, 0.04);
  transition:
    transform 180ms ease,
    box-shadow 180ms ease,
    border-color 180ms ease,
    background-color 180ms ease;

  &:hover {
    transform: translateY(-3px);
    background: #fcfdfd;
    border-color: rgba(63, 127, 123, 0.16);
    box-shadow:
      0 14px 28px rgba(0, 0, 0, 0.10),
      0 4px 10px rgba(0, 0, 0, 0.05);
  }
}

.la-wrapper--support .la-support-list--cards .la-support-list__link,
.la-wrapper--support .la-support-list--cards .la-support-list__card-action {
  display: flex;
  align-items: center;
  gap: $aac-spacing-16;
  width: 100%;
  min-height: 88px;
  padding: $aac-spacing-20 $aac-spacing-24;
  margin: 0;
  text-align: left;
  font-size: 1.40625rem; /* 1.125rem × 1.25 */
  font-weight: 500;
  color: $indigo;
  text-decoration: none;
  border: none;
  border-radius: 20px;
  background: transparent;
  box-shadow: none;
  cursor: pointer;
  font-family: inherit;
  -webkit-appearance: none;
  appearance: none;

  &:hover {
    text-decoration: none;
    color: $indigo;
  }
}

/* Icons: same style as landing-alt #la-features .la-feature-icon */
.la-wrapper--support .la-support-list--cards .la-support-list__icon.la-feature-icon {
  flex-shrink: 0;
  width: 56px;
  height: 56px;
  margin: 0;
  border-radius: 18px;
  display: grid;
  place-items: center;
  font-size: 28px;
  line-height: 1;
  border: 1px solid rgba($indigo, 0.05);
  box-shadow:
    0 6px 14px rgba(0, 0, 0, 0.05),
    inset 0 1px 0 rgba(255, 255, 255, 0.7);
  transition:
    transform 180ms ease,
    box-shadow 180ms ease,
    border-color 180ms ease;
}

.la-wrapper--support .la-support-resource-card:hover .la-support-list__icon.la-feature-icon {
  transform: translateY(-1px);
  box-shadow:
    0 10px 20px rgba(0, 0, 0, 0.08),
    inset 0 1px 0 rgba(255, 255, 255, 0.8);
  border-color: rgba($indigo, 0.08);
}

.la-wrapper--support .la-support-list--cards .la-feature-icon--teal {
  background: linear-gradient(
    180deg,
    rgba(63, 127, 123, 0.10),
    rgba(63, 127, 123, 0.05)
  );
}

.la-wrapper--support .la-support-list--cards .la-feature-icon--navy {
  background: linear-gradient(
    180deg,
    rgba($indigo, 0.08),
    rgba($indigo, 0.04)
  );
}

.la-wrapper--support .la-support-list--cards .la-feature-icon--coral {
  background: linear-gradient(
    180deg,
    rgba(240, 106, 91, 0.10),
    rgba(240, 106, 91, 0.05)
  );
}

.la-wrapper--support .la-support-list--cards .la-support-list__text {
  flex: 1;
  line-height: 1.4;
}

/* Legacy lead class when used outside cards (e.g. modal) */
.la-wrapper--support .la-support-lead.md-support-lead {
  font-size: 1.5625rem; /* 1.25rem × 1.25 */
  margin: 0 0 $aac-spacing-12;
  color: $brand-charcoal-dark;
}

.la-wrapper--support .la-support-page-card .la-support-list:not(.la-support-list--cards) .la-support-list__link,
.la-wrapper--support .la-support-page-card .la-support-list:not(.la-support-list--cards) .la-support-list__btn {
  font-size: 1.40625rem; /* 1.125rem × 1.25 */
}

.la-wrapper--support .la-support-page-card .la-support-list:not(.la-support-list--cards) .la-support-list__icon {
  font-size: 1.40625em; /* scale with list item */
}

.la-wrapper--support .la-support-form__actions {
  justify-content: center;
}
.la-wrapper--support .la-support-form__actions .la-btn--ghost {
  background: rgba($brand-charcoal-dark, 0.08);
  color: $brand-charcoal-dark;
  border: 1px solid rgba($brand-charcoal-dark, 0.2);
}
.la-wrapper--support .la-support-form__actions .la-btn--ghost:hover {
  background: rgba($brand-charcoal-dark, 0.14);
  color: #1f2937;
}
.la-wrapper--support .la-support-form__actions .la-btn {
  font-size: 1.40625rem; /* 25% larger than 1.125rem */
  padding: 0.5rem 1.25rem;
  min-height: 44px;
}

/* Send Message button on support page */
.la-wrapper--support .la-support-form__actions .la-btn--primary {
  background: $brand-charcoal-blue;
  color: #fff;
  border: none;
  box-shadow: 0 4px 14px rgba(0, 0, 0, 0.15);
  transition: filter 0.2s ease, box-shadow 0.2s ease, transform 0.15s ease;

  &:hover:not(:disabled) {
    filter: brightness(1.08);
    box-shadow: 0 6px 20px rgba(0, 0, 0, 0.18);
    transform: translateY(-1px);
    color: #fff;
  }

  &:active:not(:disabled) {
    transform: translateY(0);
    box-shadow: 0 2px 8px rgba(0, 0, 0, 0.12);
  }
}

/* Beta feedback form (same wrapper as support) */
.la-wrapper--support .la-support-form.md-support-form {
  position: relative;
}
.la-wrapper--support .la-beta-feedback__screenshot-preview {
  margin-top: 0.75rem;
}
.la-wrapper--support .la-beta-feedback__screenshot-img {
  max-width: 100%;
  max-height: 220px;
  border-radius: 8px;
  border: 1px solid rgba($brand-charcoal-dark, 0.15);
  display: block;
}
.la-wrapper--support .la-beta-feedback__clear-shot {
  margin-top: 0.5rem;
}

.la-wrapper--support .la-beta-feedback__dropzone {
  border: 2px dashed rgba($brand-charcoal-dark, 0.28);
  border-radius: 12px;
  padding: 1rem 1.25rem;
  margin-bottom: 0.5rem;
  min-height: 5.5rem;
  background: rgba(255, 255, 255, 0.45);
  transition: border-color 0.15s ease, background 0.15s ease, box-shadow 0.15s ease;
}
.la-wrapper--support .la-beta-feedback__dropzone:focus-visible {
  @include focus-ring;
}
.la-wrapper--support .la-beta-feedback__dropzone--active {
  border-color: rgba($brand-charcoal-blue, 0.55);
  background: rgba(70, 95, 120, 0.08);
  box-shadow: inset 0 0 0 1px rgba($brand-charcoal-blue, 0.12);
}
.la-wrapper--support .la-beta-feedback__dropzone-hint {
  font-size: 14px;
  line-height: 1.45;
  color: $brand-charcoal-dark;
  margin: 0 0 0.75rem 0;
}
.la-wrapper--support .la-beta-feedback__file-input {
  width: 100%;
  max-width: 100%;
}

/* Honeypot row: off-screen, not keyboard-focusable in normal tab order.
   Applies in both the standalone /beta-feedback page and the beta-feedback
   modal — the field type itself is a honeypot regardless of host. */
.la-wrapper--support .la-beta-feedback-hp,
.beta-feedback-modal-wrap .la-beta-feedback-hp {
  position: absolute;
  left: -10000px;
  top: auto;
  width: 1px;
  height: 1px;
  overflow: hidden;
}
.la-wrapper--support .la-beta-feedback-hp__input,
.beta-feedback-modal-wrap .la-beta-feedback-hp__input {
  pointer-events: none;
}

/* Public Speak Mode demo */
