  text-transform: uppercase;
  letter-spacing: $aac-letter-spacing-wide;
  color: #0d5c5f;
  background: rgba($brand-teal, 0.14);
  backdrop-filter: blur(6px);
  -webkit-backdrop-filter: blur(6px);
  border: 1px solid rgba($brand-teal, 0.35);
  border-radius: $aac-radius-pill;
  padding: 6px $aac-spacing-20;
  margin-bottom: $aac-spacing-16;
  box-shadow: 0 2px 10px rgba($brand-teal, 0.12);
  opacity: 1;
}

.la-wrapper .la-section-title {
