  letter-spacing: -0.02em;
  line-height: 1.15;
  font-kerning: normal;

  em {
    font-style: normal;
    color: $brand-smart-blue;
  }
}

.la-section-subtitle {
  /* Landing-alt body copy tracks .la-hero-subtitle's fluid size (see the
     .la-wrapper--landing .la-plan-subtitle rule, which keeps the spotlight/plan
     bodies identical to this). clamp() min/max are the hero's; the ≤640px floor
     lives with that rule. This class is landing-alt-only, so it's set in place. */
  font-size: clamp(1.25rem, calc(0.65rem + 1.38vw), 1.755rem);
  font-weight: 400;
  color: rgba($indigo, 0.9);
  /* Same container width as the spotlight bodies (.la-slp-spotlight__body /
     .la-devices-spotlight__body are max-width: 720px, centred, at both breakpoints)
     so the two read as one column. Was 558.72px. */
  max-width: 720px;
  margin: 0 auto;
  line-height: 1.8;
  letter-spacing: 0.005em;
}

