/* Ready to start section: animate entire block when section scrolls into view */
@keyframes la-cta-section-enter {
  from {
    opacity: 0;
    transform: translateY(32px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

#la-cta .la-cta-inner {
  opacity: 0;
  animation: la-cta-section-enter 0.6s cubic-bezier(0.22, 1, 0.36, 1) forwards;
  animation-play-state: paused;
}

#la-cta.la-cta-visible .la-cta-inner {
  animation-play-state: running;
}

.la-btn--lg {
  padding: $aac-spacing-14 $aac-spacing-32;
  font-size: $aac-font-size-base;
}

.la-btn--ghost {
  background: transparent;
  color: rgba(white, 0.75);
  border: 1px solid rgba(white, 0.2);
  padding: $aac-spacing-10 $aac-spacing-24;
  border-radius: $aac-radius-pill;
  font-size: $aac-font-size-sm;
  font-weight: $aac-font-weight-semi;
  text-decoration: none;
  transition: all 0.2s ease;
  cursor: pointer;

  &:hover {
    background: rgba(white, 0.08);
    color: white;
    border-color: rgba(white, 0.35);
  }
}

// ── A11y bar ─────────────────────────────────────────────────────────────────
.la-a11y-bar {
  display: flex;
  align-items: flex-start;
  gap: $aac-spacing-14;
  background: $cat-actions-bg;
  border: 1px solid $cat-actions-base;
  border-radius: $aac-radius-lg;
  padding: $aac-spacing-16 $aac-spacing-20;

  p {
    font-size: $aac-font-size-sm;
    color: $color-text-mid;
    margin: 0;
    line-height: $aac-line-height-loose;
  }

  a {
    color: $cat-actions-text;
    font-weight: $aac-font-weight-bold;

    &:hover { color: $color-text; }
  }

  .la-sidebar & {
    display: grid;
    grid-template-columns: auto 1fr;
    gap: $aac-spacing-4 $aac-spacing-8;
    align-items: center;
    padding: $aac-spacing-12;
    background: linear-gradient(135deg, rgba($la-navy, 0.04) 0%, white 60%);
    border-color: rgba($la-navy, 0.3);

    a { color: $indigo; &:hover { color: color.adjust($indigo, $lightness: -10%); } }
    font-size: $la-panel-font-size-xs * 1.09;

    .la-a11y-icon { grid-row: 1; grid-column: 1; padding-right: $aac-spacing-12; }
    .la-a11y-heading { grid-row: 1; grid-column: 2; font-size: $la-panel-font-size-base * 1.035; color: $indigo; }
    p { grid-row: 2; grid-column: 1 / -1; font-size: $la-panel-font-size-xs * 1.1 * 1.09; color: $indigo; word-wrap: break-word; overflow-wrap: break-word; }
    p strong { color: $brand-teal; }
  }
}

.la-a11y-icon {
  font-size: 36px;
  flex-shrink: 0;
  margin-top: 2px;
}

// ── Divider ──────────────────────────────────────────────────────────────────
.la-divider {
  border: none;
  height: 2px;
  background: linear-gradient(90deg, transparent 0%, rgba($la-teal, 0.25) 30%, rgba($la-teal, 0.25) 70%, transparent 100%);
  margin: 0;
}

// ── Footer (modern) ───────────────────────────────────────────────────────────
.la-footer {
  /* Zero horizontal padding so the bg tint extends edge-to-edge; the centered
     content column is handled by .la-footer-inner's max-width + margin:auto.
     Full-bleed full-viewport-width: the footer sits inside `.la-main` which
     has heavy left/right padding (calc(spacing-28 + 5rem)) — that padding
     would otherwise inset the footer's tinted background. Using the
     standard 100vw + negative margin-left/right trick breaks the footer
     out of `.la-main`'s content box and lets its background paint
     edge-to-edge at every screen width. */
  padding-top: $aac-spacing-48;
  padding-right: 0;
  padding-bottom: $aac-spacing-40;
  padding-left: 0;
  margin-top: 0;
  background: rgba($la-navy, 0.03);
  border-top: none;
  position: relative;
  width: 100vw;
  margin-left: calc(50% - 50vw);
  margin-right: calc(50% - 50vw);
}

.la-footer-inner {
  display: grid;
  grid-template-columns: 2fr 1fr 1fr 1fr;
  gap: $aac-spacing-40 $aac-spacing-32;
  margin-bottom: $aac-spacing-40;
  max-width: 1200px;
  margin-left: auto;
  margin-right: auto;
  padding: 0;

  @include aac-respond-to('lg') {
    grid-template-columns: 1fr 1fr;
    gap: $aac-spacing-32 $aac-spacing-24;
  }
}

.la-footer-brand {
  max-width: 320px;

  p {
    font-size: $aac-font-size-sm;
    color: rgba($la-navy, 0.7);
    line-height: 1.65;
    margin: $aac-spacing-14 0 0;
    letter-spacing: 0.01em;
  }
}

/* Footer logo: ~25% narrower, no gap after image, Lingo and Linq same style */
.la-footer-logo {
  display: inline-flex;
  align-items: center;
  gap: 0;
  font-family: 'Lexend', 'Nunito Sans', system-ui, sans-serif;
  font-size: $aac-font-size-lg * 0.75;
  font-weight: $aac-font-weight-black;
  letter-spacing: $aac-letter-spacing-base;
  white-space: nowrap;
  text-decoration: none;
  color: $la-logo-left;
  transition: opacity 0.2s ease;

  .app-logo__lingo,
  .app-logo__linq,
  & > span:first-child,
  & > span:last-child {
    color: $la-logo-left;
    font-style: normal;
  }

  &:hover {
    text-decoration: none;
    opacity: 0.88;
  }
}

.la-footer-logo-img {
  height: auto; /* width set via size="75px" (25% narrower than default 100px); keep aspect ratio */
}

.la-footer-col {
  display: flex;
  flex-direction: column;
  gap: $aac-spacing-12;

  nav {
    display: flex;
    flex-direction: column;
    gap: $aac-spacing-8;
  }

  h4 {
    font-family: 'Lexend', 'Nunito Sans', system-ui, sans-serif;
    font-size: 14px;
    font-weight: $aac-font-weight-black;
    text-transform: uppercase;
    letter-spacing: 0.12em;
    color: rgba($la-navy, 0.75);
    margin: 0 0 $aac-spacing-4;
  }

  a,
  a:visited {
    font-size: $aac-font-size-sm;
    color: $la-navy;
    text-decoration: none;
    transition: color 0.2s ease, opacity 0.2s ease;

    &:hover {
      color: $brand-teal;
      text-decoration: none;
    }
  }
}

.la-footer-link-btn {
  background: none;
  border: none;
  padding: 0;
  margin: 0;
  font-size: $aac-font-size-sm;
  font-family: inherit;
  color: rgba($la-navy, 0.85);
  text-decoration: none;
  text-align: left;
  cursor: pointer;
  transition: color 0.2s ease, opacity 0.2s ease;

  &:hover {
    color: $brand-teal;
    text-decoration: none;
  }
}

.la-footer-link-btn:focus-visible {
  @include focus-ring($color: $brand-verdigris);
}

.la-footer-bottom {
  display: flex;
  flex-wrap: nowrap;
  align-items: center;
  justify-content: space-between;
  gap: $aac-spacing-12;
  padding-top: $aac-spacing-28;
  border-top: 1px solid rgba($la-navy, 0.08);
  max-width: 1200px;
  margin-left: auto;
  margin-right: auto;
}

.la-footer-bottom__copy {
  font-size: $aac-font-size-xs;
  color: rgba($la-navy, 0.75);
  letter-spacing: 0.02em;
  flex: 0 0 auto;
  white-space: nowrap;
}

/* la-footer responsive: industry collapsing (multi-col → 2-col → single-col) */
@media (max-width: $aac-breakpoint-lg) {
  .la-footer {
    padding-top: $aac-spacing-40;
    padding-bottom: $aac-spacing-32;
  }
  .la-footer-inner {
    margin-bottom: $aac-spacing-32;
  }
}

@media (max-width: $aac-breakpoint-md) {
  .la-footer {
    padding: $aac-spacing-32 $aac-spacing-20 $aac-spacing-28;
  }
  .la-footer-inner {
    gap: $aac-spacing-24 $aac-spacing-20;
    margin-bottom: $aac-spacing-28;
  }
  .la-footer-brand {
    max-width: 100%;
  }
  .la-footer-bottom {
    padding-top: $aac-spacing-20;
    gap: $aac-spacing-12;
  }
}

@media (max-width: $aac-breakpoint-sm) {
  .la-footer {
    padding: $aac-spacing-24 $aac-spacing-16 $aac-spacing-24;
  }
  .la-footer-inner {
    gap: $aac-spacing-20;
    margin-bottom: $aac-spacing-24;
  }
  .la-footer-col h4 {
    margin-top: $aac-spacing-8;
  }
  .la-footer-col:nth-child(2) h4 {
    margin-top: 0;
  }
  .la-footer-bottom {
    padding-top: $aac-spacing-16;
    gap: $aac-spacing-12;
  }
}

/* Collapsible footer (same breakpoint as navbar: 1024px) — brand + hamburger only when collapsed */
.la-footer__mobile {
  display: none;
}

.la-footer--collapsible .la-footer__main--desktop {
  grid-column: 2 / -1;
  display: grid;
  grid-template-columns: 1fr 1fr 1fr;
  gap: $aac-spacing-40 $aac-spacing-32;
}

.la-footer--collapsible .la-footer__main--desktop .la-footer-bottom {
  grid-column: 1 / -1;
}

@media (max-width: $aac-breakpoint-lg) {
  /* ≤1024px footer layout: brand/tagline on top centered, then the
     three link columns (Product / Resources / Company) below in
     their existing 3-column grouping, centered horizontally on the
     page. The columns themselves keep their own internal left
     alignment so each heading sits flush above its links. The
     bottom row (copyright + accessibility) spans full width below
     the columns. The hamburger drawer is suppressed since the
     content is now exposed directly. This structure is flexible at
     all widths below 1024px — `grid-template-columns: repeat(3, auto)`
     plus `justify-content: center` lets the cluster shrink to fit. */
  .la-footer--collapsible .la-footer-inner {
    display: flex;
    flex-direction: column;
    align-items: center;
    text-align: center;
    margin-bottom: $aac-spacing-24;
  }
  .la-footer--collapsible .la-footer-brand {
    max-width: 600px;
    text-align: center;
    margin-bottom: $aac-spacing-16;
  }
  .la-footer--collapsible .la-footer-brand p {
    text-align: center;
  }
  .la-footer--collapsible .la-footer__main--desktop {
    display: grid !important;
    grid-template-columns: repeat(3, auto);
    gap: $aac-spacing-32 $aac-spacing-40;
    justify-content: center;
    width: 100%;
    max-width: 100%;
  }
  .la-footer--collapsible .la-footer__main--desktop .la-footer-col {
    grid-column: auto;
    /* Reset the 5rem left-padding the surrounding 2-col layout
       applies to .la-footer-col:nth-child(2)/(4) — that horizontal
       inset breaks the centered cluster here. */
    padding-left: 0 !important;
    /* Keep each column's heading + links flush-left within its own
       cell so the section reads cleanly even though the whole
       cluster is centered on the page. */
    text-align: left;
  }
  .la-footer--collapsible .la-footer__main--desktop .la-footer-col h4,
  .la-footer--collapsible .la-footer__main--desktop .la-footer-col nav {
    text-align: left;
  }
  /* Bottom row spans full footer width and lives under the cluster. */
  .la-footer--collapsible .la-footer__main--desktop .la-footer-bottom {
    grid-column: 1 / -1;
  }
  .la-footer--collapsible .la-footer__mobile,
  .la-footer--collapsible .la-footer__mobile .la-topbar-hamburger,
  .la-footer--collapsible .la-footer__hamburger {
    display: none !important;
  }
  /* The mobile drawer panel triggered by the hamburger duplicates
     the now-visible columns, so keep it hidden along with its
     trigger. */
  .la-footer--collapsible .la-mobile-drawer {
    display: none !important;
  }
  .la-footer--collapsible .la-footer-bottom {
    padding-top: $aac-spacing-16;
  }
}

/* ≤640px: the 3-column cluster no longer fits cleanly across the
   viewport — links wrap mid-column, the cluster gets pushed off
   center, and gaps eat what's left of the layout. Stack the three
   columns vertically (still centered) so each section reads cleanly
   at narrow widths. The brand-on-top-centered structure from the
   ≤1024px block is preserved. */
@media (max-width: $aac-breakpoint-sm) {
  .la-footer--collapsible .la-footer__main--desktop {
    grid-template-columns: 1fr !important;
    gap: $aac-spacing-24 !important;
    justify-content: stretch !important;
  }
  .la-footer--collapsible .la-footer__main--desktop .la-footer-col {
    text-align: center !important;
    align-items: center;
  }
  .la-footer--collapsible .la-footer__main--desktop .la-footer-col h4,
  .la-footer--collapsible .la-footer__main--desktop .la-footer-col nav {
    text-align: center !important;
  }
  .la-footer--collapsible .la-footer-bottom {
    flex-direction: column;
    align-items: center;
    gap: $aac-spacing-12;
    text-align: center;
  }
  /* Override the base .la-footer-bottom__copy `white-space: nowrap`
     so the copyright string can wrap onto multiple lines instead of
     getting clipped by the viewport edge at narrow widths. */
  .la-footer--collapsible .la-footer-bottom .la-footer-bottom__copy {
    white-space: normal;
    max-width: 100%;
  }
}

.la-footer-bottom-badges {
  display: flex;
  gap: $aac-spacing-10;

  .la-badge {
    font-size: 14px;
    font-weight: $aac-font-weight-semi;
    letter-spacing: 0.08em;
    padding: 5px $aac-spacing-12;
    opacity: 1;
    border-radius: 6px;
    transition: opacity 0.2s ease, transform 0.2s ease;

    &:hover {
      opacity: 0.9;
    }
  }

  .la-badge--oss {
    background: rgba($la-navy, 0.06);
    color: rgba($la-navy, 0.75);
    border: 1px solid rgba($la-navy, 0.12);
  }
}

// ── Right panel ───────────────────────────────────────────────────────────────
.la-panel {
  grid-area: panel;
  background: $color-surface;
  border-left: 1px solid $color-border;
  padding: $aac-spacing-20;
  overflow-y: auto;
  display: flex;
  flex-direction: column;
  gap: $aac-spacing-16;
}

.la-panel-card {
  background: white;
  border-radius: $aac-radius-lg;
  border: 1px solid $color-border;
  padding: $aac-spacing-16;

  &.la-panel-card--testimonial {
    border-color: rgba($la-teal, 0.3);
    background: linear-gradient(135deg, rgba($la-teal, 0.04) 0%, white 60%);
  }

  &.la-panel-card--cta {
    background: $indigo;
    border-color: $indigo;
  }
}

.la-panel-card-eyebrow {
  font-size: $la-panel-font-size-xs;
  font-weight: $aac-font-weight-black;
  text-transform: uppercase;
  letter-spacing: $aac-letter-spacing-wide;
  color: $brand-teal;
  margin-bottom: $aac-spacing-10;

  .la-panel-card--cta & {
    color: $brand-honey-bronze;
  }
}

.la-testimonial-quote {
  font-size: $la-panel-font-size-sm;
  font-style: italic;
  color: $color-text-mid;
  line-height: $aac-line-height-loose;
  margin: 0 0 $aac-spacing-14;
  border: none;
  padding: 0;

  &::before { content: ''; }
  &::after  { content: ''; }
}

.la-testimonial-author {
  font-size: $la-panel-font-size-sm;
  font-weight: $aac-font-weight-black;
  color: $color-text;
  margin-bottom: $aac-spacing-2;
}

.la-testimonial-role {
  font-size: $la-panel-font-size-xs;
  color: $brand-teal;
  opacity: 1;
}

.la-wrapper .la-cta-title {
  font-family: 'Lexend', 'Nunito Sans', system-ui, sans-serif;
  font-size: $la-panel-font-size-base * 1.15;
  font-weight: $aac-font-weight-black;
  color: white;
  letter-spacing: -0.02em;
  line-height: 1.15;
  margin: 0 0 $aac-spacing-12;
  padding-left: $aac-spacing-8;
}

.la-wrapper .la-cta-body {
  font-size: $la-panel-font-size-xs * 1.1;
  font-weight: 400;
  color: rgba(white, 0.68);
  line-height: 1.8;
  letter-spacing: 0.005em;
  margin: 0 0 $aac-spacing-20;
}

.la-cta-actions {
  display: flex;
  flex-direction: column;
  gap: $aac-spacing-8;
}

.la-checklist {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: $aac-spacing-8;

  li {
    display: flex;
    align-items: center;
    gap: $aac-spacing-8;
    font-size: $la-panel-font-size-sm;
    color: $color-text-mid;
  }

  .la-check {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 20px;
    height: 20px;
    border-radius: 50%;
    background: rgba($brand-honey-bronze, 0.15);
    color: $brand-teal;
    font-size: 14px;
    font-weight: $aac-font-weight-black;
    box-shadow: 0 2px 6px rgba(0, 0, 0, 0.1), 0 1px 2px rgba(0, 0, 0, 0.06);
  }
}

.la-check {
  color: $cat-people-text;
  font-weight: $aac-font-weight-black;
  flex-shrink: 0;
}

// ── Features modal ──────────────────────────────────────────────────────────
.la-modal-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: $aac-spacing-12 $aac-spacing-24;
  background: $indigo;
}

.la-modal-header-label {
  font-family: 'Lexend', 'Nunito Sans', system-ui, sans-serif;
  font-size: $aac-font-size-base;
  font-weight: $aac-font-weight-black;
  text-transform: uppercase;
  letter-spacing: $aac-letter-spacing-wide;
  color: $brand-honey-bronze;
}

// Opt-in eyebrow-weight override for ai-disclosure only (03-UI-SPEC.md 3, the
// eyebrow-weight fix). A second single-class selector at the SAME specificity as
// .la-modal-header-label above, not a nested/wrapper-scoped override -- every other
// modal keeps rendering its eyebrow at $aac-font-weight-black (800) unchanged.
.la-modal-header-label--regular {
  font-weight: $aac-font-weight-bold;
}

.la-modal-close {
  display: flex;
  align-items: center;
  justify-content: center;
  /* WCAG 2.5.5 AAA touch target (44px min) + AAC standard headroom.
     Updated 2026-04-11 per WCAG audit; was 32×32. */
  width: 48px;
  height: 48px;
  min-width: 48px;
  min-height: 48px;
  border-radius: $aac-radius-circle;
  border: 1px solid rgba(white, 0.15);
  background: rgba(white, 0.08);
  color: rgba(white, 0.7);
  font-size: 14px;
  cursor: pointer;
  transition: all 0.15s ease;

  &:hover {
    background: rgba(white, 0.15);
    color: white;
  }
}

/* Features modal: exact styles from landing-alt #la-features (Why LingoLinq) */
.la-features-modal-body {
  background-color: #F7F9FA;
  padding: $aac-spacing-32 $aac-spacing-32 $aac-spacing-40;
  border-radius: 0;
  display: flex;
  flex-direction: column;
  gap: $aac-spacing-32;
  position: relative;
  overflow: hidden;

  .la-section-header {
    text-align: center;
    max-width: 640px;
    margin: 0 auto;
  }

  .la-section-title {
    font-family: 'Maitree', serif;
    font-size: calc(38px * 0.85); /* 15% smaller than landing */
    font-weight: normal;
    color: $la-navy;
    margin: 0 0 24px;
    letter-spacing: -0.02em;
    line-height: 1.15;
    font-kerning: normal;

    em {
      font-style: normal;
      color: $brand-smart-blue;
    }
  }
}

.la-features-modal-wrap {
  border-radius: $aac-radius-xl;
  overflow: hidden;
  box-shadow: $la-shadow-lg;
  margin: -15px 0; /* vertical only so header extends to left/right edges of modal */
}

.modal-content:has(.la-features-modal-wrap) {
  background: none;
  border: none;
  box-shadow: none;
  overflow: visible !important;
  max-height: none !important;
  padding: 0;
}

.modal-dialog:has(.la-features-modal-wrap) {
  width: 90%;
  max-width: 90%;
  padding-left: 0;
  padding-right: 0;
}

// Features modal: header matches support modal (width kept via .modal-dialog:has(.la-features-modal-wrap) above)
.la-features-modal-wrap .la-modal-header {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 12px;
  padding: 20px 24px;
  border-bottom: 1px solid var(--md-line);
  background: rgba(255, 255, 255, 0.6);
}
.la-features-modal-wrap .la-modal-header-label {
  margin: 0;
  font-weight: 900;
  font-size: 20px;
  letter-spacing: -0.2px;
  color: var(--md-ink);
  flex: 1 1 auto;
  min-width: 0;
}
.la-features-modal-wrap .la-modal-close {
  display: flex;
  align-items: center;
  justify-content: center;
  /* WCAG AA + AAC touch target — was 36×36 */
  width: 48px;
  height: 48px;
  min-width: 48px;
  min-height: 48px;
  padding: 0;
  margin: 0;
  border: 1px solid rgba($brand-blue-black, 0.12);
  border-radius: 50%;
  background-color: $surface-300 !important;
  background: $surface-300 !important;
  color: var(--md-muted);
  cursor: pointer;
  font-size: 18px;
  line-height: 1;
  transition: color 0.2s ease, background 0.2s ease, border-color 0.2s ease, transform 0.2s ease-out, box-shadow 0.2s ease;

  &:hover {
    color: var(--md-ink);
    background-color: $surface-400 !important;
    background: $surface-400 !important;
    border-color: rgba($brand-blue-black, 0.2);
    transform: translateY(-2px) scale(1.04);
    box-shadow: 0 4px 12px rgba($brand-blue-black, 0.14), 0 2px 4px rgba($brand-blue-black, 0.08);
  }
  &:active {
    transform: translateY(0) scale(0.98);
    box-shadow: 0 1px 3px rgba($brand-blue-black, 0.08);
  }
}

// ── Cloud Extras modal (same styling as support modal: uses la-support-modal-wrap) ──
/* Content inside la-support-modal-body: feature list and notes */
.la-cloud-extras-modal-wrap .la-cloud-extras-features-heading {
  font-size: 17px;
  font-weight: 700;
  letter-spacing: -0.02em;
  color: var(--md-ink);
  margin: 0 0 20px;
}

.la-cloud-extras-modal-wrap .la-cloud-extras-feature-list {
  list-style: none;
  margin: 0 0 24px;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 20px;
}

