.la-word-data-modal-wrap .la-word-data-suggestions {
  margin: $aac-spacing-20 0 0;
}

.la-word-data-modal-wrap .la-word-data-modal-actions {
  margin-top: $aac-spacing-20;
  padding-top: $aac-spacing-16;
  border-top: 1px solid rgba(0, 0, 0, 0.1);
