  justify-content: center;
  gap: $aac-spacing-8;
}

.la-word-data-modal-wrap .la-word-data-modal-actions .la-btn--ghost {
  background: color.adjust(#dce1e9, $lightness: -10%);
  color: #2c3e50;
  border: 1px solid rgba(0, 0, 0, 0.15);

  &:hover {
    background: rgba(0, 0, 0, 0.1);
  color: $indigo;
  }
}

.la-word-data-modal-wrap .la-word-data-admin {
  margin-top: $aac-spacing-16;
