}

.la-word-data-modal-wrap .la-word-data-nfc-btn {
  color: $indigo;

  &:hover {
    color: $indigo;
  }
}

/* Modern modal rounding — apply to all modal containers */
.modal-dialog,
.modal-dialog > .ember-view,
.modal-content {
  border-radius: 18px !important;
  overflow: hidden;
}

/* Modify Core Word List modal (modern) */
