}
.la-modify-core-customize-btn {
  padding: 8px 20px;
  border-radius: 999px;
  border: 1px solid rgba($brand-blue-black, 0.12);
  background: $surface-100;
  color: var(--md-ink);
  font-size: 14px;
  font-weight: 600;
  cursor: pointer;
  transition: background 0.15s ease, border-color 0.15s ease;
}
.la-modify-core-customize-btn:hover {
  background: $surface-200;
  border-color: rgba($brand-teal, 0.3);
}
.la-modify-core-list-area {
  margin: 12px 0 20px;
}
.la-modify-core-textarea {
  width: 100%;
  padding: 12px 16px;
  font-size: 14px;
  border: 1.5px solid rgba($brand-blue-black, 0.12);
  border-radius: 10px;
  color: var(--md-ink);
  resize: vertical;
  box-sizing: border-box;
  transition: border-color 0.15s ease, box-shadow 0.15s ease;
}
.la-modify-core-textarea:focus-visible {
  border-color: var(--md-teal);
  box-shadow: 0 0 0 3px rgba($brand-verdigris, 0.12);
  outline: none;
}
.la-modify-core-modal-wrap .la-modify-core-words-preview {
  max-height: 150px;
  overflow: auto;
  padding: 12px 16px;
  border: 1.5px solid rgba($brand-blue-black, 0.08);
  border-radius: 10px;
  background: rgba(248, 250, 252, 0.8);
  font-size: 14px;
  color: var(--md-ink);
}
.la-modify-core-modal-wrap .la-modify-core-word-count {
  text-align: right;
  margin-top: 8px;
  font-size: 14px;
  color: var(--md-muted);
}
.la-modify-core-modal-wrap .la-modify-core-note {
  font-size: 14px;
  color: var(--md-muted);
  margin: 0;
}
.la-modify-core-modal-footer {
  display: flex;
  justify-content: flex-end;
  gap: 10px;
  padding: 16px 24px;
  border-top: 1px solid var(--md-line);
}
.la-modify-core-save-btn {
  padding: 10px 28px;
  border-radius: 999px;
  background: $brand-charcoal-dark;
  border: 1px solid rgba($brand-charcoal-dark, 0.3);
  color: #fff;
  font-size: 15px;
  font-weight: 700;
  cursor: pointer;
  transition: background 0.15s ease, box-shadow 0.15s ease;
}
.la-modify-core-save-btn:hover:not(:disabled) {
  background: #4b5563;
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.15);
}
.la-modify-core-save-btn:disabled {
  opacity: 0.5;
  cursor: not-allowed;
}
.la-modify-core-cancel-btn {
  padding: 10px 24px;
  border-radius: 999px;
  border: 1.5px solid rgba($brand-blue-black, 0.15);
  background: #fff;
  color: $brand-charcoal-dark;
  font-size: 15px;
  font-weight: 600;
  cursor: pointer;
  transition: background 0.15s ease, border-color 0.15s ease;
}
.la-modify-core-cancel-btn:hover {
  background: #f3f4f6;
  border-color: rgba($brand-blue-black, 0.25);
}

.la-support-version {
  font-size: 14px;
  color: var(--md-muted);
  font-weight: 400;
}

.la-support-modal-body {
  padding: 24px;
  color: var(--md-ink);
}

.la-support-intro {
  margin: 0 0 24px;
  font-size: 15px;
  line-height: 1.55;
  color: var(--md-ink);
}

.la-support-list {
  list-style: none;
  margin: 0 0 $aac-spacing-20;
  padding: 0;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: $aac-spacing-8;
}

.la-support-list__link {
  display: inline-flex;
  align-items: center;
  gap: $aac-spacing-8;
  font-size: 15px;
  font-weight: 500;
  color: var(--md-ink);
  text-decoration: none;
  transition: color 0.15s ease;

  &:hover {
    color: var(--md-teal);
    text-decoration: underline;
  }
}

.la-support-list__icon {
  font-size: 18px;
  flex-shrink: 0;

  &--question {
    filter: hue-rotate(210deg);
  }
}

.la-support-list__btn {
  display: inline-flex;
  align-items: center;
  gap: $aac-spacing-8;
  text-decoration: none;
  cursor: pointer;

