    text-decoration: none;
  }
}

// Support modal list button: match Getting Started ghost button
.la-support-modal-body .la-support-list__btn.la-btn.la-btn--ghost {
  padding: 10px 18px;
  border-radius: 999px;
  font-size: 15px;
  font-weight: 600;
  border: 1px solid var(--md-line);
  background: rgba($brand-blue-black, 0.06);
  color: var(--md-ink);
  transition: background 0.2s ease, border-color 0.2s ease, transform 0.2s ease-out, box-shadow 0.2s ease;

  &:hover {
    background: rgba($brand-blue-black, 0.1);
    border-color: rgba($brand-blue-black, 0.18);
    transform: translateY(-2px);
    box-shadow: 0 4px 12px rgba($brand-blue-black, 0.1);
  }
  &:active {
    transform: translateY(0);
    box-shadow: 0 1px 4px rgba($brand-blue-black, 0.08);
  }
}

.la-support-form-section {
  margin-top: 28px;
  padding-top: 20px;
  border-top: 1px solid var(--md-line);
}

.la-support-form-title {
  font-size: 18px;
  font-weight: 900;
  color: var(--md-ink);
  margin: 0 0 16px;
}

.la-support-modal-body .la-contact-form {
  gap: 0;
}

// Support modal fields: match login page (.login-card .form-group / .form-control)
.la-support-modal-body .la-contact-form__row {
  margin-bottom: $aac-spacing-8;
  gap: 2px;
}
.la-support-modal-body .la-contact-form__label {
  display: block;
  font-size: 14px;
  font-weight: $aac-font-weight-semi;
  color: var(--md-ink);
  margin-bottom: 2px;
  letter-spacing: 0.01em;
}
.la-support-modal-body .la-contact-input {
  width: 100%;
  border-radius: 8px;
  border: 1px solid var(--md-line);
  padding: 8px 12px;
  font-size: 14px;
  color: var(--md-ink);
  background: rgba(255, 255, 255, 0.9);
  transition: border-color 0.2s ease, box-shadow 0.2s ease;
  outline: none;
  box-sizing: border-box;
  height: auto;
  box-shadow: none;

  &:focus-visible {
    border-color: var(--md-teal);
    box-shadow: 0 0 0 2px rgba(44, 183, 176, 0.2);
    background: #fff;
  }

  &::placeholder {
    color: var(--md-muted);
  }

  &.la-contact-input--textarea {
    min-height: 52px;
    resize: vertical;
  }
}

/* Limit skin tones modal: list and actions (same style as support modal) */
.la-support-modal-body .la-contact-form__actions {
  margin-top: 8px;
  gap: 12px;
  justify-content: center;
  justify-content: center;
  flex-wrap: wrap;
}

.la-support-modal-body .la-contact-form__actions .la-btn {
  padding: 5.44px 20.4px; /* height 20% smaller (6.8px × 0.8), horizontal unchanged */
}
/* Send Message in support modal */
.la-support-modal-body .la-contact-form__actions .la-btn--primary {
  background: $brand-charcoal-blue;
  color: #fff;
  border: none;
  box-shadow: 0 4px 14px rgba(0, 0, 0, 0.15);
  transition: filter 0.2s ease, box-shadow 0.2s ease, transform 0.15s ease;

  &:hover:not(:disabled) {
    filter: brightness(1.08);
    box-shadow: 0 6px 20px rgba(0, 0, 0, 0.18);
    transform: translateY(-1px);
    color: #fff;
  }
  &:active:not(:disabled) {
    transform: translateY(0);
    box-shadow: 0 2px 8px rgba(0, 0, 0, 0.12);
  }
}

.la-support-modal-body .la-contact-form__actions .la-btn--ghost {
  background: rgba($brand-blue-black, 0.06);
  color: var(--md-ink);
  border: 1px solid var(--md-line);
  transition: background 0.22s ease-in-out, border-color 0.22s ease-in-out, color 0.22s ease-in-out, transform 0.22s ease-in-out, box-shadow 0.22s ease-in-out;

  /* Same hover effect as Send Message (primary) */
  &:hover {
    background: linear-gradient(135deg, rgba(44, 183, 176, 0.28), rgba(91, 141, 239, 0.24));
    border-color: rgba(44, 183, 176, 0.35);
    transform: translateY(-2px);
    box-shadow: 0 4px 14px rgba(44, 183, 176, 0.25), 0 2px 6px rgba($brand-blue-black, 0.08);
    color: var(--md-ink);
    text-decoration: none;
  }
  &:active {
    transform: translateY(0);
    box-shadow: 0 2px 6px rgba(44, 183, 176, 0.15);
  }
}

// login-btn in modal actions row (e.g. Choose Language "Update & Reload"): match sign-in style but inline, smaller text
.la-support-modal-body .la-contact-form__actions .login-btn {
  display: inline-block;
  width: auto;
  font-size: $aac-font-size-sm;
}


.la-support-form-error {
  font-size: 14px;
  color: #c53030;
  margin: 0 0 $aac-spacing-8;
}

.la-support-cookies {
  margin: 24px 0 0;
  padding-top: 16px;
  border-top: 1px solid rgba($indigo, 0.08);
  font-size: 17.5px; /* 14px × 1.25 */
  color: var(--md-muted);
  text-align: center;
}

.la-support-cookies__btn {
  display: inline-flex;
  align-items: center;
  gap: 15px; /* 12px × 1.25 */
  padding: 12px 25px; /* ~25% larger */
  border-radius: 12px;
  border: 1px solid rgba($indigo, 0.1);
  background: #fff;
  color: $indigo;
  font-size: 18.75px; /* 15px × 1.25 */
  font-weight: 500;
  letter-spacing: 0.01em;
  cursor: pointer;
  transition: background 0.2s ease, border-color 0.2s ease, color 0.2s ease, box-shadow 0.2s ease;

  &:hover {
    background: #f8fafc;
    border-color: rgba(63, 127, 123, 0.2);
    color: $indigo;
    box-shadow: 0 2px 8px rgba(0, 0, 0, 0.04);
  }
  &:active {
    background: #f1f5f9;
    border-color: rgba(63, 127, 123, 0.25);
  }
}

.la-support-cookies__icon {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 45px; /* 36px × 1.25 */
  height: 45px;
  border-radius: 10px;
  font-size: 22.5px; /* 18px × 1.25 */
  line-height: 1;
  background: linear-gradient(180deg, rgba($indigo, 0.06), rgba($indigo, 0.03));
  border: 1px solid rgba($indigo, 0.06);

  &--off {
    position: relative;
    opacity: 0.7;

    &::after {
      content: '';
      position: absolute;
      left: 50%;
      top: 50%;
      width: 120%;
      height: 1.5px;
      background: rgba($indigo, 0.35);
      transform: translate(-50%, -50%) rotate(-35deg);
      pointer-events: none;
    }
  }
}









// ── Features modal scroll for smaller screens ───────────────────────────────
@media (max-height: 1279px) {
  .modal:has(.la-features-modal-wrap),
  .modal:has(.la-support-modal-wrap),
  .modal:has(.la-speak-mode-intro-modal-wrap),
  .modal:has(.la-cloud-extras-modal-wrap),
  .modal:has(.la-terms-agree-modal-wrap),
  .modal:has(.la-new-board-modal-wrap) {
    overflow-y: auto;
  }

  .modal-dialog:has(.la-features-modal-wrap),
  .modal-dialog:has(.la-support-modal-wrap),
  .modal-dialog:has(.la-speak-mode-intro-modal-wrap),
  .modal-dialog:has(.la-cloud-extras-modal-wrap),
  .modal-dialog:has(.la-terms-agree-modal-wrap),
  .modal-dialog:has(.la-new-board-modal-wrap) {
    margin: 30px auto;
  }

  .modal-dialog:has(.la-choose-locale-modal-wrap) {
    margin-top: 10rem;
  }
}

// ── Responsive ──────────────────────────────────────────────────────────────

// — xl (≤ 1420px): removed — clamp() handles fluid scaling —

// — xl+ (≥ 1280px): restore left/right margins on workspace so we keep edges on large screens —
@media (min-width: $aac-breakpoint-xl) {
  .la-wrapper .la-main {
    padding-left: calc(#{$aac-spacing-20} + 5rem);
    padding-right: calc(#{$aac-spacing-20} + 5rem);
  }
  .md-workspace {
    margin-left: $aac-spacing-20 !important;

    margin-right: $aac-spacing-20 !important;

  }
}

// — xlg (≤ 1200px): stack hero to single column before mockup gets clipped —
@media (max-width: 1200px) {
  .la-wrapper .la-main {
    width: 100%;
    max-width: 100%;
  }

  .la-hero-card-inner {
    grid-template-columns: 1fr;
    padding: 0;
    justify-items: center;
  }

  .la-hero-card {
    text-align: center;
  }

  .la-hero-text {
    padding-left: 16px;
    padding-right: 16px;
    align-items: center;
    width: 100%;
  }

  .la-hero-headline-and-badges {
    width: auto;
    justify-items: center;
  }

  .la-hero-headline-and-badges .la-hero-headline {
    width: auto;
  }

  .la-hero-subtitle-badges-wrap {
    width: auto;
    align-items: center;
  }

  .la-wrapper .la-hero-subtitle {
    margin-left: auto;
    margin-right: auto;
    text-align: center;
  }

  .la-hero-badges-section {
    margin-left: auto;
    margin-right: auto;
  }

  .la-hero-badges {
    justify-content: center;
  }

  .la-hero-actions {
    justify-content: center;
  }

  .la-hero-headline .la-hero-title-wrap {
    margin-left: auto;
    margin-right: auto;
  }

  .la-hero-mockup-wrap {
    justify-content: center;
    width: 100%;
    max-width: min(450px, 100%); /* 10% smaller than previous 500px cap */
    margin: calc(40px - 3rem) auto 0;
    box-sizing: border-box;
  }

  .la-hero-mockup-wrap .la-mockup {
    width: 100%;
    max-width: min(450px, 100%);
  }

  .la-mockup {
    margin-top: 20px;
  }
}

// — lg (≤ 1024px): collapse topbar nav, 2-col stats —
@media (max-width: $aac-breakpoint-lg) {
  .la-wrapper .la-main {
    padding: $aac-spacing-20 calc(#{$aac-spacing-20} + 5rem);
    padding-bottom: 0;
    gap: $aac-spacing-20;
  }

  // Topbar: hide inline nav, stack CTA
  .la-topbar {
    flex-wrap: wrap;
    padding: $aac-spacing-16;
    gap: $aac-spacing-12;
  }

  .la-topbar-nav {
    display: none;
  }

  .la-topbar-hamburger {
    display: flex;
  }

  .la-topbar-right {
    margin-left: auto;
  }

  // Hide Sign In button (moved into hamburger drawer)
  .header--unauthenticated #identity {
    display: none;
  }

  // Ensure LingoLinq brand name stays visible (identity hidden, nav_header fills full width)
  .header--unauthenticated #nav_header {
    width: 100%;
    min-width: min-content;
    flex-shrink: 0;
  }

  .header--unauthenticated .nav-header__brand {
    flex-shrink: 0 !important;

  }

  // Authenticated navbar: when hamburger is present, only brand + menu — hide all else (#identity wins specificity so we need it and !important)
  // Apply globally to any #inner_header with .app-navbar, not just .header-index-with-dark-toggle
  /* Hide desktop nav items except search and help */
  .header-index-with-dark-toggle .app-navbar .app-navbar-auth-nav--desktop .dropdown,
  .header-index-with-dark-toggle .app-navbar .app-navbar-auth-nav--desktop .md-pillnav__upgrade-nav,
  .header-index-with-dark-toggle .app-navbar .app-navbar-auth-nav--desktop .ll-bento-upgrade-btn--nav,
  #inner_header .app-navbar .app-navbar-auth-nav--desktop .dropdown,
  #inner_header .app-navbar .app-navbar-auth-nav--desktop .md-pillnav__upgrade-nav,
  #inner_header .app-navbar .app-navbar-auth-nav--desktop .ll-bento-upgrade-btn--nav,
  .app-navbar .app-navbar-auth-nav--desktop .dropdown,
  .app-navbar .app-navbar-auth-nav--desktop .md-pillnav__upgrade-nav,
  .app-navbar .app-navbar-auth-nav--desktop .ll-bento-upgrade-btn--nav {
    display: none !important;
  }
  /* Keep Stop Masquerading visible at this breakpoint — exit path must not hide with Upgrade. */
  .header-index-with-dark-toggle .app-navbar .app-navbar-auth-nav--desktop .md-pillnav__stop-masquerade,
  #inner_header .app-navbar .app-navbar-auth-nav--desktop .md-pillnav__stop-masquerade,
  .app-navbar .app-navbar-auth-nav--desktop .md-pillnav__stop-masquerade {
    display: inline-flex !important;
  }
  /* Keep desktop nav visible for search + help, reflow as row */
  .header-index-with-dark-toggle .app-navbar .app-navbar-auth-nav--desktop,
  #inner_header .app-navbar .app-navbar-auth-nav--desktop,
  .app-navbar .app-navbar-auth-nav--desktop {
    display: flex !important;
    align-items: center !important;

    gap: 0 !important;

    margin: 0 !important;

    padding: 0 !important;

  }
  .app-navbar .ll-bento-help-btn--support,
  #inner_header .ll-bento-help-btn--support {
    margin: 0 2px !important;
    padding: 4px !important;
  }
  .app-navbar #header_search .header-search-btn,
  #inner_header #header_search .header-search-btn {
    margin: 0 !important;
    padding: 4px !important;
  }
  /* Group brand left, search+help+hamburger right */
  .app-navbar .app-navbar-authenticated-inner,
  #inner_header .app-navbar .app-navbar-authenticated-inner,
  #inner_header .app-navbar .app-navbar__inner {
    display: flex !important;
    align-items: center !important;

    width: 100% !important;

    position: relative !important;

  }
  .app-navbar .app-navbar__nav-header,
  #inner_header .app-navbar .app-navbar__nav-header {
    display: contents !important;
  }
  .app-navbar .app-navbar__nav-header h1,
  #inner_header .app-navbar .app-navbar__nav-header h1 {
    flex: 1 !important;

    min-width: 0 !important;

  }
  /* …EXCEPT on dashboard / empty-header pages (where the Take-a-Tour +
     Dashboard-Design discs live): don't grow the brand — keep it content-width
     so the discs tuck in just to its right (left-aligned) instead of the brand's
     flex:1 pushing them to the far edge onto the identity menu. `:has()` scopes
     this to headers that actually carry the discs; the `#inner_header` variant
     gives it the ID specificity needed to beat the grow rule above. */
  .app-navbar .app-navbar__nav-header:has(.app-navbar__home-actions) h1.app-navbar__brand,
  #inner_header .app-navbar .app-navbar__nav-header:has(.app-navbar__home-actions) h1.app-navbar__brand {
    flex: 0 0 auto !important;
    order: -2 !important;
  }
  /* Fixed position: search + help + hamburger top-right */
  .app-navbar .app-navbar-auth-nav--mobile,
  #inner_header .app-navbar .app-navbar-auth-nav--mobile {
    position: fixed !important;

    top: 12px !important;

    right: 16px !important;

    z-index: 1100 !important;

    display: flex !important;
    align-items: center !important;

    gap: 0 !important;

    margin: 0 !important;

  }
  .app-navbar #header_search,
  #inner_header #header_search {
    position: fixed !important;

    top: 18px !important;

    right: 100px !important;

    z-index: 1100 !important;

    margin: 0 !important;
  }
  .app-navbar #header_search .header-search-icon,
  #inner_header #header_search .header-search-icon {
    width: 22.5px !important;
    height: 22.5px !important;
  }
  .app-navbar .app-navbar-auth-nav--desktop .ll-bento-help-btn--support,
  #inner_header .app-navbar .app-navbar-auth-nav--desktop .ll-bento-help-btn--support {
    position: fixed !important;

    top: 16px !important;

    right: 64px !important;

    z-index: 1100 !important;

    margin: 0 !important;
    padding: 4px !important;
  }
  /* Keep the brand (h1), the search field, AND the home-actions discs (Take a
     Tour + Dashboard Design) visible at <=1024px — only those discs are the
     dashboard's guided-tour / display-style entry points, and they're meant to
     stay in the navbar at every width (see the .app-navbar__home-actions ≤1024
     block above). Excluding them here is what makes that intent win the cascade;
     the `:not(#header_search)` id-specificity otherwise defeats a class-only
     visibility rule. */
  .header-index-with-dark-toggle .app-navbar .app-navbar__nav-header > *:not(h1):not(#header_search):not(.app-navbar__home-actions),
  #inner_header .app-navbar .app-navbar__nav-header > *:not(h1):not(#header_search):not(.app-navbar__home-actions),
  .app-navbar .app-navbar__nav-header > *:not(h1):not(#header_search):not(.app-navbar__home-actions) {
    display: none !important;
  }
  /* Search icon only (hide input) on small screens */
  .app-navbar #header_search .header-search-input,
  #inner_header #header_search .header-search-input {
    display: none !important;
  }
  .app-navbar #header_search .header-search-wrap,
  #inner_header #header_search .header-search-wrap {
    border: none !important;
    background: none !important;
    box-shadow: none !important;
    padding: 0 !important;
    min-width: auto !important;
  }
  .app-navbar #header_search,
  #inner_header #header_search {
    display: block !important;
    margin: 0 !important;

  }
  .header-index-with-dark-toggle .app-navbar .app-navbar-auth-nav--mobile,
  #inner_header .app-navbar .app-navbar-auth-nav--mobile,
  .app-navbar .app-navbar-auth-nav--mobile {
    display: flex !important;
    align-items: center !important;

    margin-left: 0 !important;

  }
  .header-index-with-dark-toggle .app-navbar .app-navbar-auth-nav--mobile .la-topbar-hamburger,
  #inner_header .app-navbar .app-navbar-auth-nav--mobile .la-topbar-hamburger,
  .app-navbar .app-navbar-auth-nav--mobile .la-topbar-hamburger {
    display: flex !important;
  }
  .header-index-with-dark-toggle .la-topbar-hamburger,
  #inner_header .la-topbar-hamburger,
  .app-navbar-auth-nav--mobile .la-topbar-hamburger {
    background: transparent !important;
    border: none !important;
    gap: 6px !important;

    align-items: center !important;

    margin: 0 4px 0 0 !important;

  }
  .header-index-with-dark-toggle .la-topbar-hamburger__bar,
  #inner_header .la-topbar-hamburger__bar,
  .app-navbar-auth-nav--mobile .la-topbar-hamburger__bar {
    background: $brand-charcoal-dark !important;
    border-radius: 2px !important;

    height: 2px !important;

    width: 20px !important;

  }
  .header-index-with-dark-toggle .la-topbar-hamburger__bar:nth-child(3),
  #inner_header .la-topbar-hamburger__bar:nth-child(3),
  .app-navbar-auth-nav--mobile .la-topbar-hamburger__bar:nth-child(3) {
    display: none !important;

  }

  // Unauthenticated navbar: when hamburger shows, hide Try Free so only hamburger remains (brand when present is outside this block)
  .header--unauthenticated .la-topbar-cta {
    display: none !important;

  }

  // Hero: tighten further
  .la-hero-card-inner {
    padding: 0;
  }

  .la-hero-mockup-wrap {
    max-width: min(562px, 100%); /* 10% smaller (was 625px) */
  }

  .la-hero-mockup-wrap .la-mockup {
    width: 100%;
    max-width: min(562px, 100%);
  }

  // Stats: relax to 2x2
  .la-stats-strip {
