// — xs (≤ 480px) —
@media (max-width: 480px) {
  /* CTA section: content 15% smaller; headline matches "Built for how..." (24px at 480px) */
  .la-cta-section .la-cta-inner {
    font-size: 14px; /* WCAG minimum; was 85% (resolved sub-14px on 14px parent) */
  }
  .la-cta-section .la-cta-headline {
    font-size: 24px;
  }
}

// — xxs (≤ 460px, iPhone Pro Max and below): collapse horizontal padding —
// Sits after the sm/xs landing-alt cascade so it wins on file order.
@media (max-width: 460px) {
  .la-wrapper .la-main {
    padding-left: 2px;
    padding-right: 2px;
  }
  // CTA section — match specificity of base rule (.la-wrapper #la-cta.la-cta-section)
  // so file-order wins.
  .la-wrapper #la-cta.la-cta-section {
    padding-left: 32px;
    padding-right: 32px;
  }
  /* About page open-source (aka .la-a11y-statement) section — 60% width.
     Match base rule's specificity (la-wrapper.la-wrapper--about .la-a11y-statement)
     and override max-width which would otherwise cap it at 37.5%. */
  .la-wrapper.la-wrapper--about .la-a11y-statement {
    width: 60%;
    max-width: 60%;
    margin-left: auto;
    margin-right: auto;
  }
}

/* ===== Modern Register Page (matches login: same gradient + orbs + card, compact layout) ===== */
/* Register – same bg as modern-dashboard */
.register-page-bg {
  /* Transparent content-alignment box ONLY. The gradient/blobs mesh lives on
     the full-viewport #within_ember (see the
     `:has(.page-footer):has(.register-page-bg)` rule) so it fills the ENTIRE
     page height behind the scrolling #content — no seam, no short bg — and
     the same mesh is shared with the login page. Mirrors .login-page-bg.

     Two things were removed here, both of which broke the layout:
     - `background: <gradient>` — moved to #within_ember (above). On this box
       it only painted as far down as the box reached, so the card spilled
       onto a bare white strip below it.
     - `min-height: 100vh` — as a flex child of the shorter #content
       scrollport it pinned this box to the viewport floor while taller forms
       (the Google-signup consent block) overflowed past it. With no
       min-height the box sizes to its content and #content scrolls. */
  position: relative;
  display: flex;
  align-items: flex-start;
  justify-content: center;
  padding: 2.5rem 16px 2rem;
  overflow: visible;
}

.register-page-bg .la-bg-orbs {
  display: none;
  z-index: 0;
}

.register-page {
  position: relative;
  z-index: 1;
  margin: 0 auto;
  width: 100%;
  max-width: 560px;
}

.register-step-copy {
  margin: 0 0 18px;
  color: #4f5c6f;
  font-size: 16px;
  line-height: 1.45;
}

.register-role-heading {
  margin: 0 0 18px;
  color: $la-navy;
  font-size: 22px;
  line-height: 1.25;
  font-weight: 700;
}

.register-role-options {
  display: grid;
  gap: $aac-spacing-12;
  margin-bottom: $aac-spacing-16;
}

.register-choice-card {
  display: flex;
  align-items: center;
  justify-content: space-between;
  width: 100%;
  min-height: 64px;
  padding: $aac-spacing-16 $aac-spacing-20;
  border-radius: 14px;
  border: 1px solid rgba($brand-smart-blue, 0.22);
  background: linear-gradient(180deg, rgba(255, 255, 255, 0.94) 0%, rgba(241, 246, 255, 0.9) 100%);
  color: $brand-smart-blue;
  font-size: 18px;
  font-weight: 700;
  text-align: left;
  cursor: pointer;
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.7),
    0 2px 8px rgba($la-navy, 0.12);
  transition: border-color 0.15s ease, box-shadow 0.15s ease, transform 0.15s ease;

  &:hover,
  &:focus-visible {
    border-color: rgba($brand-smart-blue, 0.55);
    box-shadow:
      inset 0 1px 0 rgba(255, 255, 255, 0.78),
      0 4px 14px rgba($la-navy, 0.16);
    transform: translateY(-1px);
    outline: none;
  }
}

.register-date-row {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: $aac-spacing-12;
}

.register-back-link {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  margin: 0 0 $aac-spacing-14;
  padding: 0;
  border: 0;
  background: transparent;
  color: $brand-smart-blue;
  font-size: 15px;
  font-weight: 700;
  cursor: pointer;

  &:hover,
  &:focus-visible {
    text-decoration: underline;
    outline: none;
  }
}

/* Supporter sub-type buttons — revealed under the role dropdown when
   "Supporter" is selected. Modern glassy pill buttons (2 per row), with a
   brand-smart-blue active state for the chosen type. */
.register-supporter-types {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin-top: 10px;
}

.register-supporter-types--large {
  margin-bottom: $aac-spacing-16;
}
.register-supporter-type {
  flex: 1 1 calc(50% - 4px);
  min-width: 120px;
  padding: 11px 14px;
  border-radius: 12px;
  border: 1px solid rgba($la-navy, 0.14);
  background: linear-gradient(180deg, rgba(255, 255, 255, 0.92) 0%, rgba(241, 244, 248, 0.92) 100%);
  color: $la-navy;
  font-size: 15px;
  font-weight: 600;
  text-align: center;
  cursor: pointer;
  transition: background 0.15s ease, border-color 0.15s ease, box-shadow 0.15s ease, transform 0.1s ease, color 0.15s ease;
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.6),
    0 1px 3px rgba($la-navy, 0.08);
}
.register-supporter-type:hover {
  border-color: rgba($brand-smart-blue, 0.5);
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.7),
    0 2px 8px rgba($la-navy, 0.12);
  transform: translateY(-1px);
}
.register-supporter-type--active {
  background: linear-gradient(180deg, rgba($brand-smart-blue, 0.16) 0%, rgba($brand-smart-blue, 0.08) 100%);
  border-color: $brand-smart-blue;
  color: $brand-smart-blue;
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.5),
    0 0 0 2px rgba($brand-smart-blue, 0.18);
}

.register-footer-link {
  margin: 18px 0 0;
  color: $brand-blue-black;
  font-size: 15px;
  text-align: center;

  a {
    color: $brand-smart-blue;
    font-weight: 700;
    text-decoration: underline;
  }
}

.register-help-text {
