  /* Auth header/divider: match about page design */
  .la-section-header {
    text-align: center;
    max-width: 100%;
    margin-bottom: $aac-spacing-20;
  }

  .la-hero-title-wrap {
    margin-bottom: 0;
  }

  .la-hero-title {
    font-family: 'Maitree', serif;
    font-size: 24px;
    font-weight: normal;
    color: $indigo;
    line-height: 1.2;
    letter-spacing: -0.02em;
    margin: 0;
    text-align: center;

    @media (max-width: 480px) {
