    }

    /* Field backgrounds match .login-card .form-control */
    .form-control {
      width: 100%;
      border-radius: 10px;
      border: 1px solid rgba(0, 0, 0, 0.1);
      padding: 10px 14px;
      font-size: 15px;
      color: $indigo;
      background: rgba(255, 255, 255, 0.9);
      transition: border-color 0.2s ease, box-shadow 0.2s ease;
      outline: none;
      box-sizing: border-box;
      height: auto;

      &:focus-visible {
        border-color: $brand-smart-blue;
        box-shadow: 0 0 0 3px rgba(58, 107, 199, 0.12);
        background: #fff;
      }

      &::placeholder {
        color: #a0a8b8;
      }

      &:-webkit-autofill,
      &:-webkit-autofill:hover,
      &:-webkit-autofill:focus-visible,
      &:-webkit-autofill:active {
        -webkit-box-shadow: 0 0 0 30px rgba(255, 255, 255, 0.9) inset;
        box-shadow: 0 0 0 30px rgba(255, 255, 255, 0.9) inset;
      }
    }

    select.form-control {
      appearance: none;
      background: rgba(255, 255, 255, 0.9);
      background-image: url("data:image/svg+xml,%3Csvg width='12' height='8' viewBox='0 0 12 8' xmlns='http://www.w3.org/2000/svg'%3E%3Cpath d='M1 1l5 5 5-5' stroke='%238c95a6' stroke-width='1.5' fill='none' stroke-linecap='round' stroke-linejoin='round'/%3E%3C/svg%3E");
      background-repeat: no-repeat;
      background-position: right 12px center;
      padding: 8px 32px 8px 12px;
      line-height: 1.3;
      height: auto;
    }

    .text-danger {
      display: block;
      font-size: 14px;
      margin-top: 4px;
      color: #d9534f;
    }
  }

  .register-start-code-link {
    font-size: 14px;
    color: $brand-smart-blue;
    text-decoration: none;
    display: block;
    background: none;
    border: none;
    padding: 0;
    cursor: pointer;

    &:hover {
      text-decoration: underline;
    }

    // On the dedicated email step the start-code link sits directly above the
    // Sign Up button; add breathing room so it isn't crowded against it.
    &.register-start-code-link--spaced {
      margin-bottom: $aac-spacing-16;
    }
  }
}

.register-invite {
  display: flex;
  align-items: flex-start;
  gap: $aac-spacing-12;
  background: #f4f6fa;
  border-radius: 12px;
  padding: $aac-spacing-14;
  margin-bottom: $aac-spacing-16;
  border: 1px solid rgba($la-navy, 0.06);

  .register-invite-icon {
    flex-shrink: 0;
    width: 48px;
    height: 48px;
    border-radius: 10px;
    overflow: hidden;
    display: flex;
    align-items: center;
    justify-content: center;
    background: #fff;
    border: 1px solid rgba(0, 0, 0, 0.06);

    img {
      width: 100%;
      height: 100%;
      object-fit: contain;
    }

    .glyphicon {
      font-size: 22px;
      color: #8c95a6;
    }
  }

  .register-invite-info {
    flex: 1;
    min-width: 0;

    h4 {
      margin: 0 0 $aac-spacing-4;
      font-size: 14px;
      font-weight: 600;
      color: $indigo;
    }

    p {
      margin: 0;
      font-size: 14px;
      color: #5a6578;
      line-height: 1.4;
    }
  }
}

.register-checkboxes {
  margin-bottom: $aac-spacing-16;

  /* Modern checkbox styling — filled $brand-slate-blue background
     with a white tick when checked (light mode). 18×18 box, hairline
     border at rest, switches to slate-blue fill on :checked. The
     input is absolute-positioned at the wrapper's top-left with a
     matching `padding-left` on the wrapper so multi-line label text
     (incl. inline `<a>` links) wraps as one block aligned to the
     right of the box — NOT broken into flex columns. Selector
     specificity beats the global .big_checkbox rule above; no
     !important needed. */
  .big_checkbox {
    position: relative;
    margin-top: $aac-spacing-10;
    margin-bottom: 0;
    padding-left: 28px;
    padding-top: 0;

    /* `.big_checkbox__consent` is the non-<label> consent text span used by
       the signup Terms+Privacy checkboxes (see register.hbs); it shares the
       label typography so the markup change to satisfy no-nested-interactive
       is visually identical. */
    label,
    .big_checkbox__consent {
      display: block;
      font-weight: normal;
      font-size: 14px;
      color: var(--md-ink, $brand-blue-black);
      line-height: 1.5;
      cursor: pointer;
      padding-left: 0;
      margin: 0;

      a {
        color: $brand-smart-blue;
        text-decoration: underline;
      }
    }

    input[type="checkbox"] {
      -webkit-appearance: none;
      -moz-appearance: none;
      appearance: none;
      position: absolute;
      top: 2px;
      left: 0;
      width: 18px;
      height: 18px;
      min-width: 18px;
      min-height: 18px;
      margin: 0;
      border: 1.5px solid rgba($brand-slate-blue, 0.4);
      border-radius: 4px;
      background: #fff;
      box-shadow: none;
      cursor: pointer;
      transition: border-color 0.15s ease, background 0.15s ease;

      &:hover {
        border-color: $brand-slate-blue;
      }

      &:checked {
        background: $brand-slate-blue;
        border-color: $brand-slate-blue;
      }

      &:checked::after {
        position: absolute;
        content: '';
        top: 2px;
        left: 5px;
        width: 5px;
        height: 10px;
        border: solid #fff;
        border-width: 0 2px 2px 0;
        transform: rotate(45deg);
      }
    }
  }

  .register-checkboxes__error {
    display: block;
    margin: $aac-spacing-4 0 0 28px;
    font-size: 13px;
    line-height: 1.4;
  }
}

/* Center Sign Up button in its wrap */
.register-btn-wrap {
  text-align: center;
}

/* Sign Up button — same bg as identity Sign In dropdown on landing-alt */
.register-btn {
  display: inline-block;
  width: auto;
  padding: 11px 20px;
  border: 1px solid rgba(255, 255, 255, 0.12);
  border-radius: 50px;
  background: rgba($brand-charcoal-dark, 1);
  color: rgba(255, 255, 255, 0.95);
  font-size: 16px;
  font-weight: 700;
  cursor: pointer;
  transition: background 0.2s ease, box-shadow 0.2s ease, transform 0.15s ease, border-color 0.2s ease, color 0.2s ease;
  box-shadow: 0 4px 14px rgba(0, 0, 0, 0.15);
  text-align: center;

  &.register-btn--wide {
    width: 100%;
  }

  &:hover:not(:disabled):not(.register-btn--disabled) {
    background: color.adjust(rgba($brand-charcoal-dark, 1), $lightness: 8%);
    color: #ffffff;
    border-color: rgba(255, 255, 255, 0.2);
    box-shadow: 0 6px 20px rgba(0, 0, 0, 0.18);
    transform: translateY(-1px);
  }

  &:active:not(:disabled):not(.register-btn--disabled) {
    transform: translateY(0);
    box-shadow: 0 2px 8px rgba(0, 0, 0, 0.12);
  }

  &:disabled, &.register-btn--disabled {
    background: #a0a8b8;
    box-shadow: none;
    cursor: not-allowed;
    transform: none;
    filter: none;
  }

  /* "Continue with Google" button on the register page — follows
     the same Google Identity Branding Guidelines as the login-form
     equivalent above. See that block (.login-btn--google) for full
     rationale. The chrome here is identical; the only difference
     is the .register-btn-* class scope and a small margin-bottom
     to space it from the OR divider underneath. */
  &.register-btn--google {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 12px;
    width: 100%;
    min-height: 40px;
    padding: 0 12px;
    margin-bottom: 0.75rem;
    border-radius: 4px;
    background: #ffffff;
    border: 1px solid #dadce0;
    color: #3c4043;
    font-family: 'Roboto', 'Helvetica Neue', Arial, sans-serif;
    font-size: 14px;
    font-weight: 500;
    letter-spacing: 0.25px;
    /* Resting elevation — same subtle 2-layer shadow as the login
       variant so the button reads as raised off the page. */
    box-shadow:
      0 1px 2px rgba(60, 64, 67, 0.12),
      0 2px 6px rgba(60, 64, 67, 0.08);
    cursor: pointer;
    transition: background-color 0.218s, box-shadow 0.218s, border-color 0.218s, transform 0.15s ease;
    text-transform: none;

    &:hover:not(:disabled):not(.register-btn--disabled) {
      background: #f8f9fa;
      /* Hold the dark Google-brand label color; the base .register-btn:hover
         sets color:#fff, which would otherwise bleed through here. */
      color: #3c4043;
      border-color: #d2e3fc;
      box-shadow:
        0 1px 2px rgba(60, 64, 67, 0.30),
        0 4px 12px rgba(60, 64, 67, 0.18);
      transform: translateY(-1px);
    }
    &:active:not(:disabled):not(.register-btn--disabled) {
      background: #f1f3f4;
      box-shadow: 0 1px 2px rgba(60, 64, 67, 0.30);
    }
    &:focus-visible {
      outline: none;
      box-shadow:
        0 0 0 3px rgba(66, 133, 244, 0.30),
        0 1px 2px rgba(60, 64, 67, 0.30);
    }
    &:disabled,
    &.register-btn--disabled {
      background: #ffffff;
      border-color: rgba(60, 64, 67, 0.12);
      color: rgba(60, 64, 67, 0.38);
      cursor: not-allowed;
      box-shadow: none;
      filter: none;
    }
  }
}
.register-btn--google__icon {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 18px;
  height: 18px;
  flex-shrink: 0;
}
.register-btn--google__label {
  font-family: inherit;
  font-size: inherit;
  font-weight: inherit;
  letter-spacing: inherit;
}

.login-google-divider {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  margin: 1rem 0;
  color: #6b7280;
  font-size: 14px;

  &::before,
  &::after {
    content: '';
    flex: 1;
    height: 1px;
    background: rgba(0, 0, 0, 0.12);
  }
}

.google-link-picker {
  border: 0;
  margin: 0 0 1rem;
  padding: 0;

  legend {
    font-size: 1.05rem;
    font-weight: 600;
    margin-bottom: 0.75rem;
  }
}

.google-link-picker__option {
  margin-bottom: 0.5rem;
}

.google-link-picker__label {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  min-height: 3rem;
  padding: 0.75rem 1rem;
  border: 2px solid #dadce0;
  border-radius: 12px;
  cursor: pointer;
  font-size: 1.05rem;

  input {
    width: 1.25rem;
    height: 1.25rem;
    margin: 0;
  }
}

.google-link-picker__label--readonly {
  cursor: default;
  background: #f8f9fa;
  border-color: #c8ccd0;
}

.google-link-found-accounts__lead {
  font-size: 1.05rem;
  font-weight: 600;
  margin-bottom: 0.75rem;
}

.google-link-picker__username {
  font-weight: 700;
}

.google-link-picker__display-name {
  color: #4b5563;
}

.google-link-context,
.google-link-account {
  font-size: 1.05rem;
  margin-bottom: 1rem;
}

.google-link-account {
  font-weight: 600;
}

.register-error {
  margin-top: $aac-spacing-12;
  padding: $aac-spacing-10 $aac-spacing-12;
  background: #fef2f2;
  border: 1px solid #f8d7d7;
  border-radius: 10px;
  color: $brand-danger;
  font-size: 14px;
  line-height: 1.4;
}

/* Search page: top spacing below header; flex-fills the outlet so bg covers full viewport on short screens */
.search-page {
  margin-top: 5rem;
  flex: 1 1 auto;
  min-height: 0;
  display: flex;
  flex-direction: column;
}

/* Search page: same layout/board styles as boards page; search-specific header and form */
.ub-search-page {
  .ub-search-page__header {
    .la-hero-title {
      font-size: 28px;
      @media (max-width: 768px) { font-size: 22px; }
    }
    /* Same gradient text as landing-alt "actually" (.la-section-title em) */
    .ub-search-page__title-boards {
      background: $la-highlight-gradient;
      -webkit-background-clip: text;
      background-clip: text;
      -webkit-text-fill-color: transparent;
      color: transparent;
      font-style: normal;
      padding-left: 0.25em;
      font-size: 28px;
    }
    /* "(Page-Sets & Vocabularies)" qualifier in the hero — same gradient
       style as "Boards" but 10px smaller so it reads as a subtitle. */
    .ub-search-page__title-boards.ub-search-page__title-boards--note {
      font-size: 22px;
    }
    .la-about-hero-separator {
      margin-bottom: 1.25rem;
    }
  }
  .ub-search-page__form-wrap {
    max-width: 640px;
    margin: 0 auto;
    padding: 0 1rem;
  }
  .ub-search-page__form {
    margin-top: 0.5rem;
  }
  .ub-search-page__form-row {
    display: flex;
    flex-wrap: wrap;
    align-items: stretch;
    gap: 10px 14px;
    margin-bottom: 8px;
  }
  .ub-search-page__label {
    font-size: 14px;
    font-weight: 500;
    color: $brand-slate-blue;
    margin: 0;
    flex: 0 0 auto;
    position: absolute;
    width: 1px;
    height: 1px;
    padding: 0;
    overflow: hidden;
    clip: rect(0, 0, 0, 0);
    white-space: nowrap;
    border: 0;
  }
  $ub-search-page-control-h: 48px;
  .ub-search-page__input {
    flex: 1 1 200px;
    min-width: 160px;
    height: $ub-search-page-control-h;
    min-height: $ub-search-page-control-h;
    box-sizing: border-box;
    padding: 0 14px;
    border: 1.5px solid rgba($brand-blue-black, 0.12);
    border-radius: 10px;
    font-size: calc(1.15rem * 1.3);
    line-height: 1.2;
    background: rgba(246, 247, 250, 0.9);
    &::placeholder {
      color: #8a9ab8;
      font-size: inherit;
    }
    &:focus-visible {
      outline: none;
      border-color: $brand-teal;
      box-shadow: 0 0 0 3px rgba($brand-teal, 0.12);
    }
  }
  /* Find-a-board combobox (search-board-jump) — replaces the old
     .ub-search-page__input. The component root takes the input's flex
     slot and anchors the floating panel; the trigger mimics the field's
     look so the header reads unchanged when collapsed. */
  .ub-search-jump {
    flex: 1 1 200px;
    min-width: 160px;
    position: relative;
    display: flex;
  }
  .ub-search-jump__trigger {
    flex: 1 1 auto;
    display: inline-flex;
    align-items: center;
    gap: 8px;
    width: 100%;
    height: $ub-search-page-control-h;
    min-height: $ub-search-page-control-h;
    box-sizing: border-box;
    padding: 0 14px;
    border: 1.5px solid rgba($brand-blue-black, 0.12);
    border-radius: 10px;
    background: rgba(246, 247, 250, 0.9);
    font-size: calc(1.15rem * 1.3);
    line-height: 1.2;
    color: $brand-charcoal-dark;
    text-align: left;
    cursor: pointer;
    transition: border-color 0.15s ease, box-shadow 0.15s ease, background 0.15s ease;
    &:hover {
      border-color: rgba($brand-blue-black, 0.20);
    }
    &:focus-visible,
    &.ub-search-jump__trigger--open {
      outline: none;
      border-color: $brand-teal;
      box-shadow: 0 0 0 3px rgba($brand-teal, 0.12);
      background: #fff;
    }
  }
  .ub-search-jump__trigger-icon {
    flex-shrink: 0;
    color: rgba($brand-blue-black, 0.55);
  }
  .ub-search-jump__trigger-label {
    flex: 1 1 auto;
    min-width: 0;
    padding-left: 14px; /* extra breathing room between the search icon and the "Find a board…" text */
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
  }
  .ub-search-jump__trigger--placeholder .ub-search-jump__trigger-label {
    color: #8a9ab8;
  }
  .ub-search-jump__trigger-chevron {
    flex-shrink: 0;
    color: rgba($brand-blue-black, 0.45);
    transition: transform 0.15s ease;
  }
  .ub-search-jump__trigger-chevron--open {
    transform: rotate(180deg);
  }
  /* Floating panel — anchored under the trigger, overlays the results.
     z-index sits below the topbar (400) per docs/styling-recurring-problems
     §2. Interior reuses the .md-board-collection markup; cap the height and
     let .md-board-collection__body scroll inside. */
  .ub-search-jump__panel {
    position: absolute;
    top: calc(100% + 6px);
    left: 0;
    width: 100%;
    min-width: 280px;
    max-height: min(60vh, 460px);
    display: flex;
    flex-direction: column;
    background: #fff;
    border: 1px solid rgba($brand-blue-black, 0.10);
    border-radius: 14px;
    box-shadow: 0 6px 16px rgba($brand-blue-black, 0.10), 0 18px 48px rgba($brand-blue-black, 0.14);
    overflow: hidden;
    z-index: 150;
    .md-board-collection {
      flex: 1 1 auto;
      min-height: 0;
    }
    /* The shared search pill carries a top margin meant to separate it
       from the panel title in speak mode; this panel has no title, so
       collapse it. */
    .md-board-collection__search {
      margin-top: 0;
    }
    /* Match the trigger's helper-text indent — push the live input's
       "Find a board…" placeholder off the search icon. Scoped to this panel
       so the shared speak-mode drawer field is untouched. */
    .md-board-collection__search-input {
      padding-left: 8px;
    }
  }
  .ub-search-page__locale-wrap {
    flex: 0 0 auto;
    width: 175px;
    display: flex;
    align-items: stretch;
    position: relative;
    .ub-search-page__locale-select {
      width: 100%;
      display: flex;
      align-items: stretch;
    }
    .modern-select {
      width: 100%;
      position: relative;
    }
    .modern-select__trigger {
      width: 100%;
      height: $ub-search-page-control-h;
      min-height: $ub-search-page-control-h;
      box-sizing: border-box;
      padding: 0 32px 0 12px;
      border: 1.5px solid rgba($brand-blue-black, 0.12);
      border-radius: 10px;
      font-size: calc(1.05rem * 1.3);
      line-height: 1.2;
      background: rgba(246, 247, 250, 0.9);
      text-align: left;
      cursor: pointer;
      display: inline-flex;
      align-items: center;
      position: relative;
      /* caret indicator */
      &::after {
        content: '';
        position: absolute;
        right: 12px;
        top: 50%;
        width: 10px;
        height: 10px;
        border-right: 2px solid rgba($brand-blue-black, 0.55);
        border-bottom: 2px solid rgba($brand-blue-black, 0.55);
        transform: translateY(-70%) rotate(45deg);
        pointer-events: none;
      }
      &:hover {
        border-color: rgba($brand-blue-black, 0.22);
      }
      &:focus-visible {
        outline: none;
        border-color: $brand-teal;
        box-shadow: 0 0 0 3px rgba($brand-teal, 0.12);
      }
    }
    .modern-select__trigger-text {
      display: inline-block;
      width: 100%;
      overflow: hidden;
      text-overflow: ellipsis;
      white-space: nowrap;
    }
    .modern-select--open .modern-select__trigger {
      border-color: $brand-teal;
      box-shadow: 0 0 0 3px rgba($brand-teal, 0.12);
    }
    .modern-select--open .modern-select__trigger::after {
      transform: translateY(-30%) rotate(-135deg);
    }
    .modern-select__list {
      position: absolute;
      top: calc(100% + 4px);
      left: 0;
      right: 0;
      z-index: 40;
      max-height: 280px;
      overflow-y: auto;
      margin: 0;
      padding: 6px;
      list-style: none;
      background: #fff;
      border: 1px solid rgba($brand-blue-black, 0.12);
      border-radius: 10px;
      box-shadow: 0 12px 28px rgba($brand-blue-black, 0.14), 0 2px 6px rgba($brand-blue-black, 0.08);
    }
    .modern-select__option {
      padding: 8px 12px;
      border-radius: 8px;
      font-size: calc(1rem * 1.2);
      line-height: 1.2;
      color: $brand-blue-black;
      cursor: pointer;
      &:hover {
        background: rgba($brand-teal, 0.08);
      }
    }
    .modern-select__option--selected {
      background: rgba($brand-teal, 0.14);
      color: $brand-teal;
      font-weight: 600;
      &:hover {
        background: rgba($brand-teal, 0.2);
      }
    }
  }
  .ub-search-page__go {
    flex: 0 0 auto;
    white-space: nowrap;
    height: $ub-search-page-control-h;
    min-height: $ub-search-page-control-h;
    box-sizing: border-box;
    padding: 0 20px;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    line-height: 1;
  }
  .ub-search-page__actions {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    gap: 6px 10px;
    font-size: 14px;
  }
  .ub-search-page__link {
    color: $brand-teal;
    font-weight: 500;
    text-decoration: none;
    &:hover {
      text-decoration: underline;
    }
  }
  .ub-search-page__sep {
    color: #8a9ab8;
    font-weight: 300;
  }
  .ub-search-page__see-all {
    white-space: nowrap;
  }

  /* No-results message: 60% larger than .ub-boards-page__loading (0.92rem) */
  .ub-search-page__none-found {
    font-size: calc(0.92rem * 1.6);
    line-height: 1.45;
    color: $brand-slate-blue;
    font-weight: 500;
    margin: 4px 0 0;
  }

  /* Online / Local / My Boards: tighter cards, clear gap between sections */
  .ub-boards-page__content {
    display: flex;
    flex-direction: column;
    gap: 14px;
  }
  .ub-boards-page__boards-section {
    padding: 14px 18px 16px;
    margin-bottom: 0;
    width: 100%;
    max-width: 100%;
    min-width: 0;
    box-sizing: border-box;
  }
  .ub-boards-page__boards-header {
    margin-bottom: 8px;
  }
  .ub-boards-page__boards-title {
    font-size: 1.55rem;
    letter-spacing: -0.02em;
  }
  /* "(Page-Sets & Vocabularies)" qualifier after the Boards heading —
     verdigris brand accent (AA-safe variant for legibility on the
     light page surface), sized down so it reads as a subordinate note
     rather than competing with the heading. */
  .ub-search-page__boards-title-note {
    color: $brand-verdigris-aa;
    font-size: 0.7em;
    font-weight: 600;
    letter-spacing: 0;
  }
  /* Brand groups within the Boards results (CommuniKate, Quick Core,
     Vocal Flair, …). Each group gets a labeled sub-heading above its own
     grid so the listing reads as separated-by-type. */
  .ub-search-page__board-group {
    width: 100%;
    margin-bottom: 1.75rem;
  }
  .ub-search-page__board-group:last-child {
    margin-bottom: 0;
  }
  .ub-search-page__board-group-title {
    font-size: 1.3rem;
    font-weight: 700;
    letter-spacing: -0.01em;
    color: $la-navy;
    margin: 0 0 0.85rem;
    padding-bottom: 0.45rem;
    border-bottom: 1px solid rgba($brand-blue-black, 0.10);
  }
}

/* Search page: flex wrap, full-width row — ~3×280px + gaps on desktop; wraps on smaller viewports */
.ub-search-page .ub-search-page__board-grid.ub-boards-page__board-grid {
  $ub-search-board-gap-x: 1.25rem;
  $ub-search-board-gap-y: 1rem;
  display: flex !important;
  flex-wrap: wrap;
  justify-content: center;
  align-content: flex-start;
  gap: $ub-search-board-gap-y $ub-search-board-gap-x;
  width: 100%;
  max-width: 100%;
  min-width: 0;
  box-sizing: border-box;
  margin-left: 0 !important;
  margin-right: 0 !important;
  overflow-anchor: none;

  > .ub-boards-page__board-item.simple_board_holder,
  > .simple_board_holder {
    flex: 0 0 280px;
    width: 280px;
    max-width: min(280px, 100%);
    min-width: 0;
    padding: 0;
    margin: 0;
    box-sizing: border-box;
    /* Column + stretch: board-icon sits in an ember-view wrapper; row+center left that
       wrapper shrink-to-fit, so width:100% on .btn never resolved to 280px */
    display: flex;
    flex-direction: column;
    align-items: stretch;
    justify-content: flex-start;

    > .ember-view,
    > * {
      width: 100%;
      max-width: 100%;
      min-width: 0;
      box-sizing: border-box;
      display: flex;
      flex-direction: column;
      align-items: stretch;
    }
  }

  .btn.simple_board_icon {
    @include board-card-modern;
    @include simple-board-card-layout;
    width: 100% !important;
    min-width: 0 !important;
    max-width: 100% !important;
    flex: 1 1 auto;
    height: 100%;
    min-height: 0;
    box-sizing: border-box !important;
  }
}

/* Narrow: one fluid column so cards use available width */
@media (max-width: 375px) {
  .ub-search-page .ub-search-page__board-grid.ub-boards-page__board-grid {
    > .ub-boards-page__board-item.simple_board_holder,
    > .simple_board_holder {
      flex: 1 1 100%;
      width: 100%;
      max-width: 100%;
    }
  }
}

/* ===== Beta welcome & agreement (register-style full-page onboarding) ===== */
.beta-welcome-page.register-page-bg {
  /* Match .register-page-bg: min-height fills viewport; #content is the only scrollport. */
  min-height: 100vh;
  align-items: flex-start;
  justify-content: center;
  overflow: hidden;
  /* No top padding (the card sits up near the top); side + generous bottom only. */
  padding: 0 16px clamp(2.5rem, 6vh, 4rem);
  width: 100%;
  box-sizing: border-box;
  /* The warm atmospheric mesh lives on #content (the full-height scrollport) so
     it fills the topbar/bottombar padding bands; this inner layer stays
     transparent so there's one continuous background with no seam. */
  background: transparent;

  /* Orbs removed on the beta page: this inner box has `overflow: hidden`, so the
     blurred orbs were clipped flat at its edge — painting a tinted rectangle
     over the uniform #content mesh and creating the top/bottom seam. The mesh
     alone carries the atmosphere now (single continuous background). */
  .la-bg-orbs {
    display: none;
  }
}

.beta-welcome-page__frame {
  /* Wider, more generous reading column for the premium feel. */
  max-width: 760px;
  box-sizing: border-box;
  /* The single frosted-glass surface for the welcome screen — the card inside
     is transparent and just supplies content padding, so THIS frame is the
     visible glass container. No padding here (the card's padding insets the
     content); the mesh frosts through the translucent veil + strong blur. */
  border-radius: 36px;
  /* Faint COOL tint (not pure white) so the frosted surface reads as a distinct
     glass card over the near-white page instead of vanishing into it. Brighter
     defined rim + stronger frost + deeper float shadow make the "glass" read. */
  background: linear-gradient(180deg, rgba(255, 255, 255, 0.55) 0%, rgba(232, 239, 247, 0.40) 100%);
  backdrop-filter: blur(28px) saturate(1.5);
  -webkit-backdrop-filter: blur(28px) saturate(1.5);
  /* GPU layer — prevents backdrop-filter recompute flash on scroll (see .la-pricing-card ~27720) */
  will-change: transform;
  transform: translateZ(0);
  border: 1px solid rgba(255, 255, 255, 0.85);
  box-shadow:
    0 36px 90px rgba(15, 23, 42, 0.14),
    0 14px 36px rgba(15, 23, 42, 0.07),
    0 2px 6px rgba(15, 23, 42, 0.04),
    inset 0 1px 0 rgba(255, 255, 255, 0.95);
}

.beta-welcome-card {
  margin-top: 0;
  /* Transparent content wrapper — the outer .beta-welcome-page__frame is the
     single glass surface now, so this card carries no surface of its own
     (overrides the flat-white .register-card it inherits). It keeps its padding
     and inner layout; the padding is what insets content from the glass edge. */
  padding: $aac-spacing-32 clamp($aac-spacing-24, 5vw, 40px) $aac-spacing-40;
  border-radius: 32px;
  background: transparent;
  backdrop-filter: none;
  -webkit-backdrop-filter: none;
  border: 0;
  box-shadow: none;

  .la-section-header {
    /* More breathing room beneath the hero now the divider is gone. */
    margin-bottom: $aac-spacing-32;
    text-align: center;
    display: flex;
    flex-direction: column;
    align-items: center;
    width: 100%;
  }

  .la-hero-title-wrap {
    width: 100%;
    max-width: 100%;
    margin-left: auto;
    margin-right: auto;
    text-align: center;
    padding-bottom: 0;
  }

  .la-section-eyebrow-badge {
    display: inline-block;
    margin-bottom: $aac-spacing-16;
    /* 15px floor (not 14) so the uppercase, letter-spaced pill never reads
       below the AAC minimum. */
    font-size: 15px;
    font-weight: $aac-font-weight-semi;
    letter-spacing: 0.08em;
    text-transform: uppercase;
    color: #0d5c5f;
    padding: 7px 16px;
    border-radius: 999px;
    /* Subtle glass glow around the pill (background/border come from the
       shared eyebrow rule). */
    box-shadow:
      0 4px 16px rgba($brand-verdigris, 0.16),
      inset 0 1px 0 rgba(255, 255, 255, 0.6);
  }

  .la-hero-title {
    /* Larger, more cinematic serif headline — landing-page scale, light weight,
       tight tracking, with a touch more line breathing room. clamp keeps it
       graceful from phone to desktop (h1 header size scaling down to ~32px on
       narrow screens). This title is an <h1> (the page's main heading), so
       display/height are reset here to neutralize the legacy global
       `h1 { display:inline-block; height:60px }` nav style from leaking in. */
    display: block;
    height: auto;
    font-family: 'Maitree', serif;
    font-size: clamp(32px, 5.5vw, 48px);
    font-weight: normal;
    line-height: 1.18;
    letter-spacing: -0.025em;
    color: $indigo;
    text-align: center;
    margin: 0 auto;
  }
}

.beta-welcome-card__subtitle {
  margin: $aac-spacing-16 auto 0;
  /* Softer conversational subhead — relaxed leading, lighter ink. */
  font-size: 17px;
  line-height: 1.65;
  font-weight: $aac-font-weight-regular;
  color: rgba(45, 55, 72, 0.74);
  max-width: 34rem;

  /* "help shape what comes next." reuses the landing-alt "every student"
     gradient (.hero-gradient = verdigris→dusty-denim clipped to text). Keep
     it the same size/weight as the rest of the line — we only want the color,
     not .hero-gradient's 1.155em bump. Forced onto its own centered row so the
     gradient phrase always reads as a distinct second line. */
  .hero-gradient {
    font-size: inherit;
    font-weight: inherit;
    display: block;
    width: fit-content;
    margin: 0 auto;
  }
}

.beta-welcome-body {
  text-align: left;
  font-size: 14px;
  line-height: 1.6;
  color: #3d4654;

  p {
    margin: 0 0 $aac-spacing-14;
  }
}

.beta-welcome-intro {
  /* Narrower, centered, conversational — relational not instructional. */
  margin: 0 auto $aac-spacing-40;
  max-width: 540px;
  padding: $aac-spacing-20 $aac-spacing-28;
  border-radius: 20px;
  text-align: center;
  /* Softer, more translucent tinted glass — barely-there, not a boxed panel. */
  background: linear-gradient(
    135deg,
    rgba($brand-verdigris, 0.05) 0%,
    rgba($brand-dusty-denim, 0.035) 100%
  );
  border: 1px solid rgba(255, 255, 255, 0.5);
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.55);

  p:last-child {
    margin-bottom: 0;
  }
}

.beta-welcome-section {
  /* Intentional rhythm — generous breathing room BEFORE each major section so
     the page pauses between ideas (landing-page pacing), while internal groups
     (grids/timeline) stay tight. */
  margin-bottom: clamp(48px, 7vh, 72px);

  &--feedback {
    margin-bottom: $aac-spacing-24;
  }
}

.beta-welcome-section__title {
  font-family: 'Maitree', serif;
  /* Refined editorial heading — serif, light weight (already below 'bold'),
     tighter tracking for the premium SaaS feel. Hierarchy comes from spacing +
     the serif contrast, not heavy weight. */
  font-size: 20px;
  font-weight: normal;
  color: $indigo;
  margin: 0 0 $aac-spacing-20;
  letter-spacing: -0.03em;
  line-height: 1.25;
}

.beta-welcome-feature-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(240px, 1fr));
  gap: $aac-spacing-20;
  margin: 0;
}

.beta-welcome-feature-card {
  position: relative;
  text-align: left;
  padding: $aac-spacing-28 $aac-spacing-24;
  border-radius: 22px;
  /* Elevated glass surface (no hard gray outline) — onboarding pathway card.
     Subtle top-to-bottom surface gradient + bright top-edge light + airy
     layered shadow so it reads like the floating internal app surfaces. */
  border: 1px solid rgba(255, 255, 255, 0.7);
  background: linear-gradient(180deg, rgba(255, 255, 255, 0.92), rgba(248, 250, 252, 0.82));
  backdrop-filter: blur(12px) saturate(1.1);
  -webkit-backdrop-filter: blur(12px) saturate(1.1);
  /* GPU layer — prevents backdrop-filter recompute flash on scroll (see .la-pricing-card ~27720) */
  will-change: transform;
  transform: translateZ(0);
  box-shadow:
    0 18px 40px rgba(15, 23, 42, 0.06),
    0 6px 18px rgba(15, 23, 42, 0.04),
    inset 0 1px 0 rgba(255, 255, 255, 0.82);

  /* Icon sits beside the heading (not stacked above it). */
  .beta-welcome-feature-card__head {
    display: flex;
    align-items: center;
    gap: $aac-spacing-16;
    margin: 0 0 $aac-spacing-16;
  }

  h4 {
    margin: 0;
    font-size: clamp(19px, 2.6vw, 22px);
    font-weight: $aac-font-weight-semi;
    color: $indigo;
    line-height: 1.25;
  }

  p {
    margin: 0;
    font-size: 14px;
    line-height: 1.6;
    color: #5a6578;
  }

  /* Richer gradient icon tile — deeper tint, softer edge sheen, more glow. */
  .la-feature-icon {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 60px;
    height: 60px;
    margin: 0;
    flex-shrink: 0;
    border-radius: 18px;
    font-size: 30px;
    background: linear-gradient(135deg, rgba($brand-verdigris, 0.20), rgba($brand-dusty-denim, 0.12));
    box-shadow:
      inset 0 1px 0 rgba(255, 255, 255, 0.8),
      0 8px 20px rgba($brand-verdigris, 0.16);
  }
  .la-feature-icon--navy {
    background: linear-gradient(135deg, rgba($brand-dusty-denim, 0.20), rgba($la-navy, 0.12));
    box-shadow:
      inset 0 1px 0 rgba(255, 255, 255, 0.8),
      0 8px 20px rgba($brand-dusty-denim, 0.16);
  }
}

/* Featured card — brighter surface and soft teal glow for visual emphasis
   only (no interactive lift): it highlights the primary "explore" message
   without implying a clickable action. */
.beta-welcome-feature-card--featured {
  background: linear-gradient(180deg, rgba(255, 255, 255, 0.92), rgba(236, 248, 246, 0.82));
  border-color: rgba($brand-verdigris, 0.32);
  box-shadow:
    0 18px 48px rgba($brand-verdigris, 0.16),
    0 8px 24px rgba(15, 23, 42, 0.06),
    inset 0 1px 0 rgba(255, 255, 255, 0.85);
}

/* Weekly-missions card — same elevated tinted surface as the featured card,
   in a softer bluish-purple (brand lavender blended toward denim). Tint and
   glow are dialed down so it reads quieter than the teal "Speak" card.
   Visual emphasis only (no lift). */
.beta-welcome-feature-card--missions {
  $missions-accent: color.mix($brand-dusty-denim, $brand-right-logo, 45%);
  background: linear-gradient(180deg, rgba(255, 255, 255, 0.94), rgba(238, 241, 251, 0.6));
  border-color: rgba($missions-accent, 0.22);
  box-shadow:
    0 18px 48px rgba($missions-accent, 0.10),
    0 8px 24px rgba(15, 23, 42, 0.05),
    inset 0 1px 0 rgba(255, 255, 255, 0.85);
}

.beta-welcome-steps {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: $aac-spacing-24;
  position: relative;
}
/* Connected progression — a soft gradient line down the number column (low
   opacity, not a hard border). Inset to span first→last badge centers; the
   opaque badges sit on top so it reads as connected steps. */
.beta-welcome-steps::before {
  content: '';
  position: absolute;
  /* Aligned to the centre of the 36px number circles. */
  left: 18px;
  top: 18px;
  bottom: 18px;
  width: 2px;
  transform: translateX(-50%);
  background: linear-gradient(
    180deg,
    rgba($brand-verdigris, 0.40) 0%,
    rgba($brand-dusty-denim, 0.20) 100%
  );
  /* Whisper-faint connector — guides the eye without reading as a border. */
  opacity: 0.18;
  border-radius: 999px;
  pointer-events: none;
}

.beta-welcome-steps__item {
  display: flex;
  align-items: flex-start;
  /* Pull the text closer to the timeline (was 16) so it reads as one fluid
     unit, not a rigid two-column grid. */
  gap: $aac-spacing-14;
  /* Lighter — no heavy boxed container; the timeline + spacing carry it. */
  padding: 0;
  background: transparent;
  border: 0;
  position: relative;
}

.beta-welcome-steps__num {
  flex-shrink: 0;
  /* Smaller, more elegant circles (was 42px) — less dominant in the column. */
  width: 36px;
  height: 36px;
  border-radius: 50%;
  display: grid;
  place-items: center;
  font-size: 16px;
  font-weight: $aac-font-weight-bold;
  /* Dark numerals on a light glass badge — high contrast, crisp look. */
  color: $indigo;
  /* Glassmorphism disc — a bright specular sheen over a translucent denim→
     verdigris tint, frosted backdrop, crisp light rim, and layered inner
     highlight + colored under-glow so the circles read like polished glass. */
  background:
    radial-gradient(125% 125% at 30% 18%, rgba(255, 255, 255, 0.9) 0%, rgba(255, 255, 255, 0) 52%),
    linear-gradient(150deg, rgba($brand-dusty-denim, 0.32) 0%, rgba($brand-verdigris, 0.28) 100%);
  backdrop-filter: blur(8px) saturate(1.4);
  -webkit-backdrop-filter: blur(8px) saturate(1.4);
  border: 1px solid rgba(255, 255, 255, 0.7);
  box-shadow:
    0 6px 16px rgba($brand-dusty-denim, 0.20),
    inset 0 1px 1px rgba(255, 255, 255, 0.85),
    inset 0 -4px 8px rgba($brand-verdigris, 0.16);
  position: relative;
  z-index: 1;
}

.beta-welcome-steps__content {
  flex: 1;
  min-width: 0;

  strong {
    display: block;
    font-size: 16px;
    color: $indigo;
    margin-bottom: 4px;
  }

  p {
    margin: 0;
    font-size: 14px;
    color: #5a6578;
    line-height: 1.55;
  }
}

/* Emotional intro framing for the participation section — centered and
   conversational, sets the "you're shaping this" tone before the checklist. */
.beta-welcome-feedback__intro {
  max-width: 560px;
  margin: 0 auto $aac-spacing-28;
  text-align: center;
  font-size: 15px;
  line-height: 1.7;
  color: #4a5568;
}

/* Mission checklist — reuses the landing-alt plan-item card + check icon
   styling (.la-plan-item / .la-plan-check) for a consistent look, laid out as
   a calm single-column list. No hover effect here: this is an informational
   checklist, not an interactive surface (landing-alt keeps its own hover). */
.beta-welcome-missions {
  list-style: none;
  margin: 0 auto;
  padding: 0;
  max-width: 560px;
  display: flex;
  flex-direction: column;
  gap: $aac-spacing-12;

  /* Neutralize the shared .la-plan-item hover lift in this context only —
     reset to its own resting shadow so the cards stay static. */
  .la-plan-item:hover {
    transform: none;
    box-shadow:
      0 2px 8px rgba(0, 0, 0, 0.06),
      0 8px 24px rgba(0, 0, 0, 0.06),
      0 0 0 1px rgba(0, 0, 0, 0.04);
  }
}

/* "We're listening" community panel — premium centered glass with a soft
   verdigris/denim mesh glow; replaces the old generic thank-you signoff. */
.beta-welcome-listening {
  position: relative;
  max-width: 580px;
  margin: clamp(40px, 6vh, 64px) auto 0;
  padding: $aac-spacing-40 $aac-spacing-40;
  border-radius: 24px;
  text-align: center;
  overflow: hidden;
  background:
    radial-gradient(120% 130% at 18% 0%, rgba($brand-verdigris, 0.12) 0%, rgba($brand-verdigris, 0) 55%),
    radial-gradient(120% 130% at 85% 100%, rgba($brand-dusty-denim, 0.10) 0%, rgba($brand-dusty-denim, 0) 55%),
    linear-gradient(180deg, rgba(255, 255, 255, 0.90), rgba(248, 250, 252, 0.82));
  backdrop-filter: blur(14px) saturate(1.08);
  -webkit-backdrop-filter: blur(14px) saturate(1.08);
  /* GPU layer — prevents backdrop-filter recompute flash on scroll (see .la-pricing-card ~27720) */
  will-change: transform;
  transform: translateZ(0);
  border: 1px solid rgba(255, 255, 255, 0.62);
  box-shadow:
    0 18px 48px rgba(15, 23, 42, 0.07),
    0 8px 22px rgba(15, 23, 42, 0.04),
    inset 0 1px 0 rgba(255, 255, 255, 0.75);
}

.beta-welcome-listening__pill {
  display: inline-flex;
  align-items: center;
  gap: $aac-spacing-8;
  padding: 6px 16px;
  border-radius: 999px;
  font-size: 14px;
  font-weight: $aac-font-weight-semi;
  letter-spacing: 0.01em;
  color: #0d5c5f;
  background: linear-gradient(135deg, rgba($brand-verdigris, 0.16), rgba($la-teal, 0.12));
  border: 1px solid rgba($brand-verdigris, 0.26);
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.55);
  /* Badge owns the gap to the message below it. */
  margin-bottom: $aac-spacing-32;
}

/* Small "live" dot — signals an open, listening channel. */
.beta-welcome-listening__dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: $brand-verdigris;
  box-shadow: 0 0 0 3px rgba($brand-verdigris, 0.16);
}

.beta-welcome-listening__body {
  /* Full-width centered (no narrow inner column) — badge owns the top gap. */
  margin: 0 auto $aac-spacing-20;
  font-size: 15px;
  line-height: 1.75;
  color: #3d4654;
}

.beta-welcome-listening__hint {
  margin: 0 auto;
  font-size: 14px;
  line-height: 1.65;
  color: #6b7688;
}

/* Right-aligned closing signature with a leading em-dash (added decoratively
   so the translatable team name stays clean). */
.beta-welcome-listening__team {
  display: block;
  margin-top: $aac-spacing-32;
  font-size: 14px;
  font-weight: $aac-font-weight-semi;
  color: $indigo;
  text-align: right;

  &::before {
    content: '— ';
  }
}

.beta-welcome-actions {
  margin-top: $aac-spacing-24;
  padding-top: $aac-spacing-8;

  /* Brand-slate-blue Next / Get Started / Back button (scoped — the shared
     .register-btn stays charcoal everywhere else). White text (inherited from
     the base .register-btn) keeps ~5.5:1 contrast; text-decoration:none is for
     the Back button, which is a LinkTo (<a>). */
  .register-btn {
    min-width: 12rem;
    padding-left: 2rem;
    padding-right: 2rem;
    background: $brand-slate-blue;
    text-decoration: none;

    &:hover:not(:disabled):not(.register-btn--disabled) {
      background: color.adjust($brand-slate-blue, $lightness: 8%);
    }

    /* Leading "‹" on the Back button. */
    .glyphicon {
      margin-right: 6px;
      font-size: 0.8em;
      top: 1px;
    }
  }
}

.beta-welcome-lead {
  font-size: 15px;
  line-height: 1.65;
  color: #4a5568;
  margin-bottom: $aac-spacing-24;
}

/* Each agreement section is a translucent glass card (same family as the
   message page's feature/listening cards) for the modern sectioned rhythm —
   kept light enough that the frosted panel reads through between blocks. */
.beta-welcome-agreement-block {
  margin-bottom: $aac-spacing-20;
  padding: $aac-spacing-24;
  border-radius: 20px;
  background: linear-gradient(180deg, rgba(255, 255, 255, 0.66), rgba(248, 250, 252, 0.54));
  backdrop-filter: blur(12px) saturate(1.08);
  -webkit-backdrop-filter: blur(12px) saturate(1.08);
  /* GPU layer — prevents backdrop-filter recompute flash on scroll (see .la-pricing-card ~27720) */
  will-change: transform;
  transform: translateZ(0);
  border: 1px solid rgba(255, 255, 255, 0.6);
  box-shadow:
    0 14px 36px rgba(15, 23, 42, 0.05),
    0 6px 16px rgba(15, 23, 42, 0.035),
    inset 0 1px 0 rgba(255, 255, 255, 0.7);

  &:last-child {
    margin-bottom: 0;
  }

  .beta-welcome-section__title {
    margin-bottom: $aac-spacing-12;
  }

  p {
    font-size: 15px;
    line-height: 1.6;
    color: #3d4654;
  }

  p:last-child {
    margin-bottom: 0;
  }
}

.beta-welcome-list {
  margin: 0;
  padding-left: 1.25rem;

  li {
    margin-bottom: $aac-spacing-12;
    line-height: 1.6;
    font-size: 15px;
    color: #3d4654;

    &::marker {
      color: $brand-verdigris;
    }

    &:last-child {
      margin-bottom: 0;
    }
  }

  a {
    color: $brand-smart-blue;
    text-decoration: underline;
    text-underline-offset: 2px;
  }
}

.beta-welcome-callout {
  display: flex;
  gap: $aac-spacing-14;
  align-items: flex-start;
  padding: $aac-spacing-20 $aac-spacing-24;
  border-radius: 20px;
  margin-bottom: $aac-spacing-20;
  /* Glass backdrop + lift to match the card family; the safety tint still
     carries the warning color so it stands apart from the neutral blocks. */
  backdrop-filter: blur(12px) saturate(1.08);
  -webkit-backdrop-filter: blur(12px) saturate(1.08);
  /* GPU layer — prevents backdrop-filter recompute flash on scroll (see .la-pricing-card ~27720) */
  will-change: transform;
  transform: translateZ(0);
  box-shadow:
    0 14px 36px rgba(15, 23, 42, 0.05),
    inset 0 1px 0 rgba(255, 255, 255, 0.6);

  &--safety {
    background: linear-gradient(
      135deg,
      rgba(240, 106, 91, 0.10) 0%,
      rgba(255, 193, 7, 0.07) 100%
    );
    border: 1px solid rgba(240, 106, 91, 0.26);
  }
}

.beta-welcome-callout__icon {
  flex-shrink: 0;
  font-size: 24px;
  line-height: 1;
}

.beta-welcome-callout__title {
  margin: 0 0 $aac-spacing-8;
  font-size: 20px;
  font-weight: $aac-font-weight-semi;
  color: $indigo;
}

.beta-welcome-callout__content p {
  margin: 0;
  font-size: 15px;
  line-height: 1.6;
  color: #3d4654;
}

.beta-welcome-footer {
  flex-shrink: 0;
  margin-top: $aac-spacing-16;
  padding-top: $aac-spacing-16;
  /* Transparent on the beta-welcome page so the glass panel shows through
     (no separate white surface or divider behind the accept + Get Started). */
  background: transparent;
}

.beta-welcome-accept {
  margin-bottom: $aac-spacing-12;

  .big_checkbox label,
  .big_checkbox .big_checkbox__consent {
    font-size: 15px;
    line-height: 1.45;
    color: #3d4654;
  }
}

/* Short layout only (the beta-welcome-message page — NOT the agreement page,
   which carries the .beta-welcome-page--agreement modifier). Center the
   checkbox + agreement text as a unit to match the centered Get Started button.
   The inner box stays left-aligned so a wrapped line reads normally. */
.beta-welcome-page:not(.beta-welcome-page--agreement) .beta-welcome-accept {
  text-align: center;

  .big_checkbox {
    display: inline-block;
    text-align: left;
  }
}

/* Preview mode slider on beta-welcome-message (Original <-> Short). Segmented
   sliding-pill control pinned to the top-right of the viewport; the app header
   is force-hidden on this page, so the corner is free. */
.beta-mode-toggle {
  position: fixed;
  top: 16px;
  right: 16px;
  z-index: $aac-z-toast;
  display: inline-flex;
  align-items: stretch;
  height: 34px;
  padding: 3px;
  border-radius: 999px;
  border: 1px solid rgba($brand-blue-black, 0.12);
  background: rgba(255, 255, 255, 0.7);
  backdrop-filter: blur(6px);
  -webkit-backdrop-filter: blur(6px);
  box-shadow: 0 4px 14px rgba(0, 0, 0, 0.1);
}

.beta-mode-toggle__slider {
  position: absolute;
  left: 3px;
  top: 3px;
  width: calc(50% - 3px);
  height: calc(100% - 6px);
  border-radius: 999px;
  background: linear-gradient(135deg, rgba(44, 183, 176, 0.22) 0%, rgba(91, 141, 239, 0.14) 100%);
  border: 1px solid rgba(44, 183, 176, 0.32);
  transition: transform 0.25s ease;
  z-index: 0;
  pointer-events: none;
}

.beta-mode-toggle--short .beta-mode-toggle__slider {
  transform: translateX(100%);
}

.beta-mode-toggle__option {
  position: relative;
  z-index: 1;
  flex: 1 1 0;
  min-width: 0;
  padding: 0 16px;
  font-size: 14px;
  font-weight: 700;
  line-height: 1;
  white-space: nowrap;
  border: none;
  border-radius: 999px;
  background: transparent;
  /* Inactive label — must clear WCAG AA 4.5:1 (0.55 alpha was 3.91:1 at 14px
     bold). 0.72 keeps it visibly lighter than the active $indigo label while the
     sliding pill still signals which option is selected. */
  color: rgba($brand-blue-black, 0.72);
  cursor: pointer;
  transition: color 0.2s ease;
}

.beta-mode-toggle__option--active {
  color: $indigo;
}

@media (max-width: 550px) {
  .beta-welcome-page.register-page-bg {
    padding: 0 12px 2rem;
  }

  #within_ember:has(.beta-welcome-page) #content {
    padding-top: 1.25rem !important;
    padding-bottom: calc(var(--bottombar-height) + 1.25rem) !important;
  }

  .beta-welcome-card {
    padding: $aac-spacing-24 $aac-spacing-16 $aac-spacing-24;
  }

  .register-page {
    padding-top: 2rem;
  }

  .register-card {
    padding: $aac-spacing-20 $aac-spacing-16;
    border-radius: 16px;
  }

  .login-page {
    padding-top: 3rem;
  }

  .login-card {
    padding: 28px 20px;
    border-radius: 16px;
  }
}

/* ===== Login / Forgot password / Forgot username – same bg as modern-dashboard ===== */
.login-page-bg {
  /* Gradient is now applied on #content (the scroll container) so it fills
     including the topbar/bottombar padding bands. This wrapper is just the
     content-alignment box. */
  position: relative;
  display: flex;
  align-items: flex-start;
  justify-content: center;
  padding: 4rem 16px 3rem;
  overflow: visible;
}

.login-page-bg .la-bg-orbs {
  display: none;
  z-index: 0;
}

.login-page {
  position: relative;
  z-index: 1;
  margin: 0 auto;
  width: 100%;
  max-width: 440px;
}

.password-field {
  position: relative;
  width: 100%;

  input.form-control {
    padding-right: 48px;
  }

  &__toggle {
    position: absolute;
    top: 50%;
    right: 8px;
    transform: translateY(-50%);
    display: inline-flex;
    align-items: center;
    justify-content: center;
    min-width: 44px;
    min-height: 44px;
    padding: 0;
    border: 0;
    border-radius: 8px;
    background: transparent;
    color: #6b7280;
    cursor: pointer;
    transition: color 0.2s ease, background-color 0.2s ease;

    &:hover {
      color: $indigo;
      background: rgba(0, 0, 0, 0.04);
    }

    &:focus-visible {
      outline: 2px solid $brand-smart-blue;
      outline-offset: 2px;
    }
  }

  &__icon {
    width: 20px;
    height: 20px;
    display: block;
  }
}

/* Registration confirmation screen (user.confirm_registration). Mirrors the
   .login-card auth treatment — centered, soft dual-radial gradient, teal top
   border, Maitree title — with a success/error status badge and a single Home
   CTA. Lives in the user outlet below the Home/Account/Logs pill-nav. */
.la-reg-confirm {
  display: flex;
  justify-content: center;
  padding: $aac-spacing-40 $aac-spacing-24;
}
.la-reg-confirm__card {
  width: 100%;
  max-width: 480px;
  text-align: center;
  background:
    radial-gradient(ellipse 50% 60% at 15% 20%, rgba($la-teal, 0.07) 0%, transparent 70%),
    radial-gradient(ellipse 45% 50% at 85% 70%, rgba(58, 107, 199, 0.05) 0%, transparent 70%),
    rgba(255, 255, 255, 0.95);
  border-radius: $aac-radius-xl;
  padding: $aac-spacing-40 $aac-spacing-32;
  border: 1px solid rgba(0, 0, 0, 0.06);
  border-top: 1px solid rgba($brand-teal, 0.14);
  box-shadow:
    0 2px 8px rgba(0, 0, 0, 0.06),
    0 8px 24px rgba(0, 0, 0, 0.07),
    0 24px 48px -12px rgba(0, 0, 0, 0.08);
}
.la-reg-confirm__icon {
  width: 64px;
  height: 64px;
  margin: 0 auto $aac-spacing-20;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
}
.la-reg-confirm__icon--success {
  color: #2A9D8F;
  background: rgba(42, 157, 143, 0.12);
}
.la-reg-confirm__icon--error {
  color: #C0392B;
  background: rgba(192, 57, 43, 0.10);
}
.la-reg-confirm__title {
  font-family: 'Maitree', serif;
  font-size: 26px;
  font-weight: normal;
  color: $indigo;
  line-height: 1.2;
  letter-spacing: -0.02em;
  margin: 0 0 $aac-spacing-12;

  @media (max-width: 480px) {
    font-size: 22px;
  }
}
.la-reg-confirm__message {
  font-family: 'Lexend', 'Nunito Sans', system-ui, sans-serif;
  font-size: $aac-font-size-md;
  color: $brand-charcoal-dark;
  line-height: 1.5;
  max-width: 40ch;
  margin: 0 auto $aac-spacing-28;
}
.la-reg-confirm__cta {
  display: inline-flex;
  align-items: center;
}
/* Success celebration: a party-popper badge with confetti bursting from behind
   it. The badge sits centered; the celebrate wrapper owns the bottom spacing
   (the plain --error badge keeps its own auto margin). */
.la-reg-confirm__celebrate {
  position: relative;
  width: 64px;
  height: 64px;
  margin: 0 auto $aac-spacing-20;
}
.la-reg-confirm__celebrate .la-reg-confirm__icon {
  margin: 0;
}
/* Party-popper icon pops in on entry. */
.la-reg-confirm__icon--success svg {
  animation: la-reg-pop 0.5s ease-out both;
}
/* Confetti pieces burst outward on a gentle loop. Each carries its own
   direction (--tx/--ty in px), spin (--rot), color and delay. Pieces are
   pre-centered on the badge's midpoint via negative margins, so the keyframe
   translate stays pure-px (no mixed %+px calc for SassC to choke on). */
.la-reg-confirm__confetti {
  position: absolute;
  top: 50%;
  left: 50%;
  margin: -3.5px 0 0 -3.5px;
  width: 7px;
  height: 7px;
  border-radius: 1px;
  opacity: 0;
  animation: la-reg-confetti 2.6s ease-out infinite;
}
.la-reg-confirm__confetti--a { --tx: -40px; --ty: -26px; --rot: 200deg;  background: #2A9D8F; animation-delay: 0s; }
.la-reg-confirm__confetti--b { --tx:  38px; --ty: -32px; --rot: -220deg; background: #4C86D8; animation-delay: 0.12s; }
.la-reg-confirm__confetti--c { --tx: -30px; --ty:  30px; --rot: 160deg;  background: #F4A259; animation-delay: 0.24s; }
.la-reg-confirm__confetti--d { --tx:  34px; --ty:  28px; --rot: -160deg; background: #E76F92; animation-delay: 0.36s; }
.la-reg-confirm__confetti--e { --tx:  -6px; --ty: -44px; --rot: 260deg;  background: #F6C453; animation-delay: 0.5s; }
.la-reg-confirm__confetti--f { --tx:   8px; --ty:  42px; --rot: -120deg; background: #6C5CE7; animation-delay: 0.62s; }

@keyframes la-reg-pop {
  0%   { transform: scale(0) rotate(-14deg); }
  60%  { transform: scale(1.15) rotate(4deg); }
  100% { transform: scale(1) rotate(0); }
}
@keyframes la-reg-confetti {
  0%   { transform: translate(0, 0) scale(0.3) rotate(0deg); opacity: 0; }
  12%  { opacity: 1; }
  70%  { opacity: 1; }
  100% { transform: translate(var(--tx), var(--ty)) scale(1) rotate(var(--rot)); opacity: 0; }
}
/* Respect reduced-motion: no burst or pop; the party-popper badge stays static. */
@media (prefers-reduced-motion: reduce) {
  .la-reg-confirm__icon--success svg { animation: none; }
  .la-reg-confirm__confetti { animation: none; opacity: 0; }
}

.login-card {
  margin-top: $aac-spacing-24;
  background:
    radial-gradient(ellipse 50% 60% at 15% 20%, rgba($la-teal, 0.07) 0%, transparent 70%),
    radial-gradient(ellipse 45% 50% at 85% 70%, rgba(58, 107, 199, 0.05) 0%, transparent 70%),
    rgba(255, 255, 255, 0.9);
  border-radius: $aac-radius-xl;
  padding: $aac-spacing-32 $aac-spacing-28 $aac-spacing-40;
  border: 1px solid rgba(0, 0, 0, 0.06);
  border-top: 1px solid rgba($brand-teal, 0.14);
  box-shadow:
    0 2px 8px rgba(0, 0, 0, 0.06),
    0 8px 24px rgba(0, 0, 0, 0.07),
    0 24px 48px -12px rgba(0, 0, 0, 0.08);
  position: relative;
  overflow: hidden;

  /* Auth header/divider: match about page design */
  .la-section-header {
    text-align: center;
    max-width: 100%;
    margin-bottom: $aac-spacing-24;
  }

  .la-hero-title-wrap {
    margin-bottom: 0;
  }

  .la-hero-title {
    font-family: 'Maitree', serif;
    font-size: 26px;
    font-weight: normal;
    color: $indigo;
    line-height: 1.2;
    letter-spacing: -0.02em;
    margin: 0;
    text-align: center;

    @media (max-width: 480px) {
      font-size: 22px;
    }
  }

  .la-about-hero-separator {
    height: 1px;
    max-width: 100%;
    border: none;
    border-radius: 0;
    background: rgba(0, 0, 0, 0.12);
    margin: 0 auto $aac-spacing-24;
  }

  /* Login Help title: match "Login" size to "Help" (same as .hero-gradient) */
  .la-hero-title__prefix {
    font-size: 1.155em;
  }

  .form-group {
    margin-bottom: $aac-spacing-20;

    label {
      display: block;
      font-size: $aac-font-size-sm;
      font-weight: $aac-font-weight-semi;
      color: $la-navy;
      margin-bottom: $aac-spacing-6;
      letter-spacing: 0.01em;
    }

    .form-control {
      width: 100%;
      border-radius: 12px;
      border: 1px solid rgba(0, 0, 0, 0.1);
      padding: 12px 16px;
      font-size: $aac-font-size-base;
      color: $indigo;
      background: rgba(255, 255, 255, 0.9);
      transition: border-color 0.2s ease, box-shadow 0.2s ease;
      outline: none;
      box-sizing: border-box;
      height: auto;

      &:focus-visible {
        border-color: $brand-smart-blue;
        box-shadow: 0 0 0 3px rgba(58, 107, 199, 0.12);
        background: #fff;
      }

      &::placeholder {
        color: #a0a8b8;
      }
    }
  }

  /* Center Sign In / Submit button in its form-group (login, forgot_password, forgot_login) */
  .form-group:has(.login-btn) {
    text-align: center;
  }

  /* Sign In / Submit button — same bg as identity Sign In dropdown
     on landing-alt. Excludes --outline AND --google so the Google
     button can render its own brand-spec light treatment defined
     further down (.login-btn.login-btn--google). Without the
     --google exclusion this rule has higher specificity than the
     scoped .login-btn.login-btn--google override below and was
     leaking the dark navy fill into Google's branded button. */
  .login-btn:not(.login-btn--outline):not(.login-btn--google) {
    background: rgba($brand-charcoal-dark, 1);
    border: 1px solid rgba(255, 255, 255, 0.12);
    color: rgba(255, 255, 255, 0.95);

    &:hover {
      background: color.adjust(rgba($brand-charcoal-dark, 1), $lightness: 8%);
      color: #ffffff;
      border-color: rgba(255, 255, 255, 0.2);
    }
  }
}

.login-btn {
  display: inline-block;
  width: auto;
  padding: 13px 24px;
  border: 1px solid rgba(255, 255, 255, 0.12);
  border-radius: 50px;
  background: rgba($brand-charcoal-dark, 1); /* same as identity Sign In button on landing-alt */
  color: rgba(255, 255, 255, 0.95);
  font-size: 16px;
  font-weight: 700;
  cursor: pointer;
  transition: background 0.2s ease, box-shadow 0.2s ease, transform 0.15s ease, border-color 0.2s ease, color 0.2s ease;
  box-shadow: 0 4px 14px rgba(0, 0, 0, 0.15);
  text-align: center;

  &:hover {
    background: color.adjust(rgba($brand-charcoal-dark, 1), $lightness: 8%);
    color: #ffffff;
    border-color: rgba(255, 255, 255, 0.2);
    box-shadow: 0 6px 20px rgba(0, 0, 0, 0.18);
    transform: translateY(-1px);
  }

  &:active {
    transform: translateY(0);
    box-shadow: 0 2px 8px rgba(0, 0, 0, 0.12);
  }

  &:disabled {
    background: #a0a8b8;
    box-shadow: none;
    cursor: not-allowed;
    transform: none;
    filter: none;
  }

  &.login-btn--outline {
    background: #fff;
    color: rgba($brand-charcoal-dark, 1);
    border: 2px solid rgba($brand-charcoal-dark, 1);
    box-shadow: none;

    &:hover {
      background: #f0f4fa;
      box-shadow: none;
      transform: translateY(-1px);
    }
  }

  /* "Continue with Google" button — follows Google's official
     Identity Branding Guidelines
     (https://developers.google.com/identity/branding-guidelines).
     - White field, 1px #dadce0 hairline border, 4px corners
     - 18px multi-color G mark on the left, 12px gap to label
     - Roboto Medium 14px label, color #3c4043, 0.25px letter-spacing
     - Hover: bg shifts to #f8f9fa with Material elevation shadow
     - Active: bg deepens to #f1f3f4
     - Disabled: text drops to 38% alpha
     Overrides the page-default .login-btn pill chrome so the
     Google button reads as a recognizable platform-standard control
     rather than a custom-styled CTA. */
  &.login-btn--google {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 12px;
    width: 100%;
    min-height: 40px;
    /* Vertical gap above the button so it sits comfortably below
       the OR divider rather than crowding right under it. */
    margin-top: 16px;
    padding: 0 12px;
    border-radius: 4px;
    background: #ffffff;
    border: 1px solid #dadce0;
    color: #3c4043;
    font-family: 'Roboto', 'Helvetica Neue', Arial, sans-serif;
    font-size: 14px;
    font-weight: 500;
    letter-spacing: 0.25px;
    /* Resting elevation — subtle 2-layer shadow (close grounding +
       soft ambient lift) so the button reads as raised off the page
       rather than sitting flush. Hover state deepens both layers
       for press affordance. */
    box-shadow:
      0 1px 2px rgba(60, 64, 67, 0.12),
      0 2px 6px rgba(60, 64, 67, 0.08);
    cursor: pointer;
    transition: background-color 0.218s, box-shadow 0.218s, border-color 0.218s, transform 0.15s ease;
    text-transform: none;

    &:hover:not(:disabled) {
      background: #f8f9fa;
      /* Hold the dark Google-brand label color; the base .login-btn:hover
         sets color:#fff, which would otherwise bleed through here. */
      color: #3c4043;
      border-color: #d2e3fc;
      box-shadow:
        0 1px 2px rgba(60, 64, 67, 0.30),
        0 4px 12px rgba(60, 64, 67, 0.18);
      transform: translateY(-1px);
    }
    &:active:not(:disabled) {
      background: #f1f3f4;
      box-shadow: 0 1px 2px rgba(60, 64, 67, 0.30);
    }
    &:focus-visible {
      outline: none;
      box-shadow:
        0 0 0 3px rgba(66, 133, 244, 0.30),
        0 1px 2px rgba(60, 64, 67, 0.30);
    }
    &:disabled {
      background: #ffffff;
      border-color: rgba(60, 64, 67, 0.12);
      color: rgba(60, 64, 67, 0.38);
      cursor: not-allowed;
      box-shadow: none;
    }
  }
  .login-btn--google__icon {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 18px;
    height: 18px;
    flex-shrink: 0;
  }
  .login-btn--google__label {
    font-family: inherit;
    font-size: inherit;
    font-weight: inherit;
    letter-spacing: inherit;
  }

  .login-btn__title {
    display: block;
    font-size: 16px;
    font-weight: 700;
  }
  .login-btn__sub {
    display: block;
    font-size: 14px;
    font-weight: 400;
    opacity: 0.9;
    margin-top: 2px;
  }
  &.login-btn--outline .login-btn__sub {
    opacity: 0.8;
  }
}

/* Device activation step (login/device): full-width centered buttons */
.login-device-buttons {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 12px;
}
.login-btn--device {
  width: 100%;
  max-width: 400px;
}

.login-error {
  margin-bottom: 14px;
  padding: 10px 14px;
  background: #fef2f2;
  border: 1px solid #f8d7d7;
  border-radius: 10px;
  color: $brand-danger;
  font-size: 14px;
  line-height: 1.45;
}

.login-privacy-note {
  margin: -8px 0 14px;
  font-size: 14px;
  line-height: 1.45;
}

.login-links {
  margin-top: 14px;
  text-align: center;
  font-size: 14px;

  a {
    color: $brand-smart-blue;
    text-decoration: none;

    &:hover {
      text-decoration: underline;
    }
  }
}

/* =========================
   Modern Dashboard (LingoLinq)
   Light/medium, low-cognitive load
   ========================= */

:root {
  --md-bg: #eef1f6;
  --md-ink: #{$brand-blue-black};
  --md-muted: #{$la-navy};
  --md-line: #{rgba($brand-blue-black, 0.10)};

  --md-navy: #{$la-navy};
  --md-navy-2: #1e2f52;

  --md-teal: #{$brand-verdigris};
  --md-teal-soft: rgba(44, 183, 176, 0.18);

  --md-coral: #f06a5b;
  --md-coral-soft: rgba(240, 106, 91, 0.16);

  --md-surface: rgba(255, 255, 255, 0.76);
  --md-surface-2: rgba(255, 255, 255, 0.88);

  --md-shadow: 0 18px 50px #{rgba($brand-blue-black, 0.12)};
  --md-shadow-2: 0 12px 28px #{rgba($brand-blue-black, 0.10)};

  --md-r-lg: 28px;
  --md-r-md: 20px;
  --md-r-sm: 14px;

  --md-tap: 0.99;
}

/* Modern dashboard shell: size to content (min 100vh) so bg extends to bottom of page; min-width 0 so it shrinks with viewport */
#content .ember-view > .md-shell,
#content > .md-shell {
  flex: 0 0 auto;
  min-height: 100vh;
  min-width: 0;
  max-width: 100%;
  display: flex;
  flex-direction: column;
}

.md-shell {
  min-height: 100vh !important;

  min-width: 0 !important;

  max-width: 100% !important;

  overflow-x: hidden !important;

  padding-top: 3rem !important;

  display: flex !important;

  flex-direction: column !important;

  background:
    radial-gradient(1400px 700px at 10% 5%, rgba($brand-stormy-teal, 0.22), transparent 50%),
    radial-gradient(1200px 600px at 90% 15%, rgba($brand-charcoal-blue, 0.18), transparent 50%),
    radial-gradient(1100px 700px at 50% 95%, rgba($brand-charcoal-dark, 0.20), transparent 50%),
    radial-gradient(900px 500px at 80% 55%, rgba($brand-verdigris, 0.14), transparent 45%),
    radial-gradient(800px 400px at 25% 65%, rgba($brand-dusty-denim, 0.10), transparent 50%),
    linear-gradient(180deg, #{color.adjust($brand-stone-100, $lightness: 10%)} 0%, #{color.adjust($brand-stone-200, $lightness: 10%)} 50%, #{color.adjust($brand-stone-300, $lightness: 10%)} 100%) !important;
  color: var(--md-ink) !important;

}

/* User pages (badges/goals/subscription/etc.) don't get the dashboard's
   `.page-footer` flex-grow rules, so `.md-shell--user`'s own `min-height:100vh`
   mesh is pinned to the viewport as a flex child of the scrolling #content and
   taller content (e.g. the badges grid) overflows past it, revealing #content's
   grey (#aaa) base below the shell. #content is the actual scroll container and
   its background stays behind the full scroll height, so paint the mesh there;
   the shell is made transparent below so the two meshes don't seam. */
#content:has(.md-shell--user),
#within_ember:has(.md-shell--user) .page-footer {
  background:
    radial-gradient(1400px 700px at 10% 5%, rgba($brand-stormy-teal, 0.22), transparent 50%),
    radial-gradient(1200px 600px at 90% 15%, rgba($brand-charcoal-blue, 0.18), transparent 50%),
    radial-gradient(1100px 700px at 50% 95%, rgba($brand-charcoal-dark, 0.20), transparent 50%),
    radial-gradient(900px 500px at 80% 55%, rgba($brand-verdigris, 0.14), transparent 45%),
    radial-gradient(800px 400px at 25% 65%, rgba($brand-dusty-denim, 0.10), transparent 50%),
    linear-gradient(180deg, #{color.adjust($brand-stone-100, $lightness: 10%)} 0%, #{color.adjust($brand-stone-200, $lightness: 10%)} 50%, #{color.adjust($brand-stone-300, $lightness: 10%)} 100%) !important;
  /* Pin the mesh to the viewport so #content AND the page-footer below it render
     the identical mesh with no seam, covering the whole page (the footer renders
     on every non-board page and is a sibling of #content). */
  background-attachment: fixed !important;
}
#content:has(.md-shell--user) {
  /* fill the viewport when the badge grid is short so the mesh isn't cut off */
  min-height: 100vh !important;
}
/* Two-class selector (0,2,0) so this beats the plain `.md-shell` (0,1,0)
   background rules defined later in the file (e.g. ~L58263/58282) that would
   otherwise re-apply the shell's own mesh on top of #content's — creating the
   two-tone "gray band" where the shell ends. With the shell transparent, only
   #content's single fixed mesh shows across the whole page. */
.md-shell.md-shell--user {
  background: transparent !important;
  /* Let #content drive the page height; the shell's own 100vh would double-count
     against #content's top padding and overflow. */
  min-height: 0 !important;
}

