  background: #fff !important;
  border-color: rgba($brand-blue-black, 0.4) !important;
}
.md-edit-profile__form input[type="checkbox"]:checked::after {
  content: '' !important;
  position: absolute;
  top: 2px;
  left: 5px;
  width: 5px;
  height: 10px;
  border: solid $brand-charcoal-blue !important;
