}
.md-user-summary__stats-row .ub-boards-page__badge {
  font-size: 14px;
}
.md-user-summary__stats-row .ub-boards-page__stat-link {
  font-size: 14px;
  overflow-wrap: break-word;
  word-break: break-word;
}
.md-user-summary__sub-link .ub-boards-page__stat-link {
  font-size: 14px;
}
.md-user-summary__stats-row .ub-boards-page__stat-none {
  font-size: inherit;
}
.md-user-summary__stats-row .md-user-summary__action-btn {
  font-size: 1.41rem;
}
.md-user-summary .md-card {
  padding: 18px 20px;
  border-radius: var(--md-r-lg);
  background: rgba(255, 255, 255, 0.72);
  border: 1px solid var(--md-line);
  box-shadow: var(--md-shadow-2);
}
.md-user-summary .md-card__title {
  margin: 0 0 4px;
  font-size: 14px;
  font-weight: 750;
  letter-spacing: 0.02em;
