/* Boards card: same height as left column (top of speak to bottom of extras), shortened by 2rem */
.md-card--boards {
  align-self: stretch !important;

  height: 100% !important;

  /* Always tall enough to show the board preview row in full —
     stops the card from collapsing when the surrounding column
     (Extras / My Organizations stack) is shorter than the boards
     content. 362 → 450 → 425 → 415 → 400 — keeps the mini-boards
     row + CTA visible without overshooting the adjacent column. */
  min-height: 400px;

  padding-right: calc(18px + 0.25rem) !important;

  display: flex !important;

  flex-direction: column !important;

  padding-bottom: 18px; /* same as extras card */
}
/* Elegant separator under the Boards header: a thin brand-denim line that fades to
   transparent at both ends, with a soft glow for presence. */
.md-card--boards__divider {
  height: 1px;
  margin: 6px 0 16px;
  border-radius: 1px;
  background: linear-gradient(90deg,
    transparent 0%,
    rgba($brand-dusty-denim, 0.30) 12%,
    rgba($brand-dusty-denim, 0.60) 50%,
    rgba($brand-dusty-denim, 0.30) 88%,
    transparent 100%);
  box-shadow: 0 1px 3px rgba($brand-dusty-denim, 0.15);
}
/* The Boards card uses its own boards__divider below the header, so drop the
   generic card-head bottom hairline to avoid a double line. */
.md-card--boards .md-card__head {
  border-bottom: none !important;
  padding-bottom: 0 !important;
  margin-bottom: 0 !important;
}
.md-card__empty {
  flex: 1 1 0 !important;

  display: flex !important;

  flex-direction: column !important;

  align-items: center !important;

  justify-content: center !important;

  text-align: center !important;

  padding: 3.5rem 1.5rem !important;

  gap: 1rem !important;

}
.md-card__empty-icon {
  width: 73px !important;

  height: 73px !important;

  border-radius: 20px !important;

  display: grid !important;

  place-items: center !important;

  background: rgba($brand-charcoal-blue, 0.05) !important;

  border: 1px solid rgba($brand-charcoal-blue, 0.07) !important;

  margin-bottom: 0.5rem !important;

}
.md-card__empty-text {
  font-size: 1.69rem !important;

  color: rgba($brand-charcoal-blue, 0.45) !important;

  margin: 0 !important;

  font-weight: 400 !important;

}
.md-card__empty .md-btn {
  margin-top: 0.75rem !important;

}
/* Loading state for cards (boards, reports, etc.) */
.md-card__loading {
  display: flex !important;
  flex-direction: column !important;
  align-items: center !important;
  justify-content: center !important;
  padding: 2.5rem 1rem !important;
  gap: 14px !important;
}
.md-card__loading-text {
  font-size: 15px !important;
  color: rgba($brand-charcoal-blue, 0.55) !important;
  margin: 0 !important;
  font-weight: 500 !important;
  letter-spacing: 0.01em !important;
}
.md-spinner svg {
  animation: md-spin 0.8s linear infinite !important;
}
@keyframes md-spin {
  from { transform: rotate(0deg); }
  to { transform: rotate(360deg); }
}
.md-card__loading--reports {
  padding: 4rem 1rem !important;
}
.md-card--boards .md-strip {
  flex: 1 1 0 !important;

  /* `max-content` (not 0) so the strip never shrinks below its
     tallest tile's natural height. The strip has `overflow-x:
     auto` (~line 48047), which per CSS spec makes `overflow-y`
     auto/clip too — so when a tile's label wraps to more lines
     than the strip's flex-allocated height accommodates, the
     bottom of the tile gets clipped. Letting min-height track
     content size means the strip grows to fit, all tiles match
     (default flex `align-items: stretch`), and the parent
     boards card grows with it (the card already has
     `height: 100%` and the dashboard grid row is auto-sized,
     so the cascade Just Works). */
  min-height: max-content !important;

}
.md-card--boards .md-btn--wide {
  margin-top: auto !important;

}

.md-card {
  position: relative !important;

  border-radius: var(--md-r-lg) !important;

  background: var(--md-surface) !important;

  border: 1px solid var(--md-line) !important;

  box-shadow: none !important;

  overflow: hidden !important;

  padding: 18px !important;

  min-width: 0 !important;

}
/* Modern dashboard: subtle vertical gradient on cards with grounded bottom */
.md-grid .md-card {
  background: linear-gradient(180deg, rgba(255, 255, 255, 0.97), rgba(240, 242, 245, 0.95)) !important;

  border-bottom: 2px solid rgba($la-navy, 0.08) !important;

}

.md-card__head {
  display: flex !important;

  align-items: center !important;

  gap: 14px !important;

  padding-bottom: 12px !important;

  border-bottom: 1px solid rgba($la-navy, 0.08) !important;

  margin-bottom: 4px !important;

}

.md-card__head--between {
  display: flex !important;

  align-items: center !important;

  justify-content: space-between !important;

  gap: 12px !important;

}

/* Boards card: pin the New Board button to the true horizontal center of
   the card head, independent of the right-hand count widget's width.
   Without this, justify-content: space-between makes the button drift left
   as the boardCount text grows from "0" to "1436", etc. The 1fr | auto | 1fr
   grid keeps the center cell anchored to the card's midpoint. */
/* Boards-card head: title/sub on the left, the New Board button
   right-aligned in the slot the (now-removed) board-count stat used to
   occupy. A 2-column `1fr auto` grid at every width — the button pins to
   the right edge via `justify-self: end`. */
.md-card--boards .md-card__head--between {
  display: grid !important;
  grid-template-columns: 1fr auto;
  align-items: center !important;
  gap: 12px !important;
}
.md-card--boards .md-card__head--between > .md-card__left {
  justify-self: start;
  min-width: 0;
}
.md-card--boards .md-card__head--between > .md-btn {
  justify-self: end;
  font-size: 16px !important;
}
/* ≤640px: collapse the 1fr|auto header grid to a single column so the
   "Create a Board" button wraps onto its own row below the title (left-aligned
   under it) instead of being squeezed beside it. Adjacent to the base rule
   above; same 0,2,0 specificity wins by source order at this width. (Focused
   View keeps its own 3-column header rule, defined later at higher specificity.) */
@media (max-width: 640px) {
  .md-card--boards .md-card__head--between {
    grid-template-columns: 1fr;
  }
  .md-card--boards .md-card__head--between > .md-btn {
    justify-self: start;
  }
}

/* `.md-card__title` is now applied to <h3> elements (WCAG 1.3.1 — Heading hierarchy).
   Reset browser h3 defaults so the visual is identical to the prior <div> usage. */
.md-card__title { font-weight: 900; font-size: 18px; letter-spacing: -0.2px; margin: 0; line-height: 1.35; color: inherit; } /* line-height bumped to 1.35 for WCAG 1.4.12 readability */

/* Getting Started card header — 20% larger on small screens (≤820px) so it reads
   prominently on the authenticated home page when the dashboard is condensed.
   !important because a later media query override may be winning otherwise. */
@media (max-width: 820px) {
  .md-card--getting-started .md-card__title {
    font-size: 1.5rem !important;
  }
}
.md-card__sub { color: #3A506E; margin-top: 4px; font-weight: 500; font-size: 14px; }

.md-muted { color: var(--md-muted); }

.md-link {
  padding: 8px 12px !important;

  border-radius: 999px !important;

  border: 1px solid var(--md-line) !important;

  background: rgba(255, 255, 255, 0.65) !important;

  color: rgba($brand-blue-black, 0.70) !important;

  font-weight: 750 !important;

}
.md-link:active { transform: scale(var(--md-tap)); }

/* `.md-link-btn` — used by <button> elements that need to LOOK like inline
   links but provide proper button semantics. Added 2026-04-11 per WCAG audit
   when converting <a href="#" {{action ...}}> patterns to real buttons. */
.md-link-btn {
  appearance: none;
  background: none;
  border: none;
  padding: 0;
  margin: 0;
  font: inherit;
  color: inherit;
  text-decoration: underline;
  cursor: pointer;
}
.md-link-btn:hover { text-decoration: none; }

/* `.md-link-btn-pill` — used inside Bootstrap `<ul class="nav nav-pills">`
   structures where the legacy markup expected `<li><a>` (which Bootstrap
   styles into a pill). Resets button defaults so the parent Bootstrap pill
   styles still apply. */
.nav-pills > li > .md-link-btn-pill {
  appearance: none;
  background: none;
  border: none;
  padding: 10px 15px;
  margin: 0;
  font: inherit;
  color: inherit;
  text-decoration: none;
  cursor: pointer;
  display: block;
  width: 100%;
  text-align: left;
}

/* --- Getting Started Card (home only, when checklist incomplete) --- */
.md-grid--dashboard .md-card--getting-started,
.md-grid--with-getting-started .md-card--getting-started {
  grid-area: getting_started !important;

  position: relative !important;

  display: flex !important;

  margin-top: 1rem !important;

  border-radius: var(--md-r-lg) !important;

  -webkit-border-radius: var(--md-r-lg) !important;

  overflow: hidden !important;

  box-shadow: none !important;

  flex-direction: column !important;

  align-items: stretch !important;

  padding-top: 35px !important;

  padding-bottom: 35px !important;

}
/* Welcome notice ("Watch for an email from us...") shown above
   the boards content while model.pending. Uses the brand verdigris
   palette (replaces the old Bootstrap .alert-success green) with
