  svg { width: 32px; height: 32px; stroke: currentColor; }
}

.ub-boards-page__empty-title {
  margin: 0;
  font-family: 'Lexend', 'Nunito Sans', system-ui, sans-serif;
  font-size: 20px;
  font-weight: $aac-font-weight-bold;
  color: var(--md-ink, $brand-blue-black);
  letter-spacing: -0.01em;
}

.ub-boards-page__empty-subtitle {
  margin: 0;
  max-width: 44ch;
  font-size: 14px;
  line-height: 1.55;
  color: var(--md-muted, $la-navy);
}

