  color: $la-navy !important;

  border-color: rgba($brand-dusty-denim, 0.22) !important;

  border-radius: 999px !important;
  /* NOTE: `!important` may appear only ONCE, at the end of the whole
     box-shadow declaration — repeating it per comma layer invalidates the
     entire value (renders flat). */
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.7),
    inset 0 -1px 0 rgba($brand-dusty-denim, 0.18),
    0 1px 2px rgba($la-navy, 0.08),
    0 6px 16px rgba($brand-dusty-denim, 0.20) !important;
