/* Hover effect for "I'm Done with this Checklist" button */
.md-getting-started-modal__actions .md-btn--primary.md-getting-started-modal__btn {
  transition: background 0.2s ease, border-color 0.2s ease, transform 0.2s ease-out, box-shadow 0.2s ease;
}
.md-getting-started-modal__actions .md-btn--primary.md-getting-started-modal__btn:hover {
  background: linear-gradient(135deg, rgba(44, 183, 176, 0.28), rgba(91, 141, 239, 0.24));
  border-color: rgba(44, 183, 176, 0.35);
  transform: translateY(-2px);
  box-shadow: 0 4px 14px rgba(44, 183, 176, 0.25), 0 2px 6px rgba($brand-blue-black, 0.08);
}
.md-getting-started-modal__actions .md-btn--primary.md-getting-started-modal__btn:active {
  transform: translateY(0);
  box-shadow: 0 2px 6px rgba(44, 183, 176, 0.15);
}

.md-morepill {
  margin-top: 4px;
  padding: 12px 14px;
  border-radius: 999px;
  border: 1px solid var(--md-line);
  background: rgba(255, 255, 255, 0.70);
  font-weight: 850;
  color: $la-navy;
}
.md-morepill:active { transform: scale(var(--md-tap)); }

/* --- Reports, Extras & Org --- */
.md-card--reports { grid-area: reports; }
.md-card--extras  { grid-area: extras; align-self: stretch; }
.md-card--extras .md-card__extras-wave {
  position: absolute !important;

  inset: 0 !important;

  width: 100% !important;

  height: 100% !important;

  background-image: url('/images/extras-wave.png') !important;
  background-size: cover !important;
  /* Move the wave image DOWN ~1rem. The 300×200 source is scaled up by
     `cover` on this much wider/shorter button, so there's plenty of vertical
     overflow and the box always stays fully covered (top + right included —
     no gap). A background-position-y BELOW 50% shifts the image downward;
     ~43% ≈ 1rem of downward shift at the dashboard card width. (`center
     bottom` did the opposite — it revealed the lower part of the image,
     pulling content up.) Lower this % to drop the image further. */
  background-position: center 43% !important;

  pointer-events: none !important;

  z-index: 0 !important;

}
/* Lift the head above the absolutely-positioned wave bg + the as-button
   gloss `::before`. */
.md-card--extras .md-card__head,
.md-card--badge-action .md-card__head {
  position: relative !important;

  z-index: 1 !important;

  /* No divider line under the head now that the card IS the button
     (matches the speak/caseload as-button heads). */
  border-bottom: none !important;

  /* Drop the base .md-card__head 12px bottom padding — the card IS the
     button, so the head doesn't need the separation gap. */
  padding-bottom: 0 !important;

}

.md-miniStats {
  margin-top: 12px !important;

  display: flex !important;

  gap: 10px !important;

}
.md-miniStat {
  flex: 1 !important;

  padding: 12px !important;

  border-radius: 18px !important;

  border: 1px solid var(--md-line) !important;

  background: rgba(255, 255, 255, 0.65) !important;

}
.md-miniStat__num { font-weight: 950; font-size: 22px; }
.md-miniStat__label { margin-top: 4px; color: var(--md-muted); font-weight: 650; }

.md-spark {
  margin-top: 12px !important;

  height: 62px !important;

  border-radius: 18px !important;

  border: 1px solid rgba($brand-blue-black, 0.08) !important;

  background:
    linear-gradient(180deg, rgba(44,183,176,0.12), transparent),
    radial-gradient(circle at 20% 70%, rgba(91,141,239,0.18), transparent 60%),
    rgba($brand-blue-black, 0.04);
}

/* `.md-extrasIcon` was removed when the Extras icon was promoted to
   a direct child of `.md-card__head` (matching every other dashboard
   card) — see `.md-card__icon--extras` (~l. 44323) for the
   replacement modifier. */

/* ---------- Bottom Focus Bar ---------- */
.md-focusbar {
  position: fixed;
  left: 12px;
  right: 12px;
  bottom: 12px;
  z-index: 40;
  max-width: 920px;
  margin: 0 auto;
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 8px;
  padding: 10px;
  border-radius: 26px;
  background: linear-gradient(180deg, rgba(255, 255, 255, 0.95), rgba(248, 250, 252, 0.95));
  border: 1px solid var(--md-line);
  box-shadow: var(--md-shadow);
  backdrop-filter: blur(18px);
}

.md-focusbar__item {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 10px;
  padding: 12px 10px;
  border-radius: 18px;
  color: rgba($brand-blue-black, 0.72);
  font-weight: 850;
}
.md-focusbar__item.is-active {
  background: rgba(44, 183, 176, 0.14);
  border: 1px solid rgba(44, 183, 176, 0.18);
  color: rgba($brand-blue-black, 0.92);
}
.md-focusbar__item:active { transform: scale(var(--md-tap)); }
.md-focusbar__icon { opacity: 0.9; }
.md-focusbar__text { font-size: 1rem; } /* 16px */

/* ---------- Search Overlay ---------- */
.md-searchOverlay {
  position: fixed !important;

  inset: 0 !important;

  z-index: 80 !important;

  background: rgba(238, 241, 246, 0.92) !important;

  backdrop-filter: blur(16px) !important;

  padding: 16px !important;

  display: flex !important;

  flex-direction: column !important;

}

.md-searchOverlay__top {
  display: flex !important;

  gap: 10px !important;

  align-items: center !important;

}

.md-searchOverlay__input {
  flex: 1 !important;

  padding: 12px 14px !important;

  border-radius: 18px !important;

  border: 1px solid var(--md-line) !important;

  background: rgba(255, 255, 255, 0.86) !important;

  box-shadow: var(--md-shadow-2) !important;

  outline: none !important;

}

.md-searchOverlay__input:focus-visible {
  @include focus-ring;
}

.md-searchOverlay__body {
  margin-top: 14px !important;

  overflow: auto !important;

  padding-bottom: 100px !important;

}

.md-row {
  width: 100% !important;

  text-align: left !important;

  padding: 14px 12px !important;

  border-radius: 18px !important;

  border: 1px solid var(--md-line) !important;

  background: rgba(255, 255, 255, 0.70) !important;

  box-shadow: var(--md-shadow-2) !important;

  margin-top: 10px !important;

}
.md-row:active { transform: scale(var(--md-tap)); }

/* Prevent black flash on modern-dashboard load: paint content area with dashboard bg as soon as route is active */
#within_ember #content.modern-dashboard {
  background: var(--md-bg);
}
#within_ember #content:has(.md-shell) {
  background: var(--md-bg);
}
#within_ember #content.stats-page {
  background: var(--md-bg);
}
/* Dashboard-style pages (extras/home/boards/stats): shared top padding so all four tabs align under the fixed header */
#within_ember #content.modern-dashboard,
#within_ember #content.home-page,
#within_ember #content.boards-page,
#within_ember #content.stats-page {
  padding-top: calc(var(--topbar-height) + 1rem) !important;
}
/* At ≤1024px the four dashboard pages need extra clearance below the fixed
   navbar — placed immediately after the base rule so source-order wins the
   !important tie (same specificity as the rule above). */
@media (max-width: 1024px) {
  #within_ember #content.home-page,
  #within_ember #content.boards-page,
  #within_ember #content.stats-page,
  #within_ember #content.extras-page,
  #within_ember #content.modern-dashboard {
    padding-top: 52px !important;
  }
}
/* Stats page: allow scrolling when in page-footer layout (#content is not .index so it needs explicit scroll) */
#within_ember:has(.page-footer) #content.stats-page.with_user {
  flex: 1 1 auto;
  min-height: calc(100vh - var(--topbar-height) - var(--bottombar-height));
  overflow-x: hidden;
  overflow-y: auto;
  display: flex;
  flex-direction: column;
  box-sizing: border-box;
}
#within_ember:has(.page-footer) #content.stats-page.with_user > .ember-view {
  flex: 1 1 auto;
  min-height: 0;
  display: flex;
  flex-direction: column;
}
/* Search page: #content is scroll container when not on index (fixed header + footer layout); bg matches .md-shell / authenticated-view */
#within_ember.bento-page-with-footer #content:has(.search-page),
#within_ember:has(.page-footer) #content:has(.search-page) {
  flex: 1 1 auto;
  min-height: calc(100vh - var(--topbar-height) - var(--bottombar-height));
  overflow-x: hidden;
  overflow-y: auto;
  display: flex;
  flex-direction: column;
  box-sizing: border-box;
  padding-top: calc(var(--topbar-height) + 3rem);
  padding-bottom: var(--bottombar-height);
  /* Match authenticated home (#content.index.with_user): blue → gold → green top-down gradient */
  background: linear-gradient(to bottom,
    rgba(126, 184, 224, 0.25) 0%,
    rgba(212, 168, 75, 0.12) 50%,
    rgba(61, 122, 92, 0.14) 100%);
  color: var(--md-ink);
}
#within_ember:has(.page-footer) #content:has(.search-page) > .ember-view {
  flex: 1 1 auto;
  min-height: 0;
  display: flex;
  flex-direction: column;
}

/* ---------- Stats page (user.stats): same look as modern-dashboard and reports ---------- */
.md-stats-page {
  min-height: 100vh;
  background:
    radial-gradient(1200px 600px at 20% 20%, rgba(44, 183, 176, 0.12), transparent 55%),
    radial-gradient(1200px 600px at 80% 15%, rgba(240, 106, 91, 0.10), transparent 60%),
    radial-gradient(1000px 700px at 60% 85%, rgba(91, 141, 239, 0.12), transparent 60%),
    var(--md-bg);
  color: var(--md-ink);
}
/* Parts of Speech chart: stretch to full workspace width */
.md-stats-page .col-sm-8:has([id^="sankey-parts-of-speech"]),
.md-stats-page .col-sm-8:has([id^="sankey-word-pairs"]) {
  width: 100% !important;
  max-width: 100% !important;
  flex: 0 0 100% !important;
}
.md-stats-main {
  max-width: 1120px;
  /* No margin or padding — the report's own cards carry their spacing. `auto` is
     kept on the horizontal axis ONLY so the 1120px column stays centred in the
     workspace; it contributes no fixed inset. */
  margin: 0 auto;
  padding: 0;
}

/* Stats hero: about-page style — transparent container, eyebrow badge, title, separator */
.md-stats-hero-card {
  width: auto;
  max-width: fit-content;
  margin-left: auto;
  margin-right: auto;
  /* Top padding cut 2.5rem → 0.25rem: the hero title inside is
     display:none on the reports view (the page title is the md-hero
     above), so this card was an empty 40px spacer. Collapsing it removes
     the biggest dead gap before the report content. */
  padding: 0.25rem 2rem 0;
  text-align: center;
  background: transparent;
  border: none;
  box-shadow: none;
}
.md-stats-hero__eyebrow {
  display: inline-block;
  margin-bottom: 12px;
  padding: 6px 14px;
  border-radius: 999px;
  font-size: 14px;
  font-weight: 650;
  letter-spacing: 0.02em;
  color: $brand-stormy-teal;
  background: rgba($brand-teal, 0.1);
  border: 1px solid rgba($brand-teal, 0.25);
}
.md-stats-hero__head {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: center;
  gap: 14px;
}
.md-stats-hero__title {
  margin: 0;
  font-size: clamp(21px, 2.4vw, 34.5px);
  font-weight: 750;
  letter-spacing: -0.02em;
  color: $indigo;
  line-height: 1.2;
}
.md-stats-page .md-stats-hero__title {
  margin-bottom: 24px;
}
.md-stats-hero__title em {
  color: $brand-smart-blue;
  font-style: italic;
  font-weight: 800;
}
/* Reports page: inherits the project-wide thin-line divider from the base rule;
   only the bottom-margin tweak remains here. */
.md-stats-page .la-about-hero-separator {
  margin-bottom: 24px;
}
@media (max-width: 768px) {
  .md-stats-hero-card {
    padding: 1.75rem 1.25rem 0 !important;

  }
  .md-stats-hero__title {
    font-size: 19.5px !important;

  }
}
/* Notice states (logging disabled / unauthorized / premium required) carry a
   `.md-stats-text` and no data grid — center the message + action both
   vertically and horizontally in the panel. `:has(.md-stats-text)` targets
   only these states (the data view has no .md-stats-text). */
.md-stats-main:has(.md-stats-text) {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  text-align: center;
  min-height: 48vh;
  /* Even top/bottom padding so justify-content:center is truly centered — the
     base bottom padding reserves ~83px for the bottom navbar (uneven vs the
     8px top), which pushed the content up. The centered notice is short and
     never reaches the bottom, so the reservation isn't needed here. */
  padding-top: 32px !important;
  padding-bottom: 32px !important;
}
.md-stats-text {
  margin: 0 auto 16px;
  color: var(--md-muted);
  max-width: 56ch;
  text-align: center;
}
.md-stats-actions {
  margin-top: 18px;
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
}
/* Dashboard section headers — light "stopping points" that split the report
   into Report Summary / Communication Usage / Vocabulary Analysis (single-
   period view). A small uppercase label + a hairline rule filling the rest
   of the row, so the page reads as distinct sections, not one long panel. */
.md-stats-section-head {
  display: flex;
  align-items: center;
  gap: 16px;
  margin: 32px 0 14px;
}
.md-stats-section-head--first {
  margin-top: 6px;
}
.md-stats-section-head__label {
  margin: 0;
  flex-shrink: 0;
  font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
  /* !important to beat the global `h2 { font-size: 25px !important }` (~l.2589)
     — these section labels are <h2> headings. */
  font-size: clamp(18px, 2.2vw, 22px) !important;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: rgba($la-navy, 0.6);
}
.md-stats-section-head__rule {
  flex: 1 1 auto;
  height: 1px;
  background: linear-gradient(90deg, rgba($la-navy, 0.16), rgba($la-navy, 0.02));
}
/* Tiny scanability icon before a metric-card label (Sessions/Words/etc.). */
.md-stat-icon {
  display: inline-flex;
  align-items: center;
  vertical-align: -2px;
  margin-right: 6px;
  color: rgba($la-navy, 0.5);
}
/* Summary panels → md-miniStat style (stats page). Stronger surface +
   shadow than the washed-out 0.65 white so the metric cards read as
   solid, elevated tiles (matches the home/board-detail card language). */
.md-stats-page .panel.panel-default.summary,
.md-eval-report .panel.panel-default.summary {
  border-radius: 18px;
  border: 1px solid rgba($la-navy, 0.08);
  background: rgba(255, 255, 255, 0.92);
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.7),
    0 2px 6px rgba($la-navy, 0.07),
    0 8px 20px rgba($la-navy, 0.08);
}
/* The metric VALUE — large, bold, navy — so it dominates the small muted
   label above it (the hierarchy the cards were missing). */
.md-stats-page .panel.panel-default.summary .panel-body {
  font-size: clamp(30px, 3.4vw, 42px);
  font-weight: 800;
  letter-spacing: -0.02em;
  color: $la-navy;
  padding: 14px 10px 16px;
}
.md-stats-page .panel.panel-default.summary .panel-heading,
.md-eval-report .panel.panel-default.summary .panel-heading {
  background: transparent;
  border-bottom: 1px solid rgba($brand-blue-black, 0.1);
  color: var(--md-muted);
  font-weight: 650;
  font-size: 14px;
  padding: 12px 14px 10px;
  border-radius: 18px 18px 0 0;
  box-shadow: 0 1px 0 0 rgba(255, 255, 255, 0.6) inset, 0 2px 4px -1px rgba($brand-blue-black, 0.06);
}
/* Eval results report (user/log.hbs): reuse the stats-page metric-card language
   (rules above) + light layout polish so the report matches the reports page. */
.md-eval-report {
  margin-top: 6px;
}
.md-eval-report .row {
  margin-bottom: 8px;
}
/* Values here are text (dates, "0 hits, 0%", "Touch", "N/A") not short numbers,
   so the stats-page big-number size overflows/truncates. Use a readable size
   that wraps to the full value instead of clipping. */
.md-eval-report .panel.panel-default.summary .panel-body {
  font-size: clamp(16px, 1.5vw, 22px);
  font-weight: 700;
  letter-spacing: -0.01em;
  line-height: 1.25;
  color: $la-navy;
  padding: 12px 12px 14px;
  white-space: normal;
  overflow: visible;
  text-overflow: clip;
}
.md-eval-report h3 {
  color: $la-navy;
  font-weight: 700;
  letter-spacing: -0.01em;
  margin-top: 26px;
  margin-bottom: 12px;
}
/* Same panel heading dimension + tint for comparison/trends/other pages with summary panels */
.panel.panel-default.summary .panel-heading {
  border-bottom: 1px solid rgba($brand-blue-black, 0.1);
  color: var(--md-muted);
  font-weight: 650;
  font-size: 14px;
  padding: 12px 14px 10px;
  border-radius: 18px 18px 0 0;
  box-shadow: 0 1px 0 0 rgba(255, 255, 255, 0.6) inset, 0 2px 4px -1px rgba($brand-blue-black, 0.06);
  background: linear-gradient(180deg, rgba($brand-blue-black, 0.06) 0%, rgba($brand-blue-black, 0.02) 100%);
}
/* Summary card header backgrounds: one per row type, slight tint + dimension.
   Visual hierarchy — the PRIMARY totals (row 1) read heavier than the rate
   metrics (row 2): more-saturated header + deeper shadow + larger value;
   row 2 is deliberately quieter. */
/* Row 1 (primary): deeper shadow + slightly larger value. */
/* Row 2 (rates): quieter surface, flatter shadow, smaller muted value. */
/* Compare view row tints: need .md-stats-page so they override base .panel-heading { background: transparent } */
.md-stats-page .md-stats-compare-group .md-stats-compare-group__row:nth-child(1) .panel-heading {
  background: linear-gradient(180deg, rgba(44, 183, 176, 0.18) 0%, rgba(44, 183, 176, 0.1) 100%);
}
.md-stats-page .md-stats-compare-group .md-stats-compare-group__row:nth-child(2) .panel-heading {
  background: linear-gradient(180deg, rgba(91, 141, 239, 0.18) 0%, rgba(91, 141, 239, 0.1) 100%);
}
.md-stats-page .md-stats-compare-group .md-stats-compare-group__row:nth-child(3) .panel-heading {
  background: linear-gradient(180deg, rgba(212, 168, 75, 0.18) 0%, rgba(212, 168, 75, 0.1) 100%);
}
.md-stats-page .md-stats-compare-group .md-stats-compare-group__row:nth-child(4) .panel-heading {
  background: linear-gradient(180deg, rgba(160, 120, 200, 0.18) 0%, rgba(160, 120, 200, 0.1) 100%);
}
/* split=1 (compare view): same panel heading format as single-period stats page */
.md-stats-page .md-stats-compare-group .panel.panel-default.summary .panel-heading {
  border-bottom: 1px solid rgba($brand-blue-black, 0.1);
  color: var(--md-muted);
  font-weight: 650;
  font-size: 14px;
  padding: 12px 14px 10px;
  border-radius: 18px 18px 0 0;
  box-shadow: 0 1px 0 0 rgba(255, 255, 255, 0.6) inset, 0 2px 4px -1px rgba($brand-blue-black, 0.06);
}
.md-stats-page .panel.panel-default.summary .panel-body {
  padding: 12px;
  font-weight: 950;
  font-size: 22px;
  color: var(--md-ink);
}
/* Compare mode: left and right groups wrapping all four stat rows */
.md-stats-compare-group {
  border-radius: 14px;
  border: 1px solid rgba($brand-blue-black, 0.08);
  background: rgba(255, 255, 255, 0.5);
  padding: 12px 10px 14px;
  box-sizing: border-box;
}
.md-stats-compare-group__inner {
  display: flex;
  flex-direction: column;
  gap: 10px;
}
.md-stats-compare-group__row {
  margin-left: -4px;
  margin-right: -4px;
  display: flex;
  flex-wrap: wrap;
}
.md-stats-compare-group__row > [class*='col-'] {
  padding-left: 4px;
  padding-right: 4px;
  margin-bottom: 0;
}

/* Speech / modeling toggle: pill segmented control with sliding pill animation */
.md-stats-page .md-stats-modeling-toggle {
  position: relative;
  display: inline-flex;
  align-items: stretch;
  height: 26px;
  border-radius: 999px;
  border: 1px solid rgba($brand-blue-black, 0.1);
  background: rgba(255, 255, 255, 0.5);
  padding: 2px;
  margin-bottom: 8px;
  float: right;
  margin-top: 0;
}
.md-stats-page .md-stats-modeling-toggle__slider {
  position: absolute;
  left: 2px;
  top: 2px;
  width: calc(50% - 2px);
  height: calc(100% - 4px);
  border-radius: 999px;
  background: linear-gradient(135deg, rgba(44, 183, 176, 0.2) 0%, rgba(91, 141, 239, 0.12) 100%);
  border: 1px solid rgba(44, 183, 176, 0.3);
  transition: transform 0.25s ease;
  z-index: 0;
  pointer-events: none;
}
.md-stats-page .md-stats-modeling-toggle--modeling .md-stats-modeling-toggle__slider {
  transform: translateX(100%);
}
.md-stats-page .md-stats-modeling-toggle__option {
  flex: 1 1 0;
  min-width: 0;
  padding: 0 14px;
  font-size: 14px;
  font-weight: 700;
  line-height: 1;
  border: none;
  border-radius: 999px;
  background: transparent;
  color: var(--md-muted);
  cursor: pointer;
  transition: color 0.2s ease;
  font-family: inherit;
  position: relative;
  z-index: 1;
}
.md-stats-page .md-stats-modeling-toggle__option:hover {
  color: var(--md-ink);
}
.md-stats-page .md-stats-modeling-toggle__option--active {
  color: var(--md-ink);
}
.md-stats-page .md-stats-modeling-toggle__option:focus-visible {
  @include focus-ring;
}

/* Word Usage chart: modern card container + chart styling */
.md-stats-page .md-stats-chart--word-usage {
  border-radius: 14px;
  border: 1px solid rgba($brand-blue-black, 0.08);
  background: rgba(255, 255, 255, 0.6);
  padding: 12px;
  margin-top: 4px;
  box-shadow: 0 1px 3px rgba($brand-blue-black, 0.04);
}
.md-stats-page .md-stats-chart--word-usage .daily_stats {
  border-radius: 8px;
  min-height: 280px;
  width: 100%;
}
/* Force Google Chart wrapper to fill container width (overrides inline width: 408px) */
.md-stats-page .md-stats-chart--word-usage .daily_stats > div {
  width: 100% !important;
  max-width: 100%;
  height: 320px !important;
  box-sizing: border-box;
}
.md-stats-page .md-stats-chart--word-usage .daily_stats svg {
  width: 100% !important;
  height: 100% !important;
}

/* Stats page rows and filter form */
.md-stats-page .row {
  margin-left: -8px;
  margin-right: -8px;
}
.md-stats-page .row [class*="col-"] {
  padding-left: 8px;
  padding-right: 8px;
  margin-bottom: 12px;
}
.md-stats-page .form-inline .form-group {
