/* Stats period select: custom dropdown with same content style as identity .dropdown-menu */
.md-stats-period-select {
  position: relative;
  display: inline-block;
}
.md-stats-period-select__trigger {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  /* Compact: 128px min (was 160) and tighter padding. Height is set to the 44px
     target minimum by the period-bar rule above. */
  /* No intrinsic floor: the trigger fills whatever width its wrap is given
     (`.md-stats-filter__period-wrap` carries the 92px floor in the period row),
     so it can never overflow its own box and land on the label beside it. */
  min-width: 0;
  width: 100%;
  height: 26px;
  min-height: 26px;
  padding: 0 24px 0 10px;
  line-height: 1;
  border-radius: 999px;
  border: 1px solid rgba(0, 0, 0, 0.08);
  background-color: rgba(255, 255, 255, 0.65);
  font-size: 14px;
