    inset 0 1px 0 rgba(255, 255, 255, 0.85),
    inset 0 -1px 0 rgba($la-navy, 0.06),
    0 1px 2px rgba($la-navy, 0.05),
    0 4px 10px rgba($la-navy, 0.08),
    0 12px 28px rgba($la-navy, 0.10) !important;

  overflow: hidden !important;

  /* Native <button> resets so the whole card reads as the card (now that the
     card itself is the action button, with no separate CTA inside). */
