  }

  // === Modern nav header (non-speak) ===
  #inner_header:has(#nav_header) {
    background: rgba(255, 255, 255, 0.88) !important;
    box-shadow: 0 2px 12px rgba($brand-blue-black, 0.09) !important;
    border-bottom: 1px solid rgba($brand-blue-black, 0.07) !important;
