.board-picker__selecting-home-msg {
  width: 92%;
  max-width: 720px;
  margin: 0 auto 8px;
  padding: 10px 14px;
  background: rgba($brand-verdigris-aa, 0.14);
  border: 1px solid rgba($brand-verdigris-aa, 0.40);
  border-radius: 10px;
  color: $brand-verdigris-aa;
