/* Placement mode */
.md-board-detail-placement-cursor {
  position: fixed;
  z-index: 10000;
  pointer-events: none;
  width: 40px;
  height: 40px;
  display: flex;
  align-items: center;
  justify-content: center;
  background: rgba(255, 255, 255, 0.92);
  border: 2px solid $brand-verdigris;
  border-radius: 8px;
  box-shadow: 0 3px 12px rgba($brand-verdigris, 0.25);
  color: $brand-verdigris;
  animation: md-placement-pulse 1.2s ease-in-out infinite;
}
@keyframes md-placement-pulse {
  0%, 100% { box-shadow: 0 3px 12px rgba($brand-verdigris, 0.25); }
  50% { box-shadow: 0 3px 18px rgba($brand-verdigris, 0.40); }
}
.md-board-detail-grid--placing {
