}
.md-board-detail-placement-banner__cancel {
  margin-left: auto;
  padding: 5px 14px;
  border: 1px solid rgba($la-navy, 0.15);
  border-radius: 6px;
  background: #fff;
  font-size: 15px;
  font-weight: 600;
  color: $brand-charcoal-dark;
  cursor: pointer;
