}

.md-board-detail-categories {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
}
.md-board-detail-category-btn {
  padding: 10px 20px;
  border-radius: 999px;
  border: 1px solid rgba($la-navy, 0.08);
  background: rgba(255, 255, 255, 0.6);
  font-size: 16px;
  font-weight: 600;
  color: rgba(75, 78, 92, 0.80);
  cursor: pointer;
  transition: all 0.15s ease;
}
.md-board-detail-category-btn:hover:not(.md-board-detail-category-btn--active) {
