}

// Nouns — Orange
.md-board-detail-symbol-card--noun,
.md-board-detail-symbol-card--nominative {
  background-color: var(--fitzgerald-noun-orange);
  .md-board-detail-symbol-card__label { color: var(--fitzgerald-noun-orange-text); }
}

// Social — Pink
.md-board-detail-symbol-card--social,
