}
.md-board-detail--dark .md-settings-select:focus {
  border-color: $brand-verdigris;
  box-shadow: 0 0 0 3px rgba($brand-verdigris, 0.3), 0 2px 6px rgba(0, 0, 0, 0.25);
}
.md-board-detail--dark .md-settings-select option {
