  }
  .md-board-detail-color-trigger {
    width: 22px;
    height: 22px;
    top: 4px;
    right: 4px;
    font-size: 15px;
  }
  .md-board-detail-toolbar {
    gap: 6px;
  }
  .md-board-detail-quick-toggle {
    padding: 6px 10px;
    font-size: 15px;
