}
.md-board-detail--dark .md-board-detail-sentence-nav .md-board-detail-collapse-btn--sentence-row {
  background: rgba($brand-blue-grey, 0.15) !important;
  border-color: rgba(255, 255, 255, 0.10) !important;
  color: rgba(255, 255, 255, 0.92) !important;
}
.md-board-detail--dark .md-board-detail-sentence-nav .md-board-detail-collapse-btn--sentence-row:hover {
  background: rgba($brand-blue-grey, 0.3) !important;
  color: #fff !important;
}
.md-board-detail--dark .md-board-detail-actions-toggle {
