}
.md-board-detail--dark .md-board-detail-actions-backdrop {
  background: transparent;
}
.md-board-detail--dark .md-board-detail-actions-menu {
  background: #1e2530;
  border: 1px solid rgba(255, 255, 255, 0.10);
  box-shadow: 0 12px 40px rgba(0, 0, 0, 0.50), 0 4px 12px rgba(0, 0, 0, 0.25);
}
.md-board-detail--dark .md-board-detail-actions-menu__item {
  color: #d1d5db;
}
.md-board-detail--dark .md-board-detail-actions-menu__item:hover {
  /* Neutral glass overlay on dark — translucent white, no teal. */
