}
#within_ember .md-board-detail-edit-toolbar__search-input:focus-visible {
  box-shadow: none !important;
  outline: none !important;
}
.md-board-detail--dark .md-board-detail-divider {
  border-top-color: rgba(255, 255, 255, 0.08);
}
.md-board-detail--dark .md-board-detail-options-btn {
  background: rgba(30, 37, 48, 0.85);
  border-color: rgba(255, 255, 255, 0.10);
  color: rgba(255, 255, 255, 0.65);
}
.md-board-detail--dark .md-board-detail-options-btn:hover {
  background: rgba(40, 50, 65, 0.90);
  color: #fff;
}
.md-board-detail--dark .md-board-detail-grid__empty {
  color: rgba(255, 255, 255, 0.35);
}
.md-board-detail--dark .md-board-detail-suggestion {
  background: rgba(30, 37, 48, 0.80);
  border-color: rgba(255, 255, 255, 0.10);
  color: #d1d5db;
}
.md-board-detail--dark .md-board-detail-suggestion:hover {
  background: rgba($brand-verdigris, 0.15);
  border-color: rgba($brand-verdigris, 0.30);
  color: #fff;
}
.md-board-detail--dark .md-board-detail-phrase-list__item {
  color: rgba(255, 255, 255, 0.75);
}
.md-board-detail--dark .md-board-detail-phrase-list__item:hover {
  background: rgba(255, 255, 255, 0.06);
  color: #fff;
}

/* ── Modern Modal Styles ──────────────────────────────── */
/* Reduce the default Bootstrap margin-top on modernized modals so they sit
   closer to the top of the viewport — the default 30px is too much. */
.modal-dialog:has(.md-modal-header) {
  margin-top: 15px;
}
.md-modal-header {
  border-bottom: 1px solid rgba($la-navy, 0.08);
  padding: 32px 24px;
  position: relative;
}
/* Button Settings header: the modal title + a live COPY of the button as it
   appears in speak mode (colour, symbol, label) — replaces the plain "- label"
   text so the user sees exactly which button they're editing. */
.md-bs-header__title-row {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 16px;
  flex-wrap: wrap;
}
.md-bs-header__title-row h3 {
  margin: 0;
}
/* Text-position preference (shared by the header + Color-tab mockups): label on top
   flips the flex column so the label sits ABOVE the symbol (DOM order is
   symbol-then-label = "text on bottom"); "text only" hides the symbol entirely (the
   template omits the <img>), matching how the board renders in speak mode. */
.md-bs-header__button.md-bs-preview--text-top {
  flex-direction: column-reverse;
}
.md-bs-header__button {
  display: inline-flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 4px;
  flex: 0 0 auto;
  /* Matches the ACTUAL board button's speak-mode size — didInsertElement measures a
     live board card and publishes --bs-preview-w / --bs-preview-h (60px fallback).
     CLAMPED: the measured value is a real board card, which on a 2x2 or 3x3 starter
     board is 300-500px — unclamped that renders a half-screen "preview" that pushes
     the modal title out of the header. The bounds keep it recognisable as a thumbnail
     at both extremes (tiny on a 24-column board, huge on a 2x2). */
  width: clamp(44px, var(--bs-preview-w, 60px), 120px);
  height: clamp(44px, var(--bs-preview-h, 60px), 120px);
  padding: 6px;
  border-radius: 12px;
  /* Colour comes from the inline style (button's fill + border); this sets the
     width/style + a neutral fallback so a colourless button still frames. */
  border: 2px solid #cbd3de;
  box-shadow: 0 1px 4px rgba($la-navy, 0.14);
  overflow: hidden;
  /* Size container so the symbol + label scale WITH the button (mirrors the board
     card's `container-type: size`), so a big button gets a big symbol/label. */
  container-type: size;
}
.md-bs-header__button-img {
  max-width: 78cqmin;
  max-height: 55cqmin;
  object-fit: contain;
}
.md-bs-header__button-label {
  font-size: clamp(11px, 15cqmin, 22px);
  font-weight: 600;
  color: #222222;
  line-height: 1.05;
  text-align: center;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  max-width: 100%;
}
.md-modal-header .close,
.md-modal-header .la-modal-close {
  position: absolute;
  top: 50%;
  transform: translateY(-50%);
  right: 16px;
  /* WCAG 2.5.5 AAA touch target. */
  width: 44px;
  height: 44px;
  min-width: 44px;
  min-height: 44px;
  display: flex;
  align-items: center;
  justify-content: center;
  border: 1px solid rgba($la-navy, 0.10);
  border-radius: 50%;
  background: rgba($la-navy, 0.04);
  color: $brand-slate-gray;
  font-size: 14px;
  font-weight: 300;
  cursor: pointer;
  transition: background 0.15s ease, color 0.15s ease, box-shadow 0.15s ease;
  line-height: 1;
  padding: 0;
  opacity: 1;
}
.md-modal-header .close:hover,
.md-modal-header .la-modal-close:hover {
  background: $brand-charcoal-blue;
  color: #fff;
  border-color: $brand-charcoal-blue;
  box-shadow: 0 2px 6px rgba($brand-charcoal-blue, 0.25);
}
.md-modal-title {
  font-size: 18px;
  font-weight: 700;
  color: $la-navy;
  margin: 0;
}
.md-modal-body {
  padding: 8px 24px 28px;
  text-align: center;
  font-size: 16px;
}
/* Speak Mode PIN input (pin-settings modal): sized for a 4-digit PIN and
   centered. The modal body is already text-align: center, so margin auto
   centers the fixed-width field; text-indent offsets the trailing
   letter-spacing so the digits stay visually centered. */
.md-pin-settings__input {
  width: 120px;
  max-width: 120px;
  /* Centering + top gap now handled by __input-wrap (which also holds the clear
     button); the input just fills its 120px slot. */
  margin: 0;
  text-align: center;
  letter-spacing: 0.3em;
  text-indent: 0.3em;
  font-weight: 600;
}
/* Holds the centered PIN input; the clear (✕) button floats to its right via
   absolute positioning so the input stays put whether or not the button shows
   (it only shows when there's a value), avoiding a left-shift as you type. */
.md-pin-settings__input-wrap {
  position: relative;
  width: fit-content;
  margin: 6px auto 0;
}
.md-pin-settings__clear {
  position: absolute;
  left: 100%;
  top: 50%;
  transform: translateY(-50%);
  margin-left: 8px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 5px;
  height: 34px;
  padding: 0 12px;
  white-space: nowrap;
  border: 1px solid rgba($la-navy, 0.15);
  border-radius: 8px;
  background: rgba($la-navy, 0.04);
  color: $la-navy;
  cursor: pointer;
  transition: background 0.14s ease, color 0.14s ease, border-color 0.14s ease;
}
.md-pin-settings__clear-label {
  /* AAC: keep the control label comfortably readable. */
  font-size: 14px;
  font-weight: 600;
  line-height: 1;
}
/* Sits below the PIN input row — give it breathing room from the field/button. */
.md-pin-settings__warning {
  margin-top: 14px;
}
.md-pin-settings__clear:hover {
  background: rgba(225, 82, 65, 0.14);
  border-color: rgba(225, 82, 65, 0.4);
  color: #c0392b;
}
.md-pin-settings__clear:focus-visible {
  outline: 2px solid $brand-verdigris-aa;
  outline-offset: 2px;
}
/* Modern checkbox cards (la-edit-board-checkbox) sit in a centered modal body —
   constrain + center each card, and keep its label text left-aligned. */
.md-pin-settings__checkbox {
  max-width: 360px;
  margin-left: auto;
  margin-right: auto;
  text-align: left;
}

/* Import from another platform modal — CoughDrop export bookmarklet + file upload */
.md-json-bundle-export {
  text-align: left;
  max-width: 34rem;
  margin: 0 auto 1.25rem;
}
.md-json-bundle-export__title {
  margin: 0 0 0.65rem;
  font-size: 1.15rem;
  font-weight: 700;
  color: $la-navy;
}
.md-json-bundle-export__lead {
  margin: 0 0 1rem;
  font-size: 1rem;
  line-height: 1.5;
  color: rgba($la-navy, 0.82);
}
.md-json-bundle-export__drag {
  margin: 0 0 1.35rem;
  padding: 1rem 1.1rem;
  border-radius: 12px;
  background: rgba($la-navy, 0.04);
  border: 1px solid rgba($la-navy, 0.1);
}
.md-json-bundle-export__drag-label {
  margin: 0 0 0.75rem;
  font-size: 1.05rem;
  font-weight: 600;
  line-height: 1.45;
  color: $la-navy;
}
.md-json-bundle-export__steps {
  margin: 0 0 0.85rem 1.15rem;
  padding: 0;
  font-size: 1rem;
  line-height: 1.6;
  color: rgba($la-navy, 0.9);
  li + li {
    margin-top: 0.65rem;
  }
}
.md-json-bundle-export__actions {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 0.65rem 1rem;
  margin-bottom: 0.5rem;
}
.md-json-bundle-export__bookmarklet {
  min-height: 2.75rem;
  padding: 0.55rem 1.1rem;
  font-size: 1rem;
  font-weight: 600;
  cursor: grab;
}
.md-json-bundle-export__bookmarklet:active {
  cursor: grabbing;
}
.md-json-bundle-export__alt-links {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 0.35rem 0.5rem;
  margin-top: 0.35rem;
}
.md-json-bundle-export__alt-sep {
  color: rgba($la-navy, 0.35);
  font-size: 1rem;
  line-height: 1;
}
.md-json-bundle-export__copy {
  font-size: 1rem;
  padding: 0.35rem 0;
}
.md-json-bundle-export__help {
  margin: 0;
  font-size: 0.95rem;
  line-height: 1.45;
  color: rgba($la-navy, 0.7);
}
.md-json-bundle-export__help--drag {
  margin-top: 0.15rem;
}
.md-json-bundle-export__divider {
  max-width: 34rem;
  margin: 1.35rem auto;
  border-color: rgba($la-navy, 0.12);
}
.md-modal-body .md-json-bundle-export + hr + section {
  text-align: left;
  max-width: 34rem;
  margin: 0 auto;
  font-size: 1rem;
  line-height: 1.5;
}

/* Board Details modal — fill the viewport. We pin the dialog via
   `position: fixed` with explicit insets rather than relying on
   Bootstrap's centered `.modal-dialog` margin, because the
   surrounding `#within_ember` ancestor uses `position: fixed; inset: 0`
   under some routes (bento layout) which makes the auto-centered
   sizing fragile. Pinning directly to the viewport is deterministic
   and survives both layouts. */
.md-board-details-modal__dialog.md-board-details-modal__dialog {
  position: fixed !important;
  top: 12px !important;
  left: 12px !important;
  right: 12px !important;
  bottom: 12px !important;
  width: auto !important;
  max-width: none !important;
  height: auto !important;
  max-height: none !important;
  margin: 0 !important;
  padding: 0 !important;
  z-index: 1051; /* above the .modal-backdrop (1040) and the .modal (1050) */
}
.md-board-details-modal__content {
  /* Fill the dialog box (which is sized to nearly the full viewport).
     Body scrolls when content exceeds the available height. */
  height: 100%;
  max-height: 100%;
  border-radius: 22px;
  border: 1px solid rgba($la-navy, 0.08);
  background: #fff;
  box-shadow: 0 24px 64px rgba($la-navy, 0.22);
  display: flex;
  flex-direction: column;
  overflow: hidden;
}
/* Modern modal header: title centered with the loading indicator
   sitting next to it, close button pinned right via la-modal-close. */
.md-board-details-modal__header {
  position: relative;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 14px;
  /* Symmetric 72px horizontal inset reserves room for the absolutely-positioned
     close button (right:18px, 48px wide) on BOTH sides, so a long wrapping title
     (e.g. the "We recommend this board" suggestion header) stays centered and
     never runs under the close X. */
  padding: 24px 72px 16px;
  border-bottom: 1px solid rgba($la-navy, 0.08);
  h3 {
    margin: 0;
    min-width: 0;
    text-align: center;
    font-size: 22px;
    font-weight: 800;
    color: $la-navy;
    letter-spacing: -0.01em;
  }
}
/* Close X button — modern circular chrome matching the beta-feedback
   modal close pattern (48×48 WCAG AAA target, navy-tinted surface
   with a soft border, charcoal icon that flips to white on hover).
   Double-class selector raises specificity above `.la-modal-close`
   so we win the cascade regardless of source-order.
   IMPORTANT: must explicitly reset `transform: none` — the global
   `.md-modal-header .la-modal-close` rule sets
   `top: 50%; transform: translateY(-50%)` to vertically center,
   and at our explicit `top: 18px` the translate pulled a 48px
   button to y = -6, clipping its top half against the modal's
   `overflow: hidden` + `border-radius: 22px` corner. */
.md-board-details-modal__close.md-board-details-modal__close {
  position: absolute;
  top: 18px;
  right: 18px;
  transform: none;
  width: 48px;
  height: 48px;
  min-width: 48px;
  min-height: 48px;
  padding: 0;
  margin: 0;
  border-radius: 50%;
  border: 1px solid rgba($la-navy, 0.12);
  background: rgba($la-navy, 0.06);
  color: $brand-charcoal-blue;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  transition: background 0.15s ease, color 0.15s ease, border-color 0.15s ease;
  svg {
    width: 18px;
    height: 18px;
  }
  &:hover, &:focus-visible {
    background: $brand-charcoal-blue;
    border-color: $brand-charcoal-blue;
    color: #fff;
    outline: none;
  }
}
/* Inline loading indicator on the header — spinner + "Loading
   preview..." text next to the title. Shrinks gracefully on narrow
   modals. */
.md-board-details-modal__header-loading {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 4px 12px;
  border-radius: 999px;
  background: rgba($brand-verdigris, 0.10);
  color: $brand-verdigris-aa;
  font-size: 13px;
  font-weight: 600;
}
.md-board-details-modal__header-spinner {
  width: 14px;
  height: 14px;
  border-radius: 50%;
  border: 2px solid rgba($brand-verdigris, 0.22);
  border-top-color: $brand-verdigris;
  animation: ll-loading-overlay-spin 0.9s linear infinite;
}
.md-board-details-modal__header-loading-text {
  white-space: nowrap;
}
.md-board-details-modal__body {
  flex: 1 1 auto;
  min-height: 0;
  overflow: auto;
  padding: 20px 28px 28px;
  text-align: left;
  font-size: 15px;
  /* Positioning context for the loading overlay so it pins to the
     body bounds instead of the document. */
  position: relative;
}

/* Full-body loading overlay — covers the modal body with a soft white
   wash + centered spinner card until the canvas image-loading promises
   have all settled. Shown until either the board model failed to load
   or the canvas component emits `onCanvasReady`. */
.md-board-details-modal__overlay {
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  background: rgba(255, 255, 255, 0.88);
  z-index: 5;
  /* Modern blur effect on the obscured content; degrades gracefully
     on browsers that don't support backdrop-filter. */
  backdrop-filter: blur(4px);
  -webkit-backdrop-filter: blur(4px);
  animation: md-board-details-modal__overlay-fade 0.18s ease-out;
}
.md-board-details-modal__overlay-card {
  display: inline-flex;
  align-items: center;
  gap: 14px;
  padding: 18px 26px;
  border-radius: 14px;
  background: #fff;
  box-shadow: 0 12px 30px rgba($la-navy, 0.18);
  border: 1px solid rgba($la-navy, 0.08);
}
.md-board-details-modal__overlay-spinner {
  width: 22px;
  height: 22px;
  border-radius: 50%;
  border: 3px solid rgba($brand-verdigris, 0.22);
  border-top-color: $brand-verdigris;
  animation: ll-loading-overlay-spin 0.9s linear infinite;
  flex: 0 0 auto;
}
.md-board-details-modal__overlay-text {
  color: $la-navy;
  font-weight: 600;
  font-size: 16px;
  letter-spacing: 0.005em;
}
/* Per-image "N / total" count under the loading label. Block so it sits on its
   own line; tabular-nums so the width doesn't jitter as the count ticks up. */
.md-board-details-modal__overlay-count {
  display: block;
  margin-top: 6px;
  font-weight: 600;
  font-size: 15px;
  font-variant-numeric: tabular-nums;
  color: rgba($la-navy, 0.65);
}
@keyframes md-board-details-modal__overlay-fade {
  from { opacity: 0; }
  to   { opacity: 1; }
}
/* The canvas wrapper inside the body picks up dark-mode styling via
   the inline `style` attribute the component sets; we just give the
   surrounding column a tiny breathing strip so the dark preview has
   room to breathe from the left actions column. */
.md-board-details-modal__body .col-sm-8 {
  padding-left: 18px;
}

/* ──────────────────────────────────────────────────────────────
   BOARD PREVIEW inner column — modernizes the bootstrap btn /
   dl-horizontal vocabulary inside the preview modal so the inner
   content matches the modal chrome (md-board-details-modal__*).
   Scoped under .md-board-preview to avoid leaking into other
   places that still use the older bootstrap classes.
   ────────────────────────────────────────────────────────────── */
.md-board-preview__info {
  font-size: 15px;
  color: $brand-charcoal-blue;
}
/* Fill the modal body's full height so the preview canvas can use all the
   available vertical space (the canvas grows to fill, see below) instead of
   stopping short and leaving a gap. The bootstrap `.row` columns stretch to the
   row height (flex align-items:stretch default), so the canvas column gets the
   full height to distribute. */
.md-board-details-modal__body .md-board-preview {
  display: flex;
  flex-wrap: wrap;
  align-items: stretch;
  min-height: 100%;
}
/* Right-hand column: stack the canvas (grows) above the action row (natural
   height). The growing canvas pushes the actions to the bottom of the modal. */
.md-board-preview__canvas-col {
  display: flex;
  flex-direction: column;
  min-height: 0;
}
/* 20% de-saturation on the rendered preview board buttons — applies wherever the
   board-preview-canvas is used (the board-preview modal AND the Find Boards preview). */
.board-preview-canvas__el {
  filter: saturate(0.8);
}
/* Action buttons sit in a row DIRECTLY BELOW the preview canvas (inside the
   right-hand canvas column, to the right of the board-detail info). The row is
   RIGHT-ALIGNED so the primary CTA and its neighbours (Board Actions / Back)
   cluster at the right edge; the destructive Remove is pushed to the far LEFT
   (margin-right:auto below) so it stays isolated. Wraps on narrow viewports.
   The canvas above is sized to the board's content height (not flex-grown), so
   `margin-top:auto` pins this row to the bottom of the modal. */
.md-board-preview__actions {
  flex: 0 0 auto;
  display: flex;
  flex-direction: row;
  flex-wrap: wrap;
  align-items: center;
  justify-content: flex-end;
  gap: 10px;
  margin-top: auto;
  /* Guaranteed breathing room between the bottom of the preview canvas and the
     buttons, independent of the flex/auto-margin sizing above. */
  padding-top: 24px;
}
/* Modern button override — beats the legacy `.btn` / `.btn-lg`
   bootstrap rules that were on these elements (we keep the bootstrap
   classes for safety, and let the md-* rules take over via specificity
   + the !important in md-modal-btn--primary). */
.md-board-preview__action.md-board-preview__action {
  display: inline-flex;
  width: auto;
  justify-content: center;
  padding: 12px 18px;
  font-size: 15px;
  font-weight: 600;
  border-radius: 12px;
  min-height: 48px;
  line-height: 1.2;
  letter-spacing: 0.01em;
  white-space: normal;
  /* Bootstrap's .btn applies a 1px transparent border + its own
     focus shadow; reset both so the modern style reads cleanly. */
  border: none;
  text-shadow: none;
}
.md-board-preview__action--primary.md-board-preview__action--primary {
  font-size: 16px;
  min-height: 52px;
  letter-spacing: 0.02em;
}
/* Touch-device parity for the tile's hover-only `.board_action`.
   De-emphasized danger treatment. `margin-right:auto` pushes it to the far LEFT
   of the right-aligned row so it stays isolated from the positive CTAs (Try /
   Board Actions / Copy For). Capitalize via CSS because remove_label ships
   lowercase ("delete", "un-like") from i18n — those strings double as title
   tooltips on the tile, where lowercase is correct. */
.md-board-preview__action--remove.md-board-preview__action--remove {
  margin-right: auto;
  background: rgba(176, 42, 42, 0.06);
  color: #b02a2a;
  font-size: 14px;
  font-weight: 600;
  min-height: 44px;
  text-transform: capitalize;
  gap: 8px;
  transition: background 0.15s ease, color 0.15s ease, box-shadow 0.15s ease;
}
.md-board-preview__action--remove.md-board-preview__action--remove:hover,
.md-board-preview__action--remove.md-board-preview__action--remove:focus-visible {
  background: #b02a2a;
  color: #fff;
  box-shadow: 0 4px 12px rgba(176, 42, 42, 0.30);
}
.md-board-preview__action--remove-icon {
  font-size: 14px;
  line-height: 1;
}
.md-board-preview__action--remove-text {
  line-height: 1;
}
.md-board-preview__heading {
  text-align: center;
  margin-bottom: 14px;
}
.md-board-preview__title {
  font-size: 22px;
  font-weight: 800;
  color: $la-navy;
  letter-spacing: -0.01em;
  margin: 0 0 2px;
  line-height: 1.2;
}
.md-board-preview__byline {
  font-size: 13px;
  color: rgba($la-navy, 0.65);
  font-weight: 500;
}
.md-board-preview__description {
  max-height: 190px;
  overflow: auto;
  padding: 12px 14px;
  border-radius: 10px;
  background: rgba($la-navy, 0.04);
  border: 1px solid rgba($la-navy, 0.08);
  font-size: 14px;
  line-height: 1.5;
  color: $brand-charcoal-blue;
  margin-bottom: 14px;
}
.md-board-preview__description-text {
  white-space: pre-line;
}
.md-board-preview__status {
  padding: 14px;
  text-align: center;
  font-size: 14px;
  color: rgba($la-navy, 0.55);
  font-style: italic;
}
.md-board-preview__status--error {
  color: #b03a3a;
  font-style: normal;
  font-weight: 600;
}
/* Modern definition list — replaces the bootstrap .dl-horizontal
   look (floated dt with fixed width + truncation). Uses a 2-column
   grid so labels and values align neatly without truncating long
   board keys. */
.md-board-preview__meta.md-board-preview__meta {
  display: grid;
  grid-template-columns: minmax(110px, 38%) 1fr;
  column-gap: 14px;
  row-gap: 6px;
  margin: 0;
  font-size: 13px;
  dt {
    /* Override bootstrap's float / width / overflow rules. */
    float: none;
    width: auto;
    overflow: visible;
    text-align: left;
    text-overflow: clip;
    white-space: normal;
    color: rgba($la-navy, 0.6);
    font-weight: 600;
    letter-spacing: 0.01em;
  }
  dd {
    margin-left: 0;
    color: $brand-charcoal-blue;
    font-weight: 500;
    word-break: break-word;
  }
}

.md-modal-icon-row {
  display: flex;
  justify-content: center;
  margin-bottom: 18px;
}
.md-modal-icon-circle {
  width: 56px;
  height: 56px;
  border-radius: 50%;
  background: rgba($brand-charcoal-blue, 0.10);
  color: $brand-charcoal-blue;
  display: flex;
  align-items: center;
  justify-content: center;
}
.md-modal-message {
  font-size: 16px;
  color: $brand-charcoal-blue;
  line-height: 1.5;
  margin: 0 0 8px;
}
.md-modal-board-name {
  font-size: 16px;
  font-weight: 700;
  color: $la-navy;
  margin: 0;
}
.md-modal-footer {
  border-top: 1px solid rgba($la-navy, 0.08);
  padding: 16px 24px;
  display: flex;
  justify-content: flex-end;
  gap: 10px;
}
.md-modal-btn {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  /* WCAG 2.5.5 AAA touch target — was 10×20 (~20 tall). */
  padding: 12px 20px;
  min-height: 44px;
  border-radius: 10px;
  font-size: 14px;
  font-weight: 600;
  border: none;
  cursor: pointer;
  transition: background 0.12s ease, box-shadow 0.12s ease;
}
.md-modal-btn--primary {
  background: $brand-charcoal-blue !important;
  color: #fff !important;
  box-shadow: 0 2px 6px rgba($brand-charcoal-blue, 0.25);
}
.md-modal-btn--primary:hover {
  background: #3a4350 !important;
  color: #fff !important;
  box-shadow: 0 4px 12px rgba($brand-charcoal-blue, 0.30);
}
/* Disabled (e.g. the PIN-settings Done button while a gate is on but the PIN
   isn't yet a valid 4-digit value) — dim the pill and block the pointer. */
.md-modal-btn--primary:disabled,
.md-modal-btn--primary[disabled],
.md-modal-btn--primary:disabled:hover,
.md-modal-btn--primary[disabled]:hover {
  background: rgba($brand-charcoal-blue, 0.45) !important;
  color: #fff !important;
  cursor: not-allowed;
  box-shadow: none;
}
.md-modal-btn--cancel {
  background: rgba($la-navy, 0.06);
  color: $brand-charcoal-blue;
}
.md-modal-btn--cancel:hover {
  background: rgba($la-navy, 0.12);
  color: $la-navy;
}

/* ──────────────────────────────────────────────────────────────
   SWITCH COMMUNICATORS modal — modernized choice rows
   ──────────────────────────────────────────────────────────────
   The original modal used Bootstrap .btn-group with btn-primary /
   btn-default and inline-style glyphicons. Replaced with a pair of
   segmented choice cards per row, matching the brand vocabulary used
   in the modern UI: verdigris-tinted active state with a soft glow +
   inset highlight, glass-translucent inactive state, hover lift.
   Icons swapped for Feather-style stroke SVGs (24×24) so they sit in
   the same icon family as the dashboard cards, board-detail menu,
   and Share & Print tiles. */
.md-switch-comms__choice-row {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 12px;
  width: 100%;
  margin-bottom: 18px;
}
.md-switch-comms__choice {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 14px 16px;
  border-radius: 14px;
  border: 1.5px solid rgba($la-navy, 0.12);
  background: rgba(255, 255, 255, 0.65);
  color: $la-navy;
  font-size: 14px;
  font-weight: 600;
  line-height: 1.3;
  text-align: left;
  cursor: pointer;
  backdrop-filter: blur(6px) saturate(1.1);
  -webkit-backdrop-filter: blur(6px) saturate(1.1);
  transition: border-color 0.15s ease, background 0.15s ease, box-shadow 0.15s ease, transform 0.1s ease;
}
.md-switch-comms__choice:hover {
  border-color: rgba($brand-verdigris-aa, 0.45);
  background: rgba(255, 255, 255, 0.85);
  box-shadow: 0 4px 14px rgba($la-navy, 0.08);
  transform: translateY(-1px);
}
.md-switch-comms__choice:focus-visible {
  outline: none;
  border-color: $brand-verdigris-aa;
  box-shadow: 0 0 0 3px rgba($brand-verdigris-aa, 0.20);
}
.md-switch-comms__choice--active {
  /* Soft verdigris-tinted illuminated active state. */
  background: linear-gradient(135deg, rgba($brand-verdigris, 0.22) 0%, rgba($brand-verdigris-aa, 0.14) 100%);
  border-color: $brand-verdigris;
  color: $la-navy;
  box-shadow:
    /* Inset highlight on top — light catching the lip. */
    inset 0 1px 0 rgba(255, 255, 255, 0.65),
    /* Subtle teal glow halo. */
    0 0 0 1px rgba($brand-verdigris, 0.25),
    /* Soft drop. */
    0 4px 14px rgba($brand-verdigris, 0.18);
}
.md-switch-comms__choice--active:hover {
  background: linear-gradient(135deg, rgba($brand-verdigris, 0.30) 0%, rgba($brand-verdigris-aa, 0.20) 100%);
  border-color: $brand-verdigris-aa;
  transform: none;
}
.md-switch-comms__choice-icon {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  width: 44px;
  height: 44px;
  border-radius: 12px;
  background: rgba(255, 255, 255, 0.55);
  border: 1px solid rgba($la-navy, 0.08);
  color: $brand-verdigris-aa;
}
.md-switch-comms__choice--active .md-switch-comms__choice-icon {
  background: rgba(255, 255, 255, 0.85);
  border-color: rgba($brand-verdigris-aa, 0.30);
  color: $brand-verdigris-aa;
}
.md-switch-comms__choice-label {
  flex: 1 1 auto;
  min-width: 0;
}
/* Narrow viewports: stack the two cards full-width. */
@media (max-width: 540px) {
  .md-switch-comms__choice-row {
    grid-template-columns: 1fr;
  }
}
.md-modal-btn--secondary {
  background: rgba($la-navy, 0.08);
  color: $la-navy;
}
.md-modal-btn--secondary:hover {
  background: rgba($la-navy, 0.15);
  color: $la-navy;
}
/* Save / Update primary action — uses brand slate blue so it reads as
   the affirmative action without competing visually with the darker
   .md-modal-btn--primary (charcoal blue). Disabled state dims the
   pill so users see the saving / submitting moment. */
.md-modal-btn--save {
  background: $brand-slate-blue !important;
  color: #fff !important;
  box-shadow: 0 2px 6px rgba($brand-slate-blue, 0.25);
}
.md-modal-btn--save:hover,
.md-modal-btn--save:focus-visible {
  background: color.adjust($brand-slate-blue, $lightness: -6%) !important;
  color: #fff !important;
  box-shadow: 0 4px 12px rgba($brand-slate-blue, 0.30);
  outline: none;
}
.md-modal-btn--save:disabled,
.md-modal-btn--save[disabled] {
  background: rgba($brand-slate-blue, 0.55) !important;
  cursor: not-allowed;
  box-shadow: none;
}
/* Modern modal disclosure/expander — a collapsed-by-default section (e.g. the
   copy-board sub-board picker: everything is selected, so the picker is opt-in). */
.md-modal-expander {
  margin: 10px 0 6px;
  border: 1px solid #e2e6ea;
  border-radius: 10px;
  overflow: hidden;
}
.md-modal-expander__toggle {
  display: flex;
  align-items: center;
  gap: 8px;
  width: 100%;
  padding: 11px 14px;
  border: none;
  background: #f6f8fa;
  color: $brand-charcoal-blue;
  font-size: 16px;
  font-weight: 600;
  text-align: left;
  cursor: pointer;
}
.md-modal-expander__toggle:hover {
  background: #eef1f4;
}
.md-modal-expander__toggle:focus-visible {
  outline: 2px solid $brand-verdigris-aa;
  outline-offset: -2px;
}
.md-modal-expander__chevron {
  flex-shrink: 0;
  color: #6b7683;
  transition: transform 0.18s ease;
}
.md-modal-expander--open .md-modal-expander__chevron {
  transform: rotate(90deg);
}
.md-modal-expander__body {
  padding: 10px 14px 12px;
  border-top: 1px solid #e2e6ea;
}
/* board-hierarchy selectable toolbar (Select All / Deselect All / Expand / Collapse). */
.md-hierarchy-toolbar {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 4px 10px;
  margin-bottom: 8px;
  font-size: 15px;
}
.md-hierarchy-toolbar__link {
  color: $brand-verdigris-aa;
  font-weight: 600;
  text-decoration: none;
}
.md-hierarchy-toolbar__link:hover {
  text-decoration: underline;
}
.md-hierarchy-toolbar__sep {
  color: #c2c9d1;
}
/* Inline spinner inside a modal button — appears next to the label
   while a network request is in flight (e.g. "Adding Goal…"). Uses
   currentColor so it inherits the button's text color (white on the
   primary button). */
.md-modal-btn__spinner {
  display: inline-block;
  width: 14px;
  height: 14px;
  margin-right: 8px;
  border: 2px solid rgba(255, 255, 255, 0.35);
  border-top-color: currentColor;
  border-radius: 50%;
  vertical-align: -2px;
  animation: md-modal-spin 0.7s linear infinite;
}
.md-modal-btn.is-loading {
  cursor: progress;
}
@keyframes md-modal-spin {
  to { transform: rotate(360deg); }
}
/* Indeterminate progress bar — slim track pinned across the footer
   while the save promise is pending. Two-bar gradient animates left-
   to-right for the "indeterminate" Material-style sweep. */
.md-modal-progress {
  flex-basis: 100%;
  margin: 10px 0 0;
  height: 3px;
  border-radius: 999px;
  background: rgba($la-navy, 0.08);
  overflow: hidden;
  position: relative;
}
.md-modal-progress__bar {
  position: absolute;
  top: 0;
  bottom: 0;
  width: 40%;
  border-radius: 999px;
  background: linear-gradient(90deg, $brand-verdigris, $brand-charcoal-blue);
  animation: md-modal-progress-slide 1.2s ease-in-out infinite;
}
@keyframes md-modal-progress-slide {
  0%   { left: -40%; }
  100% { left: 100%; }
}

/* ── Translation modal (button-set) ─────────────────────────────
   Replaces the legacy Bootstrap list-group + float layouts inside
   the Translate Boards modal with a calm 2-column row grid: source
   label on the left, translation input on the right, board-key
   path muted underneath. Each row reads as a self-contained card
   with subtle borders and hover state, matching the modern modal
   vocabulary (md-modal-*). The .md-modal-body { text-align:center }
   rule stays for the hero copy; the list overrides to
   text-align:left so words and inputs line up properly. */
.md-translate-hero {
  margin-bottom: 24px;
}
.md-translate-hero__title {
  font-size: 17px;
  font-weight: 600;
  color: $la-navy;
  margin: 0 0 8px;
}
.md-translate-hero__caption {
  font-size: 14px;
  color: $brand-slate-gray;
  line-height: 1.5;
  margin: 0 auto;
  max-width: 540px;
}
.md-translate-actions-row {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 14px;
  flex-wrap: wrap;
  gap: 12px;
  text-align: left;
}
.md-translate-filters {
  display: inline-flex;
  gap: 6px;
  flex-wrap: wrap;
}
.md-translate-filter {
  padding: 6px 14px;
  border-radius: 999px;
  font-size: 13px;
  font-weight: 600;
  color: $brand-slate-gray;
  background: rgba($la-navy, 0.04);
  border: 1px solid transparent;
  cursor: pointer;
  text-decoration: none;
  transition: background 0.15s ease, color 0.15s ease, border-color 0.15s ease;
}
.md-translate-filter:hover,
.md-translate-filter:focus-visible {
  background: rgba($la-navy, 0.10);
  color: $la-navy;
  text-decoration: none;
  outline: none;
}
.md-translate-filter--active {
  background: rgba($brand-verdigris-aa, 0.15);
  color: $brand-verdigris-aa;
  border-color: rgba($brand-verdigris-aa, 0.25);
}
.md-translate-download {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  font-size: 14px;
  color: $brand-charcoal-blue;
  text-decoration: none;
}
.md-translate-download:hover {
  color: $la-navy;
  text-decoration: underline;
}
.md-translate-list {
  display: flex;
  flex-direction: column;
  gap: 8px;
  text-align: left;
}
.md-translate-row {
  display: grid;
  grid-template-columns: 1fr 1fr;
  column-gap: 16px;
  row-gap: 6px;
  align-items: center;
  padding: 14px 18px;
  border-radius: 12px;
  border: 1px solid rgba($la-navy, 0.08);
  background: rgba(255, 255, 255, 0.55);
  transition: border-color 0.15s ease, background 0.15s ease, box-shadow 0.15s ease;
}
.md-translate-row:hover {
  border-color: rgba($la-navy, 0.16);
  background: rgba(255, 255, 255, 0.85);
  box-shadow: 0 2px 8px rgba($la-navy, 0.05);
}
.md-translate-row--repeat {
  opacity: 0.7;
  border-style: dashed;
}
.md-translate-row--board {
  background: rgba($brand-verdigris-aa, 0.06);
  border-color: rgba($brand-verdigris-aa, 0.18);
}
.md-translate-row__source {
  font-size: 17px;
  font-weight: 600;
  color: $la-navy;
  display: flex;
  align-items: center;
  gap: 8px;
  min-width: 0;
  word-break: break-word;
}
.md-translate-row__source-icon {
  flex-shrink: 0;
  width: 18px;
  height: 18px;
  opacity: 0.75;
}
.md-translate-row__source-tag {
  font-size: 13px;
  color: $brand-slate-gray;
  font-weight: 400;
  margin-left: 4px;
}
.md-translate-row__target {
  min-width: 0;
}
.md-translate-row__path {
  grid-column: 1 / -1;
  font-size: 12px;
  color: $brand-slate-gray;
  margin: 2px 0 0;
}
.md-translate-row__path a {
  color: inherit;
  text-decoration: none;
}
.md-translate-row__path a:hover {
  color: $brand-charcoal-blue;
  text-decoration: underline;
}
.md-translate-input {
  width: 100%;
  padding: 10px 14px;
  border-radius: 10px;
  border: 1px solid rgba($la-navy, 0.15);
  background: #fff;
  color: $la-navy;
  font-size: 15px;
  transition: border-color 0.15s ease, box-shadow 0.15s ease;
  box-sizing: border-box;
}
.md-translate-input:focus,
.md-translate-input:focus-visible {
  outline: none;
  border-color: $brand-verdigris-aa;
  box-shadow: 0 0 0 3px rgba($brand-verdigris-aa, 0.20);
}
.md-translate-input::placeholder {
  color: rgba($la-navy, 0.35);
  font-style: italic;
}
.md-translate-status {
  text-align: center;
  font-size: 14px;
  color: $brand-slate-gray;
  padding: 24px 0;
}
.md-translate-status--error {
  color: $brand-danger;
}
/* Stack rows full-width on narrow viewports — source above input. */
@media (max-width: 540px) {
  .md-translate-row {
    grid-template-columns: 1fr;
    row-gap: 8px;
  }
}

/* ── Edit Room Details modal — curriculum row repeater ──────────── */
.md-edit-unit-curriculum {
