  flex-direction: column;
  align-items: center;
  gap: 8px;
  padding: 14px 18px;
  border-radius: 12px;
  background: rgba($la-navy, 0.04);
  border: 1px solid rgba($la-navy, 0.10);
  min-width: 110px;
}
.md-swap-preview__card--folder {
  background: rgba($brand-verdigris, 0.06);
  border-color: rgba($brand-verdigris, 0.18);
}
.md-swap-preview__img {
  height: 48px;
  max-width: 80px;
  object-fit: contain;
}
.md-swap-preview__label {
  font-size: 14px;
  font-weight: 600;
  color: $la-navy;
}
.md-swap-preview__folder-badge {
  display: flex;
  align-items: center;
  gap: 4px;
  font-size: 14px;
  color: $brand-verdigris;
  font-weight: 500;
}
.md-swap-preview__arrow {
