/* ── Manage Languages Modal ── */
.md-manage-lang-section {
  margin-bottom: 8px;
}
.md-manage-lang-boards {
  max-height: 200px;
  overflow-y: auto;
  padding: 10px 14px;
  border: 1px solid rgba($la-navy, 0.10);
  border-radius: 10px;
  background: rgba($la-navy, 0.02);
}
.md-manage-lang-placeholder {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 12px 14px;
  color: #8896a7;
  font-size: 14px;
}
.md-manage-lang-list {
  display: flex;
  flex-direction: column;
  gap: 6px;
}
.md-manage-lang-item {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 10px 14px;
  border-radius: 10px;
  border: 1px solid rgba($la-navy, 0.10);
  background: rgba($la-navy, 0.02);
