  flex-direction: column;
  gap: 2px;
}
.md-modal-board-preview__name {
  font-size: 15px;
  font-weight: 700;
  color: $la-navy;
}
.md-modal-board-preview__size {
  font-size: 14px;
  color: $brand-slate-gray;
}
.md-modal-status--warning {
  background: rgba(212, 168, 75, 0.10);
  color: #b8860b;
}
.md-modal-supervisee-list {
  display: flex;
