  flex-direction: column;
  gap: 8px;
  margin-top: 18px;
}
.md-modal-voice {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 12px 14px;
  background: rgba($la-navy, 0.03);
  border: 1px solid rgba($la-navy, 0.08);
  border-radius: 12px;
  transition: background 0.15s ease, border-color 0.15s ease;
}
.md-modal-voice:hover {
  background: rgba($la-navy, 0.06);
  border-color: rgba($la-navy, 0.12);
}
.md-modal-voice--inactive {
  opacity: 0.65;
}
.md-modal-voice__info {
  flex: 1;
  min-width: 0;
}
.md-modal-voice__name {
  font-size: 15px;
  font-weight: 600;
  color: $la-navy;
  display: flex;
  align-items: center;
  gap: 6px;
  flex-wrap: wrap;
}
.md-modal-voice__claimed {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 18px;
  height: 18px;
  border-radius: 50%;
  background: $brand-verdigris;
