  padding: 2px 8px;
  border-radius: 999px;
}
.md-modal-voice__meta {
  font-size: 14px;
  color: $brand-slate-gray;
  margin-top: 2px;
}
.md-modal-voice__actions {
  display: flex;
  align-items: center;
  gap: 6px;
  flex-shrink: 0;
}
.md-modal-voice__btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 36px;
  height: 36px;
  border: none;
  background: rgba($la-navy, 0.06);
  color: $brand-charcoal-blue;
  border-radius: 10px;
  cursor: pointer;
  transition: background 0.12s ease, color 0.12s ease, box-shadow 0.12s ease;
}
.md-modal-voice__btn:hover {
  background: rgba($la-navy, 0.12);
