}
.md-modal-voice__btn--download {
  background: $brand-charcoal-blue;
  color: #fff;
  box-shadow: 0 2px 6px rgba($brand-charcoal-blue, 0.20);
}
.md-modal-voice__btn--download:hover {
  background: #3a4350;
  color: #fff;
  box-shadow: 0 4px 10px rgba($brand-charcoal-blue, 0.28);
}
.md-modal-voice__btn--remove:hover {
