}

.md-org-home-board {
  margin-bottom: 20px;
  text-align: center;
}
.md-org-home-board__card {
  display: inline-flex;
  align-items: center;
  gap: 12px;
  background: rgba(255, 255, 255, 0.95);
  border: 1px solid rgba($la-navy, 0.1);
  border-radius: 12px;
  padding: 12px 16px;
  box-shadow: 0 1px 4px rgba(0, 0, 0, 0.04);
  transition: box-shadow 0.2s ease, border-color 0.2s ease;
}
.md-org-home-board__card:hover {
  border-color: rgba($brand-dusty-denim, 0.25);
  box-shadow: 0 2px 8px rgba($brand-dusty-denim, 0.1);
}
.md-org-home-board__icon {
  color: $brand-dusty-denim-aa; /* WCAG AA fix. */
  flex-shrink: 0;
}
.md-org-home-board__text {
  display: flex;
  flex-direction: column;
  gap: 2px;
}
.md-org-home-board__label {
  font-size: 14px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  color: rgba($la-navy, 0.5);
}
.md-org-home-board__link {
  color: var(--md-navy, $la-navy);
  font-weight: 600;
  font-size: 15px;
  text-decoration: none;
  transition: color 0.15s ease;
}
.md-org-home-board__link:hover {
  color: $brand-dusty-denim-aa; /* WCAG AA fix. */
}
.md-org-home-board__arrow {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 32px;
  height: 32px;
  border-radius: 8px;
  color: rgba($la-navy, 0.3);
  transition: background 0.15s ease, color 0.15s ease;
  margin-left: 4px;
  flex-shrink: 0;
}
.md-org-home-board__arrow:hover {
