/* Charts layout */
.md-org-charts {
  display: grid;
  grid-template-columns: 2fr 1fr 1fr;
  /* #8 — more space between chart cards. */
  gap: 20px;
  margin-bottom: 28px;
}
/* #5 — Communication Activity: the weekly chart gets 2/3, the recent-sessions
   ratio 1/3, so the chart is clearly the emphasis. */
.md-org-charts--comm {
  grid-template-columns: 2fr 1fr;
}
/* Goals & Progress: goal ratio + (optional) two profile ratios, equal thirds. */
.md-org-charts--goals {
  grid-template-columns: repeat(3, minmax(0, 1fr));
}
.md-org-charts--words-row {
  grid-template-columns: 1fr 1fr;
}
.md-org-charts--stats {
  grid-template-columns: repeat(auto-fill, minmax(280px, 1fr));
}
.md-org-charts__item {
  background: rgba(255, 255, 255, 0.92);
  border: 1px solid rgba($la-navy, 0.08);
  border-radius: 18px;
  padding: 16px;
  min-width: 0;
  /* Same elevated tile language as the metric cards / reports panels. */
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.7),
    0 2px 6px rgba($la-navy, 0.07),
    0 8px 20px rgba($la-navy, 0.08);
}
.md-org-charts__item--wide {
  grid-column: span 1;
}
.md-org-chart-label {
  font-size: 14px;
  font-weight: 700;
  color: var(--md-ink, $brand-blue-black);
  margin: 0 0 8px;
}
/* Empty state for a data-less chart card (recent sessions / goals / profiles when
   the org has no users/data). #6 — an icon + a title + a soft one-line hint so the
   card reads as intentional ("nothing yet, here's what will appear"), not broken. */
.md-org-chart-empty {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 8px;
  min-height: 180px;
  padding: 12px;
  margin: 0;
  text-align: center;
}
.md-org-chart-empty__icon {
  color: rgba($la-navy, 0.32);
  margin-bottom: 2px;
}
.md-org-chart-empty__title {
  margin: 0;
  font-size: 16px;
  font-weight: 700;
  color: rgba($la-navy, 0.72);
}
.md-org-chart-empty__sub {
  margin: 0;
  max-width: 260px;
  font-size: 13.5px;
  line-height: 1.45;
  color: rgba($la-navy, 0.5);
}

/* Section containers */
/* Start-code detail page (/start_codes/:id) — modern card styling that reuses
   the org-section + user-row design language for a professional, consistent look. */
.md-start-code {
  width: min(680px, 100%);
  box-sizing: border-box;
  /* top margin so the card clears the fixed header + shell padding. Placed on
     the container (flex child of .md-shell) so it isn't swallowed by
     parent/first-child margin-collapsing the way a card margin would be. */
  margin: 72px auto 48px;
  padding: 0 16px;
}
.md-start-code__card {
  margin-bottom: 0;
}
.md-start-code__status {
  text-align: center;
}
.md-start-code__head {
  display: flex;
  align-items: center;
  gap: 16px;
  padding-bottom: 18px;
  margin-bottom: 18px;
  border-bottom: 1px solid rgba($la-navy, 0.08);
}
.md-start-code__badge {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 56px;
  height: 56px;
  border-radius: 16px;
  flex-shrink: 0;
  background: rgba($brand-dusty-denim, 0.10);
  color: $brand-dusty-denim-aa;
}
.md-start-code__badge svg {
  width: 28px;
  height: 28px;
}
.md-start-code__badge-img {
  width: 56px;
  height: 56px;
  border-radius: 16px;
  object-fit: cover;
}
.md-start-code__head-text {
  flex: 1;
  min-width: 0;
}
.md-start-code__eyebrow {
  display: block;
  font-size: 13px;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--md-muted, $la-navy);
  opacity: 0.75;
}
.md-start-code__code {
  margin: 3px 0 0;
  font-size: 26px;
  font-weight: 800;
  letter-spacing: 0.01em;
  color: var(--md-ink, $brand-blue-black);
  font-family: 'SFMono-Regular', 'Menlo', 'Consolas', monospace;
  word-break: break-all;
}
.md-start-code__chip {
  align-self: flex-start;
}
/* Detail card: responsive grid of label/value field tiles (mirrors the
   eyebrow → value language of the header for a modern info-panel look). */
.md-start-code__fields {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 12px 14px;
}
.md-start-code__field {
  display: flex;
  flex-direction: column;
  gap: 5px;
  padding: 12px 14px;
  border-radius: 12px;
  background: rgba($la-navy, 0.035);
  border: 1px solid rgba($la-navy, 0.05);
}
.md-start-code__field--wide {
  grid-column: 1 / -1;
}
.md-start-code__label {
  font-size: 12px;
  font-weight: 700;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: var(--md-muted, $la-navy);
  opacity: 0.7;
}
.md-start-code__value {
  font-size: 16px;
  font-weight: 600;
  color: var(--md-ink, $brand-blue-black);
  word-break: break-word;
}
.md-start-code__value a {
  color: $brand-dusty-denim-aa;
  font-weight: 700;
}
.md-start-code__chips {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
}

/* Activated-users sub-section inside the single detail card, set off with a
   divider so the whole card reads as one cohesive block of information. */
.md-start-code__section {
  margin-top: 22px;
  padding-top: 22px;
  border-top: 1px solid rgba($la-navy, 0.09);
}
.md-start-code__section-head {
  display: flex;
  align-items: center;
  gap: 10px;
  margin-bottom: 14px;
}
.md-start-code__section-title {
  margin: 0;
  font-size: 17px;
  font-weight: 800;
  letter-spacing: -0.01em;
  color: var(--md-ink, $brand-blue-black);
}
.md-start-code__count {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 24px;
  height: 24px;
  padding: 0 8px;
  border-radius: 999px;
  background: rgba($brand-dusty-denim, 0.12);
  color: $brand-dusty-denim-aa;
  font-size: 13px;
  font-weight: 700;
}
/* Activated users: responsive grid of avatar + name tiles. */
.md-start-code__users {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(190px, 1fr));
  gap: 10px;
}
.md-start-code__user {
  display: flex;
  align-items: center;
  gap: 11px;
  padding: 10px 12px;
  border-radius: 12px;
  background: rgba($la-navy, 0.035);
  border: 1px solid rgba($la-navy, 0.05);
  text-decoration: none;
  color: var(--md-ink, $brand-blue-black);
  transition: background 0.15s ease, border-color 0.15s ease, transform 0.15s ease;
}
.md-start-code__user:hover {
  background: rgba($brand-dusty-denim, 0.07);
  border-color: rgba($brand-dusty-denim, 0.20);
  color: $brand-dusty-denim-aa;
  text-decoration: none;
  transform: translateY(-1px);
}
.md-start-code__user-avatar {
  width: 36px;
  height: 36px;
  border-radius: 50%;
  object-fit: cover;
  flex-shrink: 0;
}
.md-start-code__user-name {
  font-size: 15px;
  font-weight: 600;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
@media (max-width: 560px) {
  .md-start-code__fields {
    grid-template-columns: 1fr;
  }
}

.md-org-section {
  background: rgba(255, 255, 255, 0.92);
  border: 1px solid rgba($la-navy, 0.08);
  border-radius: 18px;
  padding: 24px;
  margin-bottom: 20px;
  /* Same elevated tile language as the metric cards / reports panels. */
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.7),
    0 2px 6px rgba($la-navy, 0.07),
    0 8px 20px rgba($la-navy, 0.08);
