.md-org-section-title {
  font-size: 18px;
  font-weight: 800;
  color: var(--md-ink, $brand-blue-black);
  margin: 0 0 16px;
  letter-spacing: -0.01em;
}
.md-org-section-head {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 12px 20px;
  margin-bottom: 16px;
}
.md-org-section-head .md-org-section-title {
  margin-bottom: 6px;
}
.md-org-section-desc,
.md-org-directory__intro {
  margin: 0;
  color: var(--md-muted, $la-navy);
